INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (88, 49, 168, '全文', '…所在地的区人民政府依法指定保护责任人。 “历史建筑的保护责任人应当按照保护规划的要求和维护修缮标准，负责对历史建筑进行维护和修缮。维护修缮标准由市住房和城乡建设行政主管部门会同市旅游和文化行政主管部门制定。 “历史建筑有损毁危险，保护责任人不具备维护和修缮能力的，市、区人民政府应当采取措施予以保护。 “市、区人民…', 'supporting');
