INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (89, 50, 168, '全文', '…历史文化名城的保护和管理工作纳入国民经济和社会发展规划，并在本级财政预算中安排历史文化名城保护资金，加大对历史文化名城保护的财政投入。 “鼓励单位和个人以捐赠、资助、提供技术服务或者提出建议等方式参与历史文化名城的保护。 “鼓励投资者依法对本市历史文化名城资源实施保护性开发利用，发展旅游业及相关产业。” 四、将第十四…', 'supporting');
