INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (91, 53, 168, '全文', '…条改为第二十四条，修改为：“市、区人民政府应当制定相关的优惠扶持政策，调整优化历史文化街区业态布局，鼓励开展具有地方特色的生产经营活动，引导老字号向历史文化街区聚集，促进历史文化街区保护与文化、旅游业融合发展。” 十二、将第二十七条改为第二十五条，修改为：“具有一定历史、艺术或科学价值的近现代建筑、传统民居、商铺…', 'supporting');
