INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (92, 56, 168, '全文', '…十五条，修改为：“违反本条例第三十六条的规定，造成不可移动文物损毁、灭失的，依法承担相应的法律责任，构成犯罪的，依法追究刑事责任。 “未经依法批准，擅自迁移、拆除不可移动文物，尚不构成犯罪的，由综合行政执法部门依法予以处罚。” 二十七、将第六十条改为第五十八条，修改为：“违反本条例的行为，本条例未设定处罚但其他法律、…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (57, 'FBMCLI.10.9191486', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 6 个核心用语、9 个相关用语，关联 15 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (93, 57, 170, '第二条', '…政区域内历史文化名城的规划、保护、管理和利用等活动。 历史文化名城的保护对象包括历史城区、历史文化街区、历史地段、历史建筑、历史文化名镇、历史文化名村、传统村落、文物、非物质文化遗产、古树名木及法律、法规规定的其他保护对象。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (94, 57, 176, '第八条', '第八条 历史城区、历史文化街区、历史地段、历史建筑、历史文化名镇、历史文化名村、传统村落应当整体保护，保持传统格局、历史风貌和空间尺度，不得擅自改变与其相互依存的自然景观和历史环境要素。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (95, 57, 185, '第十七条', '…七条 市、县（市、区）人民政府或者相关部门应当与保护责任人签订保护责任书，明确保护责任。 历史文化街区、历史地段、历史文化名镇、历史文化名村、传统村落的保护责任人应当组织实施保护规划，保持保护范围内建（构）筑物的传统格局、历史风貌、空间尺度和历史环境要素的完整性；在保持街道空间尺度和风貌的情况下，改善基础设施、公共服务设…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (58, 'FBMCLI.10.9191486', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、6 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (96, 58, 177, '第九条', '…条 历史文化街区、历史地段、历史建筑、历史文化名镇、历史文化名村、传统村落保护规划应当划定保护范围。保护范围根据需要设定核心保护范围和建设控制地带。 在保护范围内进行建设活动，应当遵守下列要求： （一）在核心保护范围内，除建设必要的基础设施和公共服务设施外，不得进行新建、扩建活动。对历史建筑以外已经倒塌或者濒临倒塌的…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (97, 58, 183, '第十五条', '…、历史建筑、历史文化名镇、历史文化名村、传统村落、不可移动文物和古树名木设置保护标志，标明保护范围。保护标志由市人民政府统一样式。 任何单位和个人不得擅自设置、移动、涂改或者损毁保护标志。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (98, 58, 185, '第十七条', '…街区、历史地段、历史文化名镇、历史文化名村、传统村落的保护责任人应当组织实施保护规划，保持保护范围内建（构）筑物的传统格局、历史风貌、空间尺度和历史环境要素的完整性；在保持街道空间尺度和风貌的情况下，改善基础设施、公共服务设施和居住环境；保持保护范围内整洁美观。 历史建筑的保护责任人应当合理使用建筑，负责建筑的日常保…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (59, 'FBMCLI.10.9191486', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、6 个相关用语，关联 13 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (99, 59, 172, '第四条', '第四条 市、县（市、区）人民政府住房和城乡建设主管部门统筹历史文化名城保护工作，具体负责历史城区、历史文化街区、历史地段、历史建筑、历史文化名镇、历史文化名村、传统村落的申报以及保护、建设、管理工作。 市、县（市、区）人民政府自然资源主管部门负责历史文化名城、历史地段、历史…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (100, 59, 184, '第十六条', '…史建筑的所有权人、管理人、使用人均不明确或者下落不明的，县（市、区）人民政府住房和城乡建设主管部门为保护责任人。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (101, 59, 187, '第十九条', '…的维护和修缮，根据保护需要提出维护、修缮设计方案，由市、县（市、区）人民政府住房和城乡建设主管部门会同自然资源、文化文物主管部门审定后进行维护、修缮。 国有历史建筑的维护、修缮费用由市、县（市、区）人民政府在历史文化名城保护经费中予以安排。 非国有历史建筑的维护、修缮费用由历史建筑的保护责任人承担；保护责任人承担维护…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (60, 'FBMCLI.10.9191486', 'COORD', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (102, 60, 171, '第三条', '…、区）人民政府负责本行政区域内历史文化名城保护和监督管理工作，建立健全历史文化名城保护工作协调机制，研究处理与历史文化名城保护有关的重要事项。 乡镇人民政府、街道办事处负责本辖区内历史文化名城保护的信息采集、日常巡查和现场保护等具体工作。 村（居）民委员会协助做好历史文化名城保护相关工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (61, 'FBMCLI.10.9191486', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、5 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (103, 61, 175, '第七条', '…组织住房和城乡建设、自然资源和规划、文化文物等部门，根据国土空间总体规划，编制历史文化名城保护规划。 市、县（市）、南岳区人民政府应当根据国土空间总体规划和历史文化名城保护规划，组织编制历史文化街区、历史文化名镇、历史文化名村、传统村落保护规划。 市、县（市）、南岳区人民政府确定的主管部门应当组织编制历史地段、历史建…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (104, 61, 177, '第九条', '第九条 历史文化街区、历史地段、历史建筑、历史文化名镇、历史文化名村、传统村落保护规划应当划定保护范围。保护范围根据需要设定核心保护范围和建设控制地带。 在保护范围内进行建设活动，应当遵守下列要求： （一）在核心保护范围内，除建设必要的基础设施和公共服务设施外，不得进行新建、扩建活动。对历史建筑以外已经倒…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (105, 61, 185, '第十七条', '…任。 历史文化街区、历史地段、历史文化名镇、历史文化名村、传统村落的保护责任人应当组织实施保护规划，保持保护范围内建（构）筑物的传统格局、历史风貌、空间尺度和历史环境要素的完整性；在保持街道空间尺度和风貌的情况下，改善基础设施、公共服务设施和居住环境；保持保护范围内整洁美观。 历史建筑的保护责任人应当合理使用建筑，负…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (62, 'FBMCLI.10.9191486', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (106, 62, 181, '第十三条', '…录的历史文化资源，应当征求有关部门、相关利害关系人和社会公众的意见，经专家论证后，可以列为预先保护对象，并在十日内向所在地乡镇人民政府、街道办事处和所有权人、管理人或者使用人发出预先保护通知，告知其应当采取的保护措施。 预先保护对象确定后，市、县（市、区）人民政府应当与预先保护对象所有权人、管理人或者使用人签订协议，…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (63, 'FBMCLI.10.9191486', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (107, 63, 177, '第九条', '…。 （二）在建设控制地带内新建建（构）筑物的，应当符合保护规划确定的建设控制要求。 （三）修缮道路、地下工程及其他市政公用设施的，应当采取有效的保护措施，不得损害保护对象。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (108, 63, 186, '第十八条', '…值及完好程度，实行分类保护。 因公共利益需要进行建设活动，对历史建筑无法实施原址保护、必须迁移异地保护或者拆除的，应当由市人民政府自然资源和规划主管部门会同住房和城乡建设、文化文物主管部门，经过专家论证和征求公众意见后，报省人民政府确定的保护主管部门及文化文物主管部门批准。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (109, 63, 188, '第二十条', '…损害传统格局和历史风貌的建（构）筑物； （五）在历史建筑上刻划、涂污； （六）损坏或者擅自修缮、迁移、拆除历史建筑； （七）法律、法规禁止的其他行为。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (64, 'FBMCLI.10.9191486', 'FUND', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (110, 64, 173, '第五条', '…将历史文化名城保护工作纳入国民经济和社会发展规划，并将历史文化名城保护工作所需经费列入同级财政预算。 鼓励单位和个人通过投资、捐赠和提供服务等方式参与历史文化名城保护工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (111, 64, 187, '第十九条', '…定后进行维护、修缮。 国有历史建筑的维护、修缮费用由市、县（市、区）人民政府在历史文化名城保护经费中予以安排。 非国有历史建筑的维护、修缮费用由历史建筑的保护责任人承担；保护责任人承担维护、修缮费用确有困难的，可以向市、县（市、区）人民政府申请资金补助，或者由市、县（市、区）人民政府进行产权置换、收购，予以维护、修缮…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (65, 'FBMCLI.10.9191486', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (112, 65, 187, '第十九条', '…责任人承担；保护责任人承担维护、修缮费用确有困难的，可以向市、县（市、区）人民政府申请资金补助，或者由市、县（市、区）人民政府进行产权置换、收购，予以维护、修缮。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (113, 65, 181, '第十三条', '…护对象所有权人、管理人或者使用人签订协议，明确保护权利、义务、责任以及因合法权益受到损失的补偿等内容。 预先保护期间，任何单位和个人不得破坏预先保护对象。确定为预先保护对象的，市、县（市、区）人民政府住房和城乡建设、文化文物等部门应当在一年内按照申报条件和程序，报市人民政府核定公布后列入保护名录。未列入保护名录的…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (114, 65, 192, '第二十四条', '第二十四条 市人民政府应当建立历史文化名城保护补偿制度，对单位和个人因历史文化名城保护而受到的合法权益损失给予补偿。具体的补偿办法由市人民政府制定。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (66, 'FBMCLI.10.9191486', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (115, 66, 191, '第二十三条', '…目； （六）发展康养、文化旅游、乡村旅游、研学旅游等产业； （七）其他合理利用活动。 鼓励原住居民依据保护规划要求在原址居住，改善生产生活条件，从事当地特色产业的生产经营等相关活动。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (67, 'FBMCLI.10.9191486', 'BIZ', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (68, 'FBMCLI.10.9191486', 'DIG', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (116, 68, 182, '第十四条', '…乡建设主管部门应当建立历史文化名城保护管理系统，对纳入保护名录的保护对象建立保护档案和相关数据库，记载保护对象历史、权属、测绘数据、利用情况、相关研究成果等信息，为单位和个人查阅信息、共享研究成果、开展保护利用提供便利。 市、县（市、区）人民政府有关部门以及乡镇人民政府、街道办事处应当共同做好历史文化名城保护相关信…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (69, 'FBMCLI.10.9191486', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (117, 69, 193, '第二十五条', '…条 任何单位和个人有权对破坏历史文化名城保护对象的行为进行劝阻、制止，或者向有关部门投诉、举报。 市、县（市、区）人民政府及其有关部门应当按照国家相关规定，对在历史文化名城保护工作中作出突出贡献的单位和个人给予表彰、奖励。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (70, 'FBMCLI.10.9191486', 'LIAB', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (118, 70, 195, '第二十七条', '第二十七条 违反本条例的行为，法律、法规已有法律责任规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (71, 'FBMCLI.10.9518646', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (119, 71, 199, '第三条', '…城区，范围为东至楚州大道，南至涧河，西至文渠、萧湖东南湖岸和里运河，北至翔宇大道； （二）历史文化街区，河下古镇历史文化街区范围为东至广济桥，南至里运河，西、北各至自然街巷；驸马巷—龙窝巷—上坂街历史文化街区范围为东至漕运广场商业街西边界，南至镇淮楼西路、局巷，西至驸马巷、楚州博物馆、勺湖社区居委会，北至西门大街； （三…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (120, 71, 207, '第十一条', '…外观形象、色彩、材料、工艺等方面延续传统格局、街巷肌理、地方特色和历史风貌。 在历史城区、历史文化街区、历史地段内，可以结合城市更新和人民美好生活需求，优化提升街区、地段的风貌和品质，合理增设公共开放空间，加大市政基础设施和公共服务设施供给。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (121, 71, 210, '第十四条', '第十四条 在历史文化街区内进行建设活动，应当符合保护规划确定的建设控制规定并遵守下列要求： （一）在核心保护范围内，除新建、扩建必要的基础设施、公共服务设施外，不得进行新建、扩建活动； （二）在核心保护范围内，拆除历史建筑以外的建（构）筑物或者…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (72, 'FBMCLI.10.9518646', 'BND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (122, 72, 210, '第十四条', '…史文化街区内进行建设活动，应当符合保护规划确定的建设控制规定并遵守下列要求： （一）在核心保护范围内，除新建、扩建必要的基础设施、公共服务设施外，不得进行新建、扩建活动； （二）在核心保护范围内，拆除历史建筑以外的建（构）筑物或者其他设施的，应当依法履行审批手续； （三）修建道路、地下工程以及其他市政公用设施的，应当…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (123, 72, 214, '第十八条', '第十八条 历史文化街区核心保护范围内，除历史建筑以外的房屋需要修缮的，应当落实保护规划的要求，保持房屋的高度、体量、外观形象、色彩等传统风貌。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (124, 72, 199, '第三条', '…和历史延续的河湖水系、道路等； （六）法律、法规规定的其他保护对象。 淮安国家历史文化名城保护范围内的不可移动文物、地下文物埋藏区、古树名木、非物质文化遗产等的保护，法律、法规另有规定的，还应当依照其规定执行。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (73, 'FBMCLI.10.9518646', 'RESP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (125, 73, 201, '第五条', '第五条 市人民政府负责淮安国家历史文化名城的保护工作，将其纳入国民经济和社会发展规划，提供政策支持，安排专项经费并列入财政预算。 市住房和城乡建设部门会同有关部门负责淮安国家历史文化名城保护规划的审查报批和监督实施等工作。 市自然资源和规…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (126, 73, 205, '第九条', '第九条 淮安国家历史文化名城保护名录应当按照保护对象分类载明名称、位置、形成时间、保护责任人等内容。国务院、省、市人民政府批准公布的保护对象，直接列入保护名录。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (127, 73, 213, '第十七条', '第十七条 历史建筑所有权人应当按照保护规划的要求负责历史建筑的维护和修缮，淮安区人民政府可以按照规定给予补助。 历史建筑所有权人有权从自然资源和规划、住房和城乡建设、文化广电和旅游（文物）等部门获得保护、修缮、利用等方面的信息和技术指导。 历史建…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (74, 'FBMCLI.10.9518646', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (75, 'FBMCLI.10.9518646', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (128, 75, 202, '第六条', '…立淮安国家历史文化名城保护工作推进机制，并履行下列职责： （一）落实淮安国家历史文化名城的保护规划，编制历史文化街区、历史地段保护规划； （二）组织开展保护对象普查，编制、公布保护名录并进行动态管理； （三）编制并实施年度保护传承利用相关项目、计划； （四）宣传、贯彻落实保护有关法律、法规； （五）开展保护传承利用调…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (129, 75, 201, '第五条', '…持，安排专项经费并列入财政预算。 市住房和城乡建设部门会同有关部门负责淮安国家历史文化名城保护规划的审查报批和监督实施等工作。 市自然资源和规划部门负责淮安国家历史文化名城的规划管理等工作。 市文化广电和旅游（文物）部门负责淮安国家历史文化名城保护范围内的文物和非物质文化遗产保护的监督管理等工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (130, 75, 203, '第七条', '…物、水利、交通、园林、消防以及法律等方面的专家组成国家历史文化名城保护专家咨询委员会，参与保护规划、保护名录、建设管理等重大议题和重要项目的评估论证，并提供相关工作建议。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (76, 'FBMCLI.10.9518646', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (77, 'FBMCLI.10.9518646', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (131, 77, 209, '第十三条', '…无法实行雨污分流的，雨污合流排入城市污水收集系统，不得排入河道。 （四）不得违反规划新建、改建、扩建建（构）筑物。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (132, 77, 210, '第十四条', '…建、扩建必要的基础设施、公共服务设施外，不得进行新建、扩建活动； （二）在核心保护范围内，拆除历史建筑以外的建（构）筑物或者其他设施的，应当依法履行审批手续； （三）修建道路、地下工程以及其他市政公用设施的，应当采取有效保护措施，不得损害保护对象； （四）设置户外广告、招牌、雨棚、连廊、环境卫生设施等外部设施或者…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (133, 77, 212, '第十六条', '第十六条 任何单位或者个人不得损坏或者擅自迁移、拆除历史建筑。 对历史建筑进行修缮维护、添加设施以及改变历史建筑的结构或者使用性质的，不得破坏历史建筑的历史特征、艺术特征、空间和风貌特色。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (78, 'FBMCLI.10.9518646', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (134, 78, 202, '第六条', '…外交流； （六）办理上级政府以及相关部门交办的保护事项。 淮安区人民政府应当将保护经费列入财政预算，明确所属部门、镇人民政府、街道办事处的保护职责，依法做好综合执法工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (135, 78, 201, '第五条', '…家历史文化名城的保护工作，将其纳入国民经济和社会发展规划，提供政策支持，安排专项经费并列入财政预算。 市住房和城乡建设部门会同有关部门负责淮安国家历史文化名城保护规划的审查报批和监督实施等工作。 市自然资源和规划部门负责淮安国家历史文化名城的规划管理等工作。 市文化广电和旅游（文物）部门负责淮安国家历史文化名城保护范…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (79, 'FBMCLI.10.9518646', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (136, 79, 204, '第八条', '第八条 鼓励、引导单位和个人通过捐赠、资助、投资、成立公益性组织、提供技术或者志愿服务等方式，依法参与淮安国家历史文化名城保护工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (137, 79, 213, '第十七条', '…建筑所有权人应当按照保护规划的要求负责历史建筑的维护和修缮，淮安区人民政府可以按照规定给予补助。 历史建筑所有权人有权从自然资源和规划、住房和城乡建设、文化广电和旅游（文物）等部门获得保护、修缮、利用等方面的信息和技术指导。 历史建筑有损毁危险，所有权人不具备维护和修缮能力的，淮安区人民政府应当采取措施进行保护和…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (138, 79, 217, '第二十一条', '第二十一条 市人民政府、淮安区人民政府应当建立淮安国家历史文化名城保护补偿制度，对因国家历史文化名城保护致使合法权益受到损害的单位和个人，依法给予补偿。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (80, 'FBMCLI.10.9518646', 'RES', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (81, 'FBMCLI.10.9518646', 'BIZ', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (139, 81, 199, '第三条', '…济桥，南至里运河，西、北各至自然街巷；驸马巷—龙窝巷—上坂街历史文化街区范围为东至漕运广场商业街西边界，南至镇淮楼西路、局巷，西至驸马巷、楚州博物馆、勺湖社区居委会，北至西门大街； （三）历史地段，老西门大街历史地段、双刀刘巷历史地段、太清观街历史地段、县东街历史地段、东岳庙历史地段、河北街—光明街历史地段等； …', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (140, 81, 216, '第二十条', '…统产业发展等功能。 鼓励社会力量合理利用历史资源发展符合保护要求的产业，从事符合产业布局的经营活动。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (82, 'FBMCLI.10.9518646', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (83, 'FBMCLI.10.9518646', 'SUP', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (84, 'FBMCLI.10.9518646', 'LIAB', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (85, 'FBMCLI.10.9191449', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、10 个相关用语，关联 17 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (141, 85, 225, '第二条', '…理和利用等活动。 本条例保护的重点是建瓯历史城区。保护的对象包括历史城区的整体格局与风貌、历史文化街区、历史地段、历史建筑、传统风貌建筑、不可移动文物、非物质文化遗产和法律、法规规定的其他保护对象。具体保护范围由建瓯历史文化名城保护规划确定公布。 前款涉及对象的保护，法律、法规另有规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (142, 85, 251, '第二十八条', '…（七）损毁非物质文化遗产组成部分的实物和场所； （八）法律、法规禁止的其他行为。 第二节 历史建筑的保护管理', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (143, 85, 245, '第二十二条', '…严格控制历史城区新建建筑高度。历史城区新建建筑高度应当根据保护规划要求实行分区控制。 各级文物保护单位、未定级不可移动文物、历史建筑、传统风貌建筑等保护类建筑相邻的新建建筑物的高度不得超过该保护类建筑物的高度。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (86, 'FBMCLI.10.9191449', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、3 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (144, 86, 225, '第二条', '…、历史建筑、传统风貌建筑、不可移动文物、非物质文化遗产和法律、法规规定的其他保护对象。具体保护范围由建瓯历史文化名城保护规划确定公布。 前款涉及对象的保护，法律、法规另有规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (145, 86, 235, '第十二条', '…建瓯市人民政府应当在保护对象被纳入保护名录的三个月内，在其显著位置设立相应的保护标志，明确保护范围和要求。 任何单位和个人都不得擅自设置、移动、涂改或者损毁保护标志。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (146, 86, 233, '第十条', '…行保护名录制度。 保护名录应当明确保护对象的名称、类型、地理位置、历史文化价值、保护级别、保护范围、责任单位等事项。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (87, 'FBMCLI.10.9191449', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 21 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (147, 87, 227, '第四条', '第四条 南平市人民政府及其有关主管部门应当加强对建瓯历史文化名城保护工作的指导和监督，并依法给予相关政策支持。 建瓯市人民政府负责对历史文化名城保护工作的领导，将历史文化名城保护工作纳入国民经济和社会发展规划，所需资金列入本级财政预算。 乡（镇）人民政府、街…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (148, 87, 228, '第五条', '…工作，研究解决工作中的重大问题。历史文化名城保护工作协调机构日常工作由建瓯市住房和城乡建设主管部门承担。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (149, 87, 229, '第六条', '第六条 建瓯市住房和城乡建设主管部门会同同级文化（文物）主管部门作为建瓯历史文化名城保护主管部门，负责历史文化名城保护管理工作。 建瓯市发展和改革、自然资源、生态环境、交通运输、城市管理、应急管理、市场监督管理、消防救援等有关部门按照各自职责，共同做好历史…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (88, 'FBMCLI.10.9191449', 'COORD', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (150, 88, 228, '第五条', '第五条 建瓯市人民政府成立历史文化名城保护工作协调机构，负责统筹协调、督促推进历史文化名城保护工作，研究解决工作中的重大问题。历史文化名城保护工作协调机构日常工作由建瓯市住房和城乡建设主管部门承担。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (89, 'FBMCLI.10.9191449', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、5 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (151, 89, 231, '第八条', '第八条 建瓯市人民政府应当依法组织编制历史文化名城保护规划，并纳入国土空间规划。 建瓯市城乡规划主管部门应当根据历史文化名城保护规划组织编制详细规划。 组织编制规划应当科学评估建瓯历史文化价值，确定保护目标和保护原则、内容、重点，明确保护策略和保护要求。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (152, 89, 225, '第二条', '…不可移动文物、非物质文化遗产和法律、法规规定的其他保护对象。具体保护范围由建瓯历史文化名城保护规划确定公布。 前款涉及对象的保护，法律、法规另有规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (153, 89, 232, '第九条', '第九条 建瓯市人民政府应当加强历史文化名城保护规划实施情况的监督检查，建立历史文化名城保护专项评估机制，每年对保护情况进行一次评估，每五年向同级人民代表大会常务委员会报告历史文化名城保护工作情况。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (90, 'FBMCLI.10.9191449', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (154, 90, 237, '第十四条', '第十四条 尚未纳入保护名录，建瓯市人民政府初步确认具有保护价值的，可以确定为预先保护对象，并自确定之日起七个工作日内向所有权人、使用权人发出预先保护通知，告知其应当采取的保护措施。 自预先保护通知送达之日起满一年，预先保护对象未纳入保护名录的，预先保护自行失效。 预先保护期间，任何单位和个人不得破坏预先…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (91, 'FBMCLI.10.9191449', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、5 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (155, 91, 254, '第三十一条', '…门批准，实施原址保护。 历史建筑因公共利益需要或者地质灾害等自然原因无法实施原址保护，必须迁移异地保护或者拆除的，应当依法报有关部门批准。 经批准拆除历史建筑的，建设单位应当做好标记，保存相关资料，在条件具备时复建。 本条规定的历史建筑原址保护、迁移、拆除所需费用，由建设单位列入建设工程预算。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (156, 91, 259, '第三十六条', '…、易爆和腐蚀性的物品； （三）擅自拆卸、转让历史建筑的构件； （四）擅自对历史建筑进行外部修缮装饰、添加设施以及改变历史建筑的结构或者使用性质； （五）擅自改变历史建筑原有的高度、体量、外观形象及色彩； （六）擅自迁移、拆除历史建筑； （七）其他损坏历史建筑的行为。 第四章 传承与利用', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (157, 91, 255, '第三十二条', '第三十二条 对历史建筑进行外部修缮装饰、添加设施以及改变历史建筑的结构或者使用性质的，应当将维护、修缮等方案报建瓯历史文化名城保护主管部门批准，依法办理相关手续。 承接历史建筑修缮工程的单位应当配备具有修缮技艺的技术工人。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (92, 'FBMCLI.10.9191449', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (158, 92, 227, '第四条', '…文化名城保护工作的领导，将历史文化名城保护工作纳入国民经济和社会发展规划，所需资金列入本级财政预算。 乡（镇）人民政府、街道办事处配合做好本辖区历史文化遗产保护的日常巡查报告等工作。 村（居）民委员会协助引导群众共同做好历史文化遗产保护工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (159, 92, 253, '第三十条', '…应当按照保护图则和修缮技术规范的要求对历史建筑进行维护、修缮和使用。 建瓯市人民政府可以从保护资金中对历史建筑的维护和修缮给予补助。 历史建筑有损毁危险，保护责任人不具备维护和修缮能力的，建瓯市人民政府应当采取保护措施。 国有历史建筑的保护责任人为其管理人或者使用人；非国有历史建筑的保护责任人为其所有权人、使用人或者…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (93, 'FBMCLI.10.9191449', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (160, 93, 230, '第七条', '…条例规定的行为进行劝阻、举报。有关部门应当对举报及时处理和反馈。 鼓励单位和个人通过捐赠、资助、投资、提供技术或者志愿服务等方式参与历史文化名城保护工作。 第二章 规划与名录', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (161, 93, 237, '第十四条', '…预先保护对象。因预先保护对有关单位或者个人的合法权益造成损失的，建瓯市人民政府应当依法给予补偿。 第三章 保护与管理 第一节 历史城区的保护管理', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (162, 93, 253, '第三十条', '…对历史建筑进行维护、修缮和使用。 建瓯市人民政府可以从保护资金中对历史建筑的维护和修缮给予补助。 历史建筑有损毁危险，保护责任人不具备维护和修缮能力的，建瓯市人民政府应当采取保护措施。 国有历史建筑的保护责任人为其管理人或者使用人；非国有历史建筑的保护责任人为其所有权人、使用人或者管理人。对保护责任人另有约定的，…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (94, 'FBMCLI.10.9191449', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (163, 94, 263, '第四十条', '第四十条 鼓励原住居民依据保护要求在原址居住，支持原住居民从事地方特色手工产业等生产经营活动，促进历史文化名城原有形态、生活方式的延续传承。 鼓励老字号原址、原貌保护。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (95, 'FBMCLI.10.9191449', 'BIZ', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (164, 95, 260, '第三十七条', '…支持各类历史文化遗产的合理利用和有序开放。建瓯市人民政府应当建立历史文化遗产传承利用的项目准入正面清单或者负面清单，明确鼓励、支持或者限制、禁止的项目。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (165, 95, 261, '第三十八条', '… 鼓励利用历史建筑开设博物馆、陈列馆、纪念馆、传统作坊或者开办特色民宿等与传统文化相协调的经营活动。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (166, 95, 263, '第四十条', '第四十条 鼓励原住居民依据保护要求在原址居住，支持原住居民从事地方特色手工产业等生产经营活动，促进历史文化名城原有形态、生活方式的延续传承。 鼓励老字号原址、原貌保护。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (96, 'FBMCLI.10.9191449', 'DIG', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (167, 96, 236, '第十三条', '…建瓯市历史文化名城保护主管部门应当会同同级城乡规划主管部门等，对纳入保护名录的保护对象开展数字化信息采集和测绘建档，建立历史文化名城保护数据库，提升监测管理水平。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (97, 'FBMCLI.10.9191449', 'SUP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (168, 97, 230, '第七条', '第七条 任何单位和个人都有依法保护历史文化名城的义务，有权对违反本条例规定的行为进行劝阻、举报。有关部门应当对举报及时处理和反馈。 鼓励单位和个人通过捐赠、资助、投资、提供技术或者志愿服务等方式参与历史文化名城保护工作。 第二章 规划与名录', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (98, 'FBMCLI.10.9191449', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (169, 98, 268, '第四十五条', '…特征的，由建瓯市城市管理部门责令限期恢复原状；造成严重后果的，对单位处五万元以上十万元以下罚款，对个人处一万元以上五万元以下罚款。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (170, 98, 269, '第四十六条', '…市城市管理部门责令停止违法行为、限期恢复原状；造成严重后果的，对单位处五万元以上十万元以下罚款，对个人处一万元以上五万元以下罚款。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (171, 98, 265, '第四十二条', '…件的保护对象免费向公众开放。 鼓励运用现代科学技术手段对保护对象进行展示和管理。 第五章 法律责任', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (99, 'FBMCLI.10.9476014', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 6 个核心用语、10 个相关用语，关联 19 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (172, 99, 282, '第十一条', '…含下列重点保护内容： （一）历史城区的传统格局、历史风貌； （二）兴化府、萝苜田、鱼牙顶等历史文化街区，东岩山、广化寺、莆禧古城等历史文化风貌区； （三）历史文化名镇、名村和传统村落； （四）历史建筑、传统风貌建筑，木兰陂、仙游文庙、南少林寺遗址等不可移动文物； （五）湄洲岛、九鲤湖等风景名胜区，自然保护区； （六）工业…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (173, 99, 273, '第二条', '…文化名城的规划、保护、利用和管理等活动，适用本条例。 历史文化名城的保护对象包括历史城区、历史文化街区、名镇、名村、传统村落、文物、历史建筑、传统风貌建筑、历史环境要素、传统地名、非物质文化遗产等。 法律、法规对保护对象的保护与管理另有规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (174, 99, 283, '第十二条', '…府应当在本条例实施之日起一年内建立历史文化名城保护名录，实施分级分类管理。 已经批准公布的历史文化街区、名镇、名村、传统村落和历史建筑、传统风貌建筑等直接列入保护名录。 其他拟由市、县（区）人民政府确定的保护对象，经保护对象主管部门征求利害关系人和社会公众意见、专家论证、社会公示等程序，由住房和城乡建设主管部门报同级人民…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (100, 'FBMCLI.10.9476014', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (175, 100, 287, '第十六条', '…当按照保护规划要求实施整体保护、系统保护、全面保护。 历史文化街区、名镇、名村、传统村落的保护范围包括核心保护范围、建设控制地带。除必要的基础设施和公共服务设施以外，核心保护范围内不得进行新建、扩建活动。在建设控制地带内的新建建（构）筑物，应当符合保护规划确定的建设控制要求。 历史文化街区、名镇、名村、传统村落实施成…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (176, 100, 288, '第十七条', '第十七条 市、县（区）人民政府应当在历史文化街区、名镇、名村、传统村落核心保护范围的主要出入口设置保护标志，并对历史建筑、传统风貌建筑以及其他保护对象设置保护标志。保护标志的样式和内容应当符合有关规范和要求，通过二维码等智能化形式向公众展示保护对象的相关信息，并归集至保护与管理信息平台。 任何单位和个…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (177, 100, 293, '第二十二条', '第二十二条 历史文化街区、名镇、名村、传统村落核心保护范围和历史建筑、传统风貌建筑内的消防设施、消防通道，应当按照有关消防技术标准和规范设置并明确消防安全责任人。确因客观条件无法按照标准和规范设置的，市、县（区）住房和城乡建设主管部门应当会同消防救援机构制定与保护要求相匹配的防…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (101, 'FBMCLI.10.9476014', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、6 个相关用语，关联 14 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (178, 101, 277, '第六条', '第六条 住房和城乡建设主管部门会同文化旅游主管部门负责历史文化名城、街区、名镇、名村、传统村落和历史建筑、传统风貌建筑保护与管理的具体工作。 文化旅游主管部门负责文物保护的监督管理和非物质文化遗产的保护、保存工作。 发展和改革、民族宗教、民政、财政、…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (179, 101, 290, '第十九条', '第十九条 历史城区、历史文化街区的保护责任人按照市、县（区）人民政府管辖权限确定，履行下列保护责任： （一）落实保护规划要求； （二）保持保护范围传统格局、历史风貌、空间尺度和历史环境要素的完整性； （三）改善优化公共服务、市政交通、城市安全等设施以及人居环境； …', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (180, 101, 276, '第五条', '第五条 市人民政府应当建立历史文化名城保护工作协调机构，负责统筹协调名城保护工作，建立完善名城保护工作考核机制，研究名城保护工作的重大事项。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (102, 'FBMCLI.10.9476014', 'COORD', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (181, 102, 275, '第四条', '…保护与管理工作，将历史文化名城保护纳入国民经济和社会发展规划，完善体制机制和政策保障，加强部门协同和区域协作。 乡（镇）人民政府、街道办事处负责本辖区内历史文化名城保护的日常巡查、宣传引导等具体工作。 村（居）民委员会协助做好历史文化名城保护相关工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (182, 102, 276, '第五条', '第五条 市人民政府应当建立历史文化名城保护工作协调机构，负责统筹协调名城保护工作，建立完善名城保护工作考核机制，研究名城保护工作的重大事项。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (103, 'FBMCLI.10.9476014', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (183, 103, 280, '第九条', '第九条 市人民政府负责组织编制市历史文化名城保护规划。 历史文化街区、名镇、名村、传统村落保护规划的编制，按照国家和省有关规定执行。 保护规划经依法批准后，作为实施保护、管理的依据，不得擅自修改。确需修改的，应当按照法定程序审批。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (184, 103, 281, '第十条', '第十条 编制历史文化名城、街区、名镇、名村、传统村落保护规划，应当体现“海滨邹鲁”“文献名邦”文脉传承，维护历史文化遗产的真实性、完整性，保持传统格局、历史风貌和空间尺度，保护与其相互依存的人文景观、自然景观和背景环境，加强建筑高度和建筑形态、景观视廊以及其他相关要素的管控、引导…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (185, 103, 287, '第十六条', '第十六条 历史城区应当按照保护规划要求实施整体保护、系统保护、全面保护。 历史文化街区、名镇、名村、传统村落的保护范围包括核心保护范围、建设控制地带。除必要的基础设施和公共服务设施以外，核心保护范围内不得进行新建、扩建活动。在建设控制地带内的新建建（构）…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (104, 'FBMCLI.10.9476014', 'PRE', 1, 2, 'low', 'machine_draft', '机器初编检出 1 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (186, 104, 289, '第十八条', '…护对象主管部门会同住房和城乡建设主管部门、文化旅游主管部门初步确认具有保护价值的，可以予以预先保护，并依法启动申报认定程序。确认具有保护价值的，列入保护名录；不具有保护价值的，及时通知相关单位和人员并解除预先保护措施。预先保护期间，任何单位和个人不得损坏或者擅自迁移、拆除预先保护对象，所在地乡（镇）人民政府、街道办事…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (105, 'FBMCLI.10.9476014', 'REPAIR', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (187, 105, 285, '第十四条', '…）人民政府应当按照保护规划要求对历史城区、历史文化街区、名镇、名村、传统村落开展环境整治和修缮维护，改善道路、供水、排水、排污、电力、消防等基础设施，完善周边停车场、游客服务中心等配套设施。 历史城区、历史文化街区、名镇、名村、传统村落保护范围内的电力、通信、供水、排水、燃气等管线应当按照规划依法迁移或者地下敷设…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (188, 105, 287, '第十六条', '…构）筑物，应当符合保护规划确定的建设控制要求。 历史文化街区、名镇、名村、传统村落实施成片修缮或者改造前，所在地的县（区）人民政府应当按照历史文化名城保护规划的要求编制实施方案，保障保护规划落实。 市住房和城乡建设主管部门应当组织制定历史建筑、传统风貌建筑保护修缮技术规范，加强对保护修缮的指导。对历史建筑进行外部…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (189, 105, 289, '第十八条', '…的，及时通知相关单位和人员并解除预先保护措施。预先保护期间，任何单位和个人不得损坏或者擅自迁移、拆除预先保护对象，所在地乡（镇）人民政府、街道办事处应当开展巡查监督。 紧急保护和预先保护管理办法，由市人民政府制定。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (106, 'FBMCLI.10.9476014', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (190, 106, 278, '第七条', '第七条 市、县（区）人民政府应当将历史文化名城保护资金列入本级财政预算，用于保护对象的普查认定、维护修缮、抢险利用以及相关的基础设施建设、人居环境改善等工作。 鼓励企业、事业单位、社会组织和个人通过捐赠、投资、志愿服务等方式参与历史文化名城保护。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (107, 'FBMCLI.10.9476014', 'COMP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (191, 107, 279, '第八条', '…保护工作中做出突出贡献的单位和个人，市、县（区）人民政府及其有关部门可以按照规定予以表彰和奖励。 第二章 保护规划和保护名录', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (192, 107, 291, '第二十条', '…给予统筹解决。 非国有历史建筑、传统风貌建筑的维护、修缮，市、县（区）人民政府可以给予资金补助。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (108, 'FBMCLI.10.9476014', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (193, 108, 296, '第二十五条', '…二十五条 历史文化街区、名镇、名村、传统村落和历史建筑、传统风貌建筑的保护和利用，应当保障原住居民的合法权益，保持传统生活习俗的延续性。 鼓励原住居民依据保护规划要求在原址居住，从事当地特色产业的生产经营等相关活动，以房屋、资金入股等多种形式参与保护利用，享有合理收益。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (109, 'FBMCLI.10.9476014', 'BIZ', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (194, 109, 294, '第二十三条', '第二十三条 市、县（区）人民政府应当对历史城区、历史文化街区、名镇、名村、传统村落进行业态策划和产业引导。支持发展文化旅游、非物质文化遗产保护传承等相关业态。 鼓励在符合保护要求的基础上，开设非遗展示中心、纪念馆、博物馆等场馆，展示名城的历史文化内涵。 市、县（区）人民政府应当通过政策引导、资金扶持等方式焕新…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (110, 'FBMCLI.10.9476014', 'DIG', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (195, 110, 286, '第十五条', '第十五条 市、县（区）人民政府应当建立历史文化名城保护与管理信息平台，运用数字化等新技术、新方法开展保护对象的信息采集和分析，实现数据高效归集、共享，提高保护与管理工作的智能化水平，并为公众查询提供便利。 第三章 风貌管控和保护措施', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (196, 110, 281, '第十条', '…、街区、名镇、名村等保护规划涉及空间管控要求的，应当纳入同级国土空间规划，并入国土空间基础信息平台统一管理。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (197, 110, 288, '第十七条', '…符合有关规范和要求，通过二维码等智能化形式向公众展示保护对象的相关信息，并归集至保护与管理信息平台。 任何单位和个人不得擅自设置、移动、涂改或者损毁保护标志。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (111, 'FBMCLI.10.9476014', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (198, 111, 279, '第八条', '第八条 任何单位和个人都有保护历史文化名城的义务，对破坏历史文化名城的行为有权进行劝阻、举报和投诉。相关主管部门接到举报或者投诉的，应当依法及时查处。 对在历史文化名城保护工作中做出突出贡献的单位和个人，市、县（区）人民政府及其有关部门可以按照规定予以表彰和奖励。 第二章 保护规划和保护名录', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (112, 'FBMCLI.10.9476014', 'LIAB', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (199, 112, 299, '第二十八条', '…技艺传承人和工匠培训，支持、引导高等院校、职业学校开设相关课程培养专业技术人才。 第五章 法律责任', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (200, 112, 300, '第二十九条', '第二十九条 违反本条例规定的行为，法律、法规已有法律责任规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (201, 112, 301, '第三十条', '…历史文化街区、名镇、名村、传统村落、历史建筑的保护标志的，对单位处以一万元以上五万元以下的罚款，对个人处以一千元以上一万元以下的罚款； （二）擅自设置、移动、涂改或者损毁传统风貌建筑的保护标志的，对单位处以一千元以上五千元以下的罚款，对个人处以五百元以上一千元以下的罚款。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (113, 'FBMCLI.10.8750700', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 6 个核心用语、9 个相关用语，关联 17 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (202, 113, 306, '第二条', '…名城保护规划确定并公布。 名城的保护对象包括历史城区，历史文化名镇、名村和传统村落，文物，历史建筑、传统风貌建筑，古树名木，非物质文化遗产等历史文化资源以及其他具有保护价值的对象。 前款涉及对象的保护，法律、法规另有规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (203, 113, 314, '第十条', '…山控城、坐西朝东、通山连水”的传统格局以及具备多时代特征的整体风貌； （二）尚书巷、红军街历史文化街区的历史街巷、空间尺度、景观环境和历史风貌； （三）青廉巷、后坊街等历史地段的传统风貌和地方特色； （四）其他需要保护的内容。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (204, 113, 338, '第三十四条', '第三十四条 鼓励利用历史文化街区和历史地段建设文化展示、传统居住、特色商业、休闲体验等特定功能区，完善城市功能，提升城市活力。 在符合保护要求，保持原有外观、结构、构件的基础上，鼓励采用功能置换、经营权转让、合作入股等形式，引入具备条件的组织和个人参与…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (114, 'FBMCLI.10.8750700', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、3 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (205, 114, 306, '第二条', '第二条 本条例适用于泰宁县（以下简称县）行政区域内名城的保护、利用等活动，具体保护范围由名城保护规划确定并公布。 名城的保护对象包括历史城区，历史文化名镇、名村和传统村落，文物，历史建筑、传统风貌建筑，古树名木，非物质文化遗产等历史文化资源以及其他具有保护价值的对象。 前款涉及对象的保护，法律、法规另有规…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (206, 114, 319, '第十五条', '第十五条 县名城保护管理机构应当在历史地段的主要出入口，设置统一样式的保护标志，标明保护范围。 任何组织或者个人不得擅自设置、移动、涂改或者损毁历史地段保护标志。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (207, 114, 330, '第二十六条', '第二十六条 县住房和城乡建设主管部门应当组织自然资源、文化旅游等部门开展名城保护范围内的历史建筑和传统风貌建筑等历史文化资源调查评估，提出历史建筑和传统风貌建筑保护名录初步名单，明确保护责任人，经专家论证、征求利害关系人和公众意见以及向社会公示等程序后，报县人民政府确定后公布。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (115, 'FBMCLI.10.8750700', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、6 个相关用语，关联 16 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (208, 115, 308, '第四条', '第四条 市人民政府及其有关主管部门负责指导和监督名城的保护工作，并依法给予相关政策支持。 县人民政府全面负责名城的保护工作，将其纳入县国民经济和社会发展规划，所需经费列入本级财政预算。 住房和城乡建设、文化旅游、发展和改革、城市管理、教育、民族宗教、公安…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (209, 115, 330, '第二十六条', '第二十六条 县住房和城乡建设主管部门应当组织自然资源、文化旅游等部门开展名城保护范围内的历史建筑和传统风貌建筑等历史文化资源调查评估，提出历史建筑和传统风貌建筑保护名录初步名单，明确保护责任人，经专家论证、征求利害关系人和公众意见以及向社会公示等程序后，报…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (210, 115, 332, '第二十八条', '…入保护名录，但可能具有保护价值的建（构）筑物，建设单位应当暂停施工，立即向县住房和城乡建设主管部门报告。县住房和城乡建设主管部门应当会同名城保护管理机构、文化旅游等相关部门及时勘验，在五个工作日内提出处理意见，同时书面告知所有权人、使用人或者管理人采取保护现场、设置标志等先予保护措施。 已采取先予保护措施的建（构）筑…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (116, 'FBMCLI.10.8750700', 'COORD', 1, 2, 'low', 'machine_draft', '机器初编检出 1 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (211, 116, 309, '第五条', '第五条 建立完善名城保护工作协调机制，统筹解决名城保护工作中的重大问题，具体工作由县名城保护管理机构负责，履行下列职责： （一）牵头组织编制名城保护利用专项规划，并研究制定实施方案； （二）会同有关部门编制名城保护专项资金计划； （三）组织开展名城日常保护…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (117, 'FBMCLI.10.8750700', 'PLAN', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (212, 117, 306, '第二条', '…二条 本条例适用于泰宁县（以下简称县）行政区域内名城的保护、利用等活动，具体保护范围由名城保护规划确定并公布。 名城的保护对象包括历史城区，历史文化名镇、名村和传统村落，文物，历史建筑、传统风貌建筑，古树名木，非物质文化遗产等历史文化资源以及其他具有保护价值的对象。 前款涉及对象的保护，法律、法规另有规定的，从其规定…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (213, 117, 317, '第十三条', '第十三条 在历史城区内开展的建设活动，应当符合名城保护规划的要求，不符合名城保护规划要求或者与传统格局和整体风貌不协调的建（构）筑物，应当依法逐步整治、改造。 对历史城区内建（构）筑物的高度、风格、空间尺度和色彩进行控制，建筑风格应当体现“杉阳明韵”特色，广场、人行道、传统街巷…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (214, 117, 318, '第十四条', '第十四条 县住房和城乡建设主管部门应当按照名城保护规划和历史文化街区保护规划，组织相关主管部门采取微改造方式增加历史文化街区、历史地段公共开放空间，补足配套公共基础设施和公共服务设施。 历史城区内公共基础设施和公共服务设施的建设和修缮应当遵循最小干扰原则，给水排水、电力通讯…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (118, 'FBMCLI.10.8750700', 'PRE', 1, 2, 'low', 'machine_draft', '机器初编检出 1 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (215, 118, 332, '第二十八条', '…在五个工作日内提出处理意见，同时书面告知所有权人、使用人或者管理人采取保护现场、设置标志等先予保护措施。 已采取先予保护措施的建（构）筑物，县住房和城乡建设主管部门应当在七个工作日内组织专家进行评审论证。确认具有保护价值的，列入保护名录；不具有保护价值的，在二个工作日内书面通知所有权人、使用人或者管理人解除先予保护措…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (119, 'FBMCLI.10.8750700', 'REPAIR', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (216, 119, 333, '第二十九条', '…原址保护的原则。因公共利益需要进行建设活动，对历史建筑和传统风貌建筑无法实施原址保护，必须迁移异地保护的，应当进行评估论证，广泛听取相关部门和公众意见，并依法报请批准。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (217, 119, 318, '第十四条', '…放空间，补足配套公共基础设施和公共服务设施。 历史城区内公共基础设施和公共服务设施的建设和修缮应当遵循最小干扰原则，给水排水、电力通讯、燃气等管网设施应当采用埋地敷设等方式处理。现有管网设施埋地敷设确有困难的，其布设应当规范有序。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (218, 119, 324, '第二十条', '…化旅游、水利、城市管理等相关主管部门加强古井的保护、治理和利用，结合街巷或者庭院空间，组织修缮重要的残破古井，逐步恢复古井的景观或者使用功能。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (120, 'FBMCLI.10.8750700', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (219, 120, 308, '第四条', '…持。 县人民政府全面负责名城的保护工作，将其纳入县国民经济和社会发展规划，所需经费列入本级财政预算。 住房和城乡建设、文化旅游、发展和改革、城市管理、教育、民族宗教、公安、民政、财政、人力资源和社会保障、自然资源、交通运输、水利、应急管理、市场监督管理、生态环境等主管部门按照各自职责共同做好名城保护工作。 有关乡（镇…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (220, 120, 309, '第五条', '…一）牵头组织编制名城保护利用专项规划，并研究制定实施方案； （二）会同有关部门编制名城保护专项资金计划； （三）组织开展名城日常保护、巡查，并配合开展名城保护执法； （四）组织开展名城文化品牌创建、文化交流和研究，参与编制利用名城资源的旅游规划； （五）指导街肆景观设计方案、保护与活化利用工程建设方案等； （六）收集…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (121, 'FBMCLI.10.8750700', 'COMP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (221, 121, 310, '第六条', '第六条 县人民政府应当建立名城保护补偿制度，因名城保护需要，组织和个人的合法权益遭受损失的，应当依法给予公平、合理的补偿。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (122, 'FBMCLI.10.8750700', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (222, 122, 336, '第三十二条', '第三十二条 原住居民可以依据名城保护规划、历史文化街区保护规划和保护要求在原址居住，从事地方特色产业的生产经营等相关活动，促进名城原有社会形态、生活方式的延续传承。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (123, 'FBMCLI.10.8750700', 'BIZ', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (223, 123, 337, '第三十三条', '第三十三条 历史城区的经营业态应当符合名城保护规划和历史文化街区保护规划。县住房和城乡建设主管部门应当会同市场监督管理等主管部门制定鼓励经营的项目目录，合理安排业态布局。 经营主体应当按照历史城区的业态布局，自觉服从管理，守法经营、文明经商、诚信服务…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (224, 123, 328, '第二十四条', '… 县名城保护管理机构应当组织开展历史城区城市管理、消防安全、社会治安、房屋安全、交通秩序、业态管控等的日常巡查工作，并将巡查工作纳入社区网格化管理范围。 第三章 建筑保护', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (225, 123, 338, '第三十四条', '第三十四条 鼓励利用历史文化街区和历史地段建设文化展示、传统居住、特色商业、休闲体验等特定功能区，完善城市功能，提升城市活力。 在符合保护要求，保持原有外观、结构、构件的基础上，鼓励采用功能置换、经营权转让、合作入股等形式，引入具备条件的组织和个人参与对历史建筑和传统风貌建筑的保护利用活动，提…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (124, 'FBMCLI.10.8750700', 'DIG', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (226, 124, 309, '第五条', '…护与活化利用工程建设方案等； （六）收集、整理名城的各类档案资料，建立名城档案数据库，实施数字化管理； （七）县人民政府赋予的其他职责。 县名城保护管理机构应当建立专家咨询机制，为保护中的重大事项提供评审、论证、咨询等服务。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (125, 'FBMCLI.10.8750700', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (227, 125, 312, '第八条', '第八条 任何组织和个人都有保护名城的义务，有权对破坏名城的行为进行劝阻和举报。有关主管部门应当向社会公布投诉举报方式，对接到的投诉、举报及时处理，并将处理结果告知投诉人、举报人。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (126, 'FBMCLI.10.8750700', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (228, 126, 343, '第三十九条', '…其他补救措施；有违法所得的，没收违法所得；造成严重后果的，对单位并处一万元以上五万元以下的罚款，对个人并处二千元以上一万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (229, 126, 340, '第三十六条', '…国主义教育基地，将爱国主义教育与名城保护相结合，传承红色文化，弘扬爱国主义精神。 第五章 法律责任', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (230, 126, 341, '第三十七条', '第三十七条 违反本条例规定的行为，法律、法规已有法律责任规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (127, 'FBMCLI.10.9602547', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、11 个相关用语，关联 23 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (231, 127, 355, '第八条', '…化名城保护范围涵盖本市全部行政区域，保护对象包括： （一）世界文化遗产； （二）历史城区，历史文化街区、名镇、名村，传统村落，历史地段； （三）不可移动文物、历史建筑、传统风貌建筑； （四）工业遗产、农业文化遗产、灌溉工程遗产； （五）非物质文化遗产、地名文化遗产； （六）国家、省、市批准公布的其他保护对象。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (232, 127, 356, '第九条', '…三）同安古城双溪环抱的银锭形整体结构，鹭江两岸向海而生的近代海岛历史城区空间格局； （四）历史文化街区、历史地段的空间尺度、历史街巷肌理和景观环境特色，传统村落的闽南古厝民居聚落特征； （五）以闽南红砖建筑、厦门装饰风格建筑、嘉庚建筑和骑楼建筑等为代表的历史建筑风貌； （六）闽南传统文化艺术、民俗风情、民间技艺等体现厦门…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (233, 127, 351, '第四条', '…全监督管理工作，负责统筹、协调、指导和监督传统村落保护工作。 城市管理行政执法部门负责行使历史文化街区、名镇、名村和历史地段、历史建筑、传统风貌建筑等历史文化名城保护管理方面法律、法规、规章规定的行政处罚权。 农业农村、应急、消防救援等相关部门按照职责分工，配合做好历史文化名城保护相关工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (128, 'FBMCLI.10.9602547', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (234, 128, 368, '第二十一条', '第二十一条 历史文化街区、名镇、名村和传统村落的保护范围包括核心保护范围和建设控制地带。 在核心保护范围内，除必要的基础设施和公共服务设施外，不得进行新建、扩建活动。新建、扩建必要的基础设施和公共服务设施的，按照相关规定报送审批。 在核心保护范围和建设控制地带内新建、改建、扩…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (235, 128, 355, '第八条', '第八条 厦门历史文化名城保护范围涵盖本市全部行政区域，保护对象包括： （一）世界文化遗产； （二）历史城区，历史文化街区、名镇、名村，传统村落，历史地段； （三）不可移动文物、历史建筑、传统风貌建筑； （四）工业遗产、农业文化遗产、灌溉工程遗产； （五…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (236, 128, 365, '第十八条', '第十八条 保护图则应当包括保护原则、保护内容、保护范围、保护价值、核心保护要素、保护要求、合理利用要求和消防安全要求等。 保护方案应当包括保护范围、保护要求、合理利用要求和消防安全要求等。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (129, 'FBMCLI.10.9602547', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 19 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (237, 129, 351, '第四条', '第四条 市自然资源和规划部门是全市历史文化名城保护的主管部门，负责组织、协调、指导、监督管理全市历史文化名城保护工作。 文化和旅游部门负责不可移动文物、非物质文化遗产的保护和监督管理工作。 住房和建设部门负责历史文化名城保护对象保护整修有关建设施工的工艺、质量、消防、安全监督管理…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (238, 129, 350, '第三条', '…关的规划编制、保护修缮、奖励补助等经费纳入财政预算。 区人民政府应当确定区历史文化名城保护主管部门，具体负责历史文化名城保护和监督管理相关工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (239, 129, 357, '第十条', '第十条 保护对象的认定和调整应当按照国家、省、市有关规定执行；未作规定的，保护对象主管部门应当制定保护对象认定、调整的标准和程序，经市人民政府批准后向社会公布并实施。 能够真实反映一定历史时期传统风貌和地方特色，且不属于历史文化街区、名镇、名村和传统村落的区域，由市自然资源和规划部门会同相关部门列入历史地段推…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (130, 'FBMCLI.10.9602547', 'COORD', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (240, 130, 360, '第十三条', '…管部门在历史文化名城保护工作中积极运用新技术、新方法，建立历史文化名城保护对象数据库，推进信息共享和数字化建设，为保护、修缮、管理、合理利用和公众查询等提供支持。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (241, 130, 374, '第二十七条', '…对安全状况予以标识并动态更新相关信息，与市自然资源和规划、文化和旅游、住房和建设等部门实现信息共享。 区人民政府发现前款规定的建（构）筑物有损毁危险的，应当及时通知其保护责任人按照相关规定履行修缮义务。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (131, 'FBMCLI.10.9602547', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 13 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (242, 131, 362, '第十五条', '第十五条 编制或者修改国土空间规划以及有关专项规划，应当充分考虑保护规划、保护图则和保护方案的要求。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (243, 131, 366, '第十九条', '第十九条 经依法批准的保护规划不得擅自修改；确需修改的，编制机关应当向原审批机关提出专题报告，经同意后，方可编制修改方案。修改后的保护规划应当按照原审批程序报送审批。 历史地段保护规划以及保护图则、保护方案不得擅自修改，确需修改的，应当经厦门历史文化…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (244, 131, 361, '第十四条', '第十四条 市人民政府负责组织编制厦门历史文化名城保护规划，报省人民政府批准。 市自然资源和规划部门负责组织编制历史地段保护规划和历史建筑保护图则（以下简称保护图则）、传统风貌建筑保护方案（以下简称保护方案），经厦门历史文化名城保护专家委员会论证通过后实施。 前款规定的保护规划…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (132, 'FBMCLI.10.9602547', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (133, 'FBMCLI.10.9602547', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 13 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (245, 133, 372, '第二十五条', '…风貌建筑的保护范围内，在不改变外观、梁架结构和保证安全且符合保护方案的前提下，可以进行外部修缮、内部装饰、添加设施，按照相关规定报送审批。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (246, 133, 368, '第二十一条', '…要的基础设施和公共服务设施的，按照相关规定报送审批。 在核心保护范围和建设控制地带内新建、改建、扩建建（构）筑物的，应当符合保护规划确定的建设控制要求，在高度、体量、色彩等方面，与核心保护范围内的传统格局、历史风貌相协调，不得对整体空间形态与景观环境构成破坏性影响。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (247, 133, 376, '第二十九条', '第二十九条 擅自拆除、迁移、破坏历史建筑、传统风貌建筑或者未按照规定维护、修缮、使用历史建筑、传统风貌建筑的，由区历史文化名城保护主管部门责令改正，督促限期恢复原状、采取保护措施或者补救措施。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (134, 'FBMCLI.10.9602547', 'FUND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (248, 134, 350, '第三条', '…级国民经济和社会发展规划，并将历史文化名城保护相关的规划编制、保护修缮、奖励补助等经费纳入财政预算。 区人民政府应当确定区历史文化名城保护主管部门，具体负责历史文化名城保护和监督管理相关工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (135, 'FBMCLI.10.9602547', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (249, 135, 350, '第三条', '…名城保护纳入本级国民经济和社会发展规划，并将历史文化名城保护相关的规划编制、保护修缮、奖励补助等经费纳入财政预算。 区人民政府应当确定区历史文化名城保护主管部门，具体负责历史文化名城保护和监督管理相关工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (250, 135, 354, '第七条', '…史文化名城保护公众参与制度，听取社会公众意见。 推广文物守护认领模式，鼓励社会公众以捐赠、资助、技术服务、志愿服务等方式参与历史文化名城保护。 在历史文化名城保护中有突出贡献或者做出显著成绩的保护责任人和其他组织、个人，由市、区人民政府给予表扬和奖励。 第二章 保护对象', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (251, 135, 377, '第三十条', '…原住居民生产生活或者导致其合法权益受损的，区人民政府应当依法采用住房保障、宅基地置换、经济补偿等方式予以安排。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (136, 'FBMCLI.10.9602547', 'RES', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (252, 136, 354, '第七条', '第七条 建立历史文化名城保护公众参与制度，听取社会公众意见。 推广文物守护认领模式，鼓励社会公众以捐赠、资助、技术服务、志愿服务等方式参与历史文化名城保护。 在历史文化名城保护中有突出贡献或者做出显著成绩的保护责任人和其他组织、个人，由市、区人民政府给予表…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (253, 136, 361, '第十四条', '…作为实施保护和管理的依据。 在保护规划编制过程中应当将保护规划草案进行公告，并采取论证会、听证会或者其他方式征求专家和社会公众的意见，公告时间不少于三十日。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (254, 136, 377, '第三十条', '…不能在保护范围内安排宅基地的，应当在保护规划中提出安置方案。 因历史文化名城保护需要，影响原住居民生产生活或者导致其合法权益受损的，区人民政府应当依法采用住房保障、宅基地置换、经济补偿等方式予以安排。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (137, 'FBMCLI.10.9602547', 'BIZ', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (255, 137, 384, '第三十七条', '…生产生活条件，发展多样化特色产业，适度开展旅游业、文化产业和传统手工业等与传统文化相协调的经营活动，促进原有生活方式延续传承。 鼓励社会运营主体建立历史文化名城保护资源平台，依法统筹招商和开展运营，通过产权转让、置换、委托管理、退租等方式，将历史文化街区、名镇、名村和传统村落、历史地段保护范围内的建（构）筑物或者低效…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (138, 'FBMCLI.10.9602547', 'DIG', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (256, 138, 360, '第十三条', '…史文化名城保护工作中积极运用新技术、新方法，建立历史文化名城保护对象数据库，推进信息共享和数字化建设，为保护、修缮、管理、合理利用和公众查询等提供支持。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (139, 'FBMCLI.10.9602547', 'SUP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (257, 139, 361, '第十四条', '…图则（以下简称保护图则）、传统风貌建筑保护方案（以下简称保护方案），经厦门历史文化名城保护专家委员会论证通过后实施。 前款规定的保护规划、保护图则、保护方案以及按照法律法规规定编制的其他保护规划，作为实施保护和管理的依据。 在保护规划编制过程中应当将保护规划草案进行公告，并采取论证会、听证会或者其他方式征求专家和社会公…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (258, 139, 352, '第五条', '第五条 市人民政府设立厦门历史文化名城保护专家委员会，参与历史文化名城保护对象的认定、调整、撤销和保护规划的评审以及其他历史文化名城保护相关事项的专业论证工作，为市、区人民政府及其有关部门决策提供咨询意见。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (259, 139, 357, '第十条', '…村落的区域，由市自然资源和规划部门会同相关部门列入历史地段推荐名单，经厦门历史文化名城保护专家委员会论证通过，报市人民政府批准后认定为历史地段，向社会公布。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (140, 'FBMCLI.10.9602547', 'LIAB', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (260, 140, 376, '第二十九条', '…貌建筑或者未按照规定维护、修缮、使用历史建筑、传统风貌建筑的，由区历史文化名城保护主管部门责令改正，督促限期恢复原状、采取保护措施或者补救措施。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (141, 'FBMCLI.10.9191487', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、10 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (261, 141, 392, '第二条', '…本条例适用于武冈历史文化名城的保护及其相关活动。 武冈历史文化名城保护的对象包括历史城区、历史文化街区、历史建筑和传统风貌建筑，文物古迹、传统村落，古树名木、历史河道、古码头、古井、古桥等历史环境要素，非物质文化遗产以及法律法规规定的其他保护对象。 法律法规对文物、传统村落、古树名木、非物质文化遗产等保护另有规定的，从其…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (262, 141, 397, '第七条', '第七条 历史文化街区包括西直街、木货街、穿城河、和合街、太平门等五个街区，其保护范围分为核心保护范围和建设控制地带，具体范围由武冈市人民政府根据保护规划划定并向社会公布。 武冈市人民政府应当保护历史文化街区原有风貌和空间尺度、视线廊道，控制…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (263, 141, 404, '第十四条', '…体办法由武冈市人民政府依法制定。 任何单位和个人不得擅自以危险房屋名义违法违规拆除或者改造历史文化街区、文物、历史建筑和传统风貌建筑。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (142, 'FBMCLI.10.9191487', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (264, 142, 397, '第七条', '第七条 历史文化街区包括西直街、木货街、穿城河、和合街、太平门等五个街区，其保护范围分为核心保护范围和建设控制地带，具体范围由武冈市人民政府根据保护规划划定并向社会公布。 武冈市人民政府应当保护历史文化街区原有风貌和空间尺度、视线廊道，控制街巷两侧建筑高度与界面连续性，严禁擅自拓宽或者缩小；保护街巷中的…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (265, 142, 399, '第九条', '…位的古城墙，包括墙体、城门及其遗址遗迹。 武冈市人民政府应当依法编制武冈城墙保护规划，公布保护范围和建设控制地带，建立含有保护范围、标志说明、记录档案、管理机构的档案资料，依法采取措施对城墙遗址、墙砖（石）及其它构件进行保护。按照武冈城墙保护规划完成修复的城墙墙体及其附属建筑纳入武冈城墙进行一体化保护管理。 任何单位…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (266, 142, 403, '第十三条', '第十三条 历史文化名城保护范围内的单位和个人应当落实消防安全责任，严格用火、用电、用气、用油管理，履行维护消防安全、保护消防设施、预防火灾、报告火警的义务。 历史城区内应当按照国家现行消防技术标准完善消防给水、消防车通道、消防通信等公共消防设施建设。…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (143, 'FBMCLI.10.9191487', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、7 个相关用语，关联 13 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (267, 143, 393, '第三条', '第三条 邵阳市人民政府及其相关主管部门应当加强对武冈历史文化名城保护的监督和指导；武冈市人民政府全面负责武冈历史文化名城保护工作。 武冈市建立完善党委领导、政府统筹、部门实施、公众参与的武冈历史文化名城保护工作协调机制，统筹解决保护工作中的重大问题。日常工作…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (268, 143, 398, '第八条', '…不可抗力灭失或者损毁、确已失去保护意义或者保护类型发生变化的，武冈市人民政府住房和城乡建设主管部门应当会同自然资源、文物主管部门、古城保护中心及时提出保护名录调整方案，征求有关方面意见，经依法报请批准后予以调整。 历史建筑的所有权人应当按照保护规划的要求，负责历史建筑的维护和修缮。对于无所有权人或者所有权人不明的历史…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (269, 143, 405, '第十五条', '…对武冈历史文化名城传统格局、历史风貌或者历史建筑构成破坏性影响的，由武冈市人民政府自然资源主管部门责令停止违法行为、限期恢复原状或者采取其他补救措施；有违法所得的，没收违法所得；逾期不恢复原状或者不采取其他补救措施的，可以指定有能力的单位代为恢复原状或者采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (144, 'FBMCLI.10.9191487', 'COORD', 1, 2, 'low', 'machine_draft', '机器初编检出 1 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (270, 144, 393, '第三条', '…保护工作。 武冈市建立完善党委领导、政府统筹、部门实施、公众参与的武冈历史文化名城保护工作协调机制，统筹解决保护工作中的重大问题。日常工作由武冈市古城保护与建设事务中心（以下简称古城保护中心）承担。 武冈市人民政府住房和城乡建设主管部门会同文物主管部门负责武冈历史文化名城保护及其监督管理工作，自然资源主管部门负责武冈…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (145, 'FBMCLI.10.9191487', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、3 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (271, 145, 399, '第九条', '…重点文物保护单位的古城墙，包括墙体、城门及其遗址遗迹。 武冈市人民政府应当依法编制武冈城墙保护规划，公布保护范围和建设控制地带，建立含有保护范围、标志说明、记录档案、管理机构的档案资料，依法采取措施对城墙遗址、墙砖（石）及其它构件进行保护。按照武冈城墙保护规划完成修复的城墙墙体及其附属建筑纳入武冈城墙进行一体化保护管…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (272, 145, 396, '第六条', '…北岸，西至武强路、西城墙一线，北至城壕路、同保路、解放路一线，具体范围由武冈市人民政府根据保护规划划定并向社会公布。 武冈市人民政府应当保护历史城区“两山环抱、资水绕城、渠水穿城、三城并置”的山水格局和城池格局，保护街巷格局，保护大炮台、小炮台、济川门、清渠门、庆成门、迎恩门等体现城池格局的标志物遗存。 在历史城区内…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (273, 145, 397, '第七条', '…、太平门等五个街区，其保护范围分为核心保护范围和建设控制地带，具体范围由武冈市人民政府根据保护规划划定并向社会公布。 武冈市人民政府应当保护历史文化街区原有风貌和空间尺度、视线廊道，控制街巷两侧建筑高度与界面连续性，严禁擅自拓宽或者缩小；保护街巷中的古树、古井、老院墙、传统路面铺装、绿化植被等历史环境要素；保护传统街…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (146, 'FBMCLI.10.9191487', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (147, 'FBMCLI.10.9191487', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (274, 147, 397, '第七条', '…工程规划许可证前，应当征求武冈市人民政府住房和城乡建设、文物主管部门、古城保护中心的意见。拆除历史建筑以外的建筑物、构筑物或者其他设施的，应当经武冈市人民政府自然资源主管部门批准，且在批准前应当征求武冈市人民政府住房和城乡建设、文物主管部门、古城保护中心的意见。在建设控制地带内新建、改建、扩建各类建筑物、构筑物，…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (275, 147, 398, '第八条', '…经依法报请批准后予以调整。 历史建筑的所有权人应当按照保护规划的要求，负责历史建筑的维护和修缮。对于无所有权人或者所有权人不明的历史建筑，由实际管理人或者使用人负责维护和修缮。历史建筑有损毁危险，其所有权人或者实际管理人、使用人不具备维护修缮能力的，武冈市人民政府应当给予必要的资金、技术等支持或者采取措施进行保护…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (276, 147, 405, '第十五条', '…条第四款规定，未经批准擅自拆除历史建筑以外的建筑物、构筑物或者其他设施，对历史建筑进行外部修缮装饰、添加设施以及改变历史建筑的结构或者使用性质，或者法律法规规定的其他行为对武冈历史文化名城传统格局、历史风貌或者历史建筑构成破坏性影响的，由武冈市人民政府自然资源主管部门责令停止违法行为、限期恢复原状或者采取其他补救…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (148, 'FBMCLI.10.9191487', 'FUND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (277, 148, 394, '第四条', '第四条 武冈市人民政府应当将武冈历史文化名城保护纳入国民经济和社会发展规划，所需资金列入财政预算。邵阳市人民政府根据武冈历史文化名城保护需要，给予资金支持。 鼓励单位和个人以捐赠、资助、投资、技术服务、志愿服务，或者以建筑物、构筑物出租、入股等方式，依法参与保护工作。 武冈市人民政府应当加强武冈历史文化名城保护的宣…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (149, 'FBMCLI.10.9191487', 'COMP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (278, 149, 394, '第四条', '…政预算。邵阳市人民政府根据武冈历史文化名城保护需要，给予资金支持。 鼓励单位和个人以捐赠、资助、投资、技术服务、志愿服务，或者以建筑物、构筑物出租、入股等方式，依法参与保护工作。 武冈市人民政府应当加强武冈历史文化名城保护的宣传教育，增强社会公众的保护意识。任何单位和个人都有权对武冈历史文化名城保护工作提出意见和…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (150, 'FBMCLI.10.9191487', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (279, 150, 393, '第三条', '…市人民政府全面负责武冈历史文化名城保护工作。 武冈市建立完善党委领导、政府统筹、部门实施、公众参与的武冈历史文化名城保护工作协调机制，统筹解决保护工作中的重大问题。日常工作由武冈市古城保护与建设事务中心（以下简称古城保护中心）承担。 武冈市人民政府住房和城乡建设主管部门会同文物主管部门负责武冈历史文化名城保护及其监督…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (151, 'FBMCLI.10.9191487', 'BIZ', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (280, 151, 397, '第七条', '…，应当符合保护规划确定的建设控制要求。 武冈市人民政府应当依法推进西直街等步行街建设，做好业态引导工作，推动历史文化街区文化旅游及相关产业发展；根据交通管理实际需要，依法对其实施交通管制。步行街管理办法由武冈市人民政府制定并向社会公布。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (152, 'FBMCLI.10.9191487', 'DIG', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (281, 152, 395, '第五条', '…性、社会生活的延续性。 武冈市人民政府应当根据武冈历史文化名城保护规划，建立保护对象名录和数字化档案，设立保护标志，明确保护管理措施和责任人，实行分区分级分类保护管理。 武冈市人民政府向本级人民代表大会常务委员会或者乡镇人民政府向本级人民代表大会报告城乡规划的实施情况时，应当将武冈历史文化名城保护情况作为重要内容。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (282, 152, 402, '第十二条', '…地方特色食品制作技艺开展调查、挖掘、整理工作，建立武冈卤菜、武冈铜鹅、米粉等制作技艺档案及数据库，鼓励和支持开设特色体验馆，弘扬地方特色饮食文化。 鼓励、支持单位和个人开设博物馆、陈列馆、纪念馆以及艺术品、民间藏品交易展示场馆等；拍摄影视作品、文艺创作、设立民间艺术传习等基地，发展特色文化创意产业；开展“六月六尝新…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (153, 'FBMCLI.10.9191487', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (283, 153, 394, '第四条', '…有权对武冈历史文化名城保护工作提出意见和建议，对破坏武冈历史文化名城的行为进行劝阻、投诉和举报，相关部门应当按照规定时限予以处理并反馈。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (154, 'FBMCLI.10.9191487', 'LIAB', 1, 2, 'low', 'machine_draft', '机器初编检出 4 个核心用语、6 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (284, 154, 405, '第十五条', '…上五万元以下的罚款；造成损失的，依法承担赔偿责任。 违反本条例规定的其他行为，法律法规已有法律责任规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (155, 'FBMCLI.10.7807668', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 8 个核心用语、12 个相关用语，关联 31 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (285, 155, 415, '第九条', '第九条 本市历史文化名城的保护对象包括历史城区、历史文化街区、历史文化名镇、历史文化名村、传统村落、历史地段、历史建筑、传统风貌建筑、地名文化遗产以及其他保护对象。 不可移动文物、古树名木、非物质文化遗产、工业遗产、农业文化遗产、灌溉工程遗产等保护、利用和管理，执行相关法律法规的…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (286, 155, 456, '第五十条', '…般是历史文化名城所在地的城市建成区中能体现其历史发展过程或某一发展时期风貌的地区； （二）历史文化街区，是指经省人民政府核定公布的保存文物特别丰富、历史建筑集中成片、能够较完整和真实地体现传统格局和历史风貌，并具有一定规模的区域； （三）历史文化名镇、历史文化名村，是指经省人民政府批准公布的保存文物特别丰富且具有重大历史…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (287, 155, 422, '第十六条', '…筑风貌管控，统筹安排各类市政管线和基础设施的铺设、安装，改善居住生活条件。 历史文化名城、历史文化街区、历史文化名镇、历史文化名村、传统村落、历史地段和历史建筑保护规划（图则）编制工作应当自保护对象确定公布之日起一年内完成。 历史建筑、传统风貌建筑确定公布后，所在地县（市、区）人民政府应当建立保护档案。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (156, 'FBMCLI.10.7807668', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、6 个相关用语，关联 16 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (288, 156, 422, '第十六条', '第十六条 编制保护规划应当按照有关规定划定核心保护范围、建设控制地带及环境协调区等历史文化保护线，提出保护和空间管控要求、保护措施等内容，以连线、成片方式实施整体保护、系统保护、全面保护，通过城市设计等方式加强历史文化遗产及周边地区空间整体形态和建筑风貌管控，统筹安排各类市…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (289, 156, 431, '第二十五条', '…文化名镇、历史文化名村、传统村落、历史地段内进行建设活动，应当遵守下列要求： （一）在核心保护范围内，不得进行新建、扩建活动。确需新建、扩建基础设施、公共服务设施的，建设单位应当提交符合保护规划要求的建设方案，并依法办理有关审批手续； （二）在核心保护范围内，拆除历史建筑以外的建筑物、构筑物或者其他设施的，建设单位应…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (290, 156, 436, '第三十条', '…筑物、构筑物在历史文化街区、历史文化名镇、历史文化名村、传统村落、历史地段等保护对象的核心保护范围或者建设控制地带内； （二）建筑物、构筑物已被认定为保护对象。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (157, 'FBMCLI.10.7807668', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 29 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (291, 157, 425, '第十九条', '…镇、街道的，所涉及镇人民政府、街道办事处均为保护责任人，保护工作由县（市、区）人民政府保护主管部门负责协调；保护对象跨县（市、区）的，所涉及县（市、区）人民政府均为保护责任人，保护工作由市人民政府保护主管部门负责协调。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (292, 157, 448, '第四十二条', '…定防火安全保障方案的； （七）未按照有关规定对列入名录的地名进行保护的； （八）未认真履行保护责任人责任，造成严重后果的； （九）其他玩忽职守、滥用职权、徇私舞弊的行为。 违反本条例规定，镇人民政府、街道办事处未开展巡查保护等日常管理工作的，由县（市、区）人民政府责令改正；情节严重的，对直接负责的主管人员和其他直接责任…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (293, 157, 412, '第六条', '第六条 市、县（市、区）人民政府自然资源和规划主管部门会同住房和城乡建设、文物主管部门（以下统称保护主管部门）对全市历史文化名城保护实施统一监督管理。 自然资源和规划主管部门负责本辖区历史城区、历史文化街区、历史地段、历史建筑、传统风貌建筑保护的监督管理。 住房和城乡建设主…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (158, 'FBMCLI.10.7807668', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (159, 'FBMCLI.10.7807668', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、5 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (294, 159, 448, '第四十二条', '…调整保护名录，或者未建立历史建筑、传统风貌建筑保护档案的； （三）未按照规定组织编制、修改保护规划、历史建筑保护图则的； （四）未将批准的保护规划主要内容予以公布的； （五）未按照保护规划的要求或者未按照法定程序履行审批职责的； （六）未依照有关标准或者程序设置消防设施、消防通道或者制定防火安全保障方案的； （七）未…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (295, 159, 422, '第十六条', '第十六条 编制保护规划应当按照有关规定划定核心保护范围、建设控制地带及环境协调区等历史文化保护线，提出保护和空间管控要求、保护措施等内容，以连线、成片方式实施整体保护、系统保护、全面保护，通过城市设计等方式加强历史文化遗产及周边地区空间整体形…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (296, 159, 423, '第十七条', '第十七条 历史文化名城、历史文化名镇保护规划应当分别纳入城市或者县、镇国土空间总体规划；历史文化街区、历史地段保护规划应当纳入详细规划；历史文化名村、传统村落保护规划应当纳入村庄规划，保护规划深度达到村庄规划深度的，可以作为该村的村庄规划。 涉及历史城区、历史文化…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (160, 'FBMCLI.10.7807668', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (161, 'FBMCLI.10.7807668', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (297, 161, 431, '第二十五条', '…单位应当提交符合保护规划要求的建设方案，并依法办理有关审批手续； （二）在核心保护范围内，拆除历史建筑以外的建筑物、构筑物或者其他设施的，建设单位应当提交符合保护规划要求的拆除方案，经所在地保护主管部门会同同级文物主管部门批准； （三）在核心保护范围内，对历史建筑以外的建筑物、构筑物或者其它设施进行更新改造的，建…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (298, 161, 433, '第二十七条', '…围内因公共利益需要进行建设活动，按照下列情形处理： （一）对历史建筑无法实施原址保护、必须迁移异地保护或者拆除的，按照有关法律法规的规定办理相关手续； （二）对传统风貌建筑翻建、改建或者拆除的，应当符合其所在的历史文化街区、历史文化名镇、名村保护规划或者历史地段保护规划的要求。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (299, 161, 432, '第二十六条', '…一）在建筑上刻划、涂污； （二）堆放易燃、易爆或者腐蚀性的物品，影响建筑安全； （三）擅自迁移、拆除历史建筑、传统风貌建筑； （四）擅自拆改传统风貌建筑结构，破坏传统风貌建筑原造型和风貌； （五）设置破坏或者影响建筑风貌的广告、标牌、招贴； （六）其他损坏建筑或者违反保护图则的行为。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (162, 'FBMCLI.10.7807668', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (300, 162, 410, '第四条', '…保护工作纳入国民经济和社会发展规划与国土空间规划，按照事权财权相一致原则将保护经费列入本级财政预算。 镇人民政府、街道办事处按照本条例规定履行本辖区内历史文化名城保护的相关职责，加强日常巡查，引导动员公众参与保护工作。 村民委员会、居民委员会应当配合做好历史文化名城保护工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (163, 'FBMCLI.10.7807668', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (301, 163, 414, '第八条', '第八条 鼓励社会力量通过捐赠、资助、投资、技术服务、志愿服务等方式，依法参与历史文化名城保护工作。 对在历史文化名城保护工作中做出突出贡献的单位和个人，市、县（市、区）人民政府应当按照国家有关规定给予表彰和奖励。 任何单位和个人都有保护历史文化名城的义务…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (302, 163, 421, '第十五条', '…保护对象得到及时保护的单位和个人，县（市、区）人民政府应当采取适当形式给予精神鼓励或者物质奖励。 第三章 保护措施', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (303, 163, 428, '第二十二条', '…时，有权从自然资源和规划、住房和城乡建设、文物等部门获得保护、修缮、利用等方面的信息、资金补助和技术指导。 转让、出租历史建筑、传统风貌建筑的，双方当事人应当在合同中约定保护及修缮义务，转让人、出租人应当将保护修缮要求告知受让人、承租人。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (164, 'FBMCLI.10.7807668', 'RES', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (304, 164, 445, '第三十九条', '…文化名镇、历史文化名村、传统村落、历史地段以及历史建筑、传统风貌建筑的保护与利用，应当保障原住居民的合法权益，调动原住居民参与保护的积极性。 鼓励原住居民从事当地特色产业的生产经营等相关活动，改善其生产生活条件，促进原有形态、生活方式的延续传承。原住居民可以采取房屋、资金入股等多种形式参与保护利用。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (305, 164, 410, '第四条', '…府、街道办事处按照本条例规定履行本辖区内历史文化名城保护的相关职责，加强日常巡查，引导动员公众参与保护工作。 村民委员会、居民委员会应当配合做好历史文化名城保护工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (306, 164, 411, '第五条', '…护规划等重大事项，其议事规则由同级人民政府制定。 历史文化名城保护委员会建立专家咨询机制和公众参与机制，历史文化名城保护重大事项的评审、论证应当邀请有关专家参加，并通过适当方式听取人大代表、政协委员和社会公众的意见。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (165, 'FBMCLI.10.7807668', 'BIZ', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (307, 165, 441, '第三十五条', '…产业孵化器、创新创业服务机构，以及共享办公空间； （四）市、县（市、区）人民政府鼓励的其他业态。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (166, 'FBMCLI.10.7807668', 'DIG', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (308, 166, 437, '第三十一条', '第三十一条 市自然资源和规划主管部门组织建立统一信息平台，对纳入保护名录的保护对象建立数据库，记载保护对象的历史、权属、测绘数据、利用情况、相关研究成果等信息；并将保护档案和相关数据信息通过互联网等平台依法向社会公开，为组织和个人查阅信息、共享研究成果、开展保护利用提供便利。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (309, 166, 435, '第二十九条', '…位置、建成时间和历史价值、保护责任人等内容，并可以根据实际需要翻译成外文。 标志物应当运用数字化手段，支持公众查询相关信息。 任何单位和个人不得冒用历史文化名城、历史文化名镇、历史文化名村和历史文化街区称号；不得擅自设置、移动、涂改或者损毁标志物。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (167, 'FBMCLI.10.7807668', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (310, 167, 414, '第八条', '…奖励。 任何单位和个人都有保护历史文化名城的义务，对破坏历史文化名城的行为有权制止、投诉、举报。有关部门接到投诉、举报，应当及时受理并组织核查、处理。 第二章 保护对象', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (168, 'FBMCLI.10.7807668', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (311, 168, 448, '第四十二条', '…反本条例规定，镇人民政府、街道办事处未开展巡查保护等日常管理工作的，由县（市、区）人民政府责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (312, 168, 449, '第四十三条', '…采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处五十万元以上一百万元以下罚款，对个人并处五万元以上十万元以下罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (313, 168, 451, '第四十五条', '…者采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处五万元以上十万元以下的罚款，对个人并处一万元以上五万元以下的罚款；造成损失的，依法承担赔偿责任： （一）拆除历史建筑以外的建筑物、构筑物或者其他设施的； （二）对历史建筑以外的建筑物、构筑物或者其它设施进行更新改造的。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (169, 'FBMCLI.10.9483232', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、12 个相关用语，关联 41 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (314, 169, 471, '第十四条', '…括下列内容： （一）世界文化遗产； （二）大遗址等不可移动文物； （三）历史城区； （四）历史文化街区、历史地段； （五）历史建筑、工业遗产、革命文化遗存； （六）历史文化名镇、名村、传统村落； （七）自然山水格局、历史轴线； （八）风景名胜区、农业文化遗产、灌溉工程遗产、历史文化线路； （九）古树名木、古井、古桥等历史…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (315, 169, 537, '第八十条', '第八十条 本条例下列用语的含义： （一）历史文化街区，是指经依法核定公布的保存文物特别丰富、历史建筑集中成片，能够较完整和真实地体现传统格局和历史风貌，并具有一定规模的区域。 （二）历史地段，是指经依法核定公布的能够真实反映西安一定历史时期传统风貌和民族、地方特色的区域。…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (316, 169, 511, '第五十四条', '第五十四条 在西安历史文化名城、历史文化街区、历史地段、历史文化名镇、名村保护范围内禁止进行下列活动： （一）开山、采石、开矿等破坏传统格局和历史风貌的活动； （二）占用或者破坏保护规划确定保留的园林绿地、河湖水系、道路、古树名木、古井、古桥以及其他历史环境要素等…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (170, 'FBMCLI.10.9483232', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、6 个相关用语，关联 13 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (317, 170, 516, '第五十九条', '第五十九条 市、区县人民政府应当在历史文化街区、历史地段、历史文化名镇、名村核心保护范围和传统村落保护范围的主要出入口以及历史建筑的显著位置设置保护标志。保护标志应当在保护对象批准公布后六个月内设置完毕。 保护标志的样式按照国家有关规定执行。没有规定的，由市人民政府结合西安历史文化特色对样式进行统一。保护标…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (318, 170, 483, '第二十六条', '…镇、名村的保护规划应当包括下列内容： （一）保护目标、原则、历史文化价值与特色、保护内容和保护范围； （二）保护措施、开发强度、建设控制要求和保障措施； （三）传统格局和历史风貌保护要求； （四）历史城区保护范围，历史文化街区、历史地段、历史文化名镇、名村的核心保护范围和建设控制地带； （五）基础设施、公共服务设施、…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (319, 170, 508, '第五十一条', '第五十一条 历史文化街区、历史地段、历史文化名镇、名村、传统村落核心保护范围内的建设活动，应当遵守下列规定： （一）除建设必要的基础设施、公共服务设施和人居环境改善项目外，不得进行新建、扩建活动； （二）修建道路、桥梁、地下工程等市政公用设施，应当采取有效的保护措施，不得损害保护对象； （三）设…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (171, 'FBMCLI.10.9483232', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、8 个相关用语，关联 39 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (320, 171, 488, '第三十一条', '…项的保护责任人由市人民政府向社会公布；第三项、第四项、第五项的保护责任人确定后，市资源规划主管部门应当告知其承担的保护责任。 市资源规划主管部门应当定期核查历史建筑的权属、管理以及使用情况；保护责任人发生变更的，应当及时调整。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (321, 171, 462, '第五条', '第五条 市人民政府负责西安历史文化名城的保护利用与管理工作，加强统筹协调和政策保障，完善体制机制，协调解决工作中的重大问题，并将保护利用工作纳入本市国民经济和社会发展规划。 区县人民政府负责本辖区西安历史文化名城保护对象的保护利用与管理工…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (322, 171, 463, '第六条', '第六条 市资源规划主管部门是西安历史文化名城保护的主管部门，会同市文物行政部门负责西安历史文化名城的保护利用和监督管理工作，并组织实施本条例。 资源规划主管部门负责历史城区、历史文化街区、历史地段、历史文化名镇、名村、历史建筑等的保护和规划管理工…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (172, 'FBMCLI.10.9483232', 'COORD', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (323, 172, 479, '第二十二条', '…建立相关数据库，录入保护对象的历史、权属、测绘信息、利用情况、相关研究成果等信息，推动实现信息共享。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (324, 172, 514, '第五十七条', '第五十七条 市人民政府应当建立自然山水格局、历史文化线路保护协调机制，加强工作联动和资源整合，组织市级有关部门、区县人民政府按照保护规划的要求，逐步修复相关的自然环境与文化景观，促进跨区域历史文化遗产的整体保护和系统展示。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (173, 'FBMCLI.10.9483232', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、7 个相关用语，关联 14 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (325, 173, 532, '第七十五条', '…主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任： （一）未依法履行保护规划、保护方案的编制、修改、公布职责的； （二）不履行监督管理职责，发现违法行为不查处的； （三）因保护不力，导致西安历史文化名城、历史文化街区、历史地段、历史文化名镇、名村、传统村落、历史建筑受到严重破坏、被列入濒危名单或…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (326, 173, 486, '第二十九条', '第二十九条 保护规划经依法批准后不得擅自修改；确需修改的，由原组织编制机关提出专题报告，经原审批机关同意后，方可进行修改。修改后的保护规划，应当按照原审批程序报送审批和备案。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (327, 173, 481, '第二十四条', '…护决定自行失效。 因先予保护对有关单位和个人的合法权益造成损失的，应当给予补偿。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (174, 'FBMCLI.10.9483232', 'PRE', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (328, 174, 481, '第二十四条', '第二十四条 任何单位和个人不得损坏、拆除先予保护对象。先予保护期间，先予保护对象所在地镇人民政府、街道办事处应当派员开展日常巡查和保护。 市资源规划主管部门应当会同市文物行政部门组织专家对先予保护对象开展价值评估，对于符合历史文化街区、历史地段认定标准的，督促区县人民…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (329, 174, 480, '第二十三条', '…荐之日起六十日内进行勘验、组织专家论证、征求利害关系人意见，认为具有保护价值的，应当确定为先予保护对象。 市资源规划主管部门应当自先予保护对象确定之日起五个工作日内发布先予保护公告，明确先予保护责任人，并书面告知其采取相应的保护措施。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (175, 'FBMCLI.10.9483232', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 19 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (330, 175, 505, '第四十八条', '第四十八条 因公共利益需要进行建设活动，对历史建筑无法实施原址保护、必须迁移异地保护或者拆除的，建设单位应当组织评估论证，广泛听取有关部门、专家和公众意见，制定迁移异地保护或者拆除方案，经市资源规划主管部门会同市住建、文物等部门审核后，报省住房和城乡建设主管部门会同省文物行政部门批准。迁移或者拆…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (331, 175, 506, '第四十九条', '…毒害性、腐蚀性物品； （三）拆卸、转让、损毁历史建筑的构件； （四）擅自对历史建筑进行外部修缮装饰、添加设施以及改变历史建筑的结构或者使用性质； （五）擅自迁移、拆除、重建历史建筑； （六）其他损害历史建筑的活动。 第四节 建设活动要求', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (332, 175, 492, '第三十五条', '…局、结构、样式和风貌等历史特征； （二）建立工业遗产档案，记录核心物项保护、遗存收集、维护修缮、发展利用、资助支持等情况； （三）在遗产区域内设立标志和相应的展陈设施； （四）保障核心物项安全，发现安全隐患或者损毁危险及时采取排除措施，核心物项损毁的及时修复，并按照管理权限向有关部门报告； （五）法律法规规定和有…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (176, 'FBMCLI.10.9483232', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (333, 176, 464, '第七条', '第七条 市人民政府应当完善西安历史文化名城保护资金筹集机制，通过预算安排以及其他合法渠道筹集保护资金。 市、区县人民政府应当根据实际情况安排西安历史文化名城保护所需资金，列入本级财政预算，并加强资金使用监管，提高资金使用效益。 西安历史文化名城保护资金主要用于保护对象的…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (177, 'FBMCLI.10.9483232', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (334, 177, 467, '第十条', '…在西安历史文化名城保护和文化传承工作中做出突出贡献的单位和个人，按照国家和本省有关规定给予奖励。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (335, 177, 481, '第二十四条', '…史建筑的，先予保护决定自行失效。 因先予保护对有关单位和个人的合法权益造成损失的，应当给予补偿。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (336, 177, 492, '第三十五条', '…风貌等历史特征； （二）建立工业遗产档案，记录核心物项保护、遗存收集、维护修缮、发展利用、资助支持等情况； （三）在遗产区域内设立标志和相应的展陈设施； （四）保障核心物项安全，发现安全隐患或者损毁危险及时采取排除措施，核心物项损毁的及时修复，并按照管理权限向有关部门报告； （五）法律法规规定和有关规定要求的其他…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (178, 'FBMCLI.10.9483232', 'RES', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (337, 178, 461, '第四条', '第四条 西安历史文化名城保护坚持和完善党委领导、政府负责、社会协同、公众参与的工作格局。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (338, 178, 465, '第八条', '第八条 市人民政府应当建立西安历史文化名城保护专家咨询和公众参与机制。西安历史文化名城保护重大事项，应当邀请有关专家论证，广泛听取公众意见。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (339, 178, 467, '第十条', '…进适用的保护利用技术和方法，提高保护利用的科学性。 鼓励建立公益性组织和志愿服务队伍，引导公众参与西安历史文化名城保护。资源规划主管部门应当对西安历史文化名城保护公益性活动和志愿服务活动进行指导和支持。 对在西安历史文化名城保护和文化传承工作中做出突出贡献的单位和个人，按照国家和本省有关规定给予奖励。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (179, 'FBMCLI.10.9483232', 'BIZ', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (340, 179, 528, '第七十一条', '…体、开放空间等，开发工业旅游项目，开展工业文化教育实践，培育工业设计、工艺美术、工业创意等业态。 利用历史建筑、工业遗产从事经营活动，应当配备必要的技防、物防、污染治理等设备设施。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (341, 179, 475, '第十八条', '…县学组成的传统格局，承载儒学、关学等优秀传统文化的文庙、书院、名人故居，传承书院文化的传统商业、生活习俗； （三）七贤庄历史文化街区重点保护以八路军西安办事处旧址、革命公园为代表的革命文化遗存，传承红色文化与革命精神的人文要素。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (342, 179, 529, '第七十二条', '…革命文化。 鼓励将革命文化遗存与其他保护对象整合，拓展展示线路和内容。展示利用应当防止过度商业化、娱乐化，杜绝低俗化。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (180, 'FBMCLI.10.9483232', 'DIG', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、5 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (343, 180, 479, '第二十二条', '…管部门，根据西安历史文化名城保护对象名录，通过采集、整理等方式，归集保护对象档案，建立相关数据库，录入保护对象的历史、权属、测绘信息、利用情况、相关研究成果等信息，推动实现信息共享。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (344, 180, 505, '第四十八条', '…国有历史建筑，应当征求保护责任人意见。 历史建筑拆除前，市资源规划主管部门应当建立历史建筑数字化模型，留存建筑照片、测绘图纸等资料，并依法向市城乡建设档案管理机构移交。 因历史建筑迁移拆卸的构件、部件，应当用于历史建筑的组装、还原；因历史建筑拆除拆卸的构件、部件，应当清点编号、妥善保存、合理利用。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (345, 180, 522, '第六十五条', '第六十五条 市人民政府应当组织保护对象主管部门建立统一的历史文化资源数字化展示平台，将西安历史文化名城保护对象名录、保护档案和相关数据信息向社会公开，为单位和个人查阅信息、共享研究成果、开展保护利用提供便利，依法应当保密的除外。 鼓励利用现代科技手段，实现保护对象的展示利用。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (181, 'FBMCLI.10.9483232', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (346, 181, 466, '第九条', '…护利用工作提出意见，对破坏保护对象以及其他违反历史文化名城保护相关法律法规的行为进行投诉、举报。 有关部门接到投诉、举报后应当按照规定时限处理并反馈。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (182, 'FBMCLI.10.9483232', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (347, 182, 532, '第七十五条', '…条例规定，市、区县人民政府及其有关部门，镇人民政府、街道办事处有下列行为之一的，由有权机关责令改正、通报批评；对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任： （一）未依法履行保护规划、保护方案的编制、修改、公布职责的； （二）不履行监督管理职责，发现违法行为不查处的； （三）因保…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (348, 182, 533, '第七十六条', '…定，在历史建筑上刻划、涂污的，由资源规划主管部门责令恢复原状或者采取其他补救措施，处五十元罚款。 违反本条例第四十九条第三项规定，拆卸、转让、损毁历史建筑的构件的，由资源规划主管部门责令停止违法行为、限期恢复原状或者采取其他补救措施；有违法所得的，没收违法所得；造成严重后果的，对单位并处五万元以上十万元以下罚款，…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (349, 182, 531, '第七十四条', '…高等院校、职业学校、职业培训机构以及其他社会力量开设相关课程，培养传统技艺人才。 第六章 法律责任', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (183, 'FBMCLI.10.7555523', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、11 个相关用语，关联 13 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (350, 183, 547, '第八条', '…城“一道双城六坊”为代表的历史城区的传统格局和历史风貌； （二）以北大街、羊市道等为代表的历史文化街区，以皇寺镇、沙河城镇等为代表的历史文化名镇，以英谈村、王硇村等为代表的历史文化名村，以神头村、樊下曹村等为代表的传统村落，以马市街等为代表的历史文化风貌区； （三）以邢窑遗址、普利寺塔、京杭大运河（邢台段）、平乡文庙大成…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (351, 183, 541, '第二条', '…史文化名城的规划、管理、保护和利用等活动，适用本条例。 历史文化名城的保护包括对历史城区、历史文化街区、历史文化名镇、历史文化名村、传统村落、历史文化风貌区、文物保护单位、不可移动文物、历史建筑、传统风貌建筑、近现代革命史迹、古树名木、传统地名和非物质文化遗产等的保护。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (352, 183, 573, '第三十四条', '…确定的团结东大街、开元路、新兴东大街、新华北路、新华南路等城市道路的围合区域。 本条例所称历史文化街区，是指国家有关部门或者省人民政府核定公布的，保存文物特别丰富、历史建筑集中成片、能够较完整和真实地体现传统格局和历史风貌，并具有一定规模的区域。 本条例所称历史建筑，是指市、县级人民政府确定公布的具有一定保护价值，能够反…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (184, 'FBMCLI.10.7555523', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (353, 184, 556, '第十七条', '…二）新发现地下遗址等重要历史文化遗存，确需修改的； （三）因自然灾害或者重大事故等，致使原保护范围内的历史文化遗存与环境发生重大变化的； （四）因行政区划调整，确需修改的； （五）因国家重大工程建设，确需修改的； （六）依法应当修改保护规划的其他情形。 修改后的保护规划，应当按法定程序重新报送审批和公布。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (354, 184, 563, '第二十四条', '…合保护规划确定的建设控制要求，严格控制建（构）筑物的形式、高度、体量、风格、色彩等，与核心保护范围的传统格局和历史风貌相协调。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (355, 184, 564, '第二十五条', '第二十五条 在历史文化名镇、名村、街区核心保护范围内，不得进行新建、扩建活动。但是，新建、扩建必要的基础设施和公共服务设施除外。 在历史文化名镇、名村、街区核心保护范围内，新建、扩建必要的基础设施和公共服务设施的，应当依法办理建设工程规划许可证或者乡村建设规划许可证。 …', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (185, 'FBMCLI.10.7555523', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 25 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (356, 185, 571, '第三十二条', '…人民政府有关部门、县级人民政府及其有关部门有下列行为之一的，由市、县级人民政府或者有关行政主管部门责令改正；对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任： （一）未按照法定程序或认定标准建立历史文化名城保护名录或者提出调整方案的； （二）未组织或者未按照法定程序组织编制、修改、公…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (357, 185, 544, '第五条', '第五条 市、县级人民政府住房和城乡建设主管部门牵头负责本行政区域内历史文化名城的保护和监督管理工作。 市、县级人民政府文化广电和旅游主管部门负责本行政区域内有关的文物、非物质文化遗产等保护工作。 城市管理、发展改革、工业和信息化、公安、民政、财政、自然资源和规划、林…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (358, 185, 545, '第六条', '第六条 支持市、县两级检察机关依法开展历史文化保护公益诉讼。 市、县级人民政府与同级人民检察院应当加强在检察公益诉讼中的协作配合，聚焦历史文化名城保护领域的典型违法行为，完善线索移送、会商研判、信息共享、联合专项、调查取证、专业支持、案例发布等工作机制，依法履行职责，共同维护国家利益和社会公共利益…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (186, 'FBMCLI.10.7555523', 'COORD', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (359, 186, 545, '第六条', '…检察公益诉讼中的协作配合，聚焦历史文化名城保护领域的典型违法行为，完善线索移送、会商研判、信息共享、联合专项、调查取证、专业支持、案例发布等工作机制，依法履行职责，共同维护国家利益和社会公共利益。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (187, 'FBMCLI.10.7555523', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、7 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (360, 187, 556, '第十七条', '第十七条 经依法批准的历史文化名城、名镇、名村、街区保护规划，不得擅自修改。有下列情形之一，确需修改保护规划的，保护规划的编制机关应当向原审批机关提出专题报告，经同意后方可编制修改方案： （一）保护规划所依据的法律、法规修改或者废止，影响原规划实施的； （二）新发现地下遗址等重要…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (361, 187, 571, '第三十二条', '…史文化名城保护名录或者提出调整方案的； （二）未组织或者未按照法定程序组织编制、修改、公布保护规划的； （三）未制定适应保护需要的道路、供（排）水、电力、环卫、消防等保障方案的； （四）未按照规定设置保护标志的； （五）未履行监督管理职责或者发现违法行为不予查处的； （六）其他违反历史文化名城保护有关法律、法规的行为…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (362, 187, 553, '第十四条', '第十四条 历史文化名城批准公布后，市人民政府应当依法组织编制历史文化名城保护规划。 历史文化名镇、名村批准公布后，所在地县级人民政府应当依法组织编制历史文化名镇、名村保护规划。 历史文化街区批准公布后，市人民政府及所在地县级人民政府应当依法组织编制历史文化街区保护规划。 保护规划应当自历史文化名城、…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (188, 'FBMCLI.10.7555523', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (189, 'FBMCLI.10.7555523', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (363, 189, 565, '第二十六条', '…筑，实行一般保护，其外部造型、色彩和内部特色构件不得改变。 任何单位和个人不得损坏或者擅自迁移、拆除历史建筑。确因公共利益需要进行建设活动，对历史建筑无法实施原址保护、必须迁移或者拆除的，应当按照有关规定报请批准。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (364, 189, 563, '第二十四条', '第二十四条 在历史文化名镇、名村、街区建设控制地带内进行新建、扩建、改建活动的，应当符合保护规划确定的建设控制要求，严格控制建（构）筑物的形式、高度、体量、风格、色彩等，与核心保护范围的传统格局和历史风貌相协调。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (365, 189, 560, '第二十一条', '第二十一条 历史建筑的保护责任人应当依法履行下列保护责任： （一）对历史建筑进行日常维护和修缮，保持原有历史建筑的高度、体量、内部结构、外观、色彩等特征； （二）保障历史建筑结构安全，确保消防、防灾等设施、设备、通道的正常使用，发现险情及时采取排险措施，并向有关部门报告； （三）转让、出租、出借历史建筑时，明确告…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (190, 'FBMCLI.10.7555523', 'FUND', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (366, 190, 546, '第七条', '…见、建议，对破坏历史文化名城的行为进行劝阻或者举报。 市、县级人民政府应当建立历史文化名城保护资金多渠道筹集机制，通过简化审批手续，制定优惠政策等方式，稳定市场预期，鼓励和支持各类经营主体持续投入历史文化名城保护工作。鼓励和支持企事业单位、志愿服务组织、社会公益组织和个人等社会力量通过提供技术服务、捐赠、资助等方式，…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (367, 190, 543, '第四条', '…史文化名城保护工作机制，健全政策制定、机构建立、监督管理、宣传教育等方面工作模式；合理安排保护资金，列入本级财政预算。 乡（镇）人民政府、街道办事处应当协助开展历史文化名城保护的具体工作。 村（居）民委员会应当配合做好历史文化名城保护的相关工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (368, 190, 561, '第二十二条', '第二十二条 市、县级人民政府可以从保护资金中对历史建筑的维护和修缮给予适当补助。 非国有历史建筑的保护责任人无法承担历史建筑维护和修缮费用的，可以向市、县级人民政府申请补助。 补助的具体办法由市、县级人民政府制定，并向社会公布。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (191, 'FBMCLI.10.7555523', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (369, 191, 546, '第七条', '…。鼓励和支持企事业单位、志愿服务组织、社会公益组织和个人等社会力量通过提供技术服务、捐赠、资助等方式，广泛参与历史文化名城保护工作。 第二章 保护名录', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (370, 191, 561, '第二十二条', '第二十二条 市、县级人民政府可以从保护资金中对历史建筑的维护和修缮给予适当补助。 非国有历史建筑的保护责任人无法承担历史建筑维护和修缮费用的，可以向市、县级人民政府申请补助。 补助的具体办法由市、县级人民政府制定，并向社会公布。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (192, 'FBMCLI.10.7555523', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (371, 192, 542, '第三条', '…保护与利用、保护与发展、保护与开发的关系，保持和延续历史文化名城的传统格局和历史风貌，保障原住居民的合法权益，维护历史文化遗产的真实性、完整性和延续性。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (193, 'FBMCLI.10.7555523', 'BIZ', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (372, 193, 566, '第二十七条', '…行展示和利用。 市、县级人民政府应当根据历史文化名城保护规划，建设文化展示、传统居住、特色商业、休闲体验等特定功能区，完善城市功能，提升城市活力。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (194, 'FBMCLI.10.7555523', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (195, 'FBMCLI.10.7555523', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (373, 195, 546, '第七条', '…名城的义务，有权对历史文化名城保护工作提出意见、建议，对破坏历史文化名城的行为进行劝阻或者举报。 市、县级人民政府应当建立历史文化名城保护资金多渠道筹集机制，通过简化审批手续，制定优惠政策等方式，稳定市场预期，鼓励和支持各类经营主体持续投入历史文化名城保护工作。鼓励和支持企事业单位、志愿服务组织、社会公益组织和个…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (374, 195, 557, '第十八条', '…规划的实施情况进行检查和评估，并通过政府门户网站、新闻媒体等向社会公布检查和评估情况，接受社会监督。对发现的问题，应当及时纠正、处理。 第四章 保护措施', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (196, 'FBMCLI.10.7555523', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (375, 196, 571, '第三十二条', '…有关部门、县级人民政府及其有关部门有下列行为之一的，由市、县级人民政府或者有关行政主管部门责令改正；对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任： （一）未按照法定程序或认定标准建立历史文化名城保护名录或者提出调整方案的； （二）未组织或者未按照法定程序组织编制、修改、公布保护规…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (376, 196, 572, '第三十三条', '…他补救措施；有违法所得的，没收违法所得；造成严重后果的，对单位处二十万元以上五十万元以下的罚款，对个人处十万元以上二十万元以下的罚款；造成损失的，依法承担赔偿责任。 第六章 附 则', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (377, 196, 560, '第二十一条', '…（三）转让、出租、出借历史建筑时，明确告知受让人、承租人、使用人对历史建筑的保护使用要求和法律责任； （四）法律、法规规定的其他保护责任。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (197, 'FBMCLI.10.8694652', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 6 个核心用语、10 个相关用语，关联 23 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (378, 197, 584, '第十条', '第十条 本市历史文化名城保护对象包括： （一）户部山、状元府等历史文化街区； （二）窑湾镇等历史文化名镇，历史文化名村，传统村落； （三）“彭城七里”徐州城市历史文脉； （四）京杭大运河徐州段； （五）城下城遗址等地下文物埋藏区； （六）汉楚王墓群、花厅遗址、云龙山摩崖造像等不可移动文物，徐州…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (379, 197, 597, '第二十三条', '第二十三条 历史文化街区、名镇、名村、传统村落的保护责任人应当履行下列保护责任： （一）落实保护规划要求； （二）保持保护范围内的传统格局、历史风貌、街巷肌理、空间尺度和历史环境要素的完整性和原真性； （三）改善优化公共服务、交通、安全等设施以…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (380, 197, 607, '第三十三条', '第三十三条 在历史文化街区、名镇、名村的核心保护范围和建设控制地带内进行建设活动，应当符合保护规划确定的建设控制要求，在布局、高度、体量、建筑风格、色调等方面与历史风貌相协调，不得破坏传统格局和历史风貌，并遵守下列要求： （一）在历史文化街区、名…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (198, 'FBMCLI.10.8694652', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、7 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (381, 198, 592, '第十八条', '…、名镇、名村、传统村落保护规划应当包括下列内容： （一）保护总体目标、保护原则、保护内容、保护范围； （二）保护措施和建设控制要求； （三）传统格局和历史风貌保护要求； （四）城乡历史文化保护传承要求； （五）历史城区界限，重点保护区范围，历史文化街区、名镇、名村的核心保护范围和建设控制地带； （六）保护规划分期实施…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (382, 198, 595, '第二十一条', '…、所在位置和建设年代； （二）核心价值要素； （三）保护类别、保护要求和利用建议； （四）保护范围、必要的建设活动控制要求和禁止使用功能； （五）法律、法规规定的其他内容。 编制历史建筑保护图则应当组织专家论证，在指导适用过程中应当适时进行专业评估，并将评估结果作为调整保护图则的依据。 第四章 保护措施', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (383, 198, 606, '第三十二条', '第三十二条 市、县（市、区）人民政府应当组织文化和旅游（文物）部门对历史文化名城保护范围内的地下文物埋藏情况进行勘查，将地下埋藏的文物分布较为集中、需要整体保护的区域依法报请划定为地下文物埋藏区，并予以公布。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (199, 'FBMCLI.10.8694652', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、6 个相关用语，关联 16 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (384, 199, 599, '第二十五条', '…安全，确保消防、防灾等设施和设备的正常使用，发现安全隐患、险情后及时采取排险措施，并向相关主管部门报告； （三）转让、出租、出借历史建筑时，书面告知受让人、承租人、使用人对历史建筑的保护要求； （四）法律、法规规定的其他保护责任。 因履行保护责任产生的维护、修缮费用，保护责任人可以申请适当补贴。具体补贴办法由市住房和…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (385, 199, 588, '第十四条', '…。 预先保护期为六个月，自发出预先保护通知书之日起开始计算。经认定列入保护名录的，保护对象主管部门应当及时告知所有权人、使用人。预先保护期届满未列入保护名录的，预先保护失效。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (386, 199, 590, '第十六条', '第十六条 保护对象主管部门应当按照各自职责，建立和维护保护对象数据库，采集、整理、录入相关信息，归集保护对象档案。保护对象档案主要包括反映保护对象的艺术特征、历史特征、年代和稀有程度、使用现状和权属变化情况的相关资料，修缮、装饰装修过程中形成的文…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (200, 'FBMCLI.10.8694652', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (201, 'FBMCLI.10.8694652', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、7 个相关用语，关联 14 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (387, 201, 591, '第十七条', '…人民政府应当自历史文化名城、街区、名镇、名村、传统村落批准公布之日起一年内组织编制完成相应保护规划，并依法报请批准。 编制历史文化名城、街区、名镇、名村、传统村落保护规划应当与国土空间规划相衔接，维护历史文化遗产的真实性、完整性，保护和延续传统格局、历史风貌和空间尺度，保护与其相互依存的人文景观、自然景观和背景环境，…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (388, 201, 593, '第十九条', '第十九条 经依法批准的历史文化名城、街区、名镇、名村、传统村落保护规划，不得擅自调整或者修改；确需调整或者修改的，保护规划的组织编制机关应当提出修改论证报告，向原审批机关提出申请，经同意后，方可编制修改方案。修改后的保护规划，应当按照原审批程序报送审批。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (389, 201, 616, '第四十二条', '…”徐州城市历史文脉的保护范围，组织编制城市文脉保护建设规划，保护建设规划应当与历史文化名城保护规划相衔接。 保护范围内新建建筑物、构筑物应当符合保护建设规划要求，并严格履行报批程序。既有建筑物、构筑物与历史风貌不相协调的应当按照保护建设规划依法逐步改造。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (202, 'FBMCLI.10.8694652', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (390, 202, 588, '第十四条', '… 市、县（市、区）人民政府应当将初步确认具有保护价值、尚未列入保护名录的历史文化资源确定为预先保护对象，自确定之日起十个工作日内向预先保护对象所有权人、使用人发出预先保护通知，并按照拟推荐保护对象对应类别书面告知其相关保护要求。所在地镇人民政府、街道办事处应当开展日常巡查。 预先保护期为六个月，自发出预先保护通知书之…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (203, 'FBMCLI.10.8694652', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (391, 203, 602, '第二十八条', '第二十八条 任何单位和个人不得损坏或者擅自迁移、拆除历史建筑。 建设工程选址，应当尽可能避开历史建筑；因特殊情况不能避开的，应当尽可能实施原址保护。对历史建筑实施原址保护的，建设单位应当事先确定保护措施，报市、县（市、区）自然资源和规划部门会同同级文化和旅游（文物）…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (392, 203, 600, '第二十六条', '第二十六条 历史建筑修缮应当严格遵守国家和地方相关技术规范、质量标准和保护图则的要求。 对历史建筑进行外部修缮装饰、添加设施以及改变历史建筑结构或者使用性质的，保护责任人应当制定修缮方案，明确修缮范围、方式、材料等，并依法办理相关审批手续。 历…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (393, 203, 633, '第五十九条', '第五十九条 违反本条例规定，损坏或者擅自迁移、拆除历史建筑的，由住房和城乡建设部门责令停止违法行为，限期恢复原状或者采取其他补救措施；逾期不恢复原状或者不采取其他补救措施的，住房和城乡建设部门可以指定有能力的单位代为恢复原状或者采取其他补救措施，所需费用由违法者承…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (204, 'FBMCLI.10.8694652', 'FUND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (394, 204, 623, '第四十九条', '第四十九条 市、县（市、区）人民政府应当将历史文化名城保护利用资金纳入本级财政预算，统筹现有历史文化名城保护传承相关领域各级财政资金，支持历史文化名城保护传承工作。 鼓励社会资本参与历史文化名城保护传承项目，拓宽历史文化名城保护传承投入渠道。市、县（市、区）人民政府应当通过制定政策措施、发布项目信息等…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (205, 'FBMCLI.10.8694652', 'COMP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (395, 205, 582, '第八条', '第八条 鼓励单位和个人通过捐赠、资助、投资、成立公益性组织、提供技术或者志愿服务等方式，依法参与历史文化名城保护工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (396, 205, 583, '第九条', '…当及时处理。 对在历史文化名城保护工作中做出突出贡献的单位和个人，按照国家和省有关规定给予奖励。 第二章 保护对象', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (206, 'FBMCLI.10.8694652', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (397, 206, 591, '第十七条', '…系统保护、全面保护。 保护规划草案应当依法予以公示，公示时间不少于三十日，可以采取论证会、听证会等方式征求有关部门、专家、利害关系人和社会公众意见。保护规划报送审批文件中应当附具意见采纳情况及理由；经过听证的，还应当附具听证笔录。 保护规划经批准后，按照法定程序公布。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (207, 'FBMCLI.10.8694652', 'BIZ', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (398, 207, 618, '第四十四条', '…、区）人民政府应当制定产业引导扶持政策，调整优化历史文化街区、名镇等历史文化遗产集中区域的业态布局，鼓励开展具有地方特色的生产经营活动，通过扶持和培育老字号、非物质文化遗产代表项目，引入文化艺术机构、大师和名人工作室，植入创新服务机构、共享办公空间等，促进历史文化街区、名镇保护与文化、旅游业的融合发展。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (399, 207, 612, '第三十八条', '…八条 市、县（市、区）人民政府应当遵循保护为主、适度利用的原则，注重保护整体风貌，注重管控商业开发强度，合理增设公共开放空间，采用渐进式微改造的方式统筹推进历史文化名城的合理利用。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (400, 207, 615, '第四十一条', '…府应当统筹推进“彭城七里”徐州城市历史文脉的保护利用，深入挖掘历史内涵，优化功能布局，引导业态调整，完善公共服务设施，提升环境品质，构建城市历史文脉保护传承利用体系，打造纵贯主城区南北文化轴。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (208, 'FBMCLI.10.8694652', 'DIG', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (401, 208, 590, '第十六条', '第十六条 保护对象主管部门应当按照各自职责，建立和维护保护对象数据库，采集、整理、录入相关信息，归集保护对象档案。保护对象档案主要包括反映保护对象的艺术特征、历史特征、年代和稀有程度、使用现状和权属变化情况的相关资料，修缮、装饰装修过程中形成的文字、图纸、图片、影像等资料，测绘信息记录等…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (402, 208, 627, '第五十三条', '第五十三条 市、县（市、区）人民政府应当建立历史文化名城保护工作数字化信息平台，将各类历史文化名城保护要素信息纳入信息平台并动态维护，实现互联互通、数据共享。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (209, 'FBMCLI.10.8694652', 'SUP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (403, 209, 583, '第九条', '第九条 任何单位和个人都有保护历史文化名城的义务，有权对破坏历史文化名城的行为进行劝阻、举报。有关部门接到举报后，应当及时处理。 对在历史文化名城保护工作中做出突出贡献的单位和个人，按照国家和省有关规定给予奖励。 第二章 保护对象', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (210, 'FBMCLI.10.8694652', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (404, 210, 633, '第五十九条', '…者采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位处二十万元以上五十万元以下罚款，对个人处十万元以上二十万元以下罚款。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (405, 210, 630, '第五十六条', '…可以依法提起公益诉讼，市、县（市、区）人民政府及其相关部门应当予以支持或者配合。 第七章 法律责任', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (406, 210, 632, '第五十八条', '… 违反本条例规定，损毁历史建筑保护标志的，由住房和城乡建设部门给予警告，可以并处五百元以下罚款。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (211, 'FBMCLI.10.9474334', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 6 个核心用语、9 个相关用语，关联 12 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (407, 211, 645, '第九条', '第九条 名城保护对象包括： （一）旧县历史文化街区、御城历史文化街区； （二）河西历史文化名镇； （三）大回村、克呆村等传统村落； （四）秀山古建筑群、通海文庙、聚奎阁等文物保护单位，以及尚未核定公布为文物保护单位的不可移动文物； （五）周氏宗祠、曾家大院等历史建筑； …', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (408, 211, 648, '第十二条', '第十二条 历史文化街区、历史文化名镇、传统村落的保护责任人应当履行下列保护责任： （一）保持传统格局、历史风貌、特色装饰、空间尺度、主要景观视廊和历史环境要素的完整性； （二）保障保护对象的安全，确保防灾、消防等公共设施、设备正常使用； （三…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (409, 211, 643, '第七条', '第七条 县人民政府应当依法组织编制名城、历史文化街区、历史文化名镇保护规划（以下简称保护规划）。 保护规划编制应当保持传统格局、历史风貌，加强建筑高度、形态和景观视廊的管控，符合国土空间总体规划，并作为专项规划纳入国土空间规划体系。其他专项规划涉及名城保护内容的，应当与保…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (212, 'FBMCLI.10.9474334', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、3 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (410, 212, 644, '第八条', '第八条 通海古城、河西历史文化名镇的保护范围划分为核心保护区、建设控制区、环境协调区，具体范围由县人民政府根据经依法批准的保护规划划定并公布。县人民政府应当在核心保护区的主要出入口设置标志牌。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (411, 212, 648, '第十二条', '…防等公共设施、设备正常使用； （三）开展日常巡查，发现危害行为及时制止、处理； （四）保持保护范围内环境的整洁、美观； （五）法律、法规规定的其他保护责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (412, 212, 651, '第十五条', '第十五条 在名城保护范围内进行建设活动，应当符合保护规划的要求，体现当地建筑特色，尽可能采用传统工艺、传统材料，不得损害历史文化遗产的真实性和完整性，不得对其传统格局、街巷肌理和传统风貌构成破坏性影响，并遵守下列规定： （一）核心保护区内，除必…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (213, 'FBMCLI.10.9474334', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (413, 213, 641, '第五条', '第五条 县人民政府住房城乡建设主管部门会同文化和旅游、综合行政执法部门负责名城保护管理和监督工作。 发展改革、公安、财政、自然资源、生态环境、农业农村、林草、应急管理、防震减灾等有关部门和消防救援机构按照各自职责，做好名城保护的相关工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (414, 213, 649, '第十三条', '…、消防设施设备的正常使用，发现安全隐患或者险情及时采取排险措施，并向县人民政府住房城乡建设主管部门报告； （二）进行日常维护和修缮，保持原有建筑的高度、体量、外观形象、色彩等传统风貌和院落结构； （三）转让、出租、出借历史建筑的，应当与受让人、承租人、使用人签订书面协议，约定双方的保护责任。 历史建筑的修缮，应当按照…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (415, 213, 640, '第四条', '第四条 市人民政府应当加强对名城保护工作的领导，统筹协调和研究解决名城保护的重大事项和重大问题，相关保护资金列入本级财政预算。 通海县（以下简称县）人民政府负责名城的保护工作，将名城保护纳入国民经济和社会发展规划，建立和完善保护机制，所需…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (214, 'FBMCLI.10.9474334', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (215, 'FBMCLI.10.9474334', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、7 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (416, 215, 643, '第七条', '第七条 县人民政府应当依法组织编制名城、历史文化街区、历史文化名镇保护规划（以下简称保护规划）。 保护规划编制应当保持传统格局、历史风貌，加强建筑高度、形态和景观视廊的管控，符合国土空间总体规划，并作为专项规划纳入国土空间规划体系。其他专项规划涉及名城保护内容的，应当与保护规划相衔接。 经依法…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (417, 215, 644, '第八条', '…镇的保护范围划分为核心保护区、建设控制区、环境协调区，具体范围由县人民政府根据经依法批准的保护规划划定并公布。县人民政府应当在核心保护区的主要出入口设置标志牌。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (418, 215, 657, '第二十一条', '第二十一条 县人民政府应当统筹推进保护规划的组织实施，定期对保护规划实施情况进行监督检查，对名城保护状况进行评估，发现问题及时纠正、处理。 县人民政府住房城乡建设、自然资源、文化和旅游、综合行政执法等部门及乡（镇）人民政府、街道办事处应当严格执行保护规划，加强对…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (216, 'FBMCLI.10.9474334', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (419, 216, 645, '第九条', '…（三）大回村、克呆村等传统村落； （四）秀山古建筑群、通海文庙、聚奎阁等文物保护单位，以及尚未核定公布为文物保护单位的不可移动文物； （五）周氏宗祠、曾家大院等历史建筑； （六）马克昌故居、郑开文故居等名人故（旧）居； （七）烈士陵园、张盾烈士墓等革命遗址； （八）以木城山遗址、兴义遗址等为代表的各个历史时期有价值的历史…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (217, 'FBMCLI.10.9474334', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (420, 217, 649, '第十三条', '…患或者险情及时采取排险措施，并向县人民政府住房城乡建设主管部门报告； （二）进行日常维护和修缮，保持原有建筑的高度、体量、外观形象、色彩等传统风貌和院落结构； （三）转让、出租、出借历史建筑的，应当与受让人、承租人、使用人签订书面协议，约定双方的保护责任。 历史建筑的修缮，应当按照批准的方案进行施工，不得擅自改变…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (421, 217, 651, '第十五条', '…内，除必要的基础设施和公共服务设施以外，不得进行新建、扩建活动。 （二）建设控制区内新建、改建、扩建建筑物、构筑物的，应当符合保护规划确定的建设控制要求，建筑物、构筑物的形式、高度、体量、风格、色彩等，与核心保护区的传统格局和历史风貌相协调。 （三）环境协调区内进行建设活动的，应当与建设控制区风貌、特色相协调，不…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (422, 217, 653, '第十七条', '…筑物或者其他设施； （五）破坏原有建筑风格、景观、视廊、环境的整体性； （六）损坏或者擅自迁移、拆除历史建筑； （七）拆卸、转让历史建筑的门、窗、牌、匾、坊以及其他装饰构件； （八）在历史建筑上刻划、涂污； （九）损坏、挪用或者擅自拆除、停用消防设施、器材的； （十）法律、法规禁止的其他行为。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (218, 'FBMCLI.10.9474334', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (423, 218, 640, '第四条', '…人民政府应当加强对名城保护工作的领导，统筹协调和研究解决名城保护的重大事项和重大问题，相关保护资金列入本级财政预算。 通海县（以下简称县）人民政府负责名城的保护工作，将名城保护纳入国民经济和社会发展规划，建立和完善保护机制，所需保护资金列入本级财政预算。 乡（镇）人民政府、街道办事处负责本辖区名城保护的日常工作，建立…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (219, 'FBMCLI.10.9474334', 'COMP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (424, 219, 642, '第六条', '…化的传承和展示，普及保护知识，增强公众保护意识。 鼓励企业事业单位、社会团体和个人以捐赠、资助、志愿服务等方式，参与名城的保护和利用。 任何单位和个人都有权对名城保护提出意见和建议，对破坏名城的行为进行劝阻、投诉和举报。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (220, 'FBMCLI.10.9474334', 'RES', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (221, 'FBMCLI.10.9474334', 'BIZ', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (222, 'FBMCLI.10.9474334', 'DIG', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (425, 222, 656, '第二十条', '第二十条 县人民政府应当建设名城保护数字化动态监测系统，在名城保护范围内重点保护区域、重点保护对象配备相关设施设备，提升消防、安防、智能巡查、数据监测、信息反馈、为民服务等智慧化管理水平。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (223, 'FBMCLI.10.9474334', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (426, 223, 642, '第六条', '…护和利用。 任何单位和个人都有权对名城保护提出意见和建议，对破坏名城的行为进行劝阻、投诉和举报。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (224, 'FBMCLI.10.9474334', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (427, 224, 663, '第二十七条', '…采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处5万元以上10万元以下的罚款，对个人并处1万元以上5万元以下的罚款；造成损失的，依法承担赔偿责任； （二）违反第十八条第一项至第三项规定的，由县人民政府综合行政执法部门责令限期改正，恢复原状；逾期不改正的，由有关行政执法部门依法拆除。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (428, 224, 664, '第二十八条', '第二十八条 违反本条例规定的其他行为，法律、法规已有法律责任规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (225, 'FBMCLI.10.9277156', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 6 个核心用语、10 个相关用语，关联 25 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (429, 225, 676, '第十一条', '…度及传统风貌，城湖之间、重要公共建筑与自然山体之间，街巷与楼庙塔亭之间的景观视廊。 （二）历史文化街区。包括洞庭南路历史文化街区和陆城南北正街历史文化街区。重点保护重要城市轴线、城垣形制、历史街巷、文物保护单位、历史建筑、非物质文化遗产、重要公共建筑、景观视廊、历史环境要素等。洞庭南路历史文化街区范围为西临洞庭湖景区，东…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (430, 225, 675, '第十条', '第十条 历史文化名城保护对象包括历史城区、历史文化街区、历史风貌保护区、文物保护单位、历史建筑、非物质文化遗产、古树名木及法律、法规规定的其他保护对象。 市人民政府应当建立保护名录，载明保护对象的名称、权属、位置、类型、保护等级、历史沿革和历史价值等内容，并向社会公布。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (431, 225, 680, '第十五条', '第十五条 市人民政府负责组织编制本市历史文化名城、历史文化街区、历史风貌保护区保护规划等工作，区人民政府负责组织编制历史建筑保护规划和历史建筑修缮方案等工作。 编制城市规划应当符合历史文化名城保护的要求，保持、延续城市传统格局和历史风貌，维护历史文化遗产的真实性和完整性。 历史文化…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (226, 'FBMCLI.10.9277156', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (432, 226, 685, '第二十条', '第二十条 历史文化街区应当划定核心保护范围和建设控制地带。核心保护范围内，除确需建造的基础设施和公共服务设施外，不得进行新建、扩建活动。新建、扩建的基础设施和公共服务设施建筑层数不得超过两层，檐口高度不得超过七米。建设控制地带范围内的建筑，层数不得超过三层，檐口…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (433, 226, 684, '第十九条', '第十九条 历史城区的保护应当坚持“整体控制，重点保护”的原则。依照保护规划划定保护范围，标示古城廓遗址；严格保护历史城区周边金鹗山、赶山、月山、君山、洞庭湖、南湖等山水景观要素，重点保护岳阳楼、洞庭湖构成的“楼湖大观”；禁止在九华山、火庙山、文庙山、白鹤山取土等破坏山体风貌的行为；保护历史城区“一水四山，…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (434, 226, 682, '第十七条', '第十七条 在历史文化名城保护范围内进行下列活动，应当制订保护方案，经市住房和城乡建设部门会同文物主管部门批准，并依照有关法律、法规的规定办理相关手续： （一）改变园林绿地、河湖水系等自然状态的活动； （二）在核心保护范围内进行影视摄制、举办大型群众性活…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (227, 'FBMCLI.10.9277156', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 20 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (435, 227, 699, '第三十四条', '…照本条例第二十八条第三款规定对需要迁移异地保护或者拆除的历史建筑按程序报批的； （三）文物主管部门未按照本条例第四条第二款、第二十二条、第二十三条规定对历史文化名城保护范围内不可移动文物的保护履行职责的； （四）文化旅游部门未按照本条例第四条第三款、第三十条、第三十一条规定对历史文化名城保护范围内非物质文化遗产和优秀…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (436, 227, 669, '第四条', '第四条 市住房和城乡建设部门会同文物主管部门负责历史文化名城保护和监督的具体工作。市、区住房和城乡建设部门负责历史文化名城保护范围内的历史建筑修缮与使用安全的监督管理工作。 市、区文物主管部门负责历史文化名城不可移动文物的保护工作。 市、区文化旅游部门负责历史文化…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (437, 227, 690, '第二十五条', '第二十五条 国有历史建筑，其代管人为保护责任人；没有代管人的，其使用权人为保护责任人。 非国有历史建筑，其所有权人为保护责任人；所有权人下落不明或者权属不清的，代管人为保护责任人；无代管人的，使用人为保护责任人。 所有权人、使用权人或者代管人均不明确的，房屋行政管理…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (228, 'FBMCLI.10.9277156', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (229, 'FBMCLI.10.9277156', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、5 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (438, 229, 671, '第六条', '第六条 历史文化名城保护资金使用范围包括： （一）历史文化名城的各类保护规划、相关文物保护单位及历史建筑修缮方案的编制和修改； （二）不可移动文物、历史建筑的维修经费补助； （三）非物质文化遗产和优秀传统文化的资源普查、征集、保护和传承经费补助； （四）用于历史文化名城保护的其他开支。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (439, 229, 680, '第十五条', '第十五条 市人民政府负责组织编制本市历史文化名城、历史文化街区、历史风貌保护区保护规划等工作，区人民政府负责组织编制历史建筑保护规划和历史建筑修缮方案等工作。 编制城市规划应当符合历史文化名城保护的要求，保持、延续城市传统格局和历史风貌，维护历史文化遗产的真实性和完整性。 历史文化名城保护规划应当单独编制…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (440, 229, 698, '第三十三条', '…化名城保护情况进行监督检查和评估的； （四）未按照本条例第十五条第一款规定组织编制历史建筑保护规划和历史建筑修缮方案的； （五）未按照本条例第二十九条规定组织设置保护标志的； （六）未按照本条例第三十二条规定对辖区内的古树名木加强保护的； （七）其他玩忽职守、滥用职权、徇私舞弊的行为。', 'supporting');
