INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (231, 'FBMCLI.10.9277156', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (441, 231, 692, '第二十七条', '第二十七条 历史建筑有损毁危险，所有权人不具备修缮能力的，由其所在地的区人民政府采取措施予以保护。 任何单位或者个人不得损坏或者擅自迁移、拆除历史建筑。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (442, 231, 693, '第二十八条', '…设部门会同文物主管部门批准。 因公共利益需要进行建设活动，对历史建筑无法实施原址保护、必须迁移异地保护或者拆除的，应当由市住房和城乡建设部门会同文物主管部门，报省人民政府确定的保护主管部门及文物主管部门批准。 本条规定的历史建筑原址保护、迁移、拆除所需费用，由建设单位列入建设工程预算。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (443, 231, 699, '第三十四条', '…； （五）住房和城乡建设部门未按照本条例第四条第一款规定对历史文化名城保护范围内历史建筑的修缮与使用安全进行监督管理工作的； （六）发展改革、财政、自然资源和规划、城市管理和综合执法、林业、工业和信息化、水利、民政等有关部门未按照本条例第四条第四款规定依各自职责协同做好历史文化名城保护工作的； （七）其他玩忽职守…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (232, 'FBMCLI.10.9277156', 'FUND', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (444, 232, 670, '第五条', '第五条 市、区人民政府应当将历史文化名城保护工作纳入国民经济和社会发展规划，并将保护资金列入本级财政预算。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (445, 232, 671, '第六条', '第六条 历史文化名城保护资金使用范围包括： （一）历史文化名城的各类保护规划、相关文物保护单位及历史建筑修缮方案的编制和修改； （二）不可移动文物、历史建筑的维修经费补助； （三）非物质文化遗产和优秀传统文化的资源普查、征集、保护和传承经费补助； …', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (446, 232, 698, '第三十三条', '…责任人员，依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）未按照本条例第五条规定将保护资金列入本级财政预算的； （二）未按照本条例第八条规定组织开展历史文化名城保护宣传教育的； （三）未按照本条例第九条规定对历史文化名城保护情况进行监督检查和评估的； （四）未按照本条例第十五条第一款规定组织编制历史建筑保护规…', 'supporting');
