INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (452, 240, 703, '全文', '…文物主管部门负责历史文化名城保护和监督的具体工作。市、区住房和城乡建设部门负责历史文化名城保护范围内的历史建筑修缮与使用安全的监督管理工作。”将第三款中的“文化主管部门”修改为“文化旅游部门”。 （三）删除第五条。 （四）将第十二条改为第十一条，将第二项中的“历史建筑、文物保护单位”修改为“文物保护单位、历史建筑”、…', 'supporting');
