INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (455, 253, 715, '第十二条', '…城保护对象（以下简称保护对象）包括下列内容： （一）历史文化名镇、历史文化名村、传统村落、历史文化街区、历史地段、不可移动文物、历史建筑、工业遗产、农业文化遗产、古树名木、非物质文化遗产、地名文化遗产等法律、法规规定的保护对象； （二）经批准的各类历史文化保护专项规划和国家、省、市确定的其他保护对象。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (456, 253, 728, '第二十五条', '第二十五条 历史文化名城、历史文化名镇、历史文化名村、传统村落、历史文化街区、历史地段的保护责任主体应当履行下列保护责任： （一）保持保护范围内建（构）筑物的传统格局、历史风貌和空间尺度，不得改变与其相互依存的自然景观和环境； （二）开展日常巡查，发现危害保护对象行为及时制止，依法处理或者告知有…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (457, 253, 716, '第十三条', '第十三条 市、县（市）区人民政府应当组织开展对历史文化名镇、历史文化名村、传统村落、历史文化街区、历史地段、历史建筑等各类保护对象的普查工作，有关单位和个人应当予以配合。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (254, 'FBMCLI.10.8049106', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 13 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (458, 254, 722, '第十九条', '…统村落、历史文化街区保护规划的内容依照国家和省相关法律、法规规定执行。 保护规划中应当明确保护范围，历史文化名镇、历史文化名村、传统村落、历史文化街区的保护范围包括核心保护范围和建设控制地带。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (459, 254, 732, '第二十九条', '第二十九条 在历史文化名镇、历史文化名村、传统村落、历史文化街区核心保护范围内，除新建、扩建必要的基础设施和公共服务设施外，不得进行新建、扩建活动。新建、扩建必要的基础设施和公共服务设施的，应当办理规划许可。规划和自然资源主管部门核发规划许可前，应当征求同级文化广播电视和旅游主管部门的意见。 在…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (460, 254, 733, '第三十条', '第三十条 在历史文化名镇、历史文化名村、传统村落、历史文化街区核心保护范围内，建设必要的基础设施和公共服务设施的，应当遵守下列要求： （一）不得新建污染环境的设施； （二）修建道路、地下工程以及其他市政公用设施的，应当采取有效的保护措施，不得损害保护对象； （三）新建、改造城市管线应当入地埋设…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (255, 'FBMCLI.10.8049106', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、6 个相关用语，关联 20 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (461, 255, 740, '第三十七条', '第三十七条 县（市）区负责房屋安全的主管部门应当按照职责对历史文化名镇、历史文化名村、传统村落、历史文化街区核心保护范围和历史建筑保护范围内的建（构）筑物安全进行监管，在房屋安全普查工作中对不可移动文物、历史建筑的安全状况予以标识并动态更新相关信息。 县（市）区负…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (462, 255, 709, '第六条', '…作，研究历史文化名城保护重大事项，为市人民政府决策提供咨询意见。日常工作由市规划和自然资源主管部门会同市文化广播电视和旅游主管部门负责。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (463, 255, 710, '第七条', '第七条 市规划和自然资源主管部门负责历史文化名城保护的规划管理工作。 市文化广播电视和旅游主管部门负责不可移动文物、非物质文化遗产等的保护和监督管理工作。 市城乡建设、城市管理、住房保障和房屋管理、交通、林业和园林、工业和信息化、农业农村、水务、民政、…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (256, 'FBMCLI.10.8049106', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (257, 'FBMCLI.10.8049106', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 12 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (464, 257, 725, '第二十二条', '第二十二条 经依法批准的历史文化名城、历史文化名镇、历史文化名村、传统村落、历史文化街区保护规划，不得擅自修改；确需修改的，保护规划的组织编制机关应当向原审批机关提出专题报告，经同意后，方可编制修改方案。修改后的保护规划，应当按照原审批程序报送审批。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (465, 257, 721, '第十八条', '第十八条 历史文化名城保护规划由所在城市人民政府组织编制。 历史文化名镇、历史文化名村保护规划由所在地县（市）区人民政府组织编制。 传统村落保护规划由所在地乡（镇）人民政府组织编制。 市区范围的历史文化街区保护规划由市人民政府组织编制，县（市）范围的…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (466, 257, 723, '第二十条', '第二十条 保护规划报送审批前，保护规划的组织编制机关应当广泛征求有关部门、专家和公众的意见；必要时，可以举行听证。 保护规划报送审批文件中应当附具意见采纳情况及理由；经听证的，还应当附具听证笔录。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (258, 'FBMCLI.10.8049106', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (467, 258, 720, '第十七条', '第十七条 尚未列入保护对象名录，市、县（市）区人民政府初步确认具有保护价值的，应当确定为预先保护对象，并自确定之日起十个工作日内向所有权人、使用人发出预先保护通知，书面告知其应当采取的保护措施。 被确定为预先保护对象的，由保护对象主管部门在预先保护通知发出之日起六个月内按照规定开展认定工作。预先保护对象超过六个月未…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (259, 'FBMCLI.10.8049106', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (468, 259, 738, '第三十五条', '第三十五条 经依法批准迁移、拆除的历史建筑，规划和自然资源主管部门应当会同同级文化广播电视和旅游主管部门、保护责任主体做好测绘、鉴定、信息记录、档案资料保存等工作，并按照有关规定，及时将档案资料报送相关档案机构。 建设单位应当将迁移、拆除的历史建…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (469, 259, 732, '第二十九条', '…旅游主管部门的意见。 在历史文化名镇、历史文化名村、传统村落、历史文化街区核心保护范围内，拆除历史建筑以外的建（构）筑物或者其他设施的，应当经规划和自然资源主管部门会同同级文化广播电视和旅游主管部门批准。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (470, 259, 737, '第三十四条', '第三十四条 任何单位和个人不得损坏或者擅自迁移、拆除历史建筑。 建设工程选址，应当避开历史建筑。因特殊情况不能避开的，建设单位应当尽可能实施原址保护。 对历史建筑实施原址保护的，建设单位应当事先确定保护措施，报规划和自然资源主管部门会同同级文化广播电视和旅游主管部门…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (260, 'FBMCLI.10.8049106', 'FUND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (471, 260, 711, '第八条', '…应当将历史文化名城保护工作纳入本级国民经济和社会发展规划，保障资金需求，将所需经费列入本级财政预算。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (261, 'FBMCLI.10.8049106', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (472, 261, 713, '第十条', '…保护历史文化名城的义务，有权对保护规划的制定和实施提出意见和建议。 鼓励单位和个人以捐赠、资助、志愿服务等方式，依法参与历史文化名城保护工作。 对在历史文化名城保护工作中做出突出贡献的单位和个人，按照国家和省有关规定给予表彰、奖励。 第二章 保护对象', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (473, 261, 720, '第十七条', '…保护失效。因预先保护对有关单位或者个人的合法权益造成损失的，市、县（市）区人民政府应当给予补偿。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (474, 261, 736, '第三十三条', '…照批准的保护设计方案和施工图设计文件对历史建筑进行修缮。市、县（市）区人民政府可以给予资金补助。 历史文化名镇、历史文化名村、传统村落、历史文化街区、历史地段保护范围内历史建筑以外的建（构）筑物涉及维护和修缮活动的，居民应当按照有关保护规划和修缮技术标准进行维护和修缮。市、县（市）区人民政府可以给予资金补助。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (262, 'FBMCLI.10.8049106', 'RES', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (475, 262, 723, '第二十条', '…报送审批前，保护规划的组织编制机关应当广泛征求有关部门、专家和公众的意见；必要时，可以举行听证。 保护规划报送审批文件中应当附具意见采纳情况及理由；经听证的，还应当附具听证笔录。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (476, 262, 755, '第五十二条', '… 背景资料 立法草案 长春市人大常委会办公厅关于对《长春市历史文化名城保护条例(草案)》征求意见的通告 本篇引用的法规 地方法规 长春市历史文化街区和历史建筑保护条例(2021修正) 引用本篇的法规 案例 论文 地方法规规章 长春市历史文化名城保护条例实施办法', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (263, 'FBMCLI.10.8049106', 'BIZ', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (477, 263, 747, '第四十四条', '…化遗产制定产业引导政策，扶持和培育老字号、非物质文化遗产代表性项目，以及承载历史文化价值的商业、产业等，支持发展文化旅游、文化创意等多样化特色产业。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (264, 'FBMCLI.10.8049106', 'DIG', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (478, 264, 719, '第十六条', '第十六条 保护对象主管部门应当建立并及时公布保护对象名录，开展保护对象测绘建档工作，进行数字化管理并动态维护更新。 保护对象名录应当报同级人民代表大会常务委员会备案。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (479, 264, 742, '第三十九条', '第三十九条 保护对象主管部门和其他相关部门在历史文化名城保护工作中应当运用数字化等新技术、新方法，开展保护对象的信息采集和分析，实现数据高效归集、共享，并为公众查询历史文化信息等相关内容提供便利。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (265, 'FBMCLI.10.8049106', 'SUP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (480, 265, 707, '第四条', '第四条 本市建立健全党委领导、政府统筹、部门联动、多方参与、社会监督的历史文化名城保护工作机制。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (266, 'FBMCLI.10.8049106', 'LIAB', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (481, 266, 750, '第四十七条', '…。 鼓励和支持高等院校、中等职业学校以及社会力量开设相关课程，培养专业技术人才。 第六章 法律责任', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (482, 266, 751, '第四十八条', '…尚可采取改正措施消除对规划实施的影响的，限期改正，处建设工程造价百分之五以上百分之十以下的罚款；无法采取改正措施消除影响的，限期拆除，不能拆除的，没收实物或者违法收入，可以并处建设工程造价百分之十以下的罚款。 （二）在乡、村庄规划区内未依法取得乡村建设规划许可证或者未按照乡村建设规划许可证的规定进行建设的，由乡（…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (267, 'FBMCLI.10.7321447', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、10 个相关用语，关联 20 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (483, 267, 757, '第二条', '…条例。 遵义历史文化名城的保护对象是以长征红色文化为核心，兼具黔北地域文化特色的历史城区、历史文化街区、历史文化名镇、历史文化名村的整体格局与风貌以及相关的文物、历史建筑、传统风貌建筑、古树名木、传统地名、传统村落和非物质文化遗产等。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (484, 267, 780, '第二十五条', '第二十五条 历史城区和历史文化街区、名镇、名村保护范围内，除文物保护单位外的建（构）筑物，应当进行分类保护： （一）对历史建筑，可以修缮、改善，鼓励根据不同历史建筑的特点进行不同形式的活化利用； （二）对传统风貌建筑，在不改变外观风貌的前提下，可以修缮、…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (485, 267, 776, '第二十一条', '第二十一条 历史文化街区、名镇、名村的保护责任人是其所在地街道办事处或者乡镇人民政府。保护责任人应当履行以下保护责任： （一）保持保护范围内建（构）筑物的传统格局、历史风貌、特色装饰、空间尺度和历史环境要素的完整性； （二）开展日常巡查，及时制…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (268, 'FBMCLI.10.7321447', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (486, 268, 779, '第二十四条', '…规定： （一）控制周边的景观环境，保持原有的空间格局与尺度，不得改变街巷肌理； （二）保持保护范围内建（构）筑物原有的高度、体量、风格及色彩等； （三）核心保护范围内，除新建、扩建必要的基础设施和公共服务设施外，不得新建、扩建建（构）筑物； （四）建设控制地带内，新建、改建、扩建建（构）筑物应当符合历史文化街区、名镇…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (487, 268, 760, '第五条', '…文化名城保护规划的审查报批、实施以及监督管理等工作。 市、县级文物主管部门负责历史文化名城保护范围内文物的保护与管理工作。 党史、档案、财政、教育、林业、旅游、地方志、应急管理、自然资源、综合行政执法等部门或者机构，在各自职责范围内，做好历史文化名城的保护和管理工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (488, 268, 770, '第十五条', '第十五条 历史城区的保护范围东起内环路，南至老鸦山山脊线，西抵府后山山脊线，北达凤凰山山脊线。历史城区重点保护以下内容： （一）凤凰山、府后山、老鸦山环抱老城和新城，湘江从中穿越的历史城区整体格局； （二）子尹路、民主路、杨柳街、捞沙巷等传统街巷格…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (269, 'FBMCLI.10.7321447', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 27 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (489, 269, 759, '第四条', '第四条 市人民政府统一负责历史文化名城的保护工作。 县级人民政府负责辖区内历史文化名城保护对象的保护工作。 乡镇人民政府、街道办事处按照本条例的规定履行保护职责。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (490, 269, 805, '第五十条', '…例规定，国家机关及其工作人员有下列情形之一，尚不构成犯罪的，由市、县级人民政府或者有关行政主管部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分： （一）未组织或者未按照法定程序组织编制、报批、修改、公布保护规划的； （二）未按照法定程序履行审批职责的； （三）未按照本条例第三十条、第三十一条的规定，制…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (491, 269, 777, '第二十二条', '…障结构安全，确保消防、防灾等设施、通道的正常使用，发现险情及时采取排险措施，并告知相关行政主管部门； （四）法律、法规规定的其他责任。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (270, 'FBMCLI.10.7321447', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (271, 'FBMCLI.10.7321447', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 14 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (492, 271, 805, '第五十条', '…和其他直接责任人员依法给予处分： （一）未组织或者未按照法定程序组织编制、报批、修改、公布保护规划的； （二）未按照法定程序履行审批职责的； （三）未按照本条例第三十条、第三十一条的规定，制定保障方案、整治方案的； （四）未按照规定对历史文化街区、名镇、名村开展日常巡查保护或者未履行对历史建筑和传统风貌建筑安全、消防…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (493, 271, 772, '第十七条', '第十七条 市人民政府组织编制历史文化名城、历史文化街区保护规划，县级人民政府组织编制历史文化名镇、名村保护规划。 新批准公布的历史文化名镇、名村、街区的保护规划，应当自历史文化名镇、名村、街区批准公布之日起一年内编制完成。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (494, 271, 760, '第五条', '第五条 市、县级住房城乡建设主管部门负责历史文化名城保护规划的审查报批、实施以及监督管理等工作。 市、县级文物主管部门负责历史文化名城保护范围内文物的保护与管理工作。 党史、档案、财政、教育、林业、旅游、地方志、应急管理、自然资源、综合行政执法等部门或者机构，在各自职责范围内，做…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (272, 'FBMCLI.10.7321447', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (495, 272, 768, '第十三条', '…者进行征集；对单位和个人提供的历史文化资源保护线索应当立即组织核实，具有保护价值的，确定为预先保护对象。 预先保护对象所在地乡镇人民政府、街道办事处应当自预先保护对象确定之日起十日内书面告知所有权人、使用人或者代管人，明确保护责任。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (273, 'FBMCLI.10.7321447', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、5 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (496, 273, 780, '第二十五条', '…名村保护范围内，除文物保护单位外的建（构）筑物，应当进行分类保护： （一）对历史建筑，可以修缮、改善，鼓励根据不同历史建筑的特点进行不同形式的活化利用； （二）对传统风貌建筑，在不改变外观风貌的前提下，可以修缮、维护，改善内部设施，以满足日常生活需要； （三）对其他建（构）筑物，与历史风貌无冲突的，予以保留，并进…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (497, 273, 782, '第二十七条', '…得新建妨碍历史建筑保护的生产企业，现有妨碍历史建筑保护的生产企业，应当按照保护规划要求逐步迁移。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (498, 273, 778, '第二十三条', '…入地条件的同类管线应当合并入地； （六）不得新增工业、仓储用地； （七）不得违反规划新建、改建、扩建建（构）筑物； （八）法律、法规规定的其他要求。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (274, 'FBMCLI.10.7321447', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 1 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (499, 274, 762, '第七条', '…级人民政府应当将历史文化名城保护纳入经济和社会发展规划，将历史文化名城保护所需经费列入同级财政预算。 市、县级人民政府应当出台政策措施，引导和鼓励社会资本通过捐赠、资助、投资等方式依法参与历史文化名城保护。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (275, 'FBMCLI.10.7321447', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (500, 275, 762, '第七条', '…所需经费列入同级财政预算。 市、县级人民政府应当出台政策措施，引导和鼓励社会资本通过捐赠、资助、投资等方式依法参与历史文化名城保护。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (501, 275, 764, '第九条', '…条 因历史文化名城保护需要，造成公民、法人或者其他组织财产损失的，有关人民政府应当依法给予补偿。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (502, 275, 765, '第十条', '…当对在历史文化名城保护工作中做出显著成绩的单位和个人，按照国家和省的有关规定，给予表彰或者奖励。 第二章 保护对象', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (276, 'FBMCLI.10.7321447', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (503, 276, 790, '第三十五条', '…等多种形式的宣传，普及历史文化名城保护知识。 鼓励建立历史文化名城保护志愿者服务队伍，引导公众参与历史文化名城保护和宣传工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (277, 'FBMCLI.10.7321447', 'BIZ', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (504, 277, 792, '第三十七条', '第三十七条 市、县级人民政府应当调整优化历史城区和历史文化街区、名镇、名村的业态布局，明确各类业态的构成比例，鼓励开展当地传统手工业、特色产品、非物质文化遗产传承和利用等具有地方特色的生产经营活动。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (278, 'FBMCLI.10.7321447', 'DIG', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (505, 278, 791, '第三十六条', '第三十六条 市、县级人民政府应当推动数字化技术在重点文物的信息采集、建档管理、保真修复、传承展示中的运用。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (279, 'FBMCLI.10.7321447', 'SUP', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (280, 'FBMCLI.10.7321447', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、5 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (506, 280, 804, '第四十九条', '…力的单位代为履行，所需费用由违法者承担；造成严重后果的，对单位处以5万元以上10万元以下的罚款，对个人处1万元以上5万元以下的罚款。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (507, 280, 805, '第五十条', '…国家机关及其工作人员有下列情形之一，尚不构成犯罪的，由市、县级人民政府或者有关行政主管部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分： （一）未组织或者未按照法定程序组织编制、报批、修改、公布保护规划的； （二）未按照法定程序履行审批职责的； （三）未按照本条例第三十条、第三十一条的规定，制定保障方…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (508, 280, 802, '第四十七条', '…。 任何组织和个人不得从事有损纪念设施环境和氛围的活动，不得破坏、污损纪念设施。 第五章 法律责任', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (281, 'FBMCLI.10.7185442', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、11 个相关用语，关联 22 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (509, 281, 817, '第九条', '第九条 历史文化名城的保护对象包括历史城区、历史文化街区、名镇、名村、传统村落、历史文化风貌区、历史建筑以及其他保护对象。 在本市行政区域内涉及不可移动文物、古树名木、非物质文化遗产、工业遗产、农业文化遗产、灌溉工程遗产、地名文化遗产等其他保护对象，执行有关法律、法规的规定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (510, 281, 867, '第五十九条', '…的古城区和老城区。本条例特指历史范围清楚、格局和风貌保存较为完整、需要保护的地区。 （二）历史文化街区，是指经省人民政府核定公布的保存文物特别丰富、历史建筑集中成片、能够较完整和真实地体现传统格局和历史风貌，并具有一定规模的历史地段。 （三）历史文化名镇名村，是指经住房和城乡建设部或省人民政府批准公布的保存文物特别丰富且…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (511, 281, 834, '第二十六条', '第二十六条 历史城区、历史文化街区、名镇、名村、传统村落、历史文化风貌区的保护责任人应当按照保护规划和下列要求履行保护责任： （一）保护传统格局、历史风貌、特色装饰、空间尺度和历史环境要素的完整性； （二）开展日常巡查，及时制止危害保护对象的行为，并告知…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (282, 'FBMCLI.10.7185442', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 12 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (512, 282, 846, '第三十八条', '第三十八条 划定总督署—西大街、东大街—北大街、淮军公所—清河道署等历史文化街区的核心保护范围和建设控制地带。保护和延续街区的传统格局、历史风貌及与其相互依存的自然景观和环境。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (513, 282, 826, '第十八条', '…内设置保护标志。 保护标志应当设置在历史文化街区、名镇、名村、传统村落、历史文化风貌区核心保护范围的主要出入口、历史建筑外部醒目位置。保护标志应当载明保护对象的名称、编号、区位、建成时间、文化信息等内容。 任何单位和个人不得擅自设置、移动、涂改或者损毁保护标志。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (514, 282, 836, '第二十八条', '第二十八条 在保护对象保护范围内进行建设活动，应当符合保护规划，并遵循下列要求： （一）历史城区保护范围内，不得新建影响传统格局和历史风貌的建筑物、构筑物，电力、通信、供水、排水、燃气等管线应当地下敷设；现状为架空线的应逐步入地敷设； （二）历史文化…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (283, 'FBMCLI.10.7185442', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 26 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (515, 283, 862, '第五十四条', '…化名城保护职责，造成严重后果的，由同级人民政府、上级人民政府相关部门或者监察机关追究该行政主管部门主要负责人的责任。 在历史文化名城保护工作中，工作人员玩忽职守、滥用职权、徇私舞弊的，由其所在单位或者上级主管部门、监察机关给予处分；构成犯罪的，依法追究刑事责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (516, 283, 814, '第六条', '第六条 市、县级人民政府确定的本级历史文化名城保护主管部门具体负责对本行政区域内历史文化名城保护实施监督管理。各级有关部门、单位应当按照各自职责和本条例有关规定，共同做好历史文化名城保护工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (517, 283, 834, '第二十六条', '第二十六条 历史城区、历史文化街区、名镇、名村、传统村落、历史文化风貌区的保护责任人应当按照保护规划和下列要求履行保护责任： （一）保护传统格局、历史风貌、特色装饰、空间尺度和历史环境要素的完整性； （二）开展日常巡查，及时制止危害保护对象的行为，并告知相关管理部门； （三）保持保护范围内环境的整洁美观…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (284, 'FBMCLI.10.7185442', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (285, 'FBMCLI.10.7185442', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (518, 285, 827, '第十九条', '第十九条 市、县级人民政府依法组织编制历史文化名城保护规划、历史文化街区保护规划。县级人民政府依法组织编制本行政区域内的历史文化名镇、名村、传统村落保护规划。市、县级自然资源和规划主管部门组织编制历史文化风貌区保护规划。市、县级住房和城乡建设主管部门组织编制历史建筑保护图则。 …', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (519, 285, 830, '第二十二条', '第二十二条 经批准的保护规划和保护图则，不得擅自修改；确需修改的，组织编制机关应当提出修改论证报告，经原审批机关同意后，按照原审批程序报送审批。 第四章 保护措施', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (520, 285, 829, '第二十一条', '第二十一条 市、县级人民政府应当统筹推进保护规划的组织实施，对下级政府及有关部门规划实施情况进行监督检查，并定期进行评估，对发现的问题应当及时纠正、处理。评估信息应当向社会公布。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (286, 'FBMCLI.10.7185442', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (521, 286, 822, '第十四条', '第十四条 尚未纳入保护名录但具有保护价值的对象，经市、县级人民政府同意后，可以确定为预先保护对象，并自确定之日起七个工作日内由相关部门向所有权人、使用人发出预先保护通知，告知其应当采取的保护措施。 自预先保护通知送达之日起满一年，预先保护对象未纳入保护名录的，预先保护自行失效。 在预先保护期内，任何单位和个人不…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (522, 286, 863, '第五十五条', '第五十五条 违反本条例规定，在预先保护期内损坏、擅自迁移、拆除预先保护对象的，由县级人民政府指定的部门责令限期恢复原状或者采取其他补救措施；造成严重后果的，对单位处五万元以上十万元以下的罚款，对个人处一万元以上三万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (287, 'FBMCLI.10.7185442', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (523, 287, 824, '第十六条', '…属变化情况、保护范围内建设审批情况； （四）保护规划； （五）设计、测绘信息资料； （六）修缮、迁移、拆除过程中形成的文字、图纸、图片和影像等资料； （七）其他需要保存的资料。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (524, 287, 835, '第二十七条', '…）按照相关规定配置消防器材设备，并确保消防防灾设施设备的正常使用； （六）按照相关规定进行修缮； （七）法律法规规定的其他要求。 任何单位和个人不得损坏或者擅自迁移、拆除历史建筑。确因公共利益需要进行建设，对历史建筑无法实施原址保护、必须迁移异地保护或者拆除的，按照有关法律法规的规定办理相关手续。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (525, 287, 865, '第五十七条', '…，限期改正，处建设工程造价百分之五以上百分之十以下的罚款；无法采取改正措施消除影响的，限期拆除，不能拆除的，没收实物或者违法收入，并处建设工程造价百分之十以下的罚款。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (288, 'FBMCLI.10.7185442', 'FUND', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (526, 288, 840, '第三十二条', '第三十二条 建立历史文化名城保护资金多渠道筹集机制。通过下列渠道筹集资金，用于本条例规定的保护对象的普查认定、保护修缮、抢险，以及相关的环境整治、基础设施建设，学术研究和规划设计，教育培训，考古，保护利用等工作： （一）市、县级人民政府财政预算安排的保护资…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (527, 288, 812, '第四条', '…护和管理相关工作。 市、县级人民政府应当将历史文化名城保护纳入国民经济和社会发展规划，安排保护资金，列入本级财政预算。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (289, 'FBMCLI.10.7185442', 'COMP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (528, 289, 816, '第八条', '…是全社会的共同责任。 鼓励志愿服务组织、社会公益组织和其他社会力量通过提供技术服务、捐赠、资助、投资等方式，依法参与历史文化名城保护工作。 市、县级人民政府及其有关部门对在历史文化名城保护工作中做出突出贡献的单位和个人依法给予表彰或者奖励。 任何单位和个人都有权对破坏历史文化名城保护对象的行为进行劝阻、投诉和举报…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (529, 289, 859, '第五十一条', '…物、国有历史建筑的使用权，开展合理利用； （四）通过简化手续、资金扶助、减免费用、开发权益奖励等措施支持合理利用。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (290, 'FBMCLI.10.7185442', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (530, 290, 858, '第五十条', '…栈、民俗客栈、特色餐饮等项目，利用闲置建筑物开展文化、旅游等活动。 鼓励保护对象保护范围内原住居民在原地居住，延续传统生活方式，利用自有资产依法从事与历史文化名城保护相适应的经营活动。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (291, 'FBMCLI.10.7185442', 'BIZ', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、5 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (531, 291, 850, '第四十二条', '第四十二条 建立业态准入正、负面清单，利用腾挪、置换的空间，积极发展文化、旅游、休闲服务产业，增加文化用地与公共绿地，完善公共服务设施和基础设施，改善古城人居环境。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (532, 291, 856, '第四十八条', '…护对象保护范围内开展当地传统手工业、特色产品、非物质文化遗产传承和利用等具有地方特色的生产经营活动，严格控制与历史文化名城保护无关的商业开发活动。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (533, 291, 832, '第二十四条', '…人民政府应当综合运用城市更新、乡村振兴等政策措施，逐步疏解与历史文化保护传承不相适应的功能业态，优化功能布局，保持适宜的人口密度与社会结构。推进历史城区、历史文化街区、名镇、名村、传统村落、历史文化风貌区的道路交通、河湖水系和生态环境治理，改善提升保护范围内的基础设施、公共服务设施和整体风貌。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (292, 'FBMCLI.10.7185442', 'DIG', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (534, 292, 825, '第十七条', '第十七条 在历史文化名城保护工作中应当积极运用数字化等新技术、新方法，开展保护对象的信息采集和分析，实现数据高效归集、共享，并为公众查询历史文化信息等相关内容提供便利。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (293, 'FBMCLI.10.7185442', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (535, 293, 816, '第八条', '…法给予表彰或者奖励。 任何单位和个人都有权对破坏历史文化名城保护对象的行为进行劝阻、投诉和举报。有关部门应当对投诉和举报及时处理并反馈。 第二章 保护名录', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (294, 'FBMCLI.10.7185442', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (536, 294, 863, '第五十五条', '…的部门责令限期恢复原状或者采取其他补救措施；造成严重后果的，对单位处五万元以上十万元以下的罚款，对个人处一万元以上三万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (537, 294, 860, '第五十二条', '…当支持教育行政部门和学校建立学生免费参观博物馆、展览馆、艺术馆等场所的长效机制。 第七章 法律责任', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (538, 294, 861, '第五十三条', '第五十三条 违反本条例规定，法律、法规已有法律责任规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (295, 'FBMCLI.10.1687579', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、11 个相关用语，关联 38 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (539, 295, 944, '第七十六条', '…（像），党史人物和革命人物旧（故）居等物质遗产，也包括革命故事、歌曲等非物质遗产。 （六）历史文化街区，是指保留有一定数量的不可移动文物、历史建筑、传统风貌建筑以及传统胡同、历史街巷等历史环境要素，能够较完整、真实地体现历史格局和传统风貌，并具有一定规模的区域。 （七）特色地区，是指历史文化街区外，具有一定规模、代表一定…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (540, 295, 882, '第十四条', '…保护对象包括下列内容： （一）世界遗产； （二）文物； （三）历史建筑和革命史迹； （四）历史文化街区、特色地区和地下文物埋藏区； （五）历史文化名镇、名村和传统村落； （六）历史河湖水系和水文化遗产； （七）山水格局和城址遗存； （八）传统胡同、历史街巷和传统地名； （九）风景名胜、历史名园和古树名木； （十）非物质文…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (541, 295, 907, '第三十九条', '第三十九条 在历史文化街区、名镇、名村和传统村落的保护范围内，禁止从事下列对保护对象可能造成破坏性影响的活动： （一）开山、采石、开矿等破坏传统格局和历史风貌的活动； （二）占用保护规划确定保留的园林绿地、河湖水系、道路等； （三）修建生产、储存…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (296, 'FBMCLI.10.1687579', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (542, 296, 895, '第二十七条', '…五园地区、历史文化街区、名镇、名村保护和传统村落保护发展等规划，应当包括下列内容： （一）保护范围、保护原则； （二）城乡建设用地面积、国土空间规划用途； （三）人口容量； （四）需要保护的建筑物、构筑物和周边历史环境要素； （五）传统风貌的建筑高度、体量、色彩等控制指标； （六）建筑的分类保护和整治措施； （七）保…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (543, 296, 909, '第四十一条', '…符合保护规划确定的建设控制要求，严格控制建筑物、构筑物的高度、体量、色彩、容积率等，与核心保护范围风貌相协调。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (544, 296, 908, '第四十条', '第四十条 在历史文化街区、名镇、名村的核心保护范围内，除必要的市政基础设施、公共服务设施以及按照保护规划进行风貌恢复建设外，不得进行新建、改建、扩建活动。 在历史文化街区、名镇、名村的核心保护范围内进行必要的市政基础设施、公共服务设施以及按照保护规划进行风貌恢复建设的，…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (297, 'FBMCLI.10.1687579', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 37 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (545, 297, 875, '第七条', '第七条 规划和自然资源主管部门负责历史文化名城，历史文化街区、名镇、名村、传统村落和历史建筑保护的规划管理工作。 住房和城乡建设主管部门负责历史建筑，历史文化街区和名镇范围内文物以外的建筑物、构筑物的修缮技术指导服务。 文物主管部门负责世界遗产申报的…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (546, 297, 906, '第三十八条', '…，确保防灾设施设备的正常使用，发现安全隐患或者险情，及时采取隐患或者风险排除措施，并向有关主管部门报告； （三）转让、出租、出借历史建筑的，与受让人、承租人、使用人书面约定双方的保护责任。 不动产登记机构应当及时将历史建筑产权登记信息通报历史建筑所在地的区人民政府。 法宝联想 法律法规 规范性文件（1） 法学期刊 …', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (547, 297, 916, '第四十八条', '…护和修缮条件的历史建筑有损毁危险，但是保护责任人拒绝履行维护和修缮义务的，区住房和城乡建设主管部门应当采取措施排除危险，所需费用由保护责任人承担。 法宝联想 法学期刊 法学期刊（1）', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (298, 'FBMCLI.10.1687579', 'COORD', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (548, 298, 904, '第三十六条', '…景观价值； （四）支持相关文化产业发展、改善沿线村镇人居环境。 市人民政府应当建立跨区保护协调机制，统筹协调三条文化带的保护利用。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (299, 'FBMCLI.10.1687579', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 15 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (549, 299, 898, '第三十条', '第三十条 经依法批准的保护规划，不得擅自修改；确需修改的，保护规划的组织编制机关应当向原审批机关提出专题报告，经同意后，方可编制修改方案。修改后的保护规划，应当按照原审批程序报送审批和备案。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (550, 299, 893, '第二十五条', '第二十五条 北京历史文化名城的保护规划体系包括北京历史文化名城保护规划，老城、三山五园地区、历史文化街区、名镇、名村保护规划和传统村落保护发展规划等。 规划编制部门应当有计划地编制保护规划，并作为专项规划纳入相应层级的国土空间规划。传统村落保护发展规划可以与…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (551, 299, 896, '第二十八条', '第二十八条 保护规划按照下列规定组织编制： （一）北京历史文化名城、老城和三山五园地区的保护规划由市规划和自然资源主管部门组织编制； （二）历史文化街区、名镇、名村的保护规划由所在地的区人民政府组织编制； （三）传统村落保护发展规划由所在地…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (300, 'FBMCLI.10.1687579', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (552, 300, 892, '第二十四条', '第二十四条 尚未纳入保护名录，区人民政府初步确认具有保护价值的，应当确定为预先保护对象，并自确定之日起七个工作日内向所有权人、使用人发出预先保护通知，告知其应当采取的保护措施。 任何单位和个人不得损坏、擅自迁移、拆除预先保护对象。确定为预先保护对象的，所在地的区人民政府应当在预先保护通知发出之日起两个…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (553, 300, 941, '第七十三条', '…十三条 违反本条例第二十四条第二款、第四十九条第一款规定，损坏、擅自迁移、拆除历史建筑或者预先保护对象的，由规划和自然资源主管部门责令限期恢复原状，对单位处十万元以上二十万元以下罚款，对个人处五万元以上十万元以下罚款；逾期不恢复原状的，指定有能力的单位代为恢复原状，所需费用由违法者承担，对单位处二十万元以上五十万元以…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (301, 'FBMCLI.10.1687579', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 23 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (554, 301, 910, '第四十二条', '第四十二条 在历史文化街区、名镇保护范围内新建、改建、扩建和拆除既有建筑或者改变既有建筑的外立面、屋顶或者结构的，应当向规划和自然资源主管部门申请核发规划许可，并同时提交保护设计方案；规划和自然资源主管部门核发规划许可应当征求同级住房和城乡建设、文物主管部门的意见。 在历史文化名村和…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (555, 301, 915, '第四十七条', '第四十七条 历史建筑保护责任人对历史建筑进行维护和修缮的，应当按照历史建筑保护图则和修缮技术标准编制保护设计方案，报区规划和自然资源主管部门审批；并依据经批准的保护设计方案编制施工方案，报区住房和城乡建设主管部门审批。日常保养或者进行不涉及体现历史风貌特色的部位、材料、构造…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (556, 301, 917, '第四十九条', '…设、文物主管部门共同审批。必要时由市规划和自然资源主管部门报市人民政府决定。 不具备维护和修缮条件的历史建筑有损毁危险的，保护责任人可以向市规划和自然资源主管部门申请原址复建。市规划和自然资源主管部门应当组织专家进行评审，会同市住房和城乡建设、文物、生态环境等主管部门共同审批。必要时由市规划和自然资源主管部门报市…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (302, 'FBMCLI.10.1687579', 'FUND', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (557, 302, 877, '第九条', '第九条 本市建立北京历史文化名城保护资金多渠道筹集机制。通过下列渠道筹集资金，用于本条例规定的保护对象的普查认定、保护修缮、抢险，以及相关的环境整治、基础设施建设，学术研究和规划设计，教育培训，考古，保护利用等工作： （一）市、区人民政府财政预算安排的保护资金…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (558, 302, 873, '第五条', '…历史文化名城保护工作，将北京历史文化名城保护纳入本市国民经济和社会发展规划、计划，统筹安排保护资金，完善体制机制和政策保障，推进世界遗产申报和历史文化名城保护与发展。 区人民政府负责本行政区域内的历史文化名城保护工作，将历史文化名城保护纳入本级国民经济和社会发展规划、计划，落实保护利用、改善民生等责任。 街道办事处、…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (559, 302, 919, '第五十一条', '…会同市农业农村等主管部门和有关区人民政府按照本市规定，建立健全历史文化名镇、名村和传统村落保护资金筹措机制，统筹相关政策，支持历史文化名镇、名村和传统村落的保护发展。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (303, 'FBMCLI.10.1687579', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (560, 303, 878, '第十条', '第十条 鼓励单位和个人以捐赠、资助、志愿服务等方式，参与保护利用、名录认定、宣传教育、规划编制等北京历史文化名城保护工作。 对保护北京历史文化名城作出突出贡献的单位和个人，市、区人民政府或者有关主管部门按照国家和本市规定予以表彰或者奖励。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (561, 303, 915, '第四十七条', '…对历史建筑进行维护和修缮。保护责任人按照规定维护和修缮历史建筑的，区人民政府可以给予资金等补助，区住房和城乡建设主管部门应当提供技术指导。 法宝联想 法律法规 规范性文件（2）', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (562, 303, 918, '第五十条', '…和修缮历史建筑以外的建筑物、构筑物；按照前述要求进行维护和修缮的，区人民政府可以给予资金等补助，区住房和城乡建设或者农业农村主管部门应当提供技术指导。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (304, 'FBMCLI.10.1687579', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (563, 304, 872, '第四条', '第四条 本市建立健全党委领导、政府统筹、单位实施、公众参与、社会监督的北京历史文化名城保护工作机制。 涉及北京历史文化名城保护的重大事项，应当经首都规划建设委员会审议，向党中央、国务院请示报告。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (564, 304, 873, '第五条', '…善民生等责任。 街道办事处、乡镇人民政府加强对本辖区的历史文化名城保护情况的巡查，引导动员公众参与历史文化名城保护工作。 居民委员会、村民委员会协助街道办事处、乡镇人民政府做好历史文化名城保护相关工作。 法宝联想 法律法规 规范性文件（2）法律动态（1） 司法案例 案例报道（2）', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (305, 'FBMCLI.10.1687579', 'BIZ', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (565, 305, 928, '第六十条', '…保护利用应当遵守先保护后利用的原则，注重整体风貌保护，符合正面或者负面清单的要求，合理控制商业开发规模，完善公共服务设施，传承传统文化。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (566, 305, 899, '第三十一条', '…综合实施方案应当包含建设工程设计要求、土地权属、规划指标、市政以及交通条件、实施时序、功能业态、风貌管控、投资主体和工程定额、保护更新模式、房源保障等内容。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (567, 305, 931, '第六十三条', '…革命传统精神。 鼓励将革命史迹与其他保护对象整合，拓展展示路线和内容；展示利用应当防止过度商业化、娱乐化，杜绝低俗化。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (306, 'FBMCLI.10.1687579', 'DIG', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (568, 306, 937, '第六十九条', '… 市规划和自然资源主管部门组织建立统一信息平台，对纳入保护名录的保护对象建立保护档案和相关数据库，记载保护对象的历史、权属、测绘数据、利用情况、相关研究成果等信息；并将保护档案和相关数据信息通过互联网等平台向社会公开，展示历史文化资源，为组织和个人查阅信息、共享研究成果、开展保护利用提供便利；依法应当保密的除外。 …', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (307, 'FBMCLI.10.1687579', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (569, 307, 872, '第四条', '第四条 本市建立健全党委领导、政府统筹、单位实施、公众参与、社会监督的北京历史文化名城保护工作机制。 涉及北京历史文化名城保护的重大事项，应当经首都规划建设委员会审议，向党中央、国务院请示报告。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (570, 307, 876, '第八条', '…城的义务，有权对保护规划的制定和实施提出意见和建议，对破坏北京历史文化名城的行为进行监督、举报。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (571, 307, 923, '第五十五条', '…以发起建立保护基金，支持北京历史文化名城保护相关领域的发展。 基金的使用应当公开透明，接受社会监督。 基金的捐赠人、受益人依照有关法律、法规的规定享受税收优惠。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (308, 'FBMCLI.10.1687579', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (572, 308, 938, '第七十条', '…保护责任的，由规划和自然资源主管部门责令改正；逾期不改正的，对单位处五万元以上二十万元以下罚款，对个人处一万元以上十万元以下罚款；造成历史建筑损毁的，对单位处二十万元以上五十万元以下罚款，对个人处十万元以上二十万元以下罚款，并责令限期恢复原状，逾期不恢复原状的，指定有能力的单位代为恢复原状，所需费用由历史建筑保护…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (573, 308, 939, '第七十一条', '…能力的单位代为恢复原状，所需费用由违法者承担；造成不利后果的，对单位处五万元以上十万元以下罚款，对个人处一万元以上五万元以下罚款。 法宝联想 法律法规 规范性文件（1） 司法案例 司法案例（1）', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (574, 308, 940, '第七十二条', '…准的保护设计方案对历史建筑进行修缮的，由规划和自然资源主管部门对单位处一万元以上五万元以下罚款，对个人处五千元以上一万元以下罚款；造成不利后果的，责令限期恢复原状，对单位处五万元以上十万元以下罚款，对个人处一万元以上五万元以下罚款；逾期不恢复原状的，指定有能力的单位代为恢复原状，所需费用由违法者承担。 违反本条例…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (309, 'FBMCLI.10.7056842', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 6 个核心用语、9 个相关用语，关联 12 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (575, 309, 956, '第十一条', '…文化遗产； （二）凤山镇等承德历史文化名镇、历史文化名村（传统村落）； （三）承德二道牌楼历史文化街区、滦河老街历史文化街区、寿王坟历史文化街区，已经公布的历史地段； （四）各级文物保护单位和尚未核定公布为文物保护单位的不可移动文物； （五）以磬锤峰、双塔山等为代表的中国北方丹霞地貌遗产； （六）清帝北巡御道文化线路及城…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (576, 309, 962, '第十七条', '…列保护责任： （一）保持保护范围内建筑物、构筑物的传统格局、历史风貌、特色装饰、空间尺度和历史环境要素的完整性； （二）保障结构安全，发现险情及时采取排险措施，并向有关部门报告； （三）协助有关部门确保消防、防灾等公共设施、设备的正常使用； （四）保持保护范围内整洁美观； （五）按照相关规定进行修缮； （六）开展日常巡查…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (577, 309, 967, '第二十二条', '…存爆炸性、易燃性、放射性、毒害性、腐蚀性物品的工厂、仓库等； （四）损坏或者擅自迁移、拆除历史建筑； （五）未经批准对历史建筑进行外部修缮装饰、添加设施以及改变历史建筑的结构或者使用性质的； （六）破坏属于非物质文化遗产组成部分的实物和场所。 第四章 合理利用', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (310, 'FBMCLI.10.7056842', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (578, 310, 963, '第十八条', '第十八条 在历史文化名城保护范围内的建设活动应当遵循以下规定： （一）历史城区应当以避暑山庄及其周围寺庙为核心，通过高度控制、分区风貌控制以及规划管理等手段保护重要观景点及空间视廊、视域，避免建筑遮挡避暑山庄及周边寺庙与周边山体的空间视廊，保持重要视域…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (579, 310, 957, '第十二条', '…入国土空间总体规划。保护规划应当包括保护原则、总体目标、保护体系、保护内容、保护重点、核心保护范围、保护要求、保障措施等。 县（市、区）人民政府应当根据保护规划要求，编制本区域内的专项保护规划。 经批准的保护规划，不得擅自修改；确需修改的，编制机关应当提出修改论证报告，经原审批机关同意后，按照原程序报送审批。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (580, 310, 964, '第十九条', '第十九条 市、县（市、区）人民政府应当在历史文化街区、名镇、名村核心保护范围的主要出入口设置标志牌。任何单位和个人不得擅自设置、移动、涂改或者损毁标志牌。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (311, 'FBMCLI.10.7056842', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 6 个核心用语、9 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (581, 311, 961, '第十六条', '第十六条 历史文化名城保护实行保护责任人制度，保护责任人按照下列规定确定： （一）国家级历史文化名城的保护责任人为市人民政府； （二）历史文化街区、名镇、名村的保护责任人为所在地县（市、区）人民政府；县（市、区）人民政府设立保护管理组织的，该组织为保护责任人；…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (582, 311, 950, '第五条', '第五条 市、县（市、区）住房和城乡建设主管部门负责历史文化名城保护和监督管理工作。 自然资源和规划主管部门负责历史文化名城保护规划管理工作。 文物主管部门负责世界遗产申报的具体实施，指导革命文物的保护管理以及其他法律、法规规定的有关历史文化名城保护工作。 其他有关部…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (583, 311, 966, '第二十一条', '…权人不具备维护和修缮能力的，市、县（市、区）人民政府应当采取措施进行保护。 住房和城乡建设主管部门负责历史建筑范围内文物以外的建筑物、构筑物的修缮技术指导服务。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (312, 'FBMCLI.10.7056842', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (313, 'FBMCLI.10.7056842', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、7 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (584, 313, 957, '第十二条', '第十二条 市人民政府应当组织编制本市历史文化名城保护规划，纳入国土空间总体规划。保护规划应当包括保护原则、总体目标、保护体系、保护内容、保护重点、核心保护范围、保护要求、保障措施等。 县（市、区）人民政府应当根据保护规划要求，编制本区域内的专项保护规划。 经批准的保护规划，不…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (585, 313, 973, '第二十八条', '…政府责令改正，对直接负责的主管人员和其他直接责任人员，依法给予处分： （一）未组织编制专项保护规划的； （二）未按照程序组织编制专项保护规划的； （三）擅自修改专项保护规划的； （四）未将批准的专项保护规划予以公布的。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (586, 313, 958, '第十三条', '第十三条 市、县（市、区）人民政府应当统筹推进保护历史文化名城专项保护规划的组织实施，加强对规划实施情况的监督检查，定期进行评估。检查和评估信息应当通过政府门户网站和当地主要新闻媒体向社会公布，接受社会监督。对发现的问题，应当及时纠正、处理。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (314, 'FBMCLI.10.7056842', 'PRE', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (587, 314, 960, '第十五条', '第十五条 尚未纳入保护名录，市、县（市、区）人民政府初步确认具有保护价值的，可以确定为预先保护对象，并自确定之日起七个工作日内向所有权人、使用权人发出预先保护通知，告知其应当采取的保护措施。 自预先保护通知送达之日起满一年，预先保护对象未纳入保护名录的，预先保护自行失效。 预先保护期间，任何单位和个人不得破坏预先…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (588, 314, 956, '第十一条', '…、滦河老街历史文化街区、寿王坟历史文化街区，已经公布的历史地段； （四）各级文物保护单位和尚未核定公布为文物保护单位的不可移动文物； （五）以磬锤峰、双塔山等为代表的中国北方丹霞地貌遗产； （六）清帝北巡御道文化线路及城址遗存； （七）其他应当依法保护的对象。 第三章 保护措施', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (315, 'FBMCLI.10.7056842', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、6 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (589, 315, 967, '第二十二条', '…的工厂、仓库等； （四）损坏或者擅自迁移、拆除历史建筑； （五）未经批准对历史建筑进行外部修缮装饰、添加设施以及改变历史建筑的结构或者使用性质的； （六）破坏属于非物质文化遗产组成部分的实物和场所。 第四章 合理利用', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (590, 315, 963, '第十八条', '…庄及周边寺庙与周边山体的空间视廊，保持重要视域的完整性； （二）在核心保护范围内，除新建、扩建必要的公共基础设施和公共服务设施外，不得进行新建、扩建活动；确需新建、扩建必要的公共基础设施和公共服务设施的，应当报行政审批部门批准，行政审批部门批准之前，应当征求规划、文物等主管部门的意见； （三）在建设控制地带进行建…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (591, 315, 975, '第三十条', '…的罚款；造成损失的，依法承担赔偿责任。 违反本条例第二十二条第五项规定，对历史建筑进行外部修缮装饰、添加设施以及改变历史建筑的结构或者使用性质的，由住房和城乡建设主管部门责令停止违法行为、限期恢复原状或者采取其他补救措施；有违法所得的，没收违法所得；逾期不恢复原状或者不采取其他补救措施的，住房和城乡建设主管部门可…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (316, 'FBMCLI.10.7056842', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (592, 316, 949, '第四条', '…本行政区域内历史文化名城的保护工作，把历史文化名城保护工作纳入国民经济和社会发展规划，安排保护资金，列入本级财政预算。 历史文化名城保护管理委员会负责监督、指导、协调历史文化名城保护工作等重大事项。 乡（镇）人民政府、街道办事处依照本条例有关规定负责本辖区内历史文化名城保护的日常管理工作。 村（居）民委员会协助乡（镇…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (317, 'FBMCLI.10.7056842', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (593, 317, 953, '第八条', '…进行反馈。 对在历史文化名城保护工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰和奖励。 第二章 保护内容', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (594, 317, 960, '第十五条', '…象。因预先保护对有关单位或者个人的合法权益造成损失的，市、县（市、区）人民政府应当依法给予补偿。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (595, 317, 966, '第二十一条', '…责维护和修缮，非国有历史建筑由所有权人负责维护和修缮，市、县（市、区）人民政府可以给予资金补助。所有权人不具备维护和修缮能力的，市、县（市、区）人民政府应当采取措施进行保护。 住房和城乡建设主管部门负责历史建筑范围内文物以外的建筑物、构筑物的修缮技术指导服务。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (318, 'FBMCLI.10.7056842', 'RES', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (319, 'FBMCLI.10.7056842', 'BIZ', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (596, 319, 968, '第二十三条', '…史城区、历史文化街区、历史文化名镇、历史文化名村、中国传统村落和历史建筑等的合理利用，进行业态策划，依法制定产业引导、控制和禁止目录，合理控制商业开发，鼓励和支持开展当地传统手工业、特色产品、非物质文化遗产传承和利用等具有地方特色的生产经营活动。 历史文化街区、名镇、名村（传统村落）根据保护规划要求，发展多样化特…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (597, 319, 970, '第二十五条', '…革命传统精神。 鼓励将革命史迹与其他保护对象整合，拓展展示路线和内容；展示利用应当防止过度商业化、娱乐化，杜绝低俗化。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (320, 'FBMCLI.10.7056842', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (321, 'FBMCLI.10.7056842', 'SUP', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (598, 321, 958, '第十三条', '…督检查，定期进行评估。检查和评估信息应当通过政府门户网站和当地主要新闻媒体向社会公布，接受社会监督。对发现的问题，应当及时纠正、处理。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (599, 321, 953, '第八条', '第八条 任何单位和个人对违反保护规划、破坏历史文化名城的行为有权进行劝阻、举报，有关部门应当及时受理举报，依法组织核查、处理并进行反馈。 对在历史文化名城保护工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰和奖励。 第二章 保护内容', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (322, 'FBMCLI.10.7056842', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (600, 322, 975, '第三十条', '…取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处五十万元以上一百万元以下的罚款，对个人并处五万元以上十万元以下的罚款；造成损失的，依法承担赔偿责任。 违反本条例第二十二条第四项规定，损坏或者擅自迁移、拆除历史建筑的，由住房和城乡建设主管部门责令停止违法行为、限期恢复原状或者采取其他补救措施；有违法…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (601, 322, 973, '第二十八条', '第二十八条 违反本条例规定，县（市、区）人民政府有下列情形之一的，由市人民政府责令改正，对直接负责的主管人员和其他直接责任人员，依法给予处分： （一）未组织编制专项保护规划的； （二）未按照程序组织编制专项保护规划的； （三）擅自修改专项保护规划的； （四）未将批准的专项保护规划予以公布的。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (602, 322, 971, '第二十六条', '…推广传统手工艺品； （六）建立学生教育体验基地； （七）其他公益性保护利用活动。 第五章 法律责任', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (323, 'FBMCLI.10.7179694', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 6 个核心用语、9 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (603, 323, 986, '第八条', '…（一）滁州古城、凤阳古城； （二）滁城北大街、金刚巷、遵阳街，凤阳门台子英美烟草公司旧址等历史文化街区； （三）天长龙岗村、汊河村，凤阳小岗村，明光梅郢村，南谯太平集村等历史文化名村、传统村落； （四）凤阳云霁街、定远炉桥镇老街、南谯乌衣老街、来安石界牌古村、全椒袁家湾老街等历史地段； （五）清流关、柏子龙潭、清末老滁县…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (604, 323, 996, '第十八条', '第十八条 历史文化名城保护实行保护责任人制度，保护责任人按照下列规定确定： （一）历史文化街区、历史文化名镇、历史文化名村、传统村落和历史地段的保护责任人为所在地的县（市、区）人民政府； （二）历史建筑的所有权人为保护责任人，所有权人下落不明或者权属不清的，使用人为保护责任人； （三）保护对象单独设立保护管理单位…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (605, 323, 997, '第十九条', '第十九条 历史文化街区、历史文化名镇、历史文化名村、传统村落和历史地段的保护责任人应当按照保护要求履行下列保护责任： （一）保持保护范围内建筑物、构筑物的传统格局和历史风貌的完整性； （二）开展日常巡查，发现危害行为及时制止； （三）保持保护…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (324, 'FBMCLI.10.7179694', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (606, 324, 989, '第十一条', '…规划相衔接。 历史文化街区、历史文化名镇、历史文化名村和传统村落的保护规划应当依法划定核心保护范围和建设控制地带。 历史建筑的保护范围应当包括历史建筑本身和必要的建设控制地带。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (607, 324, 992, '第十四条', '第十四条 在历史文化街区、历史文化名镇、历史文化名村保护范围内进行建设活动，应当符合保护规划要求，不得损害历史文化遗产的真实性和完整性，不得对其传统格局和历史风貌构成破坏性影响，并遵守下列要求： （一）在核心保护范围内，除必要基础设施和公共服务设施外，不得进行新建、扩建活动；进行…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (608, 324, 988, '第十条', '…，直接列入保护名录。 保护名录应当载明保护对象的名称、位置、历史沿革、历史价值、保护级别和保护范围等内容。保护名录应当自本条例实施起一年内编制完成。 任何单位和个人都可以提出将具有保护价值的历史文化遗产列入保护名录的建议。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (325, 'FBMCLI.10.7179694', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (609, 325, 999, '第二十一条', '…，保护责任人应当及时履行维护、修缮责任；经鉴定为危险房屋的，市、县（市、区）住房和城乡建设主管部门应当督促保护责任人立即实施治理；保护责任人不具备维护和修缮能力的，市、县（市、区）人民政府应当采取措施进行保护。 历史建筑的维护、修缮费用由所有权人承担，市、县（市、区）人民政府可以给予补助。所有权人、使用人对于维护、修…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (610, 325, 1002, '第二十四条', '…国家机关及其工作人员有下列违反本条例规定情形之一的，由市、县（市、区）人民政府或者有关行政主管部门责令其改正，对直接负责的主管人员和其他直接责任人员，依法追究行政责任： （一）未按照法定程序组织编制、修改保护规划和确定、调整保护名录的； （二）未按照法定程序或者未按照保护规划的要求履行审批职责的； （三）未依法对保护…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (611, 325, 983, '第五条', '第五条 住房和城乡建设主管部门会同文化和旅游部门负责历史文化名城的申报、保护规划的编制与实施、监督、管理等具体工作。 发展改革、自然资源和规划、公安、财政、城市管理、交通运输、农业农村、生态环境、林业等部门和消防救援机构，应当按照各自职责做好历史文化…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (326, 'FBMCLI.10.7179694', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (327, 'FBMCLI.10.7179694', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (612, 327, 989, '第十一条', '第十一条 历史文化名城所在地的市、县（市、区）人民政府应当依法编制保护规划，并按法定程序报批。历史文化名城保护规划应当纳入同级国土空间规划；编制或者修改其他专项规划，应当与历史文化名城规划相衔接。 历史文化街区、历史文化名镇、历史文化名村和传统村落的保护规划应当依法划定核心保护范围和建设控制地…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (613, 327, 1002, '第二十四条', '…接负责的主管人员和其他直接责任人员，依法追究行政责任： （一）未按照法定程序组织编制、修改保护规划和确定、调整保护名录的； （二）未按照法定程序或者未按照保护规划的要求履行审批职责的； （三）未依法对保护对象的保护状况实施监督检查，或者对经批准的保护对象的改造、利用情况监管不力的； （四）未依法受理举报、控告和查处违…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (614, 327, 983, '第五条', '第五条 住房和城乡建设主管部门会同文化和旅游部门负责历史文化名城的申报、保护规划的编制与实施、监督、管理等具体工作。 发展改革、自然资源和规划、公安、财政、城市管理、交通运输、农业农村、生态环境、林业等部门和消防救援机构，应当按照各自职责做好历史文化名城的保护工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (328, 'FBMCLI.10.7179694', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (329, 'FBMCLI.10.7179694', 'REPAIR', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (615, 329, 992, '第十四条', '…合，鼓励采用传统工艺和传统材料，保护传统格局和历史风貌； （二）在建设控制地带内进行新建、改建、扩建等建设活动的，应当符合建设控制要求，体现传统建筑及空间形态，严格控制建（构）筑物的形式、高度、体量、风格、色彩等，与核心保护范围的传统格局和历史风貌相协调。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (616, 329, 994, '第十六条', '…、重点保护部位、保护要求以及合理利用要求。 历史建筑应当按照保护规划和图则的要求进行维护和修缮；历史建筑的修缮不得改变原有形式、高度、体量、风格、色彩等。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (617, 329, 998, '第二十条', '第二十条 历史建筑保护责任人应当按照保护规划要求履行下列保护责任： （一）进行日常维护和修缮，保持原有建筑的外部造型、风貌特征； （二）保障结构安全，协助有关部门确保消防、防灾等公共设施、设备的正常使用，发现险情时及时采取排险措施，并向有关主管部门报告； （三）转让、出租、出借时，书面告知受让人、承租人、使用人…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (330, 'FBMCLI.10.7179694', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (618, 330, 982, '第四条', '…将历史文化名城保护纳入本级国民经济和社会发展规划，建立和完善保护机制，根据本地实际情况安排保护资金，列入本级财政预算。 乡镇人民政府、街道办事处负责本辖区内历史文化名城保护的日常巡查、宣传引导等具体工作。 村民委员会、居民委员会配合乡镇人民政府、街道办事处做好历史文化名城保护工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (331, 'FBMCLI.10.7179694', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (619, 331, 984, '第六条', '…见和建议，对破坏历史文化名城的行为进行劝阻、举报。 鼓励企事业单位、社会团体和个人以捐赠、资助、志愿服务等形式，参与历史文化名城的保护。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (620, 331, 985, '第七条', '…人民政府对在历史文化名城保护工作中做出突出贡献的单位和个人，按照国家和省有关规定给予表彰和奖励。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (621, 331, 999, '第二十一条', '…取措施进行保护。 历史建筑的维护、修缮费用由所有权人承担，市、县（市、区）人民政府可以给予补助。所有权人、使用人对于维护、修缮费用另有约定的，从其约定。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (332, 'FBMCLI.10.7179694', 'RES', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (333, 'FBMCLI.10.7179694', 'BIZ', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (622, 333, 1001, '第二十三条', '…利用历史文化名城资源开展文化创意、文化体验、休闲旅游、传统手工业、非物质文化遗产传播等特色经营活动或者公益活动； （三）组织开展与历史文化名城保护相关的学术研究、实践创新、文化宣传和教育活动，支持学校开展与历史文化名城保护相关的实践教育活动； （四）鼓励企事业单位、社会组织和个人将符合条件的历史建筑作为公共场所向社会…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (334, 'FBMCLI.10.7179694', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (335, 'FBMCLI.10.7179694', 'SUP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (623, 335, 1002, '第二十四条', '…保护状况实施监督检查，或者对经批准的保护对象的改造、利用情况监管不力的； （四）未依法受理举报、控告和查处违法行为的； （五）滥用职权、玩忽职守、徇私舞弊的； （六）法律、法规规定的其他违法行为。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (624, 335, 984, '第六条', '…何单位和个人都有权对历史文化名城保护工作提出意见和建议，对破坏历史文化名城的行为进行劝阻、举报。 鼓励企事业单位、社会团体和个人以捐赠、资助、志愿服务等形式，参与历史文化名城的保护。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (336, 'FBMCLI.10.7179694', 'LIAB', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (337, 'FBMCLI.10.1666467', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 6 个核心用语、10 个相关用语，关联 33 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (625, 337, 1006, '第二条', '…理，适用本条例。 历史文化名城的保护包括对历史城区、历史片区、历史文化名镇、历史文化名村、历史文化街区、历史文化风貌区和历史建筑的保护等。 历史文化名城保护涉及文物保护单位、尚未核定公布为文物保护单位的不可移动文物、可移动文物、非物质文化遗产、工业遗产、历史环境要素等保护与管理的，按照法律、法规和有关规定执行。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (626, 337, 1028, '第二十四条', '…项： （一）历史文化名城保护规划应当提出分期实施要求； （二）历史文化名镇、历史文化名村、历史文化街区、历史文化风貌区保护规划应当包含重要的传统格局、街巷肌理、历史环境要素等； （三）历史建筑保护规划应当包含核心保护要素、使用功能和保护图则等； （四）法律、法规规定的其他事项。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (627, 337, 1061, '第五十七条', '…，建筑样式、空间格局和街区景观较完整地体现本市某一历史时期地域文化特点的地区，但不具备作为历史文化街区的城市区域； （四）历史环境要素，是指反映历史风貌的古井、围墙、石阶、铺地、驳岸、古树名木等。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (338, 'FBMCLI.10.1666467', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (628, 338, 1029, '第二十五条', '第二十五条 历史文化名城保护名录中的下列保护对象，应当根据保护规划科学合理划定保护范围： （一）历史城区可以根据需要划定环境协调区； （二）历史文化名镇、历史文化名村、历史文化街区的保护范围包括核心保护范围和建设控制地带； （三）历史文化街区内历史建筑的保护范围应当为历史建筑本身，历史文化街区外历史建筑的…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (629, 338, 1038, '第三十四条', '第三十四条 历史文化名镇、历史文化名村、历史文化街区核心保护范围内，除必要的基础设施和公共服务设施外，不得进行新建、扩建活动。新建、扩建必要的基础设施和公共服务设施，应当与历史风貌和传统格局相协调，保持街巷的原有宽度、走向、空间尺度，保护传统院落空间，不得随意搭建影响院落格局特色的建…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (630, 338, 1040, '第三十六条', '…提交的规划方案应当包含历史保护专题： （一）在历史文化名镇、历史文化名村、历史文化街区核心保护范围内，依法进行新建、扩建必要的基础设施和公共服务设施活动的； （二）在历史文化名镇、历史文化名村、历史文化街区建设控制地带内，历史文化风貌区、历史建筑的保护范围内，依法进行新建、改建、扩建活动的。 市、县（市）人民政府自然…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (339, 'FBMCLI.10.1666467', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 27 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (631, 339, 1057, '第五十三条', '…条 违反本条例规定，国家机关及其工作人员有下列情形之一的，由市及区（市）县人民政府或者相关主管部门责令其改正，对直接负责的主管人员和其他直接责任人员，依法给予处分： （一）未组织编制或者未按照法定程序组织编制保护规划的； （二）擅自修改或者未将批准的保护规划予以公布的； （三）未按照法定程序或者未按照保护规划的要求履…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (632, 339, 1009, '第五条', '第五条 市、县（市）人民政府自然资源主管部门会同同级文物主管部门，负责本行政区域内历史文化名城保护规划的实施和监督管理等工作。 市及区（市）县人民政府发展改革、教育、工业和信息化、民族和宗教、公安、民政、财政、住房和城乡建设、水务、应急管理、人防、城市管理等工作的…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (633, 339, 1020, '第十六条', '…护对象的名称、区位、历史价值等历史文化资料信息，经相关部门汇总整理后，由市人民政府自然资源主管部门纳入保护名录档案。 单位或者个人可以依法查询、利用保护名录档案记载的相关信息。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (340, 'FBMCLI.10.1666467', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (341, 'FBMCLI.10.1666467', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、7 个相关用语，关联 20 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (634, 341, 1057, '第五十三条', '…责的主管人员和其他直接责任人员，依法给予处分： （一）未组织编制或者未按照法定程序组织编制保护规划的； （二）擅自修改或者未将批准的保护规划予以公布的； （三）未按照法定程序或者未按照保护规划的要求履行审批职责的； （四）因保护不力，导致已批准公布的历史文化名城、历史文化名镇、历史文化名村被列入濒危名单的； （五）其…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (635, 341, 1030, '第二十六条', '第二十六条 保护规划报送审批前，组织编制部门应当向社会公告，征求相关部门、专家和公众的意见。公告时间不少于三十日。涉及房屋征收、土地征用的，应当依法举行听证。 保护规划应当自批准之日起十五日内向社会公布。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (636, 341, 1022, '第十八条', '… 历史文化名城、历史文化名镇、历史文化名村、历史文化街区、历史文化风貌区和历史建筑应当编制保护规划，保护规划自批准公布之日起一年内编制完成。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (342, 'FBMCLI.10.1666467', 'PRE', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (637, 342, 1029, '第二十五条', '…当为历史建筑本身，历史文化街区外历史建筑的保护范围应当包括建筑本身和必要的建设控制地带。 预先保护对象预保护范围参照前款规定执行。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (638, 342, 1021, '第十七条', '第十七条 本市建立历史文化名城预先保护制度。符合下列条件之一的，可以作为预先保护对象先行保护： （一）符合法律、法规及本条例规定的申报条件，尚未得以认定的； （二）历史文化资源普查、城市开发建设活动以及单位或者个人提供的线索中发现的具有一定保护价值，经专家评…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (639, 342, 1006, '第二条', '…名村、历史文化街区、历史文化风貌区和历史建筑的保护等。 历史文化名城保护涉及文物保护单位、尚未核定公布为文物保护单位的不可移动文物、可移动文物、非物质文化遗产、工业遗产、历史环境要素等保护与管理的，按照法律、法规和有关规定执行。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (343, 'FBMCLI.10.1666467', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 12 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (640, 343, 1058, '第五十四条', '…象的； （二）违反本条例第三十二条第一、二、三项规定的； （三）未经批准对历史建筑进行外部修缮装饰、添加设施以及改变历史建筑的结构或者使用性质的，或者经批准进行上述活动对传统格局、历史风貌或者历史建筑构成破坏性影响的； （四）损坏或者擅自迁移、拆除历史建筑的。 违反前款行为，造成严重后果的，单位有前款第一项、第三…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (641, 343, 1047, '第四十三条', '第四十三条 任何单位和个人不得损坏或者擅自迁移、拆除历史建筑。因公共利益需要迁移或者拆除历史建筑的应当依法报请批准，并按照相关技术标准和管理规定组织迁移、拆除。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (642, 343, 1039, '第三十五条', '…史文化风貌区保护范围内应当控制各项建设活动，建设活动不得对风貌区的传统格局造成破坏；新建、改建、扩建建筑的高度、体量、色彩等应当与整体风貌相协调。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (344, 'FBMCLI.10.1666467', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (643, 344, 1008, '第四条', '…府负责本行政区域内历史文化名城的保护、利用和管理工作，并将历史文化名城保护所需资金列入本级财政预算。 乡镇人民政府、街道办事处应当配合上级人民政府及有关部门做好本辖区历史文化名城保护、利用和管理工作。 具有行政管理职能的市人民政府派出机关根据授权，负责管理区域内历史文化名城的保护、利用和管理工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (644, 344, 1043, '第三十九条', '…促相关部门或者个人按照年度修缮计划开展修缮工作。 市及区（市）县人民政府可以从历史文化名城保护资金中，对履行修缮义务的历史建筑保护责任人给予补助。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (345, 'FBMCLI.10.1666467', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (645, 345, 1012, '第八条', '…，增强全社会保护意识，对保护和利用工作中做出突出贡献的单位和个人按照国家有关规定予以表彰和奖励。 第二章 申报批准和保护名录', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (646, 345, 1043, '第三十九条', '…市及区（市）县人民政府可以从历史文化名城保护资金中，对履行修缮义务的历史建筑保护责任人给予补助。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (647, 345, 1049, '第四十五条', '…相关主管部门可以依法变更或者撤回已生效的行政许可，造成被许可人合法权益损失的，应当依法给予补偿。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (346, 'FBMCLI.10.1666467', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (648, 346, 1030, '第二十六条', '…求相关部门、专家和公众的意见。公告时间不少于三十日。涉及房屋征收、土地征用的，应当依法举行听证。 保护规划应当自批准之日起十五日内向社会公布。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (347, 'FBMCLI.10.1666467', 'BIZ', 1, 2, 'low', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (649, 347, 1050, '第四十六条', '…源。 区（市）县人民政府应当对历史文化名镇、历史文化名村、历史文化街区、历史文化风貌区进行业态策划，合理引导商业开发，鼓励开展传统手工业、特色产品等具有地方特色的生产经营活动。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (348, 'FBMCLI.10.1666467', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (349, 'FBMCLI.10.1666467', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (650, 349, 1056, '第五十二条', '… 任何单位或者个人都有保护历史文化名城的义务，有权对破坏历史文化名城的行为进行劝阻、投诉和举报。 市及区（市）县人民政府和相关主管部门应当公布投诉和举报方式。对单位或者个人投诉、举报的破坏历史文化名城的行为，应当及时进行核实、处理和反馈。 第五章 法律责任', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (350, 'FBMCLI.10.1666467', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (651, 350, 1058, '第五十四条', '…反前款行为，造成严重后果的，单位有前款第一项、第三项行为之一的，并处五万元以上十万元以下的罚款；有前款第二项行为的，并处六十万元以上一百万元以下的罚款；有前款第四项行为的，并处三十万元以上五十万元以下的罚款。个人有前款第一项，第三项行为之一的，并处二万元以上五万元以下的罚款；有前款第二项行为的，并处六万元以上十万…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (652, 350, 1056, '第五十二条', '…对单位或者个人投诉、举报的破坏历史文化名城的行为，应当及时进行核实、处理和反馈。 第五章 法律责任', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (653, 350, 1059, '第五十五条', '…改或者损毁保护标志的，由执法机关责令限期改正；逾期不改正的，对单位处二万元以上五万元以下的罚款，对个人处二千元以上一万元以下的罚款。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (351, 'FBMCLI.10.4789838', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、9 个相关用语，关联 18 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (654, 351, 1072, '第十条', '…保护内容主要包括： （一）历史城区的传统格局和历史风貌； （二）三坊七巷、朱紫坊、上下杭等历史文化街区； （三）烟台山、冶山、福建船政等历史风貌区； （四）鼓岭、福建协和大学旧址等历史建筑群； （五）螺洲、闽安等历史文化名镇、名村，传统村落； （六）优秀的传统街巷； （七）不可移动文物、历史建筑、传统风貌建筑； （八）非…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (655, 351, 1089, '第二十七条', '第二十七条 市人民政府应当对公布的历史文化街区、名镇、名村，历史风貌区、传统村落和历史建筑群、历史建筑、传统风貌建筑设置明显的保护标志，标明保护范围。 任何单位或者个人不得擅自设置、移动、涂改或者损毁保护标志。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (656, 351, 1091, '第二十九条', '第二十九条 在历史文化街区、名镇、名村，历史风貌区、传统村落和历史建筑群的建设控制地带内进行建设活动，应当维护传统格局，延续历史风貌。新建、改建建筑物、构筑物时，应当在高度、体量、色彩等方面与历史风貌相协调；新建、改建道路时，不得改变原有的道路格…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (352, 'FBMCLI.10.4789838', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、6 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (657, 352, 1080, '第十八条', '第十八条 历史文化街区、名镇、名村，历史风貌区、传统村落和历史建筑群的保护范围包括核心保护范围、建设控制地带。必要时，可以在建设控制地带外划定环境协调区，具体范围由市历史文化名城保护管理机构会同自然资源和规划、城乡建设、文物等相关主管部门确定，并列入保护规划，依法报经批准后公布。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (658, 352, 1089, '第二十七条', '…镇、名村，历史风貌区、传统村落和历史建筑群、历史建筑、传统风貌建筑设置明显的保护标志，标明保护范围。 任何单位或者个人不得擅自设置、移动、涂改或者损毁保护标志。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (659, 352, 1096, '第三十四条', '…十四条 尚未核定公布为文物保护单位的不可移动文物，区文物主管部门应当予以登记公布，并划定其保护范围。 市文物主管部门可以根据历史资料、考古调查划定地下文物埋藏区、水下文物保护区，并报市人民政府核定公布。 在地下文物埋藏区进行工程建设的，应当根据法定程序组织考古调查、勘探或者发掘，所需费用由建设单位列入工程预算。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (353, 'FBMCLI.10.4789838', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 21 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (660, 353, 1067, '第五条', '第五条 市历史文化名城保护管理机构是本市历史文化名城保护的主管部门，负责历史文化名城综合管理工作。 市自然资源和规划主管部门按照职责对历史文化名城建设项目进行规划审批、监督和管理。 市城乡建设主管部门按照职责对历史文化名城建设工程进行审批、监督和管理。 市文物、文化和旅游、发展和改革、…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (661, 353, 1074, '第十二条', '…化名城保护管理机构应当会同自然资源和规划、城乡建设、文化和旅游、文物、住房保障和房产管理等主管部门和园林部门，普查本市的历史文化资源，发现具有保护价值的，及时提出将其列入保护名录的意见。 除国务院和福建省人民政府批准公布的保护项目外，对拟列入保护名录的保护项目，市历史文化名城保护管理机构应当会同有关部门组织专家论证并…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (662, 353, 1075, '第十三条', '…三条 任何单位和个人在城市建设中发现可能具有保护价值的建筑物、构筑物，可以向所在地城乡建设主管部门报告。城乡建设主管部门应当会同市历史文化名城保护管理机构、文物等有关部门及时勘验，在五个工作日内提出处理意见，确认为先予保护对象的，应当采取保护现场、设置标志等先予保护措施，同时书面告知所有权人、使用人或者管理人。 已采…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (354, 'FBMCLI.10.4789838', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (355, 'FBMCLI.10.4789838', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、7 个相关用语，关联 12 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (663, 355, 1077, '第十五条', '…市历史文化名城保护管理机构、自然资源和规划、城乡建设、文物等有关单位，编制福州历史文化名城保护规划，依法报经批准后，向社会公布，并将其纳入国土空间规划。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (664, 355, 1078, '第十六条', '第十六条 市历史文化名城保护管理机构应当根据历史文化名城保护规划，会同自然资源和规划、城乡建设、文物等有关主管部门，编制历史文化街区、名镇、名村，历史风貌区、历史建筑群等专项保护规划。各专项保护规划应当依法报经批准后，向社会公布。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (665, 355, 1079, '第十七条', '第十七条 保护规划的编制应当进行科学论证，广泛征求有关部门、专家和公众的意见。 经依法批准的保护规划，不得擅自修改。确需修改的，应当征求有关部门、专家和公众的意见，按照法定程序批准并公布。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (356, 'FBMCLI.10.4789838', 'PRE', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (666, 356, 1075, '第十三条', '…会同市历史文化名城保护管理机构、文物等有关部门及时勘验，在五个工作日内提出处理意见，确认为先予保护对象的，应当采取保护现场、设置标志等先予保护措施，同时书面告知所有权人、使用人或者管理人。 已采取先予保护措施的建筑物、构筑物，市历史文化名城保护管理机构应当在七个工作日内组织专家进行评审论证。确认具有保护价值的，列入保…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (667, 356, 1096, '第三十四条', '第三十四条 尚未核定公布为文物保护单位的不可移动文物，区文物主管部门应当予以登记公布，并划定其保护范围。 市文物主管部门可以根据历史资料、考古调查划定地下文物埋藏区、水下文物保护区，并报市人民政府核定公布。 在地下文物埋藏区进行工程建设的，应当…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (357, 'FBMCLI.10.4789838', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、5 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (668, 357, 1090, '第二十八条', '…围内，除新增必要的公共基础设施、公共服务设施和保护规划确定的其他建设活动外，不得进行新建、扩建活动。 在历史风貌区和历史建筑群的核心保护范围内进行建设活动，应当报市自然资源和规划主管部门批准。市自然资源和规划主管部门在批准之前应当征求历史文化名城保护管理机构、文物主管部门的意见。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (669, 357, 1091, '第二十九条', '…、传统村落和历史建筑群的建设控制地带内进行建设活动，应当维护传统格局，延续历史风貌。新建、改建建筑物、构筑物时，应当在高度、体量、色彩等方面与历史风貌相协调；新建、改建道路时，不得改变原有的道路格局和景观特征。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (670, 357, 1092, '第三十条', '…区、传统村落和历史建筑群的环境协调区内进行建设活动，应当保护其依存的自然与人文环境，新建、改建的建筑物、构筑物应当与文物古迹及周边环境风貌相协调。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (358, 'FBMCLI.10.4789838', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (671, 358, 1066, '第四条', '…史文化名城保护和管理，将其纳入国民经济和社会发展规划以及年度工作计划，并将历史文化名城保护专项资金列入本级财政预算。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (359, 'FBMCLI.10.4789838', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (672, 359, 1071, '第九条', '…宣传教育，增强全民保护意识，对在历史文化名城保护工作中做出突出贡献的单位和个人，给予表彰和奖励。 任何单位和个人都有保护历史文化名城的义务，有权对破坏历史文化名城的行为进行劝阻、举报和控告。 第二章 保护内容', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (673, 359, 1094, '第三十二条', '…筑有损毁危险，所有权人或者使用人确不具备维护和修缮能力的，市、区人民政府应当根据情况，进行补助、修缮或者采取置换等措施予以保护。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (674, 359, 1099, '第三十七条', '…城保护相关的课程，培养历史文化资源保护利用专业技术人才。 鼓励公民、法人和其他组织以捐赠、资助、认保、认养、提供技术服务或者提出建议等方式参与历史文化名城的保护和利用工作。 鼓励通过政策引导、资金扶持等方式吸引社会资本投入历史文化名城的保护和利用。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (360, 'FBMCLI.10.4789838', 'RES', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (361, 'FBMCLI.10.4789838', 'BIZ', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (675, 361, 1085, '第二十三条', '…复三坊七巷的坊巷结构，保护和延续朱紫坊街区河坊一体的整体空间格局，保护和延续上下杭街区传统商业街巷、建筑、会馆的历史风貌。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (676, 361, 1086, '第二十四条', '第二十四条 历史文化街区、历史风貌区和历史建筑群范围内的商业经营布局，应当符合专项保护规划并与其内环境、功能相配套，注重闽都文化国际品牌宣传与展示。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (362, 'FBMCLI.10.4789838', 'DIG', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (677, 362, 1076, '第十四条', '…、城乡建设、文化和旅游、文物等主管部门和园林部门根据保护名录，采取文字、录音、录像、测绘、数字化多媒体等技术手段，全面系统整理历史文化名城的各类档案资料，建立历史文化名城档案数据库，实施数字化管理，并及时更新。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (363, 'FBMCLI.10.4789838', 'SUP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (678, 363, 1071, '第九条', '…和奖励。 任何单位和个人都有保护历史文化名城的义务，有权对破坏历史文化名城的行为进行劝阻、举报和控告。 第二章 保护内容', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (364, 'FBMCLI.10.4789838', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (679, 364, 1104, '第四十二条', '…维护和修缮历史建筑的，由市历史文化名城保护管理机构责令改正，对单位处五万元以上十万元以下的罚款，对个人处一万元以上五万元以下的罚款。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (680, 364, 1100, '第三十八条', '…活化利用历史文化名城各类资源和要素，设立文博馆所，发展景观旅游、文化创意等产业。 第五章 法律责任', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (681, 364, 1101, '第三十九条', '第三十九条 违反本条例规定的行为，法律、法规已有法律责任规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (365, 'FBMCLI.10.4789839', 'OBJ', 1, 2, 'low', 'machine_draft', '机器初编检出 7 个核心用语、10 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (682, 365, 1110, '全文', '…职责，协同实施本条例。” 五、将第六条修改为：“市、区人民政府设立的相关保护管理机构，负责历史文化街区、历史风貌区、历史建筑群的日常保护和管理。” 六、将第七条修改为：“市人民政府设立历史文化名城保护专家咨询委员会，编制历史文化名城保护相关规划和保护名录、开发、建设等重大事项应当听取专家咨询委员会的意见。” 七、增加一条…', 'supporting');
