INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (683, 366, 1110, '全文', '…十六条改为第十八条，修改为：“历史文化街区、名镇、名村，历史风貌区、传统村落和历史建筑群的保护范围包括核心保护范围、建设控制地带。必要时，可以在建设控制地带外划定环境协调区，具体范围由市历史文化名城保护管理机构会同自然资源和规划、城乡建设、文物等相关主管部门确定，并列入保护规划，依法报经批准后公布。” 十六、将第十七…', 'supporting');
