INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (687, 371, 1110, '全文', '…负责建筑物的保养和安全防范，保持建筑的原有风貌，接受指导、检查和监督。 “历史建筑的维护和修缮由所有权人负责，直管公房、政府代管或者所有权人下落不明、房屋权属不清的历史建筑由管理人、使用人负责。维护和修缮应当按照市、区人民政府编制的保护图则、修缮技术规范和保护方案实施。 “历史建筑有损毁危险，所有权人或者使用人确…', 'supporting');
