INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (688, 372, 1110, '全文', '…史文化名城保护和管理，将其纳入国民经济和社会发展规划以及年度工作计划，并将历史文化名城保护专项资金列入本级财政预算。” 四、将第五条修改为：“市历史文化名城保护管理机构是本市历史文化名城保护的主管部门，负责历史文化名城综合管理工作。 “市自然资源和规划主管部门按照职责对历史文化名城建设项目进行规划审批、监督和管理。 …', 'supporting');
