INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (689, 373, 1110, '全文', '…筑有损毁危险，所有权人或者使用人确不具备维护和修缮能力的，市、区人民政府应当根据情况，进行补助、修缮或者采取置换等措施予以保护。” 三十、将第三十条改为第三十三条，修改为：“依法征收拆除的建筑中留存的壁画、雕刻、建筑构件等，具有收藏价值的由市文物主管部门指定的文物收藏单位收藏；具有利用价值的，由市、区人民政府指定…', 'supporting');
