INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (690, 375, 1110, '全文', '…复三坊七巷的坊巷结构，保护和延续朱紫坊街区河坊一体的整体空间格局，保护和延续上下杭街区传统商业街巷、建筑、会馆的历史风貌。” 二十、将第二十二条改为第二十四条，修改为：“历史文化街区、历史风貌区和历史建筑群范围内的商业经营布局，应当符合专项保护规划并与其内环境、功能相配套，注重闽都文化国际品牌宣传与展示。” 二十…', 'supporting');
