INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (691, 376, 1110, '全文', '…、城乡建设、文化和旅游、文物等主管部门和园林部门根据保护名录，采取文字、录音、录像、测绘、数字化多媒体等技术手段，全面系统整理历史文化名城的各类档案资料，建立历史文化名城档案数据库，实施数字化管理，并及时更新。” 十三、将第十三条改为第十五条，修改为：“市人民政府应当组织市历史文化名城保护管理机构、自然资源和规划、…', 'supporting');
