INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (694, 379, 1120, '第十条', '…史时期都城、州府、县治所在的历史城区； （三）历史文化名镇； （四）历史文化名村； （五）历史文化街区； （六）历史风貌区； （七）历史建筑； （八）传统风貌建筑； （九）其他保护对象。 西湖文化景观、中国大运河（杭州段）、良渚古城遗址等世界遗产保护以及前款规定的保护对象涉及的文物、风景名胜、古树名木、非物质文化遗产保护…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (695, 379, 1133, '第二十三条', '…、自然环境及重要管控要求，其中保护范围应当包括历史城区和其他需要保护、控制的区域； （二）历史文化街区、名镇、名村以及历史风貌区保护规划，应当包括保护范围、不可移动文物、历史建筑、传统风貌建筑和传统格局、景观风貌及建筑高度、体量、风格、色彩等重要管控要求； （三）历史建筑保护图则应当包括保护范围和重要管控要求。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (696, 379, 1124, '第十四条', '第十四条 位于历史文化街区、名镇、名村以及历史风貌区保护范围内，未被公布为文物保护单位、文物保护点或者历史建筑的建筑物、构筑物，具备下列条件之一的，可以确定为传统风貌建筑： （一）体现城市特定发展阶段时代特征、凝聚社会公众情感记忆的； （二）对历…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (380, 'FBMCLI.10.6853863', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (697, 380, 1141, '第三十一条', '…文化、科学、艺术价值的历史建筑，其建筑的主要外部风貌、特色构件不得改变。 在历史建筑的核心保护范围内，除因保护需要外不得新建建筑物、构筑物；在核心保护范围内因保护需要新建建筑物、构筑物或者在建设控制地带内新建建筑物、构筑物的，应当符合历史建筑保护图则、保护利用导则的规定，并依照有关法律、法规的规定办理相关手续。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (698, 380, 1132, '第二十二条', '第二十二条 历史文化街区、名镇、名村以及历史风貌区、历史建筑的核心保护范围和建设控制地带等保护范围，按照下列规定划出，依法报请有权机关批准： （一）历史文化街区、名镇、名村以及历史风貌区的核心保护范围，应当包括该区域内传统格局、历史风貌较为完整和不可移动文物、历史建筑、传统风貌建筑集中成片的地…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (699, 380, 1137, '第二十七条', '第二十七条 在历史文化街区、名镇、名村以及历史风貌区核心保护范围内，除新建、扩建必要的基础设施和公共服务设施外，不得进行新建、扩建活动。 在历史风貌区核心保护范围内新建、扩建必要的基础设施和公共服务设施的，应当符合保护规划要求；需要规划和自然资源主管部门许可的，在核发选址意见书或者提…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (381, 'FBMCLI.10.6853863', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、8 个相关用语，关联 30 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (700, 381, 1116, '第六条', '第六条 市人民政府确定的本市历史文化名城保护主管部门（以下简称市名城保护主管部门）具体负责对本市行政区域内历史文化名城保护实施监督管理。区、县（市）建设主管部门具体负责对本行政区域内历史文化名城保护实施监督管理。市名城保护主管部门和区、县（市）建设主管部门统称名城保护主管…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (701, 381, 1149, '第三十九条', '…谈，督促其整改。区、县（市）人民政府可以参照建立相应的约谈机制，并督促有关保护管理责任人、保护责任人落实保护措施。 第五章 合理利用', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (702, 381, 1139, '第二十九条', '第二十九条 历史建筑的所有权人为保护责任人。国有历史建筑可以约定其使用人为保护责任人。非国有历史建筑的所有权人不明确的，由其所在地的区、县（市）人民政府指定保护责任人。 保护责任人负责历史建筑的使用安全和日常维护、修缮，并承担相应的费用。保护责任人有权从区、县（…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (382, 'FBMCLI.10.6853863', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (383, 'FBMCLI.10.6853863', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 15 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (703, 383, 1128, '第十八条', '第十八条 编制历史文化名城、街区、名镇、名村保护规划以及历史风貌区保护规划，应当维护历史文化遗产的真实性、完整性，保持传统格局、历史风貌和空间尺度，保护与其相互依存的人文景观、自然景观和背景环境，加强建筑高度和建筑形态、景观视廊以及其他相关要素的管控、引导。 规划建设超高…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (704, 383, 1130, '第二十条', '…管部门应当自历史风貌区保护名录公布之日起一年内，会同同级名城保护主管部门组织编制历史风貌区保护规划，报本级人民政府批准后公布。 历史风貌区保护规划报送批准前，组织编制机关应当依法公示草案，征求有关部门、专家和公众的意见，公示时间不少于三十日。 县（市）人民政府批准本行政区域内的历史风貌区保护规划前，应当征求市名城保护…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (705, 383, 1133, '第二十三条', '第二十三条 编制或者修改历史文化名城、街区、名镇、名村保护规划以及历史风貌区保护规划、历史建筑保护图则，应当按照下列规定明确强制性内容： （一）杭州历史文化名城保护规划，应当包括保护范围、保护对象和“三面云山一面城”等传统格局、自然环境及重要管控要求，其中保护范围应当包括历史城区和…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (384, 'FBMCLI.10.6853863', 'PRE', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (706, 384, 1145, '第三十五条', '…径推荐或者发现的建筑物、构筑物具有保护价值的，应当向其所在地的乡镇人民政府、街道办事处发出预保护通知： （一）各类规划编制中推荐保护或者专项普查中发现的； （二）社会公众推荐保护或者城市建设中发现的； （三）其他途径推荐或者发现的。 乡镇人民政府、街道办事处应当按照预保护通知要求及时设立预保护标志，开展日常巡查。 …', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (707, 384, 1156, '第四十六条', '…在历史风貌区、历史建筑列入濒危名单后未按期完成整改或者整改不到位的； （四）未按照规定设立预保护标志或者开展日常巡查的； （五）违反规定实施行政许可的。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (708, 384, 1146, '第三十六条', '…十六条 城乡建设中发现有保护价值的建筑物、构筑物的，施工单位应当立即停止拆除或者施工，采取临时保护措施，并报告建设单位，建设单位应当及时向所在地的区、县（市）名城保护主管部门报告。 名城保护主管部门接到报告后，应当在十个工作日内组织进行评估。建筑物、构筑物经评估不具有历史文化价值的，名城保护主管部门应当通知有关单位恢…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (385, 'FBMCLI.10.6853863', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (709, 385, 1143, '第三十三条', '第三十三条 因公共利益需要进行建设活动，对历史建筑无法实施原址保护、必须迁移异地保护或者拆除的，建设单位应当提供迁移或拆除的必要性与可行性论证报告、迁移方案等相关资料，经区、县（市）历史文化名城保护委员会组织论证，向社会公示方案后，依照国家和省有关规定报请批准。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (710, 385, 1125, '第十五条', '…以及乡镇人民政府、街道办事处定期组织开展本行政区域内历史文化遗产的普查。 新建建设项目需要拆除既有的建筑物、构筑物的，规划和自然资源主管部门在建设项目选址论证或者建设条件集成阶段，应当征求同级名城保护主管部门意见。必要时，市名城保护主管部门应当会同同级规划和自然资源、建设等部门，区、县（市）名城保护主管部门应当会…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (711, 385, 1137, '第二十七条', '…主管部门应当征求同级名城保护、文物等部门的意见。 在历史风貌区核心保护范围内为实施保护规划修缮、改善或者整治建筑物的，应当符合保护规划要求；建设活动组织实施单位应当将建设工程设计方案报所在地的区、县（市）名城保护主管部门备案。 在历史文化街区、名镇、名村以及历史风貌区建设控制地带内新建建筑物、构筑物的，应当符合保…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (386, 'FBMCLI.10.6853863', 'FUND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (712, 386, 1114, '第四条', '…城保护和监督管理，应当将历史文化名城保护纳入国民经济和社会发展规划纲要，将所需资金纳入本级财政预算。 乡镇人民政府、街道办事处依照本条例有关规定负责本辖区内历史文化名城保护的日常管理工作，建立保护联动机制，加强巡查、维护、宣传和监督。 村民委员会、居民委员会协助乡镇人民政府、街道办事处做好历史文化名城保护工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (387, 'FBMCLI.10.6853863', 'COMP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (713, 387, 1119, '第九条', '…是全社会的共同责任。 鼓励志愿服务组织、社会公益组织和其他社会力量通过提供技术服务、捐赠、资助、投资等方式，依法参与历史文化名城保护工作。 任何单位和个人都有权对破坏历史文化名城保护对象的行为进行劝阻和举报。名城保护主管部门和其他有关部门应当对举报及时处理并反馈。 第二章 保护对象', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (714, 387, 1148, '第三十八条', '第三十八条 与历史文化名城保护有关的奖励或者惩戒信息，应当按照信用管理的规定，纳入单位或者个人的社会信用档案。', 'supporting');
