INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (715, 390, 1117, '第七条', '第七条 名城保护主管部门和其他相关部门在历史文化名城保护工作中应当积极运用数字化等新技术、新方法，开展保护对象的信息采集和分析，实现数据高效归集、共享，并为公众查询历史文化信息等相关内容提供便利。', 'supporting');
