INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (716, 391, 1119, '第九条', '…参与历史文化名城保护工作。 任何单位和个人都有权对破坏历史文化名城保护对象的行为进行劝阻和举报。名城保护主管部门和其他有关部门应当对举报及时处理并反馈。 第二章 保护对象', 'supporting');
