INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (717, 392, 1157, '第四十七条', '…行为、限期恢复原状或者采取其他补救措施；造成严重后果的，对单位处五十万元以上一百万元以下的罚款，对个人处五万元以上十万元以下的罚款，有违法所得的，并处没收违法所得。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (718, 392, 1161, '第五十一条', '…原状或者采取其他补救措施；逾期不恢复原状、不采取其他补救措施的，对单位处五万元以上十万元的罚款，对个人处一万元以上五万元以下的罚款，有违法所得的，并处没收违法所得。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (719, 392, 1162, '第五十二条', '…者采取其他补救措施；造成预保护对象损毁、灭失等严重后果的，对单位处十万元以上二十万元以下的罚款，对个人处二万元以上十万元以下的罚款，有违法所得的，并处没收违法所得。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (393, 'FBMCLI.10.4783869', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、11 个相关用语，关联 19 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (720, 393, 1173, '第八条', '…历史城区，与历史城区相互依存的山川形胜； （二）历史文化名镇，历史文化名村； （三）以白塔历史文化街区、唐户屯历史文化街区等为代表的历史文化街区，以青年大街等为代表的历史地段； （四）各级文物保护单位，已登记尚未核定为文物保护单位的不可移动文物，地下文物埋藏区； （五）历史建筑； （六）工业遗产； （七）文化线路、文化遗…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (721, 393, 1202, '第三十七条', '…有重大历史价值或者纪念意义的、能较完整地反映一些历史时期传统风貌和地方民族特色的镇和村。 历史文化街区：经省人民政府核定公布的保存文物特别丰富、历史建筑集中成片、能够较完整和真实地体现传统格局和历史风貌，并具有一定规模的历史地段。 历史地段：能够真实地反映一定历史时期传统风貌和民族、地方特色的地区。 文物保护单位：经县级…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (722, 393, 1177, '第十二条', '第十二条 【保护规划编制体系】 市人民政府负责组织编制本市历史文化名城、历史文化街区保护规划。 县（市）人民政府负责组织编制本行政区域内历史文化名镇、历史文化名村保护规划。 市住房和城乡建设主管部门负责组织编制历史地段、历史建筑等保护对象的保护规划。 历史文化名城、历史文化名镇、历史文化名村、历史文化街…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (394, 'FBMCLI.10.4783869', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (723, 394, 1178, '第十三条', '第十三条 【划定保护范围】 历史文化名城保护规划应当划定保护对象的保护范围。 历史文化名镇、历史文化名村、历史文化街区、历史地段的保护范围应当包括核心保护范围和建设控制地带。 历史文化街区内历史建筑的保护范围应当为历史建筑本身；历史文化街区外历…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (724, 394, 1184, '第十九条', '第十九条 【历史文化名镇、历史文化名村、历史文化街区保护范围内允许活动】 在历史文化名镇、历史文化名村、历史文化街区的核心保护范围内，除必要的基础设施和公共服务设施外，不得进行新建、扩建活动。在建设控制地带内，新建建筑物、构筑物应当符合保护规划确定的建设控制要求。 在保护范围内进…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (725, 394, 1182, '第十七条', '…化名镇、历史文化名村、历史文化街区、历史地段的保护责任人应当履行以下保护责任： （一）保持保护范围内原有传统格局、历史风貌、空间尺度、与其相依存的自然景观和环境的完整性； （二）保持保护范围内整体环境的整洁美观； （三）开展日常巡查工作，及时制止危害历史文化遗产的行为，并告知有关部门； （四）采取有效措施完善消防、防…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (395, 'FBMCLI.10.4783869', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 22 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (726, 395, 1169, '第四条', '…国土空间规划，并将历史文化名城保护所需资金列入本级财政预算。 市、县（市）区住房和城乡建设主管部门会同同级文物、自然资源主管部门，负责本行政区域内历史文化名城保护规划的具体实施和监督管理等工作。 发展改革、工信、财政、生态环境、交通运输、农业农村、应急、林草等有关部门按照各自职责，履行历史文化名城保护和监督管理的有关…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (727, 395, 1181, '第十六条', '第十六条 【明确保护责任人】 历史文化名城实行保护责任人制度。 历史城区的保护责任人为市人民政府； 历史文化名镇、历史文化名村、历史文化街区、历史地段的保护责任人为其所在地县（市）区人民政府； 历史建筑的保护责任人按照下列规定确定： （一）国有建…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (728, 395, 1177, '第十二条', '…市）人民政府负责组织编制本行政区域内历史文化名镇、历史文化名村保护规划。 市住房和城乡建设主管部门负责组织编制历史地段、历史建筑等保护对象的保护规划。 历史文化名城、历史文化名镇、历史文化名村、历史文化街区保护规划应当自批准公布后一年内编制完成。 历史文化名城、历史文化名镇、历史文化名村的保护规划应当纳入相应层级的国…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (396, 'FBMCLI.10.4783869', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (397, 'FBMCLI.10.4783869', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、8 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (729, 397, 1179, '第十四条', '第十四条 【保护规划审批程序】 历史文化名城保护规划经历史文化名城保护工作委员会审议后，由市人民政府报省人民政府审批。 历史文化名镇、历史文化名村的保护规划经历史文化名城保护工作委员会审议后，由其所在地县（市）人民政府报省人民政府审批。 历…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (730, 397, 1177, '第十二条', '第十二条 【保护规划编制体系】 市人民政府负责组织编制本市历史文化名城、历史文化街区保护规划。 县（市）人民政府负责组织编制本行政区域内历史文化名镇、历史文化名村保护规划。 市住房和城乡建设主管部门负责组织编制历史地段、历史建筑等保护对象的…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (731, 397, 1200, '第三十五条', '…人民政府责令改正，对直接负责的主管人员和其他直接责任人员，依法给予处分： （一）未组织编制保护规划的； （二）未按照法定程序组织编制保护规划的； （三）擅自修改保护规划的； （四）未将批准的保护规划予以公布的。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (398, 'FBMCLI.10.4783869', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (732, 398, 1176, '第十一条', '第十一条 【预先保护制度】 在市、县（市）区人民政府开展的历史文化资源普查中，或者在有关单位和个人提供的线索中，发现具有一定保护价值而尚未纳入保护名录的历史文化资源，由其所在地县（市）区人民政府组织专家评估、论证，确定为预先保护对象。需要采…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (399, 'FBMCLI.10.4783869', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、6 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (733, 399, 1190, '第二十五条', '…方案，报市住房和城乡建设主管部门会同同级文物主管部门批准。 任何单位和个人不得损坏或者擅自迁移、拆除历史建筑。因公共利益需要进行建设活动，对历史建筑无法实施原址保护，必须迁移异地保护或者拆除的，应当由市、县（市）住房和城乡建设主管部门会同同级文物主管部门，报省有关部门审批，并按照有关技术标准和管理规定组织迁移、拆…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (734, 399, 1184, '第十九条', '…史文化名村、历史文化街区的核心保护范围内，除必要的基础设施和公共服务设施外，不得进行新建、扩建活动。在建设控制地带内，新建建筑物、构筑物应当符合保护规划确定的建设控制要求。 在保护范围内进行建设活动，应当保持与传统格局、历史风貌、空间尺度相协调，不得改变与其相依存的自然景观和环境。建设活动审批流程按照国家、省有关…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (735, 399, 1186, '第二十一条', '…历史建筑进行以下行为： （一）在历史建筑上刻划、涂污； （二）未经批准，对历史建筑进行外部修缮装饰、添加设施以及改变历史建筑的结构或者使用性质； （三）其他可能损坏历史建筑的行为。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (400, 'FBMCLI.10.4783869', 'FUND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (736, 400, 1169, '第四条', '…保护规划纳入国民经济和社会发展总体规划、国土空间规划，并将历史文化名城保护所需资金列入本级财政预算。 市、县（市）区住房和城乡建设主管部门会同同级文物、自然资源主管部门，负责本行政区域内历史文化名城保护规划的具体实施和监督管理等工作。 发展改革、工信、财政、生态环境、交通运输、农业农村、应急、林草等有关部门按照各自职…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (401, 'FBMCLI.10.4783869', 'COMP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (737, 401, 1176, '第十一条', '…行失效。 因预先保护对有关单位或者个人的合法权益造成损失的，市、县（市）区人民政府应当给予补偿。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (738, 401, 1192, '第二十七条', '第二十七条 【政府及有关部门的引导】 市、县（市）区人民政府可以通过减免租金、资金补助等政策引导社会资本和个人参与保护对象的保护和利用。 各级政府应当利用历史资源、自然及人文景观，鼓励具有地方特色的文化产业发展。推动旅游、文化体验、教育研学等产业发展。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (402, 'FBMCLI.10.4783869', 'RES', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (739, 402, 1179, '第十四条', '…名城保护工作委员会审议后，报市人民政府审批。 报送审批前组织编制机关应当公示规划草案，公开征求意见。公示时间不少于三十日，必要时可以举行听证。 组织编制机关应当在保护规划批准之日起三十日内，向社会公布。 保护规划批准后，不得擅自修改；确需修改的，应当广泛征求社会公众意见，并组织专家论证后，依照有关程序修改、报批并公布…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (403, 'FBMCLI.10.4783869', 'BIZ', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (404, 'FBMCLI.10.4783869', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (405, 'FBMCLI.10.4783869', 'SUP', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (406, 'FBMCLI.10.4783869', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (740, 406, 1194, '第二十九条', '…采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处五十万元以上一百万元以下罚款，对个人并处五万元以上十万元以下罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (741, 406, 1196, '第三十一条', '…或者采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处五万元以上十万元以下罚款，对个人并处一万元以上五万元以下罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (742, 406, 1198, '第三十三条', '…采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处二十万元以上五十万元以下罚款，对个人并处十万元以上二十万元以下罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (407, 'FBMCLI.10.4087861', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、11 个相关用语，关联 30 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (743, 407, 1205, '第二条', '…化名城的规划、保护、管理和利用等活动的，适用本条例。 历史文化名城的保护对象包括历史城区、历史文化街区、历史地段、历史建筑、文物、非物质文化遗产、传统地名、工业遗产、古树名木等。 法律、法规对文物、非物质文化遗产、古树名木等保护另有规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (744, 407, 1214, '第十一条', '…内的柳州府城为主，并向外扩展至包括柳侯公园和飞鹅路以北旧城区的历史城区； （二）以曙光西路历史文化街区、东门历史文化街区为代表的历史文化街区； （三）历史地段； （四）代表石器时代人类文化的白莲洞遗址、鲤鱼嘴遗址、柳江人遗址等不可移动文物；代表古代历史文化的柳侯祠碑刻、东门城楼、张翀及其母亲墓、鱼峰山马鞍山摩崖石刻等不可…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (745, 407, 1242, '第三十九条', '第三十九条 在历史城区、历史文化街区、历史地段、历史建筑保护范围内禁止下列行为： （一）开山、采石、开矿等破坏传统格局和历史风貌的活动； （二）占用保护规划确定保留的园林绿地、河湖水系、道路等； （三）修建生产和储存爆炸性、易燃性、放射性、毒害性、腐蚀性物…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (408, 'FBMCLI.10.4087861', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (746, 408, 1224, '第二十一条', '第二十一条 历史地段、历史建筑保护规划应当包括保护原则、保护内容、保护要求、保护范围，核心保护范围和建设控制地带区域划分和界定，保护措施、开发强度和建设控制要求，保护规划分期实施方案等内容，历史建筑保护规划还应当包括规划管控核心要素和保护修缮引导图则。 历史建筑保护规划应当根据历史、文化、科学、艺术等不…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (747, 408, 1228, '第二十五条', '…设施、公共服务设施和居住环境等。 现状以居住功能为主的历史文化街区和历史地段，应当控制核心保护范围的人口规模，有计划地引导核心保护范围内的单位和人口向外分流，使人口密度达到合理水平；核心保护范围内的土地使用权不得实施整体转让用于商业地产开发。 第四章 保护措施', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (748, 408, 1237, '第三十四条', '第三十四条 住房和城乡建设主管部门应当对历史文化街区、历史地段、历史建筑的核心保护范围内的建筑物、构筑物结构安全进行监管，发现建筑物、构筑物有损毁危险的，应当及时通知其所有权人、使用权人或者代管人按照相关规定履行修缮义务。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (409, 'FBMCLI.10.4087861', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 31 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (749, 409, 1229, '第二十六条', '…管人的，其使用权人为保护责任人；代管人、使用权人均不明确的，历史建筑所在地的住房和城乡建设主管部门为保护责任人。历史建筑属于非国有历史建筑的，其所有权人为保护责任人；所有权人下落不明、无法与所有权人取得联系或者房屋权属不明晰的，使用权人是保护责任人；所有权人下落不明、无法与所有权人取得联系或者房屋权属不明晰的，使用权…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (750, 409, 1231, '第二十八条', '…共空间的风貌管理和提升； （四）组织开展日常巡查，及时劝止危害历史文化遗产行为，并告知相关主管部门； （五）市人民政府确定的其他职责。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (751, 409, 1237, '第三十四条', '第三十四条 住房和城乡建设主管部门应当对历史文化街区、历史地段、历史建筑的核心保护范围内的建筑物、构筑物结构安全进行监管，发现建筑物、构筑物有损毁危险的，应当及时通知其所有权人、使用权人或者代管人按照相关规定履行修缮义务。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (410, 'FBMCLI.10.4087861', 'COORD', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (752, 410, 1208, '第五条', '… 区人民政府负责本行政区域内历史文化名城的保护和监督管理工作，建立城区历史文化名城保护工作协调机制。 乡（镇）人民政府、街道办事处按照本条例的规定要求，履行历史文化名城保护的相关职责。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (411, 'FBMCLI.10.4087861', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 14 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (753, 411, 1225, '第二十二条', '第二十二条 历史城区、历史地段、历史建筑等保护规划由市人民政府审批。在报送审批前，组织编制机关应当依法将保护规划草案予以公示，并采取论证会、听证会或者其他方式征求专家和公众意见，公示时间不少于三十日。 保护规划报送审批文件中应当附具意见采纳情况及理由；经听证的，还应当附…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (754, 411, 1226, '第二十三条', '第二十三条 经依法批准的保护规划，不得擅自修改；确需修改的，保护规划的组织编制机关应当向原审批机关提出专题报告，经同意后，方可编制修改方案。修改后的保护规划，应当按照原审批程序报送审批。 保护对象从保护名录中撤销的，保护规划中相应的内容自行失效。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (755, 411, 1254, '第五十一条', '…责任人员，依法给予处分；构成犯罪的，依法追究刑事责任。 （一）未按照法定程序组织编制、修改保护规划和确定、调整保护名录的； （二）未按照法定程序或者未按照保护规划的要求履行审批职责的； （三）未依法对保护对象的保护状况实施监督检查，或者对经批准的保护对象的改造、利用情况监管不力的； （四）未依法受理举报、控告和查处违…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (412, 'FBMCLI.10.4087861', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (756, 412, 1246, '第四十三条', '…门、城乡规划主管部门初步确认，并经市人民政府同意后，可以参照本条例的有关规定依法采取必要的预先保护措施。 预先保护期限为自发出预先保护通知之日起最长不超过十二个月，逾期则预先保护自行失效。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (413, 'FBMCLI.10.4087861', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、6 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (757, 413, 1236, '第三十三条', '第三十三条 历史建筑应当原址保护，任何单位、个人不得损坏或者擅自迁移、拆除。因公共利益需要无法实施原址保护的，应当按照国家和自治区有关规定办理相关审批手续。 经批准迁移或者拆除历史建筑的，建设单位应当按照规定形成历史建筑测绘、图像等资料，报市住房和城乡建设主管部门备案。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (758, 413, 1221, '第十八条', '…等； （三）使用现状和权属变化情况； （四）保护规划； （五）设计、测绘信息资料； （六）修缮、维修、迁移、拆除过程中形成的文字、图纸、图片和影像等资料； （七）其他需要保存的资料。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (759, 413, 1234, '第三十一条', '第三十一条 修缮历史建筑应当符合有关技术规范、质量标准和修缮图则的要求。 历史建筑修缮前，保护责任人可以向市、区住房和城乡建设主管部门提出修缮技术咨询，市、区住房和城乡建设主管部门应当免费提供咨询服务。市、区住房和城乡建设主管部门可以根…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (414, 'FBMCLI.10.4087861', 'FUND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (760, 414, 1210, '第七条', '…条 市、区人民政府应当将历史文化名城的保护工作纳入本级国民经济和社会发展规划，历史文化名城保护经费列入本级预算。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (415, 'FBMCLI.10.4087861', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (761, 415, 1249, '第四十六条', '…文化遗产传承和利用等具有地方特色的生产经营活动； （二）通过政策引导、资金扶助、费用减免、奖励等方式鼓励社会资本和个人投入保护利用； （三）设立管理运营企业或组织，对历史文化资源进行整合、挖掘和宣传； （四）采取政府收购、产权置换等方式对非国有历史建筑进行保护利用； （五）通过授权或者委托符合条件的企事业单位、研…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (762, 415, 1251, '第四十八条', '…播非物质文化遗产代表性项目的代表性传承人，市、区人民政府可以采取命名、授予称号、表彰奖励、资助扶持等方式予以鼓励和支持。 非物质文化遗产代表性传承人，应当发掘、收集、整理非物质文化遗产的珍贵资料，培养传承人，积极组织和参与相关展示、展演活动。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (763, 415, 1212, '第九条', '第九条 鼓励单位和个人通过捐赠、资助、投资、成立公益性组织、提供技术支持、开展志愿者活动等多种方式，依法参与历史文化名城保护工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (416, 'FBMCLI.10.4087861', 'RES', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (764, 416, 1225, '第二十二条', '…由市人民政府审批。在报送审批前，组织编制机关应当依法将保护规划草案予以公示，并采取论证会、听证会或者其他方式征求专家和公众意见，公示时间不少于三十日。 保护规划报送审批文件中应当附具意见采纳情况及理由；经听证的，还应当附具听证笔录。 保护规划应当自批准之日起二十日内，在政府网站和主要新闻媒体上公布，接受公众查询和…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (765, 416, 1259, '第五十六条', '…景资料 立法草案 柳州市人大常委会法制工作委员会关于《柳州市历史文化名城保护条例(草案)》征求意见的公告 本篇引用的法规 中央法规 中华人民共和国城乡规划法(2019修正) 中华人民共和国文物保护法(2017修正) 历史文化名城名镇名村保护条例(2017修订) 引用本篇的法规 案例 论文 地方法规规章 柳州市人民政府…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (417, 'FBMCLI.10.4087861', 'BIZ', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (766, 417, 1249, '第四十六条', '…市、区人民政府可以采取以下措施促进保护对象的合理利用： （一）对历史文化街区、历史地段进行业态策划，鼓励开展当地传统手工业、特色产业、非物质文化遗产传承和利用等具有地方特色的生产经营活动； （二）通过政策引导、资金扶助、费用减免、奖励等方式鼓励社会资本和个人投入保护利用； （三）设立管理运营企业或组织，对历史文化…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (767, 417, 1227, '第二十四条', '…门组织编制基础设施、公共服务设施、住房建设、环境保护、城市交通、绿地系统、旅游、河湖水系、商业网点等有关专项规划，应当与历史文化名城保护规划和各类保护对象的保护规划相衔接。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (768, 417, 1228, '第二十五条', '…单位和人口向外分流，使人口密度达到合理水平；核心保护范围内的土地使用权不得实施整体转让用于商业地产开发。 第四章 保护措施', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (418, 'FBMCLI.10.4087861', 'DIG', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (769, 418, 1222, '第十九条', '第十九条 组织保护对象认定的主管部门应当建立和维护保护对象专题数据库，依据各自职责采集、整理、录入相关信息。乡（镇）人民政府、街道办事处配合开展相应信息采集工作。 各有关部门收集的涉及历史文化名城保护的相关信息数据应当共享并纳入市国土空间基础信息平台。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (419, 'FBMCLI.10.4087861', 'SUP', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (770, 419, 1213, '第十条', '第十条 任何单位和个人都有保护历史文化遗产的义务，有权对破坏、损害保护对象的行为进行劝阻、举报和投诉。 市、区住房和城乡建设、城乡规划、文物等主管部门应当公布举报方式，接受举报、投诉，并及时核实、处理。 市、区人民政府对在历史文化名城保护工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰和奖励。 第二章 保…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (771, 419, 1254, '第五十一条', '…保护状况实施监督检查，或者对经批准的保护对象的改造、利用情况监管不力的； （四）未依法受理举报、控告和查处违法行为的； （五）未为保护对象设置保护标志牌的； （六）其他玩忽职守、滥用职权、徇私舞弊的行为。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (420, 'FBMCLI.10.4087861', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (772, 420, 1254, '第五十一条', '第五十一条 违反本条例规定，国家机关有下列情形之一的，由市、区人民政府或有关主管部门责令改正，对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任。 （一）未按照法定程序组织编制、修改保护规划和确定、调整保护名录的； （二）未按照法定程序或者未按照保护规划的要求履行审批职责的； （…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (773, 420, 1252, '第四十九条', '…的体验式旅游、研学旅行、休闲旅游等精品线路，推动历史文化传承与旅游产业融合发展。 第六章 法律责任', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (774, 420, 1253, '第五十条', '第五十条 违反本条例规定的行为，法律法规已有法律责任规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (421, 'FBMCLI.10.1640280', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 8 个核心用语、11 个相关用语，关联 21 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (775, 421, 1261, '第二条', '…城保护的重点是历史城区，包括现存汀州古城墙及其遗址所围合的原汀州古城，以及汀江东畔的水东街历史文化街区，并适当向外拓展，具体范围由长汀历史文化名城保护规划确定并公告。 长汀历史文化名城的保护对象包括三山（卧龙山、拜相山和南屏山）、两水（汀江和西河）、一轴（城市中轴线）、三圈（城墙圈、卧龙山南盆地圈和周边山峦围合圈）的城址…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (776, 421, 1306, '第四十七条', '第四十七条 本条例下列用语的含义： （一）历史地段，包括历史文化街区和历史风貌区，是指历史城区内存有较多的文物古迹或者成片的传统风貌建筑，能较完整、真实地体现长汀传统街巷特色，并具有一定规模的地段。 （二）历史文化街区，是指历史城区内保存文物特别丰富、历史建筑和传统风貌建筑集中成片、能够…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (777, 421, 1287, '第二十八条', '第二十八条 法律、法规对文物、历史建筑、古树名木、非物质文化遗产等保护对象的保护责任人及其保护责任已有规定的，从其规定。 国有传统风貌建筑的保护责任人为使用人。非国有传统风貌建筑的保护责任人为所有权人；所有权人下落不明或者权属不清的，由实际使用人或者管理人承…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (422, 'FBMCLI.10.1640280', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (778, 422, 1280, '第二十一条', '第二十一条 历史文化街区应当按照保护规划，划定核心保护范围和建设控制地带，并按照下列要求进行保护： （一）控制街区周边的景观环境，保持街区原有的空间格局与尺度，不得改变街巷肌理； （二）街区的核心保护范围内，除必要的基础设施和公共服务设施以外，不得进行新建、扩建活动； （三）街…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (779, 422, 1290, '第三十一条', '第三十一条 禁止在长汀历史文化名城保护范围内从事下列活动： （一）占用保护规划确定保留的园林绿地、河流水系、传统街巷、道路等； （二）擅自设置户外广告； （三）擅自设置、移动或者涂改、损毁保护标志； （四）擅自迁移或者拆除传统风貌建筑、历史建筑和文物保护单位； …', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (780, 422, 1261, '第二条', '…史建筑、传统风貌建筑、古树名木、非物质文化遗产和其他具有保护价值的对象。 长汀历史文化名城保护范围内的文物、历史建筑、古树名木、非物质文化遗产等的保护，法律、法规另有规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (423, 'FBMCLI.10.1640280', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (781, 423, 1302, '第四十三条', '…统风貌建筑损毁、坍塌的。 国有传统风貌建筑的保护责任人有前款规定情形的，由所在单位或者上级主管部门责令停止违法行为、限期恢复原状或者采取其他补救措施；逾期不改正造成严重后果的，对直接负责的主管人员和其他直接责任人员，依法给予处分。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (782, 423, 1305, '第四十六条', '第四十六条 违反本条例规定，县人民政府和有关主管部门及其工作人员不履行监督管理职责，发现违法行为不查处，或者有其他玩忽职守、滥用职权、徇私舞弊行为的，由其所在单位或者上级主管部门、监察机关责令改正，通报批评；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (783, 423, 1263, '第四条', '第四条 市人民政府及其有关主管部门负责对长汀历史文化名城的保护管理工作进行监督和指导，并根据实际情况依法给予相关政策支持。 长汀县人民政府（以下简称县人民政府）负责长汀历史文化名城的规划、保护、管理和利用工作，并将其纳入长汀县国民经济和社会发展规划，所需…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (424, 'FBMCLI.10.1640280', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (425, 'FBMCLI.10.1640280', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 20 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (784, 425, 1271, '第十二条', '第十二条 县人民政府组织编制历史文化名城保护规划（以下简称保护规划），并将保护规划依法报批和备案。 县人民政府应当依据保护规划，组织编制历史文化街区保护等规划，并按照规定报请批准。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (785, 425, 1276, '第十七条', '第十七条 县人民政府住房和城乡建设主管部门应当依据保护规划相关要求，组织编制历史城区和长汀历史文化名城其他重点地区的城市设计，报县人民政府审批。 重点地段城市设计的内容应当纳入国土空间详细规划，并落实到国土空间详细规划相关指标中。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (786, 425, 1272, '第十三条', '第十三条 组织编制机关应当将历史文化名城、历史文化街区的保护规划方案，在政府网站或者本县主要新闻媒体上公告，并采取论证会、听证会或者其他方式征求专家和公众的意见。 保护规划草案的公告时间不少于三十日。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (426, 'FBMCLI.10.1640280', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (427, 'FBMCLI.10.1640280', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、5 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (787, 427, 1279, '第二十条', '…）不得违反规划新建、改建、扩建建（构）筑物。不符合保护规划要求的建（构）筑物，逐步改造或者拆除。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (788, 427, 1290, '第三十一条', '…（四）擅自迁移或者拆除传统风貌建筑、历史建筑和文物保护单位； （五）擅自对历史建筑进行外部修缮装饰、添加设施以及改变建筑的结构或者使用性质； （六）擅自拆除历史建筑中具有历史、艺术、科学价值的砖、木、石雕等建筑构件； （七）擅自改变传统风貌建筑和历史建筑原有的高度、体量、外观形象以及色彩； （八）在历史建筑、古树…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (789, 427, 1280, '第二十一条', '…的基础设施和公共服务设施以外，不得进行新建、扩建活动； （三）街区的建设控制地带内，新建、改建、扩建建（构）筑物应当符合历史文化街区风貌保护和视觉景观要求，其高度、形式、体量、色彩和风格应当与街区风貌、特色相协调； （四）逐步搬迁街区内不符合保护规划、影响传统风貌的工厂、仓库。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (428, 'FBMCLI.10.1640280', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (790, 428, 1263, '第四条', '…名城的规划、保护、管理和利用工作，并将其纳入长汀县国民经济和社会发展规划，所需经费列入本级财政预算。 乡（镇）人民政府、街道办事处负责做好本辖区内的长汀历史文化名城的保护和管理工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (791, 428, 1265, '第六条', '…城保护利用专项规划，并研究制定相关实施方案； （三）会同有关部门编制、申报历史文化名城保护专项资金，并监督专项资金的使用； （四）组织审核历史文化名城的业态规划，审核街肆景观、店牌店招设计等方案，审核历史文化名城工程建设方案，并对实施情况进行监督； （五）协调并配合有关部门查处违反历史文化名城保护规定的违法违规行为；…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (792, 428, 1289, '第三十条', '…议搬迁的，县人民政府应当给予资金补助。 前两款规定的补偿、补助费用纳入长汀历史文化名城保护专项资金中统筹解决。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (429, 'FBMCLI.10.1640280', 'COMP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (793, 429, 1289, '第三十条', '第三十条 县人民政府应当建立历史城区保护补偿制度，因政府进行历史城区保护，单位和个人的合法权益受到损害，造成财产损失的，应当依法给予公平、合理的补偿。 传统风貌建筑保护责任人按照保护规划、技术标准和规范要求进行修缮、保养、维护，或者房屋所有权人和公有房使用人积极配…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (430, 'FBMCLI.10.1640280', 'RES', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (794, 430, 1267, '第八条', '第八条 县人民政府应当建立健全长汀历史文化名城保护工作重大事项听证制度，对属于名城保护规划、确定历史地段和传统风貌建筑保护名录等方面的重大事项，应当邀请专家和公众代表参与听证；听证结果应当作为决策的重要参考。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (795, 430, 1272, '第十三条', '…文化名城、历史文化街区的保护规划方案，在政府网站或者本县主要新闻媒体上公告，并采取论证会、听证会或者其他方式征求专家和公众的意见。 保护规划草案的公告时间不少于三十日。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (796, 430, 1307, '第四十八条', '…长汀水土流失区生态文明建设促进条例(草案)》《龙岩市长汀历史文化名城保护条例(草案)》公开征求意见的公告 本篇引用的法规 中央法规 中华人民共和国文物保护法(2017修正) 历史文化名城名镇名村保护条例(2017修订) 地方法规 福建省历史文化名城名镇名村和传统村落保护条例', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (431, 'FBMCLI.10.1640280', 'BIZ', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (797, 431, 1292, '第三十三条', '…象的合理利用。 鼓励社会力量合理利用历史资源发展符合保护规划的产业，从事符合产业布局规划的经营活动。 保护对象的合理利用，应当充分挖掘文化内涵，支持开展文化创意、休闲旅游、文化研究、传统手工业、非物质文化遗产传播、文化体验，以及开办展览馆、博物馆、民宿客栈、酒吧、茶座、咖啡屋等特色经营活动或者公益活动。 历史文化名城…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (798, 431, 1265, '第六条', '…门编制、申报历史文化名城保护专项资金，并监督专项资金的使用； （四）组织审核历史文化名城的业态规划，审核街肆景观、店牌店招设计等方案，审核历史文化名城工程建设方案，并对实施情况进行监督； （五）协调并配合有关部门查处违反历史文化名城保护规定的违法违规行为； （六）参与编制利用历史文化名城资源的旅游规划，组织开展历…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (799, 431, 1295, '第三十六条', '第三十六条 历史城区的产业业态应当符合保护规划的要求。 县人民政府应当依法制定产业引导、控制和禁止目录，支持发展科技创意、文化旅游、特色商贸等现代服务业和总部经济，提升文化传承、旅游休闲和传统产业发展等功能。 合理保留并优化提升教育、科学、文化、卫生…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (432, 'FBMCLI.10.1640280', 'DIG', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (800, 432, 1265, '第六条', '…相关文史资料； （七）负责组织编制和调整历史文化名城保护名录，建立完善历史文化名城保护名录数据库； （八）指导历史文化名城行业人才队伍建设、考核，对从业人员开展教育培训； （九）县人民政府赋予的其他职责。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (433, 'FBMCLI.10.1640280', 'SUP', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (801, 433, 1269, '第十条', '…何单位和个人都有保护历史文化名城的义务，有权对破坏历史文化名城保护的各类违法行为进行劝阻、举报和控告。 县人民政府及其有关部门、名城保护管理机构应当加强历史文化名城保护的宣传教育，普及保护知识，增强社会公众的保护意识，通过成立公益性保护组织、开展志愿服务活动等方式，引导全民参与长汀历史文化名城保护。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (802, 433, 1266, '第七条', '第七条 长汀历史文化名城保护管理机构设立历史文化名城保护专家委员会。 专家委员会由规划、房屋、建筑、园林、文化（文物）、旅游、宗教、历史、地名、民俗、法律和传统工艺等方面的专家组成，对历史文化名城保护名录、保护规划、保护措施、建设管理等事项进行论证，并提供保护管理对策建议。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (434, 'FBMCLI.10.1640280', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (803, 434, 1302, '第四十三条', '…违法行为、限期恢复原状或者采取其他补救措施；造成严重后果的，对单位处以五万元以上十万元以下罚款，对个人处以一万元以上五万元以下罚款；有违法所得的，没收违法所得；造成损失的，依法承担赔偿责任： （一）非国有传统风貌建筑的保护责任人未按照传统风貌建筑保护图则对传统风貌建筑进行保养维护、修缮，造成传统风貌建筑的格局、高…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (804, 434, 1304, '第四十五条', '…县人民政府确定的监督管理部门责令改正；拒不改正的，责令停产停业，并处二万元以上十万元以下的罚款；有违法所得的，没收违法所得；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (805, 434, 1301, '第四十二条', '第四十二条 违反本条例规定的行为，法律、法规已有法律责任规定的，从其规定；构成犯罪的，依法追究刑事责任。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (435, 'FBMCLI.10.1681552', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、11 个相关用语，关联 18 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (806, 435, 1356, '第四十九条', '…历史价值或者纪念意义的、能较完整地反映一些历史时期传统风貌和地方民族特色的镇和村。 （三）历史文化街区，是指经省人民政府核定公布的保存文物特别丰富、历史建筑集中成片、能够较完整和真实地体现传统格局和历史风貌，并具有一定规模的历史地段。 （四）传统风貌区，是指经市人民政府核定公布，保存历史建筑集中成片，建筑样式、空间结构和…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (807, 435, 1310, '第三条', '第三条 历史文化名城保护对象包括历史城区，历史文化名镇、名村、街区，传统风貌区、历史建筑，文物、古树名木、非物质文化遗产等。 在历史文化名城保护范围内涉及文物、古树名木、非物质文化遗产等保护的，执行有关法律、法规的规定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (808, 435, 1329, '第二十二条', '…事建设活动，不得影响历史城区，历史文化名镇、名村及其历史环境要素的传统风貌和格局，不得破坏历史文化街区、传统风貌区的完整性，不得破坏历史建筑的结构、原有风貌。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (436, 'FBMCLI.10.1681552', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (809, 436, 1325, '第十八条', '第十八条 保护规划应当划定保护对象的保护范围。 历史城区，历史文化名镇、名村、街区，传统风貌区的保护规划应当划定核心保护范围和建设控制地带，并设立界标，向社会公布。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (810, 436, 1341, '第三十四条', '…础设施的，由有关部门组织制订专项措施，经专家评审后公布实施。 历史文化名镇、名村、街区核心保护范围内的消防设施、消防通道，应当按照有关的消防技术标准和规范设置。确因保护需要，无法按照标准和规范设置的，由消防主管部门会同相关主管部门制订相应的防火安全保障方案。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (811, 436, 1332, '第二十五条', '第二十五条 历史城区，历史文化名镇、名村、街区，传统风貌区核心保护范围内，除必要的基础设施和公共服务设施建设外，不得从事新建、扩建活动。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (437, 'FBMCLI.10.1681552', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 23 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (812, 437, 1335, '第二十八条', '第二十八条 实行保护责任人制度。历史文化名城保护对象的责任人按照下列规定确定： （一）历史文化名镇、名村、街区，传统风貌区的保护责任人为所在地县（市、区）人民政府；县（市、区）人民政府设立了保护管理机构的，该机构按照批准的职责履行保护责任； （二…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (813, 437, 1354, '第四十七条', '…本条例规定，不履行历史文化名城保护职责，造成严重后果的，由同级人民政府、监察机关追究该行政主管部门主要负责人的责任。 在历史文化名城保护工作中，工作人员玩忽职守、滥用职权、徇私舞弊的，由其所在单位或者上级主管部门、监察机关给予处分；构成犯罪的，依法追究刑事责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (814, 437, 1313, '第六条', '第六条 自然资源和规划主管部门负责历史文化名城保护规划管理工作，并组织实施本条例。 文物主管部门负责历史文化名城保护涉及的文物保护与管理工作。 住房和城乡建设主管部门负责历史文化名城保护涉及的建设管理工作。 其他有关部门依据各自职责，共同做好相关保护…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (438, 'FBMCLI.10.1681552', 'COORD', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (815, 438, 1319, '第十二条', '…历史资料信息，建立档案，并持续补充完善，将历史文化名城保护信息纳入全市大数据管理系统，实现信息共享。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (439, 'FBMCLI.10.1681552', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、7 个相关用语，关联 15 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (816, 439, 1327, '第二十条', '第二十条 保护规划依照法律、法规以及有关规定报批后，不得擅自调整；确需调整的，由保护规划编制部门依照法定权限和程序进行修改和报批，并向社会公布。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (817, 439, 1326, '第十九条', '第十九条 编制保护规划应当经专家论证，并向社会公示，征求社会公众意见，必要时可以举行听证，公示时间不得少于三十日。 保护规划编制部门应当在报送审批的材料中附具专家和公众意见采纳情况及理由；经听证的，还应当附具听证笔录。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (818, 439, 1323, '第十六条', '…见证洛阳发展历史，具有地方特色的； （五）其他具有历史文化意义的建筑物、构筑物。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (440, 'FBMCLI.10.1681552', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (819, 440, 1356, '第四十九条', '…地域文化特点，文物古迹以及历史建筑用地不足百分之六十的地区，尚不具备历史文化街区条件，或者尚未核定公布为历史文化街区的区域。 （五）历史建筑，是指经市、县（市）人民政府确定公布的具有一定保护价值，能够反映历史风貌和地方特色的建筑物、构筑物。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (441, 'FBMCLI.10.1681552', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、5 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (820, 441, 1331, '第二十四条', '第二十四条 在保护范围内，违法建筑物、构筑物以及其他设施应当依法予以拆除，不符合保护规划要求的建筑物、构筑物以及其他设施，应当逐步改造或者搬迁。 在保护范围内，拆除不可移动文物、历史建筑以外的建筑物、构筑物以及其他设施的，应当向所在地自然资源和规划主管部门提出申请。自然资源和规划主管部门接到…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (821, 441, 1334, '第二十七条', '第二十七条 在历史文化名镇、名村、街区，传统风貌区建设控制地带内，新建、改建、扩建建筑物、构筑物以及其他设施的，其高度、体量、形态、风格、色彩等，应当与传统格局和历史风貌保持一致，符合保护规划。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (822, 441, 1340, '第三十三条', '…三十三条 市自然资源和规划主管部门应当会同文物、住房和城乡建设等主管部门组织编制历史建筑的修缮技术规范，并定期开展技术指导和培训。 对历史建筑进行外部修缮装饰、添加设施以及改变历史建筑的结构或者使用性质的，应当经自然资源和规划主管部门会同同级文物主管部门批准，并依照有关法律、法规的规定办理手续。 在保护范围内，需…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (442, 'FBMCLI.10.1681552', 'FUND', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (823, 442, 1314, '第七条', '…乡（镇）人民政府应当将历史文化名城保护工作纳入本级国民经济和社会发展规划，所需经费列入本级财政预算。 鼓励和支持企事业单位、社会团体和个人通过捐赠、投资、设立基金、提供服务等方式参与历史文化名城保护工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (824, 442, 1357, '第五十条', '…文物博物馆事业创新发展规划的通知 洛阳市人民政府办公室关于印发洛阳市历史文化名城和文物保护专项资金管理办法的通知 更多', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (443, 'FBMCLI.10.1681552', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (825, 443, 1338, '第三十一条', '…筑的维护修缮费用。 所有权人承担维护修缮费用确有困难的，可以向县（市、区）人民政府申请资金补助和设计方案援助，或者由县（市、区）人民政府进行产权置换、收购，予以维护修缮。 维护修缮资金补助的程序和标准，由市、县（市、区）人民政府制定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (826, 443, 1315, '第八条', '…以及有关部门应当按照相关规定，对在历史文化名城保护工作中做出突出贡献的单位和个人给予表彰和奖励。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (827, 443, 1339, '第三十二条', '第三十二条 对单位或者个人因历史文化名城保护而遭受到经济损失的，应当给予合理补偿，具体补偿办法由市人民政府制定。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (444, 'FBMCLI.10.1681552', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (828, 444, 1326, '第十九条', '第十九条 编制保护规划应当经专家论证，并向社会公示，征求社会公众意见，必要时可以举行听证，公示时间不得少于三十日。 保护规划编制部门应当在报送审批的材料中附具专家和公众意见采纳情况及理由；经听证的，还应当附具听证笔录。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (445, 'FBMCLI.10.1681552', 'BIZ', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (829, 445, 1347, '第四十条', '第四十条 在历史文化街区内开展经营活动的，应当符合历史文化街区保护规划确定的业态布局要求。 鼓励整理、挖掘和利用历史文化资源，开发具有地方传统特色的文化艺术产品；支持利用历史文化名镇、名村、街区，传统风貌区等开展文化创意、文化研究、文化体验、休闲旅游等活动，开展符合保护规划的文化展览、手工业等传统特…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (446, 'FBMCLI.10.1681552', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (447, 'FBMCLI.10.1681552', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (830, 447, 1315, '第八条', '第八条 任何单位和个人有权对损害历史文化名城的行为进行劝阻、投诉和举报。 市、县（市、区）、乡（镇）人民政府、街道办事处及自然资源和规划、文物、住房和城乡建设等主管部门应当公布举报方式，接受投诉、举报，并及时核实、处理。 市、县（市、区）、乡（镇）人民政府以及有关部门应当按照相关规定，对在…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (448, 'FBMCLI.10.1681552', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (831, 448, 1350, '第四十三条', '…取其他补救措施，所需费用由责任人承担；造成严重后果的，对单位并处五十万元以上一百万元以下的罚款，对个人并处五万元以上十万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (832, 448, 1351, '第四十四条', '…者采取其他补救措施，所需费用由责任人承担；造成严重后果的，对单位并处五万元以上十万元以下的罚款，对个人并处一万元以上五万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (833, 448, 1352, '第四十五条', '…取其他补救措施，所需费用由责任人承担；造成严重后果的，对单位并处二十万元以上五十万元以下的罚款，对个人并处十万元以上二十万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (449, 'FBMCLI.10.4621790', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、10 个相关用语，关联 26 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (834, 449, 1359, '第二条', '…历史文化名城的规划、保护、管理和利用等，适用本条例。 历史文化名城的保护对象包括历史城区、历史文化街区、名镇、名村和传统村落、世界文化遗产、不可移动文物、历史建筑、传统风貌建筑、非物质文化遗产等。历史城区是指泉州古城和丰州古城。 历史文化名城中涉及历史文化名镇、名村和传统村落、世界文化遗产、不可移动文物、传统风貌建筑、非…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (835, 449, 1375, '第十八条', '第十八条 在历史城区、历史文化街区保护范围内，禁止进行下列活动： （一）开山、采石、采砂、开矿、毁林开荒等破坏传统格局和历史风貌的； （二）占用保护规划确定保留的园林绿地、古树名木、河湖水系、道路等； （三）修建生产、储存爆炸性、易燃性、放射性、毒害性、…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (836, 449, 1400, '第四十三条', '第四十三条 本条例所称历史文化街区是指经省人民政府或者国家部委批准公布的，保存文物特别丰富、历史建筑集中成片、能够较完整和真实地体现传统格局和历史风貌，并具有一定规模的区域。 本条例所称历史建筑是指经市人民政府确定公布的市辖区具有一定保护价值，能够反映历…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (450, 'FBMCLI.10.4621790', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、6 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (837, 450, 1367, '第十条', '第十条 自然资源和规划、住房和城乡建设主管部门按职权划定： （一）历史城区保护范围； （二）历史文化街区核心保护范围和建设控制地带； （三）历史建筑保护范围。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (838, 450, 1372, '第十五条', '第十五条 县（市、区）人民政府应当在历史城区和历史文化街区核心保护范围的主要出入口以及历史建筑的外部醒目位置设置保护标志。保护标志由市人民政府统一样式，并与周边传统风貌相协调。 任何单位和个人不得擅自设置、移动、涂改或者损毁保护标志。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (839, 450, 1377, '第二十条', '第二十条 除必要的基础设施和公共服务设施以外，在历史文化街区核心保护范围内，不得进行新建、扩建活动。 在建设控制地带内的新建建（构）筑物，应当符合保护规划确定的建设控制要求。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (451, 'FBMCLI.10.4621790', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 25 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (840, 451, 1361, '第四条', '…府（街道办事处）履行巡查职责，发现违反历史文化名城保护规定的行为，应当及时制止，并报告有关主管部门。 村（居）民委员会可以根据本条例制定村（居）规民约，建立群众性保护组织，开展社区营造活动，协助做好历史文化名城保护工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (841, 451, 1383, '第二十六条', '…确需修复的，所有权人或者其他保护责任人应当按照保护要求编制修复设计方案，报市自然资源和规划主管部门，并按规定程序审批后，按原建筑风貌形态、空间格局修复。 历史建筑修缮、加固、修复等具体办法由市人民政府组织制定并公布。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (842, 451, 1362, '第五条', '第五条 住房和城乡建设主管部门会同文化旅游主管部门负责历史文化名城保护与管理的具体工作。 自然资源和规划主管部门负责历史文化名城保护的建设规划管理工作。 文化旅游主管部门负责世界文化遗产、不可移动文物、非物质文化遗产保护的监督管理工作。 发展和改革、…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (452, 'FBMCLI.10.4621790', 'COORD', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (843, 452, 1389, '第三十二条', '第三十二条 市、县（市、区）人民政府应当建立联合执法机制，加强历史文化名城保护利用的监督检查，及时制止、依法查处违法行为。 第四章 合理利用', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (453, 'FBMCLI.10.4621790', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、7 个相关用语，关联 12 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (844, 453, 1366, '第九条', '第九条 市人民政府负责组织编制历史文化名城和市辖区内历史文化街区的保护规划。县级人民政府负责组织编制市辖区外历史文化街区的保护规划。 编制历史文化名城和历史文化街区保护规划应当充分考虑世界文化遗产保护规划的特殊规定。 历史文化名城和历史文化街区保护规划经依法报请批准后，作为实施历史文化名城、历…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (845, 453, 1368, '第十一条', '第十一条 历史文化名城、历史文化街区保护规划涉及空间管控要求的，应当纳入同级国土空间规划，并入国土空间基础信息平台统一管理。 城市交通、市政、绿地、旅游、消防、人防等专项规划应当与保护规划相协调。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (846, 453, 1369, '第十二条', '第十二条 市、县（市、区）人民政府应当加强历史文化名城保护规划实施情况的监督检查，建立历史文化名城保护评估机制，每五年对保护情况进行一次评估，评估情况向同级人民代表大会常务委员会报告。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (454, 'FBMCLI.10.4621790', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (847, 454, 1370, '第十三条', '…经住房和城乡建设主管部门会同文化旅游主管部门初步确认具有保护价值的，可以参照本条例有关规定先予保护，并依法启动申报认定程序。 任何单位和个人可以向所在地的县（市、区）人民政府提出申报历史文化街区、历史建筑的建议。 市、县（市、区）住房和城乡建设主管部门应当对纳入保护名录的历史文化街区、历史建筑建立保护档案。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (455, 'FBMCLI.10.4621790', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (848, 455, 1382, '第二十五条', '第二十五条 非国有历史建筑的维护、修缮，市、县（市、区）人民政府可以给予资金补助。 非国有历史建筑有损毁危险，保护责任人确有经济困难无法履行抢救保护义务的，市、县（市、区）人民政府应当采取资金补助等措施进行保护；具备保护能力而未履行保护义务的，市、县（市、区…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (849, 455, 1383, '第二十六条', '…报市自然资源和规划主管部门，并按规定程序审批后，按原建筑风貌形态、空间格局修复。 历史建筑修缮、加固、修复等具体办法由市人民政府组织制定并公布。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (850, 455, 1384, '第二十七条', '…会同市文化旅游主管部门批准。 因公共利益需要进行建设活动，对历史建筑无法实施原址保护、必须迁移异地保护的，应当由市住房和城乡建设主管部门会同市文化旅游主管部门提出意见，经市人民政府同意后，按程序报省级相关主管部门批准。 历史建筑原址保护、迁移所需费用，由建设单位列入建设工程预算。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (456, 'FBMCLI.10.4621790', 'FUND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (851, 456, 1363, '第六条', '第六条 市、县（市、区）人民政府应当建立历史文化名城保护的资金保障机制，多渠道筹集保护资金，用于保护对象的普查认定、维护修缮、抢险利用以及基础设施、人居环境改善优化等相关工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (457, 'FBMCLI.10.4621790', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (852, 457, 1391, '第三十四条', '第三十四条 市、县（市、区）人民政府应当通过资金资助、产权置换、以修代租等支持方式，促进历史建筑的保护利用。 历史建筑的利用应当符合保护图则以及消防安全等专业管理的要求，并与其历史价值、内部结构相适应，不得擅自改变历史建筑主体结构、主要平面布局和外观，不得危害历史建筑及其…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (853, 457, 1382, '第二十五条', '第二十五条 非国有历史建筑的维护、修缮，市、县（市、区）人民政府可以给予资金补助。 非国有历史建筑有损毁危险，保护责任人确有经济困难无法履行抢救保护义务的，市、县（市、区）人民政府应当采取资金补助等措施进行保护；具备保护能力而未履行保护义务的，市、县（市、区）人民政府应当先予抢救保护，所需费用由保护…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (854, 457, 1387, '第三十条', '第三十条 市、县（市、区）人民政府应当建立保护补偿制度，通过资金补贴或者其他政策措施，对单位和个人因历史文化名城保护而受到的损失，给予适当补偿。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (458, 'FBMCLI.10.4621790', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (855, 458, 1393, '第三十六条', '第三十六条 市、县（市、区）人民政府应当加强历史文化名城的活态保护，尊重原住居民生活形态和传统习俗，促进原有生产生活方式的延续传承。 鼓励原住居民以房屋、资金、技术和劳动力等形式参与保护利用，调动原住居民的积极性。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (459, 'FBMCLI.10.4621790', 'BIZ', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (856, 459, 1390, '第三十三条', '…史文化内涵，增强展示效果。 支持发展文化旅游、文化创意以及传统制作技艺等与传统文化相协调的业态。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (460, 'FBMCLI.10.4621790', 'DIG', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (857, 460, 1368, '第十一条', '…化名城、历史文化街区保护规划涉及空间管控要求的，应当纳入同级国土空间规划，并入国土空间基础信息平台统一管理。 城市交通、市政、绿地、旅游、消防、人防等专项规划应当与保护规划相协调。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (461, 'FBMCLI.10.4621790', 'SUP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (858, 461, 1364, '第七条', '…名城保护工作。 任何单位和个人都有保护历史文化名城的义务，对违反本条例的行为有权进行劝阻、举报和控告。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (462, 'FBMCLI.10.4621790', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (859, 462, 1397, '第四十条', '…行为、限期恢复原状或者采取其他补救措施；造成严重后果的，对单位并处五万元以上二十万元以下的罚款，对个人并处一万元以上五万元以下的罚款；有违法所得的，没收违法所得；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任： （一）修建损坏传统格局和历史风貌的建（构）筑物和其他设施； （二）设置破坏或者影响风貌的广…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (860, 462, 1398, '第四十一条', '…取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处二十万元以上五十万元以下的罚款，对个人并处十万元以上二十万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (861, 462, 1399, '第四十二条', '…规定，国家机关及其有关工作人员有下列行为之一的，由市、县（市、区）人民政府或者相关主管部门责令改正，通报批评；对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任： （一）因保护不力或者决策失误致使历史文化名城、历史城区、历史文化街区、历史建筑被列入濒危名单或者撤销称号； （二）未按本条…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (463, 'FBMCLI.10.6844556', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、11 个相关用语，关联 22 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (862, 463, 1451, '第五十条', '…形态和非物质形态文化遗产，具有较高的历史、文化、科学、艺术、社会、经济价值的村落。 （三）历史文化街区，是指经国家有关部门或者省人民政府核定公布的保存文物特别丰富、历史建筑集中成片、能够较完整和真实地体现传统格局和历史风貌，并具有一定规模的区域。 （四）历史文化风貌区，是指历史建筑或者传统风貌建筑比较集中，且该地段在城市…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (863, 463, 1414, '第十三条', '…： （一）不可移动文物和地下文物保护区； （二）历史建筑、工业遗产、红色文化遗址； （三）历史文化街区、历史文化风貌区和历史城区； （四）历史文化名镇、名村和传统村落； （五）山水格局和城址格局； （六）历史街巷、传统地名、名人故（旧）居； （七）河湖水系、风景名胜区、自然保护地、古树名木； （八）非物质文化遗产； （九…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (864, 463, 1428, '第二十七条', '第二十七条 历史文化名镇、名村、传统村落、历史文化街区和历史文化风貌区的保护责任人应当按照保护要求履行以下保护责任： （一）维持保护范围内的传统格局、街巷肌理、历史风貌、空间尺度和历史环境要素的完整性和原真性； （二）加强各类历史文化遗产的保护修缮，制定年度修缮计划，并按照…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (464, 'FBMCLI.10.6844556', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (865, 464, 1431, '第三十条', '…三十条 在历史文化名镇、名村保护规划，传统村落保护发展规划和历史文化街区保护规划确定的核心保护范围内，不得进行新建、扩建活动。确需新建、扩建必要的基础设施和公共服务设施以及改建、复建和翻建倒塌或者濒临倒塌的传统院落的，应当遵守下列规定： （一）新建、扩建必要的基础设施和公共服务设施的，应当符合保护规划确定的建设控制要…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (866, 464, 1432, '第三十一条', '…十一条 在历史文化名镇、名村保护规划，传统村落保护发展规划和历史文化街区保护规划确定的核心保护范围内，拆除文物、历史建筑以外的建筑物、构筑物或者其他设施的，应当经市人民政府确定的主管部门批准。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (867, 464, 1433, '第三十二条', '…名村保护规划，传统村落保护发展规划和历史文化街区保护规划确定的建设控制地带和历史文化风貌区保护范围内，新建、改建、扩建建筑物、构筑物应当在高度、体量和色彩等方面与历史风貌相协调，符合保护规划确定的建设控制要求。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (465, 'FBMCLI.10.6844556', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 25 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (868, 465, 1426, '第二十五条', '…政府指定保护责任人。 无法确定保护责任人的，由市人民政府指定保护责任人。 市住房和城乡建设主管部门和市文物主管部门应当在保护名录公布后，书面告知保护责任人应当承担的保护责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (869, 465, 1407, '第六条', '第六条 市住房和城乡建设主管部门会同市文物主管部门负责全市历史文化名城的保护和监督管理工作，组织开展申报、初审以及其他相关保护工作。 市规划和自然资源、城乡管理、行政审批服务管理等主管部门按照各自职责做好历史文化名城保护规划管理、执法处罚、项目审批等相…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (870, 465, 1419, '第十八条', '…计算。在预先保护期内，任何单位和个人不得损坏、擅自迁移、拆除预先保护对象。市住房和城乡建设主管部门会同市文物主管部门应当在预先保护期内，经专家论证、公示等程序，向市人民政府提出将预先保护对象列入保护名录的建议。 预先保护期满未被列入保护名录的，预先保护失效。 红色文化遗址与工业遗产的保护按照国家和省有关规定执行。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (466, 'FBMCLI.10.6844556', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (467, 'FBMCLI.10.6844556', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、7 个相关用语，关联 15 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (871, 467, 1424, '第二十三条', '第二十三条 组织编制机关应当在报送审批前依法将保护规划草案向社会公示，充分征求有关部门、专家和公众意见，公示时间不得少于三十日，必要时可以举行听证。 编制历史文化名镇、名村保护规划和传统村落保护发展规划除符合前款规定外，还应当征求所在地乡（镇）人民政府、街道办事处的意见。编…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (872, 467, 1425, '第二十四条', '第二十四条 历史文化名城、名镇、名村保护规划和传统村落保护发展规划中相关内容应当分别纳入相应层级的国土空间规划；历史文化街区、历史建筑保护规划应当纳入控制性详细规划。保护规划期限应当与国家、省规定的有关规划期限相一致。 市政、交通、绿地、村庄布局等专项规划应当与保…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (873, 467, 1421, '第二十条', '…市规划和自然资源主管部门应当将保护对象和建设控制要求纳入相应层级的国土空间规划。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (468, 'FBMCLI.10.6844556', 'PRE', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (874, 468, 1419, '第十八条', '第十八条 尚未列入保护名录，市、县（市、区）人民政府初步确认具有保护价值的，应当确定为预先保护对象，并自确定之日起十个工作日内向所有权人、使用人发出预先保护通知，书面告知其应当采取的保护措施。 预先保护期为六个月，自发出预先保护通知书之日起开始计算。在预先保护期内，任何单位和个人不得损坏、擅自迁移、拆除预先保护对…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (875, 468, 1435, '第三十四条', '…十四条 城乡建设中发现有保护价值的建筑物、构筑物的，施工单位应当立即停止拆除或者施工，采取临时保护措施，并报告建设单位。建设单位应当及时向所在地住房和城乡建设、文物主管部门报告。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (469, 'FBMCLI.10.6844556', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (876, 469, 1420, '第十九条', '…）权属变化和使用现状、保护范围内建设审批等情况； （三）保护规划、设计等批复方案； （四）修缮、维修、迁移、拆除过程中形成的文字、图纸、图片和影像等资料； （五）其他依法依规需要保存的资料。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (877, 469, 1434, '第三十三条', '第三十三条 任何单位和个人不得损坏或者擅自迁移、拆除历史建筑。 对历史建筑进行外部修缮装饰、添加设施以及改变历史建筑的结构或者使用性质的，应当经市、县人民政府确定的主管部门批准，批准前应当征求公众、专家和利害关系人的意见，并依照有关法律、法规的规定办理相关手续。 建设工程选址，应当尽可能避开历史建筑；因特…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (878, 469, 1419, '第十八条', '…为六个月，自发出预先保护通知书之日起开始计算。在预先保护期内，任何单位和个人不得损坏、擅自迁移、拆除预先保护对象。市住房和城乡建设主管部门会同市文物主管部门应当在预先保护期内，经专家论证、公示等程序，向市人民政府提出将预先保护对象列入保护名录的建议。 预先保护期满未被列入保护名录的，预先保护失效。 红色文化遗址与…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (470, 'FBMCLI.10.6844556', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (879, 470, 1408, '第七条', '…条 市、县（市、区）人民政府应当将历史文化名城保护工作纳入本级国民经济和社会发展规划，并将保护资金列入本级财政预算。 本市建立历史文化名城保护资金多渠道筹集机制，广泛筹集社会资金，用于历史文化名城保护的相关工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (471, 'FBMCLI.10.6844556', 'COMP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (880, 471, 1410, '第九条', '第九条 鼓励企业事业单位、社会团体和个人通过捐赠、资助、投资、提供技术服务、志愿服务等方式，依法参与历史文化名城保护工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (472, 'FBMCLI.10.6844556', 'RES', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (881, 472, 1417, '第十六条', '…行听证。 公示期结束后，市住房和城乡建设主管部门应当会同市文物主管部门将保护名录初选名单、征求意见情况、专家论证意见和公示结果按照相关程序报市人民政府批准、公布。 任何单位和个人可以向所在地县（市、区）人民政府推荐保护对象。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (882, 472, 1405, '第四条', '第四条 本市建立政府统筹、部门联动、公众参与、社会监督的历史文化名城保护工作机制。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (883, 472, 1424, '第二十三条', '…划草案向社会公示，充分征求有关部门、专家和公众意见，公示时间不得少于三十日，必要时可以举行听证。 编制历史文化名镇、名村保护规划和传统村落保护发展规划除符合前款规定外，还应当征求所在地乡（镇）人民政府、街道办事处的意见。编制历史文化名村保护规划和传统村落保护发展规划，还应当征求所在地村（居）民委员会的意见。 历史…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (473, 'FBMCLI.10.6844556', 'BIZ', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (884, 473, 1441, '第四十条', '第四十条 加强对具有历史价值的商业老字号、老物件、老技艺、老剧目等的保护利用，打造太原经典传统文化品牌，结合历史文化街区等合理布局非物质文化遗产传承空间，为其提供生存、传播和发展的条件；加强对传统节日、特色民俗、传统工艺的研究传承工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (474, 'FBMCLI.10.6844556', 'DIG', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (885, 474, 1443, '第四十二条', '…护传承信息平台，整合现有各类管理平台，优化功能，满足历史文化名城保护的科学决策、信息管理、动态监测以及公众服务等需求，实现多层次精细化管理。 第五章 监督检查', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (475, 'FBMCLI.10.6844556', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (886, 475, 1405, '第四条', '第四条 本市建立政府统筹、部门联动、公众参与、社会监督的历史文化名城保护工作机制。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (887, 475, 1446, '第四十五条', '第四十五条 任何单位和个人有权劝阻和向各级人民政府及其有关主管部门举报损坏、破坏历史文化名城、名镇、名村、传统村落、历史文化街区和历史建筑的行为。 相关部门接到举报后应当依法处理并予以答复。 第六章 法律责任', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (476, 'FBMCLI.10.6844556', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (888, 476, 1449, '第四十八条', '…补救措施；有违法所得的，没收违法所得；造成严重后果的，对单位并处二十万元以上五十万元以下的罚款，对个人并处十万元以上二十万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (889, 476, 1448, '第四十七条', '第四十七条 违反本条例第二十二条、第二十三条规定的，由上级人民政府责令改正；对直接负责的主管人员和其他直接责任人员，依法给予处分。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (890, 476, 1446, '第四十五条', '…村落、历史文化街区和历史建筑的行为。 相关部门接到举报后应当依法处理并予以答复。 第六章 法律责任', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (477, 'FBMCLI.10.1685450', 'OBJ', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (891, 477, 1481, '第二十九条', '…鼓楼、碑林、宝庆寺塔、城隍庙、化觉巷清真寺以及八路军西安办事处、西安事变旧址等古城墙以内的文物保护单位，应当按照文物保护法的规定予以保护，其周边的建筑高度、风格应当与保护对象相协调。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (892, 477, 1467, '第十五条', '…求。不符合历史文化名城保护规划要求的，不予办理规划建设审批手续，建设单位不得施工建设。 在文物保护单位周边建设的，建设单位应当向市文物行政部门提出申请，按规定程序审查同意后，方可办理规划建设审批手续。 在历史文化名城保护范围内，任何组织和个人不得越权审批建设项目。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (893, 477, 1470, '第十八条', '第十八条 古遗址区域是指被列为文物保护单位的古代所遗留下来的村落、城苑、宫殿等基址保护区域。主要包括：蓝田猿人遗址、半坡遗址、周丰镐遗址、秦阿房宫遗址、汉长安城遗址、唐大明宫和华清宫遗址等。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (478, 'FBMCLI.10.1685450', 'BND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (894, 478, 1490, '第三十八条', '第三十八条 在历史文化名城保护范围内，违反文物保护法律、法规规定，进行勘探、建设或者损坏文物及文物保护标志的，由文物行政部门依照有关法律、法规的规定，给予行政处罚；构成犯罪的，依法追究刑事责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (895, 478, 1454, '第二条', '第二条 西安历史文化名城保护范围是指在西安市行政区域内体现西安历史文化的古遗址区域、古城墙及其以内区域和历史文化风貌区域。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (896, 478, 1455, '第三条', '第三条 在西安历史文化名城保护范围内从事规划、建设、保护、管理和其他活动的，均应遵守本条例。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (479, 'FBMCLI.10.1685450', 'RESP', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 13 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (897, 479, 1458, '第六条', '第六条 市资源规划主管部门和市文物行政部门主管本市历史文化名城保护管理工作。 住建、城管、文化旅游、民族宗教、生态环境等部门，按照法律、法规的规定和市人民政府确定的权限，协同做好历史文化名城的保护管理工作。 区县人民政府负责本辖区内历史文化名城保…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (898, 479, 1457, '第五条', '第五条 市人民政府应当把历史文化名城的保护和管理工作纳入国民经济和社会发展计划，并将保护、管理和编制规划的经费列入财政预算。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (899, 479, 1459, '第七条', '第七条 市人民政府应当组织对西安的历史事件、地名典故、诗词歌赋、地方戏曲、传统工艺、饮食文化、民风民俗等文化遗产，进行搜集、整理、研究、保护和开发利用。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (480, 'FBMCLI.10.1685450', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (481, 'FBMCLI.10.1685450', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、5 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (900, 481, 1466, '第十四条', '第十四条 西安历史文化名城保护规划，报经省人民政府批准后实施。 控制性详细规划和实施性详细规划，报市人民政府批准后实施。 历史文化名城保护规划、控制性详细规划和实施性详细规划批准后，应当向社会公布。 历史文化名城保护规划、控制性详细规划、实施性详细规划和…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (901, 481, 1462, '第十条', '第十条 市人民政府应当根据城市总体规划编制西安历史文化名城保护规划，制定保护图则。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (902, 481, 1463, '第十一条', '第十一条 市资源规划主管部门应当根据西安历史文化名城保护规划编制古遗址区域、古城墙及其以内区域、历史文化风貌区域的控制性详细规划和实施性详细规划。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (482, 'FBMCLI.10.1685450', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (483, 'FBMCLI.10.1685450', 'REPAIR', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (903, 483, 1469, '第十七条', '…保护规划、控制性详细规划、实施性详细规划的建筑物、构筑物及其他设施，应当改造、迁建或者依法拆除。 依照前款规定迁建、拆除建筑物、构筑物及其他设施，属于历史上所形成或者经批准建成的，由所在地的区县人民政府分期分批组织实施，并按规定予以安置和补偿；属于违法建设的，由城市管理综合执法主管部门依法查处。 第三章 古遗址区…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (904, 483, 1479, '第二十七条', '第二十七条 古城墙以内区域的建设项目，应当符合所在保护区的规划要求。新建、改建、扩建的建筑物、构筑物，其体量、造型和色彩应当体现传统建筑风格和特色。 古城墙以内区域的建筑高度实行分区控制，整体建筑控制高度不超过36米；综合容积率控制在2.5以下；在单位和居民院落内不得插建建筑物。 维修、改建、翻建…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (905, 483, 1475, '第二十三条', '第二十三条 古城墙及其以内区域是指明洪武年在隋唐皇城基础上扩建保留至今的西安城墙区域和城墙以内的区域。 古城墙区域包括西安城墙、护城河、环城林带和环城路。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (484, 'FBMCLI.10.1685450', 'FUND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (906, 484, 1457, '第五条', '…历史文化名城的保护和管理工作纳入国民经济和社会发展计划，并将保护、管理和编制规划的经费列入财政预算。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (485, 'FBMCLI.10.1685450', 'COMP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (907, 485, 1461, '第九条', '…护和开发利用。 对在历史文化名城保护工作中做出显著成绩的单位和个人，由市人民政府予以表彰和奖励。 第二章 历史文化名城的规划', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (908, 485, 1469, '第十七条', '…于历史上所形成或者经批准建成的，由所在地的区县人民政府分期分批组织实施，并按规定予以安置和补偿；属于违法建设的，由城市管理综合执法主管部门依法查处。 第三章 古遗址区域的保护', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (486, 'FBMCLI.10.1685450', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (909, 486, 1492, '第四十条', '… 对单位作出五十万元以上罚款、对个人作出五万元以上罚款处罚决定前，应当告知当事人有要求举行听证的权利。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (487, 'FBMCLI.10.1685450', 'BIZ', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (488, 'FBMCLI.10.1685450', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (489, 'FBMCLI.10.1685450', 'SUP', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (490, 'FBMCLI.10.1685450', 'LIAB', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (910, 490, 1487, '第三十五条', '…化旅游设施和管理用房的，其建筑物的体量、造型、风格和色彩，应当与文物古迹相协调。 第六章 法律责任', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (911, 490, 1489, '第三十七条', '…；尚可采取改正措施消除对规划实施的影响的，限期改正，处建设工程造价百分之五以上百分之十以下罚款；无法采取改正措施消除影响的，限期拆除，不能拆除的，没收实物或者违法收入，可以并处建设工程造价百分之十以下罚款。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (912, 490, 1491, '第三十九条', '第三十九条 违反本条例规定的其他行为，法律、法规有法律责任规定的，适用其规定。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (491, 'FBMCLI.10.4084953', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (913, 491, 1508, '第十四条', '第十四条 代县人民政府应当建立代县历史文化名城保护名录制度。 保护名录包括：历史文化街区、文物保护单位、具有保护价值的历史建筑等。 保护名录应当载明保护对象的名称、区位、界限、形成时间和历史价值等，并向社会公布。 代县人民政府应当设置统一保护标志牌，任何单位和个人不得擅自设置、移动、涂改或者损毁保护标志牌。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (914, 491, 1513, '第十九条', '… （一）建设破坏传统格局和历史风貌的建筑物、构筑物； （二）损毁或者擅自拆除具有保护价值的历史建筑； （三）擅自拆除历史建（构）筑物中的古门、古窗、古牌匾、古照壁以及其他装饰构件； （四）侵占或者损坏古树名木、古井、古牌坊、古亭、古碑、古巷道、道路； （五）擅自对历史建筑、传统民居、商铺等进行外部修缮装饰，以及改变院…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (915, 491, 1505, '第十一条', '…县国土空间总体规划相衔接，突出保护历史文化名城的完整格局，体现边塞文化特色，加强文物古迹、历史文化街区、历史建筑等的保护管理，适应城市居民现代化生活和工作环境的需要。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (492, 'FBMCLI.10.4084953', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (916, 492, 1506, '第十二条', '第十二条 代县历史文化名城保护规划应当划定保护范围。保护范围包括核心保护范围和建设控制地带，并根据实际情况划定环境协调区。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (917, 492, 1510, '第十六条', '第十六条 在核心保护范围内，不得进行新建、扩建活动。新建、扩建必要的基础设施和公共服务设施除外。 核心保护范围内具有保护价值的建筑物、构筑物的维护修缮应当保持原有的高度、体量、外观式样及色彩等，并与整体风貌相互协调。 现有对历史文化名城传统格局…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (918, 492, 1509, '第十五条', '第十五条 在代县历史文化名城保护范围内从事建设活动，应当符合保护规划的要求，核发建设工程规划许可证的部门在核发前，应当征求文物部门的意见。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (493, 'FBMCLI.10.4084953', 'RESP', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (919, 493, 1498, '第四条', '第四条 市人民政府应当加强对代县历史文化名城保护工作的领导；代县人民政府负责代县历史文化名城的规划、保护、修复、利用和监督管理等工作；代县人民政府发改、财政、自然资源、住建、公安、文旅、生态环境等部门按照各自职责做好历史文化名城保护的相关…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (920, 493, 1503, '第九条', '第九条 对保护代县历史文化名城做出突出贡献的单位和个人，代县人民政府或者有关行政主管部门应当予以表彰和奖励。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (921, 493, 1519, '第二十五条', '…本条例第十四条第四款规定，擅自设置、移动、涂改或者损毁保护标志牌的，由代县人民政府城乡建设主管部门责令限期改正；逾期不改正的，对单位处一万元以上五万元以下的罚款，对个人处三千元以上一万元以下的罚款。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (494, 'FBMCLI.10.4084953', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (495, 'FBMCLI.10.4084953', 'PLAN', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (922, 495, 1504, '第十条', '第十条 代县人民政府应当依法编制代县历史文化名城保护规划。其他专项规划应当与代县历史文化名城保护规划相协调。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (923, 495, 1505, '第十一条', '第十一条 编制代县历史文化名城保护规划应当与代县国土空间总体规划相衔接，突出保护历史文化名城的完整格局，体现边塞文化特色，加强文物古迹、历史文化街区、历史建筑等的保护管理，适应城市居民现代化生活和工作环境的需要。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (924, 495, 1507, '第十三条', '第十三条 编制代县历史文化名城保护规划，应当广泛听取社会各界的意见，并征求专家咨询委员会意见。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (496, 'FBMCLI.10.4084953', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (497, 'FBMCLI.10.4084953', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、5 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (925, 497, 1510, '第十六条', '…、扩建必要的基础设施和公共服务设施除外。 核心保护范围内具有保护价值的建筑物、构筑物的维护修缮应当保持原有的高度、体量、外观式样及色彩等，并与整体风貌相互协调。 现有对历史文化名城传统格局和历史风貌构成破坏性影响的建筑物、构筑物应当依法拆除或迁移。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (926, 497, 1511, '第十七条', '第十七条 在建设控制地带内，新建、改建、扩建建筑物、构筑物应当符合保护规划确定的建设控制要求，在高度、体量和色彩方面与历史风貌相协调。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (927, 497, 1513, '第十九条', '…、古井、古牌坊、古亭、古碑、古巷道、道路； （五）擅自对历史建筑、传统民居、商铺等进行外部修缮装饰，以及改变院落格局、结构； （六）擅自挖掘、拓宽、截弯、取直传统街巷、道路，擅自挖掘地下空间； （七）损坏或者擅自移动、拆除公共设施； （八）法律、法规禁止的其他行为。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (498, 'FBMCLI.10.4084953', 'FUND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (928, 498, 1500, '第六条', '第六条 代县人民政府应当将代县历史文化名城保护纳入国民经济和社会发展计划，并将所需经费列入财政预算。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (499, 'FBMCLI.10.4084953', 'COMP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (929, 499, 1501, '第七条', '第七条 鼓励单位和个人以捐赠、资助、提供技术服务或者提出建议等方式参与代县历史文化名城的保护工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (930, 499, 1503, '第九条', '…护代县历史文化名城做出突出贡献的单位和个人，代县人民政府或者有关行政主管部门应当予以表彰和奖励。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (500, 'FBMCLI.10.4084953', 'RES', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (501, 'FBMCLI.10.4084953', 'BIZ', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (502, 'FBMCLI.10.4084953', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (503, 'FBMCLI.10.4084953', 'SUP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (931, 503, 1502, '第八条', '…，并有权对保护规划的制定和实施提出建议，对破坏代县历史文化名城的行为进行劝阻或者向有关部门举报。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (504, 'FBMCLI.10.4084953', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (932, 504, 1520, '第二十六条', '…者采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处五万元以上十万元以下的罚款，对个人并处一万元以上五万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (933, 504, 1517, '第二十三条', '…三条 违反本条例规定，法律、行政法规以及本省人民代表大会及其常务委员会制定的地方性法规已有法律责任规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (934, 504, 1519, '第二十五条', '…，由代县人民政府城乡建设主管部门责令限期改正；逾期不改正的，对单位处一万元以上五万元以下的罚款，对个人处三千元以上一万元以下的罚款。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (505, 'FBMCLI.10.7318142', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 6 个核心用语、9 个相关用语，关联 24 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (935, 505, 1530, '第八条', '第八条 历史文化名城保护对象包括以下内容： （一）历史城区； （二）历史文化街区； （三）不可移动文物； （四）长城文化遗址； （五）秦渠、汉渠、汉延渠、唐徕渠等古灌溉渠系； （六）历史建筑； （七）传统村落； （八）古树名木； （九）历史地名； （十）非物质文化遗产； （十一）法律、法规规定的其他…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (936, 505, 1542, '第二十条', '第二十条 历史城区、历史文化街区保护责任人应当按照保护规划和下列要求履行保护责任： （一）组织开展日常巡查，及时制止危害历史文化名城保护对象的行为； （二）保持保护范围内建筑物、构筑物的传统格局、历史风貌、特色装饰、空间尺度和历史环境要素的完整性； （…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (937, 505, 1550, '第二十八条', '第二十八条 市、县（市）区人民政府应当通过政策引导、资金扶持等方式，促进历史城区、历史文化街区、历史建筑、传统村落等名城保护对象的合理利用。合理利用应当符合相关保护要求，不得损害传统格局、历史风貌和历史文化价值。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (506, 'FBMCLI.10.7318142', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (938, 506, 1534, '第十二条', '…务院文物主管部门备案。 历史文化名城保护规划应当包括下列内容： （一）保护原则、保护内容和保护范围； （二）保护措施、开发强度和建设控制要求； （三）传统格局和历史风貌保护要求； （四）历史文化街区、历史建筑核心保护范围和建设控制地带； （五）保护规划分期实施方案。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (939, 506, 1544, '第二十二条', '第二十二条 市、县（市）区人民政府应当在历史文化街区核心保护范围的主要出入口设置标志牌，对历史建筑设置保护标志。历史文化街区标志牌和历史建筑保护标志由市人民政府统一样式。 任何单位和个人不得擅自设置、移动、涂改或者损毁历史文化街区标志牌和历史建筑保护标志。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (940, 506, 1549, '第二十七条', '…的，应当符合保护规划确定的建设控制要求，严格控制建筑物、构筑物的高度、体量、色彩等，与核心保护范围风貌相协调。 第五章 合理利用', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (507, 'FBMCLI.10.7318142', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 18 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (941, 507, 1527, '第五条', '第五条 自然资源主管部门负责历史文化名城、历史文化街区和历史建筑保护的有关规划管理工作。 住房和城乡建设主管部门负责历史建筑和历史城区、历史文化街区保护范围内文物以外的建筑物、构筑物的结构安全、使用和修缮的监督管理工作。 文物主管部门负责本条例…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (942, 507, 1541, '第十九条', '第十九条 历史文化名城的保护实行保护责任制。 保护责任人按照下列规定确定： （一）历史城区、历史文化街区的保护责任人是所在地的县（市）区人民政府； （二）历史建筑的保护责任人是所有权人。所有权人下落不明、权属不清的历史建筑由管理人、使用人负责；无法确定保护责任人的，由历史建筑…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (943, 507, 1542, '第二十条', '第二十条 历史城区、历史文化街区保护责任人应当按照保护规划和下列要求履行保护责任： （一）组织开展日常巡查，及时制止危害历史文化名城保护对象的行为； （二）保持保护范围内建筑物、构筑物的传统格局、历史风貌、特色装饰、空间尺度和历史环境要素的完整性； （三）完善历…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (508, 'FBMCLI.10.7318142', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (509, 'FBMCLI.10.7318142', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (944, 509, 1538, '第十六条', '第十六条 经批准的历史文化名城保护规划、历史文化街区保护规划、历史建筑保护和利用规划不得擅自修改；确需修改的，按照以下程序办理： （一）修改历史文化名城保护规划的，由市人民政府提出专题报告，依法报自治区人民政府审查同意后按照原编制、审批、备案程序修改、报批、…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (945, 509, 1557, '第三十五条', '…的主管人员和其他直接责任人员，依法给予处分： （一）未按照规定组织编制、修改、公布历史街区保护规划、历史建筑保护和利用规划的； （二）不履行本条例第二十条规定的保护责任的； （三）未按照保护规划的要求或者未按照法定程序履行本条例第二十三条、第二十四条、第二十六条规定的职责的； （四）未按照规定设置历史文化街区标志牌、…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (946, 509, 1534, '第十二条', '第十二条 市人民政府组织编制历史文化名城保护规划，报自治区人民政府批准，并报国务院住房和城乡建设主管部门和国务院文物主管部门备案。 历史文化名城保护规划应当包括下列内容： （一）保护原则、保护内容和保护范围； （二）保护措施、开发强度和建设控制要求； （三）传统格局和…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (510, 'FBMCLI.10.7318142', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (511, 'FBMCLI.10.7318142', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (947, 511, 1545, '第二十三条', '…规划许可证前，审批主管部门应当征求同级文物主管部门的意见。 在历史文化街区核心保护范围内，拆除历史建筑以外的建筑物、构筑物或者其他设施的，应当经市自然资源主管部门会同同级文物主管部门批准。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (948, 511, 1548, '第二十六条', '第二十六条 任何单位或者个人不得损坏或者擅自迁移、拆除历史建筑。建设工程选址，应当尽可能避开历史建筑；因特殊情况不能避开的，应当尽可能实施原址保护。 因公共利益需要进行建设活动，对历史建筑无法实施原址保护、必须迁移或者拆除的，建设单位应当提供迁移或者拆除的必要性与可行…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (949, 511, 1546, '第二十四条', '…）筑物上刻划、涂污； （二）在建（构）筑物内堆放爆炸性和腐蚀性的物品； （三）擅自进行外部修缮装饰、添加设施以及改变历史建筑的结构或者使用性质； （四）实施损坏建筑主体承重结构或者其他危害建筑物安全的行为； （五）其他影响历史建筑保护的行为。 单位和个人确需在历史建筑核心保护范围内进行外部修缮装饰、添加设施以及改…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (512, 'FBMCLI.10.7318142', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (950, 512, 1526, '第四条', '…内历史文化名城的保护和监督管理工作，将其纳入国民经济和社会发展规划、计划，并将历史文化名城保护资金列入本级财政预算。 乡镇人民政府、街道办事处配合相关部门做好历史文化名城保护工作，负责本辖区内历史文化名城保护的日常巡查等工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (951, 512, 1547, '第二十五条', '…筑的所有权人应当按照保护规划的要求，负责历史建筑的维护和修缮。市、县（市）区人民政府可以从保护资金中对历史建筑的维护和修缮给予补助。 历史建筑有损毁危险，所有权人不具备维护和修缮能力的，市、县（市）区人民政府应当采取措施进行保护。 鼓励聘用传统工匠，采用传统技艺对历史建筑进行维护和修缮。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (513, 'FBMCLI.10.7318142', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (952, 513, 1529, '第七条', '第七条 鼓励单位和个人以捐赠、资助、提供技术服务、志愿服务等方式参与历史文化名城保护与利用工作。 市、县（市）区人民政府对在银川历史文化名城保护工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰和奖励。 第二章 保护对象', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (953, 513, 1547, '第二十五条', '…负责历史建筑的维护和修缮。市、县（市）区人民政府可以从保护资金中对历史建筑的维护和修缮给予补助。 历史建筑有损毁危险，所有权人不具备维护和修缮能力的，市、县（市）区人民政府应当采取措施进行保护。 鼓励聘用传统工匠，采用传统技艺对历史建筑进行维护和修缮。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (514, 'FBMCLI.10.7318142', 'RES', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (954, 514, 1536, '第十四条', '…取座谈会、论证会等方式广泛征求有关部门、利害关系人、专家和社会公众的意见。必要时，可以举行听证。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (955, 514, 1548, '第二十六条', '…资料，由市、县（市）自然资源、住房和城乡建设、文物主管部门对迁移方案、补救措施等进行论证、听证并向社会公示方案后，依照国家和自治区有关规定报请批准。 迁移或者拆除历史建筑的，应当听取历史建筑所有权人的意见。 经批准迁移或者拆除历史建筑的，由建设单位按照批准后的方案及有关规定组织迁移、拆除，县（市）区住房和城乡建设…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (956, 514, 1560, '第三十八条', '…景资料 立法草案 银川市人大常委会办公室关于公开征集《银川市历史文化名城保护条例(修订草案征求意见稿)》意见建议公告 本篇引用的法规 中央法规 中华人民共和国城乡规划法(2019修正) 中华人民共和国文物保护法(2017修正) 历史文化名城名镇名村保护条例(2017修订) 中华人民共和国非物质文化遗产法 长城保护条例…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (515, 'FBMCLI.10.7318142', 'BIZ', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (957, 515, 1551, '第二十九条', '…和传统村落发展多样化特色产业，适度开展旅游、传统工艺和传统技艺加工制作等与传统文化相协调的经营活动。 鼓励社会力量合理利用历史文化资源发展符合保护规划的产业，从事符合产业布局规划的经营活动。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (958, 515, 1552, '第三十条', '…利用，可以用作展览馆、博物馆、图书馆、美术馆等，开展地方文化研究、文化创意、旅游观光、特色商业等。 单位和个人利用历史建筑的，应当符合相关保护要求。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (516, 'FBMCLI.10.7318142', 'DIG', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (959, 516, 1533, '第十一条', '…水务、民政等有关主管部门根据历史文化名城保护对象名录，采取文字、录音、录像、测绘、多媒体、数字化等技术手段，全面系统整理历史文化名城的各类档案资料，建立历史文化名城档案数据库，实施数字化管理，并及时更新。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (517, 'FBMCLI.10.7318142', 'SUP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (960, 517, 1528, '第六条', '…川历史文化名城的义务，有权对保护工作提出意见和建议，对破坏银川历史文化名城的行为进行监督和举报。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (518, 'FBMCLI.10.7318142', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (961, 518, 1557, '第三十五条', '…有关部门或者乡镇人民政府、街道办事处有下列行为之一的，由市和县（市）区人民政府按照管理权限责令改正，通报批评；对直接负责的主管人员和其他直接责任人员，依法给予处分： （一）未按照规定组织编制、修改、公布历史街区保护规划、历史建筑保护和利用规划的； （二）不履行本条例第二十条规定的保护责任的； （三）未按照保护规划的要…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (962, 518, 1554, '第三十二条', '…价值和精神内涵，推进历史文化和旅游深度融合发展，发挥历史文化资源的社会教育作用。 第六章 法律责任', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (963, 518, 1555, '第三十三条', '第三十三条 违反本条例规定的行为，法律、法规已有法律责任规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (519, 'FBMCLI.10.6946695', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 6 个核心用语、10 个相关用语，关联 26 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (964, 519, 1570, '第十条', '…城区，以贡井老街河街为核心的贡井历史城区； （二）以贡井艾叶横街、富顺文庙-西湖等为代表的历史文化街区； （三）以仙市镇、赵化镇等为代表的历史文化名镇； （四）以三多寨村、吕仙村等为代表的传统村落； （五）以安全巷民国时期政府大院旧址、善后桥等为代表的历史建筑； （六）以燊海井、荣县大佛石窟、张伯卿公馆等为代表的文物保护…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (965, 519, 1562, '第二条', '…、利用和监督管理，适用本条例。 历史文化名城的保护对象以井盐历史文化为核心，包括历史城区、历史文化街区、历史文化名镇、历史文化名村、传统村落、文物、古生物化石遗迹、历史建筑、工业遗产、农村生产生活遗产、红色资源、非物质文化遗产、地名文化遗产、商业老字号、古树名木等。 法律法规对保护对象另有规定的，适用其规定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (966, 519, 1596, '第三十六条', '第三十六条 在历史城区、历史文化街区、历史文化名镇、历史文化名村、传统村落、历史建筑的保护范围内禁止下列行为： （一）开山、采石、开矿等破坏传统格局和历史风貌的活动； （二）占用国土空间详细规划和保护规划确定保留的园林绿地、河湖水系、塔桥亭阁、堤坝涵洞、道…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (520, 'FBMCLI.10.6946695', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (967, 520, 1577, '第十七条', '…要划定环境协调区。 历史文化街区、历史文化名镇、历史文化名村、传统村落保护规划应当依法划定保护范围，包括核心保护范围和建设控制地带，并纳入历史文化保护线。 历史文化街区内历史建筑的保护范围为历史建筑本身，历史文化街区外历史建筑的保护范围应当包括历史建筑本身和必要的建设控制地带。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (968, 520, 1589, '第二十九条', '…空间详细规划和保护规划确定的建设控制要求，严格控制建（构）筑物的高度、体量、色彩等，与核心保护范围的传统格局、历史风貌相协调。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (969, 520, 1609, '第四十九条', '第四十九条 违反本条例第二十八条第一款、第二十九条规定，在核心保护范围内进行新建、扩建活动，或者在建设控制地带内从事违反建（构）筑物高度、建筑体量、色彩等控制要求的建设活动的，由自然资源行政主管部门责令停止建设；尚可采取改正措施消除对规划实施的影响的，限期改正，并处建设工程造价百分之五以上…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (521, 'FBMCLI.10.6946695', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 39 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (970, 521, 1581, '第二十一条', '…地县级人民政府确定保护责任人； （四）地名文化遗产的保护责任人为所在地县级人民政府地名行政主管部门； （五）其他保护对象的保护责任人，法律法规有规定的适用其规定；法律法规未规定保护责任人的，由所在地县级人民政府确定保护责任人。 县级人民政府住房城乡建设行政主管部门应当在保护名录公布后十个工作日内将保护责任书面告知历史…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (971, 521, 1575, '第十五条', '…与同级国土空间规划同步编制。 历史文化名城保护规划由市人民政府组织编制，市住房城乡建设行政主管部门会同自然资源、文化广电旅游行政主管部门负责具体编制工作。 历史文化街区保护规划由县级人民政府组织编制，县级人民政府住房城乡建设行政主管部门会同自然资源、文化广电旅游行政主管部门负责具体编制工作。 历史文化名镇、历史文化名…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (972, 521, 1564, '第四条', '第四条 市人民政府负责历史文化名城保护和监督管理工作，将历史文化名城保护纳入国民经济和社会发展规划，完善体制机制和政策保障，加强部门协同和区域协作，推进世界遗产申报和历史文化名城保护与发展。 县级人民政府负责本辖区内历史文化名城保护工作。…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (522, 'FBMCLI.10.6946695', 'COORD', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (973, 522, 1564, '第四条', '…和监督管理工作，将历史文化名城保护纳入国民经济和社会发展规划，完善体制机制和政策保障，加强部门协同和区域协作，推进世界遗产申报和历史文化名城保护与发展。 县级人民政府负责本辖区内历史文化名城保护工作。 乡镇人民政府、街道办事处承担本辖区内历史文化名城保护的日常巡查、宣传引导等具体工作。 居民委员会、村民委员会协助乡镇…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (523, 'FBMCLI.10.6946695', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、8 个相关用语，关联 17 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (974, 523, 1607, '第四十七条', '…编制、公布、管理和调整保护名录的； （三）未组织编制或者未按照法定程序组织编制、报批和公布保护规划的； （四）擅自修改国土空间详细规划和保护规划的； （五）未依法设置保护标志的； （六）未履行保护责任人责任的； （七）未依法采取预先保护措施的； （八）其他滥用职权、玩忽职守、徇私舞弊的行为。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (975, 523, 1575, '第十五条', '第十五条 历史文化名城、历史文化街区、历史文化名镇、历史文化名村、传统村落等应当依法编制保护规划，并与同级国土空间规划同步编制。 历史文化名城保护规划由市人民政府组织编制，市住房城乡建设行政主管部门会同自然资源、文化广电旅游行政主管部门负责具体编制工作。 历史文化街区保护规划由县级人民政府组织编制，县级人民政府住房…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (976, 523, 1578, '第十八条', '第十八条 保护规划应当按照有关法律法规的规定报送审批和备案。 报送审批前，组织编制机关应当将保护规划草案向社会公示，并采取论证会、听证会或者其他方式征求专家和社会公众意见。公示时间不得少于三十日。 保护规划应当经专家委员会评审、历史文化名…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (524, 'FBMCLI.10.6946695', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (977, 524, 1573, '第十三条', '…同自然资源、文化广电旅游等有关行政主管部门初步确认有保护价值的，由所在地县级人民政府确定为预先保护对象，并作出预先保护决定。 预先保护对象所在地县级人民政府应当采取必要的预先保护措施，并发出预先保护通知送达保护责任人。预先保护通知发出之日起三十日内，由所在地县级人民政府启动将预先保护对象列入保护名录的申报程序。自预先…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (978, 524, 1607, '第四十七条', '…护规划的； （五）未依法设置保护标志的； （六）未履行保护责任人责任的； （七）未依法采取预先保护措施的； （八）其他滥用职权、玩忽职守、徇私舞弊的行为。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (525, 'FBMCLI.10.6946695', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 16 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (979, 525, 1591, '第三十一条', '…其传统格局和历史风貌，不得改变与其依存的自然环境和景观。 传统村落内各种建筑的翻建、改建、修缮、扩建和整体装饰应当符合村规划和保护规划要求，保持建筑形式、体量、风格、色彩以及构造装饰与传统村落整体风格相协调。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (980, 525, 1593, '第三十三条', '…避开历史建筑；因特殊情况不能避开的，应当尽可能实施原址保护。任何单位和个人不得损坏或者擅自迁移、拆除历史建筑。 因公共利益需要无法实施原址保护的，应当采取论证会、听证会或者其他方式征求专家和公众意见，由市、县住房城乡建设行政主管部门会同同级自然资源、文化广电旅游行政主管部门审核，经市政府同意并按程序报送批准后，按…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (981, 525, 1595, '第三十五条', '第三十五条 非国有历史建筑的保护责任人按照国土空间详细规划、保护规划、修缮技术规范、经批准的保护设计方案和施工方案等要求进行修缮并通过验收的，可以由政府给予资金补助。资金补助办法由市人民政府制定。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (526, 'FBMCLI.10.6946695', 'FUND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (982, 526, 1567, '第七条', '第七条 市、县级人民政府应当根据本级社会经济发展水平，同步安排历史文化名城保护资金，列入本级预算。 对濒临灭失的保护对象的保护资金，市、县级人民政府应当依法足额安排。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (527, 'FBMCLI.10.6946695', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (983, 527, 1600, '第四十条', '…色的传统手工业、特色产品的生产经营和非物质文化遗产传承利用活动； （三）通过政策引导、资金补助、费用减免等方式鼓励社会资本和个人参与保护对象的传承利用； （四）通过政府收购、产权置换、减免租金、延长租期等方式，促进历史建筑的合理利用； （五）组织开展与历史文化名城保护相关的学术研究、实践创新、文化宣传和教育活动，…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (984, 527, 1569, '第九条', '…史文化名城保护工作中做出突出贡献的单位和个人，市、县级人民政府应当按照有关规定给予表彰或者奖励。 第二章 保护名录', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (985, 527, 1573, '第十三条', '…巡查监督。 因预先保护对有关单位或者个人的合法权益造成损失的，市、县级人民政府应当依法给予补偿。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (528, 'FBMCLI.10.6946695', 'RES', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (986, 528, 1578, '第十八条', '…规定报送审批和备案。 报送审批前，组织编制机关应当将保护规划草案向社会公示，并采取论证会、听证会或者其他方式征求专家和社会公众意见。公示时间不得少于三十日。 保护规划应当经专家委员会评审、历史文化名城保护委员会审查后按程序报送审批。经批准的保护规划应当通过政府网站和主要新闻媒体向社会公布。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (987, 528, 1593, '第三十三条', '…人不得损坏或者擅自迁移、拆除历史建筑。 因公共利益需要无法实施原址保护的，应当采取论证会、听证会或者其他方式征求专家和公众意见，由市、县住房城乡建设行政主管部门会同同级自然资源、文化广电旅游行政主管部门审核，经市政府同意并按程序报送批准后，按照有关技术标准和管理规定组织迁移、拆除。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (988, 528, 1602, '第四十二条', '第四十二条 历史文化街区、历史文化名镇、历史文化名村、传统村落和历史建筑的利用，应当保障原住居民的合法权益，保持传统生活习俗的延续性。 鼓励原住居民依据保护规划要求在原址居住，以房屋、资金入股等多种形式参与保护利用和开发建设，享有合理收益。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (529, 'FBMCLI.10.6946695', 'BIZ', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (989, 529, 1600, '第四十条', '…定保护对象的传承利用正面或者负面清单，明确鼓励、支持或者限制、禁止的活动； （二）调整优化业态布局，支持发展文化旅游、文化创意以及传统制作技艺等与传统文化相协调的业态，鼓励开展具有地方特色的传统手工业、特色产品的生产经营和非物质文化遗产传承利用活动； （三）通过政策引导、资金补助、费用减免等方式鼓励社会资本和个人…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (990, 529, 1562, '第二条', '…物化石遗迹、历史建筑、工业遗产、农村生产生活遗产、红色资源、非物质文化遗产、地名文化遗产、商业老字号、古树名木等。 法律法规对保护对象另有规定的，适用其规定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (991, 529, 1570, '第十条', '…、大安寨、三八路等为代表的地名文化遗产； （十三）以“天车牌”香辣酱、太源井晒醋等为代表的商业老字号； （十四）以荣县双石镇蔡家堰村吴玉章手植黄桷兰、大安区新民镇富华村明代罗汉松等为代表的古树名木； （十五）法律法规规定的其他保护对象。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (530, 'FBMCLI.10.6946695', 'DIG', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (992, 530, 1574, '第十四条', '…城乡建设行政主管部门应当会同有关部门建立统一信息平台，对列入保护名录的保护对象建立保护档案数据库并向社会公开，但依法应当保密的除外。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (531, 'FBMCLI.10.6946695', 'SUP', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (993, 531, 1578, '第十八条', '…论证会、听证会或者其他方式征求专家和社会公众意见。公示时间不得少于三十日。 保护规划应当经专家委员会评审、历史文化名城保护委员会审查后按程序报送审批。经批准的保护规划应当通过政府网站和主要新闻媒体向社会公布。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (994, 531, 1566, '第六条', '…名城保护委员会，负责统筹规划、综合协调历史文化名城的保护工作。 历史文化名城保护委员会成立专家委员会（以下称专家委员会），为历史文化名城保护工作中的重大事项提供论证、评审、咨询等服务。 历史文化名城保护委员会的议事制度由市人民政府制定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (995, 531, 1569, '第九条', '…化名城的义务，有权对保护规划的制定和实施提出意见、建议，对破坏历史文化名城的行为进行监督、举报。 对在历史文化名城保护工作中做出突出贡献的单位和个人，市、县级人民政府应当按照有关规定给予表彰或者奖励。 第二章 保护名录', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (532, 'FBMCLI.10.6946695', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (996, 532, 1610, '第五十条', '…取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处二十万元以上五十万元以下的罚款，对个人并处十万元以上二十万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (997, 532, 1611, '第五十一条', '…者采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处五万元以上十万元以下的罚款，对个人并处一万元以上五万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (998, 532, 1607, '第四十七条', '…四十七条 违反本条例规定，国家机关及其有关工作人员有下列行为之一的，由有关部门、单位和组织责令改正，通报批评；对直接负责的主管人员和其他直接责任人员，依法依规给予处理；构成犯罪的，依法追究刑事责任： （一）因保护不力，导致已批准公布的历史文化名城、名镇、名村等保护对象被列入濒危名单的； （二）未依法编制、公布、管理和…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (533, 'FBMCLI.10.1418169', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 16 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (999, 533, 1625, '第十一条', '第十一条 市人民政府建立历史文化名城保护名录。 保护名录的范围包括： （一）北关历史文化街区、历史城区和历史文化风貌区； （二）历史建筑； （三）地下文物埋藏区、古遗址、会馆、钱庄、古民居、老字号、古树名木、古井、古酒窖池； （四）传统地名； （五）非物质文化遗产； （六）经国家、省、市人民政府批准公布的文物保…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1000, 533, 1645, '第三十一条', '…社会组织将符合条件的历史建筑作为公共开放场所； （五）支持非物质文化遗产代表性项目传承人在历史文化街区、不可移动文物、历史建筑中开展非物质文化遗产的传承和展示活动。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1001, 533, 1624, '第十条', '第十条 历史文化名城保护范围包括北关历史文化街区、历史城区和历史文化风貌区。北关历史文化街区为核心保护区。 （一）北关历史文化街区是指东至新华北路、南至和平路、西至寺西街和柴家沟、北至涡河南岸以内围合的区域。重点保护对象为：花戏楼、南京巷钱庄、北京寺等重要文物保护单位…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (534, 'FBMCLI.10.1418169', 'BND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1002, 534, 1635, '第二十一条', '…，按照批准的规划许可要求施工，并遵守下列规定： （一）在高度、体量、立面、色彩等方面与重点保护范围内的传统格局和历史风貌相协调； （二）不得破坏历史环境和人文景观特征； （三）不得危及重点保护范围内的建筑安全。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1003, 534, 1623, '第九条', '…府应当组织开展历史文化名城保护的宣传教育活动，普及保护知识，增强全社会保护意识。 第二章 保护范围', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1004, 534, 1624, '第十条', '第十条 历史文化名城保护范围包括北关历史文化街区、历史城区和历史文化风貌区。北关历史文化街区为核心保护区。 （一）北关历史文化街区是指东至新华北路、南至和平路、西至寺西街和柴家沟、北至涡河南岸以内围合的区域。重点保护对象为：花戏楼、南京巷钱庄、北京…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (535, 'FBMCLI.10.1418169', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 13 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1005, 535, 1638, '第二十四条', '…保护责任人；没有代管人的，其使用权人为保护责任人；代管人、使用权人均不明确的，由市城乡规划主管部门会同文物主管部门、房产主管部门指定保护责任人，并予以公示； （二）非国有历史建筑，其所有权人为保护责任人；所有权人下落不明或者权属不清的，代管人为保护责任人；无代管人的，使用人为保护责任人。所有权人、代管人、使用人均不明…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1006, 535, 1639, '第二十五条', '…关部门的指导、检查和监督。 历史建筑的维护和修缮由所有权人负责，维护和修缮应当按市城乡规划主管部门会同文物主管部门审定的保护方案实施。 历史建筑有损毁危险，所有权人不具备修缮能力的，区人民政府应当采取措施予以保护。 任何单位或者个人不得损坏或者擅自迁移、拆除历史建筑。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1007, 535, 1619, '第五条', '第五条 市城乡规划主管部门会同文物主管部门负责历史文化名城的申报、保护规划的编制与实施、监督、管理等具体工作。 文化旅游、城市管理、房产、住建、国土资源、环保、发展改革、民政、公安、交通、民族宗教等有关主管部门在各自职责范围内做好历史文化名城保护…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (536, 'FBMCLI.10.1418169', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (537, 'FBMCLI.10.1418169', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、4 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1008, 537, 1648, '第三十四条', '…犯罪的，依法追究刑事责任： （一）未按照规定建立历史文化名城保护名录的； （二）未组织编制保护规划的； （三）未按照法定程序组织编制保护规划的； （四）擅自修改保护规划的； （五）未将批准的保护规划予以公布的； （六）未按照规定设置保护标志的； （七）未按照规定制定相关道路、供水、排水、供电、环卫、消防等专项措施的；…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1009, 537, 1629, '第十五条', '第十五条 编制或者修改城乡规划、土地利用总体规划以及其他专业规划，应当与历史文化名城保护规划相衔接。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1010, 537, 1619, '第五条', '第五条 市城乡规划主管部门会同文物主管部门负责历史文化名城的申报、保护规划的编制与实施、监督、管理等具体工作。 文化旅游、城市管理、房产、住建、国土资源、环保、发展改革、民政、公安、交通、民族宗教等有关主管部门在各自职责范围内做好历史文化名城保护工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (538, 'FBMCLI.10.1418169', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1011, 538, 1627, '第十三条', '…查工作。对具有保护价值且未列入历史文化名城保护名录的街区、建筑物、构筑物，应当采取措施实施预先保护。 第三章 保护措施', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (539, 'FBMCLI.10.1418169', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1012, 539, 1632, '第十八条', '…储存爆炸性、易燃性、放射性、毒害性、腐蚀性物品的工厂、仓库等； （四）在核心保护区范围内，拆除历史建筑以外的建筑物、构筑物或者其他设施的，应当经市城乡规划主管部门会同市文物主管部门批准； （五）对道路、供水、排水、供电、环卫、消防等基础设施进行改建的，应当制定专项措施，延续传统格局； （六）设置户外广告不得破坏历…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1013, 539, 1633, '第十九条', '…修或重建。属于非国有的商铺房、古民居房的，应当督促责任人限期修复； （五）在建筑物、古民居修缮时，不得挖坑取土，垒墙筑院，不得破坏体现古亳州商贸风格特色的黑门白封板、砖雕、石雕、木雕、彩绘、瓦当、木门插板、柱础、牛角弯梁等建筑构件。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1014, 539, 1635, '第二十一条', '第二十一条 在历史城区保护区域内的建设控制地带内进行新建、改建、扩建活动的，应当符合保护规划要求，按照批准的规划许可要求施工，并遵守下列规定： （一）在高度、体量、立面、色彩等方面与重点保护范围内的传统格局和历史风貌相协调； （二）不得破坏历史环境和人文景观特征； （三）不得危及重…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (540, 'FBMCLI.10.1418169', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1015, 540, 1620, '第六条', '… 市、区人民政府应当将历史文化名城保护工作纳入国民经济和社会发展规划，并将历史文化名城保护专项资金列入本级财政预算。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (541, 'FBMCLI.10.1418169', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1016, 541, 1645, '第三十一条', '…民政府可以采取以下措施促进保护对象的合理利用： （一）通过资金扶助、依法减免费用、开发权益奖励等措施支持合理利用； （二）依法设立管理运营企业或者组织，对历史文化资源进行整合、挖掘和宣传； （三）采取收购、产权置换、租赁、托管等方式取得非国有文物保护单位、非国有历史建筑的所有权或者使用权；鼓励企业、社会组织和个人…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1017, 541, 1621, '第七条', '…的街区、建筑物、构筑物，应当向文物主管部门报告。 鼓励企业事业单位、社会团体、个人以捐赠、资助、开展志愿者活动等形式参与历史文化名城的保护。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1018, 541, 1622, '第八条', '…史文化名城保护工作中做出突出成绩的单位和个人，市、区人民政府按照国家和省有关规定予以表扬和奖励。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (542, 'FBMCLI.10.1418169', 'RES', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (543, 'FBMCLI.10.1418169', 'BIZ', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1019, 543, 1646, '第三十二条', '…创意、休闲旅游、文化研究、传统手工业、非物质文化遗产传播、文化体验、开办展馆和博物馆等特色经营活动或者公益活动。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (544, 'FBMCLI.10.1418169', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (545, 'FBMCLI.10.1418169', 'SUP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1020, 545, 1621, '第七条', '第七条 任何单位和个人都有权提出历史文化名城保护的意见和建议，举报破坏历史文化名城的行为；发现有保护价值的街区、建筑物、构筑物，应当向文物主管部门报告。 鼓励企业事业单位、社会团体、个人以捐赠、资助、开展志愿者活动等形式参与历史文化名城的保护。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (546, 'FBMCLI.10.1418169', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1021, 546, 1648, '第三十四条', '第三十四条 国家机关及其工作人员有下列行为之一的，由上级人民政府责令改正；对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任： （一）未按照规定建立历史文化名城保护名录的； （二）未组织编制保护规划的； （三）未按照法定程序组织编制保护规划的； （四）擅自修改…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1022, 546, 1650, '第三十六条', '…者采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处五万元以上十万元以下的罚款，对个人并处一万元以上五万元以下的罚款；造成损失的，依法承担赔偿责任： （一）违反本条例第十八条第四项规定，未经批准，拆除历史建筑以外的建筑物、构筑物或者其他设施的； （二）违反本条例第十八条第五项、第六项规定，对传统格…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1023, 546, 1653, '第三十九条', '…取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处五十万元以上一百万元以下的罚款，对个人并处五万元以上十万元以下的罚款；造成损失的，依法承担赔偿责任： （一）采砂、开矿等破坏传统格局和历史风貌的； （二）占用保护规划确定保留的园林绿地、河湖水系、道路等的； （三）修建生产、储存爆炸性、易燃性、放射性…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (547, 'FBMCLI.10.1255208', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 8 个核心用语、12 个相关用语，关联 41 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1024, 547, 1663, '第八条', '…大运河（常州段）； （二）历史城区的传统格局和历史风貌； （三）青果巷、南市河、前后北岸等历史文化街区； （四）孟河等历史文化名镇； （五）焦溪等历史文化名村； （六）杨桥等中国传统村落； （七）天宁寺-舣舟亭、锁桥湾、南河沿、三堡街-西直街等历史地段； （八）历史建筑； （九）近现代工业遗产； （十）有历史价值的历史环…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1025, 547, 1657, '第二条', '…区域内历史文化名城的规划、保护、管理和利用，适用本条例。 历史文化名城保护包括对历史城区、历史文化街区、历史文化名镇、历史文化名村、中国传统村落、历史地段、历史建筑、文物保护单位、不可移动文物、古树名木、传统地名和非物质文化遗产等的保护。 在历史文化名城保护范围内，涉及文物保护单位、不可移动文物、古树名木、传统地名和非物…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1026, 547, 1675, '第二十条', '…十条 历史文化名城保护规划应当保护下列内容： （一）传统格局和历史风貌的完整性，文物古迹、历史建筑、历史环境要素、传统民居和非物质文化遗产； （二）大运河水利工程遗产、沿线物质文化遗产、聚落遗产、非物质文化遗产、生态和景观环境； （三）古园林、古牌坊、古井、古纤道、古码头、古桥梁、古树名木等历史环境要素与周边环境风貌…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (548, 'FBMCLI.10.1255208', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 17 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1027, 548, 1678, '第二十三条', '…定。 历史文化街区、历史文化名镇、历史文化名村、中国传统村落和历史地段保护规划应当划分核心保护范围和建设控制地带。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1028, 548, 1699, '第四十四条', '…管等部门组织编制历史建筑及历史文化街区、历史文化名镇、历史文化名村、中国传统村落和历史地段保护范围内的建筑物、构筑物的修缮图则，明确其修缮的具体要求，经专家论证后公布。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1029, 548, 1687, '第三十二条', '…关部门建设和改善历史城区、历史文化街区、历史文化名镇、历史文化名村、中国传统村落、历史地段保护范围内的道路、供水、排水、电力、环卫、消防等基础设施。 确因保护需要，在历史文化街区、历史文化名镇、历史文化名村、中国传统村落和历史地段核心保护范围内，无法按照现行技术标准和规范进行建设和管理的，消防、建设、交通、水利、文物…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (549, 'FBMCLI.10.1255208', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 35 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1030, 549, 1659, '第四条', '第四条 市人民政府负责本市历史文化名城的保护和监督管理工作。辖市（区）、镇人民政府负责所辖区域内历史文化名城的保护和监督管理工作。街道办事处按照本条例的规定，履行历史文化名城保护的相关职责。 市、辖市（区）人民政府应当将历史文化名城保护工…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1031, 549, 1685, '第三十条', '…人为保护责任人；没有代管人的，其使用权人为保护责任人；代管人、使用权人均不明确的，房屋行政主管部门为保护责任人； （二）非国有的，其所有权人为保护责任人；所有权人下落不明、无法与所有权人取得联系或者房屋权属不清晰的，代管人为保护责任人；所有权人下落不明、无法与所有权人取得联系或者房屋权属不清晰，且没有代管人的，房屋使…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1032, 549, 1704, '第四十九条', '…文化名城保护信息管理系统，实现信息共享，提高历史文化名城保护的信息化水平。 市城乡规划行政主管部门负责历史文化名城保护信息管理系统的管理和维护。 有关部门按照各自职责负责历史文化名城保护相关信息的采集、录入等工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (550, 'FBMCLI.10.1255208', 'COORD', 1, 2, 'low', 'machine_draft', '机器初编检出 1 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1033, 550, 1704, '第四十九条', '…民政府应当组织建立包含地理信息、地名信息、历史文化信息等历史文化名城保护信息管理系统，实现信息共享，提高历史文化名城保护的信息化水平。 市城乡规划行政主管部门负责历史文化名城保护信息管理系统的管理和维护。 有关部门按照各自职责负责历史文化名城保护相关信息的采集、录入等工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (551, 'FBMCLI.10.1255208', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 25 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1034, 551, 1671, '第十六条', '第十六条 历史文化名城、历史文化街区、历史文化名镇、历史文化名村等保护规划的组织编制、审批、修改等，按照国家和省有关规定执行。 中国传统村落、历史地段、历史建筑保护规划由市、辖市城乡规划行政主管部门会同文物等行政主管部门组织编制，报本级人民政府批准。 历史文化名城、历史文化街区、历史文化名镇、…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1035, 551, 1715, '第六十条', '…政主管部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分： （一）未组织编制保护规划的； （二）未按照法定程序组织编制、修改、公布保护规划和确定、调整保护名录的； （三）未按照法定程序或者未按照保护规划的要求履行审批职责的； （四）未制定适应保护需要的保障方案的； （五）未履行对历史建筑和传统风貌建筑安…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1036, 551, 1672, '第十七条', '第十七条 保护规划报送审批前，组织编制机关应当将规划草案予以公告，公告时间不少于三十日，并采取论证会、听证会或者其他方式征求有关主管部门、专家和公众的意见。 保护规划应当自批准之日起三十个工作日内，在政府网站和当地主要新闻媒体公布。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (552, 'FBMCLI.10.1255208', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (553, 'FBMCLI.10.1255208', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 14 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1037, 553, 1669, '第十四条', '…等； （三）使用现状和权属变化情况； （四）保护规划； （五）设计、测绘信息资料； （六）修缮、迁移、拆除过程中形成的文字、图纸、图片和影像等； （七）其他需要保存的资料。 任何单位和个人有权依法查询档案所记载的相关信息。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1038, 553, 1694, '第三十九条', '…科技与工艺增强其抗震、防火、防雷、防洪、防潮、防蛀等性能。 任何单位和个人不得损坏或者擅自迁移、拆除历史建筑。确因公共利益需要进行建设活动，对历史建筑无法实施原址保护、必须迁移或者拆除的，应当根据有关规定报请批准。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1039, 553, 1690, '第三十五条', '…和公共服务设施外，不得进行新建、扩建活动； （三）中国传统村落、历史地段保护范围内，新建、改建、扩建建筑物、构筑物的高度、体量、形态和色彩等，不得与传统格局和历史风貌相冲突； （四）历史建筑保护范围内，除因保护需要建设附属设施外，不得新建建筑物、构筑物。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (554, 'FBMCLI.10.1255208', 'FUND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1040, 554, 1661, '第六条', '第六条 市、辖市（区）人民政府应当设立历史文化名城保护专项资金，用于历史文化名城保护工作中的普查、测量、认定、抢险、规划编制、修缮补助、学术研究、奖励等方面。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (555, 'FBMCLI.10.1255208', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1041, 555, 1661, '第六条', '…史文化名城保护专项资金，用于历史文化名城保护工作中的普查、测量、认定、抢险、规划编制、修缮补助、学术研究、奖励等方面。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1042, 555, 1701, '第四十六条', '…的保护责任人，按照修缮技术要求、修缮图则进行修缮的，市、辖市（区）人民政府应当给予维护修缮补助。 维护修缮补助具体办法由市人民政府制定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1043, 555, 1706, '第五十一条', '…以依法变更或者撤回已经生效的行政许可；给公民、法人或者其他组织造成财产损失的，应当依法给予补偿。 补偿方案由城乡规划行政主管部门会同文物、发改、财政、房管、建设等有关部门制定，报本级人民政府批准后施行。 第五章 利用与传承', 'supporting');
