INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1044, 556, 1672, '第十七条', '…护规划报送审批前，组织编制机关应当将规划草案予以公告，公告时间不少于三十日，并采取论证会、听证会或者其他方式征求有关主管部门、专家和公众的意见。 保护规划应当自批准之日起三十个工作日内，在政府网站和当地主要新闻媒体公布。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1045, 556, 1713, '第五十八条', '…用的历史文化场所定期或者部分对公众开放。 鼓励建立历史文化名城保护专业志愿者服务队伍，引导公众参与历史文化名城保护和宣传工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1046, 556, 1722, '第六十七条', '…自2017年6月1日起施行。 背景资料 立法草案 《常州市历史文化名城保护条例(草案)》征求意见公告 本篇引用的法规 中央法规 中华人民共和国文物保护法(2015修正) 中华人民共和国城乡规划法(2015修正) 历史文化名城名镇名村保护条例 地方法规 江苏省历史文化名城名镇保护条例(2010修正) 引用本篇的法规 …', 'supporting');
