INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1047, 557, 1698, '第四十三条', '…境。 以居住使用功能为主的保护片区，应当延续保持其居住功能，控制人口密度，延续传统文化生活业态。', 'supporting');
