INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1048, 560, 1717, '第六十二条', '…其他补救措施；有违法所得的，没收违法所得；造成严重后果的，对单位并处五万元以上十万元以下的罚款，对个人并处一万元以上五万元以下的罚款；造成损失的，依法承担赔偿责任。 保护责任人未按照规定履行保护责任，对传统风貌建筑造成损坏的，由城乡规划行政主管部门责令停止违法行为、限期恢复原状或者采取其他补救措施；有违法所得的，…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1049, 560, 1718, '第六十三条', '…补救措施；有违法所得的，没收违法所得；造成严重后果的，对单位并处五十万元以上一百万元以下的罚款，对个人并处五万元以上十万元以下的罚款；造成损失的，依法承担赔偿责任： （一）开山、采石、开矿等破坏传统格局和历史风貌的活动； （二）占用保护规划确定保留的园林绿地、河湖水系、传统街巷、道路等； （三）修建生产、储存爆炸…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1050, 560, 1715, '第六十条', '…例规定，国家机关及其工作人员有下列情形之一的，由市、辖市（区）人民政府或者有关行政主管部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分： （一）未组织编制保护规划的； （二）未按照法定程序组织编制、修改、公布保护规划和确定、调整保护名录的； （三）未按照法定程序或者未按照保护规划的要求履行审批职责的；…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (561, 'FBMCLI.10.1424720', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 6 个核心用语、10 个相关用语，关联 28 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1051, 561, 1735, '第十三条', '第十三条 历史文化名城、历史文化名镇、历史文化名村、历史文化街区、传统镇街、传统村落、传统场所、历史建筑的保护规划应当包括下列内容： （一）保护原则、保护内容和保护范围； （二）保护措施、开发强度和建设控制要求； （三）传统格局和历史风貌保护要求； （四）保护规划分期实施方案。 历史…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1052, 561, 1756, '第三十四条', '第三十四条 历史文化名城、历史文化名镇、历史文化名村、历史文化街区、历史建筑的保护范围内禁止进行下列行为： （一）开山、采石、开矿等； （二）占用保护规划确定保留的园林绿地、河湖水系、道路等； （三）修建生产和储存爆炸性、易燃性、放射性、毒害性、腐蚀性物品的工厂、仓库等； （四）在历史…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1053, 561, 1737, '第十五条', '…护单位，开发和利用唐宋时期历史遗存资源，突出府城历史风貌为主题； （三）“海滨邹鲁”以保护历史文化街区，体现民俗生活氛围和弘扬潮州传统文化、民俗风貌为主题； （四）“商埠侨乡”以保护有代表性的近代建筑与革命史迹，弘扬潮籍华侨爱国爱乡的精神、反映潮州作为对外开放商埠的历史为主题。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (562, 'FBMCLI.10.1424720', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、6 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1054, 562, 1735, '第十三条', '…镇街、传统村落、传统场所、历史建筑的保护规划应当包括下列内容： （一）保护原则、保护内容和保护范围； （二）保护措施、开发强度和建设控制要求； （三）传统格局和历史风貌保护要求； （四）保护规划分期实施方案。 历史文化名镇、历史文化名村、历史文化街区的保护规划应当包括核心保护范围和建设控制地带。历史文化名镇、名村、街…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1055, 562, 1753, '第三十一条', '…护图则包括下列主要内容： （一）基本信息、保护类别、风貌特色及其相关环境要素； （二）核心保护范围和建设控制地带内的保护控制要求； （三）保护、维护修缮要求； （四）合理利用指引； （五）历史建筑保护规划要求的其他内容。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1056, 562, 1755, '第三十三条', '第三十三条 历史文化名镇、历史文化名村、历史文化街区核心保护范围内，除新建、扩建、改建必要的基础设施和公益性公共服务设施外，不得进行与保护无关的建设活动。 历史文化名镇、历史文化名村、历史文化街区建设控制地带进行新建、扩建、改建活动，应当符合保护规划或者保护措施的要求，不得破坏传统格…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (563, 'FBMCLI.10.1424720', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 30 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1057, 563, 1742, '第二十条', '… 国家和省、市人民政府确定的保护对象，直接纳入历史文化名城保护名录。 市、县（区）城乡规划主管部门对普查中发现的具有保护价值且尚未列入历史文化名城保护名录的镇街、村庄、街区、建筑物、构筑物，应当会同同级文物主管部门征求有关建筑物、构筑物所有权人、使用权人或者代管人的意见，并组织勘验和专家论证，确有保护价值的，分别启动…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1058, 563, 1746, '第二十四条', '…代管人为保护责任人；没有代管人的，其使用权人为保护责任人；代管人、使用权人均不明确的，房屋主管部门为保护责任人； （二）非国有历史建筑，其所有权人为保护责任人；所有权人下落不明、无法与所有权人取得联系或者房屋权属不明晰的，代管人为保护责任人；所有权人下落不明、无法与所有权人取得联系或者房屋权属不明晰，且没有代管人的，…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1059, 563, 1748, '第二十六条', '第二十六条 历史文化名镇、历史文化名村、历史文化街区的保护责任人应当履行以下职责： （一）组织实施保护规划，保持传统格局、历史风貌、空间尺度和与其相互依存的自然景观和环境； （二）在保护街道空间尺度和风貌的情况下，改善基础设施、公共服务设施和居住环境； （三）开展日常巡查，发现危害历…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (564, 'FBMCLI.10.1424720', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (565, 'FBMCLI.10.1424720', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、5 个相关用语，关联 19 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1060, 565, 1734, '第十二条', '第十二条 历史文化名城、历史文化名镇、历史文化名村、历史文化街区保护规划的编制和审批依据有关法律法规执行。 传统镇街、传统村落、传统场所、历史建筑的保护规划，由所在地县（区）人民政府组织编制并报送市人民政府审批。 市、县（区）人民政府应当加强对各类保护规划实施情况的监督检查，并对各类保护对象…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1061, 565, 1764, '第四十二条', '…人员，依法追究行政责任；构成犯罪的，依法追究刑事责任。 （一）未按照法定程序组织编制、修改保护规划和确定、调整保护名录的； （二）未按照法定程序或者未按照保护规划的要求履行审批职责的； （三）未依法对保护对象的保护状况实施监督检查，或者对经批准的保护对象的改造、利用情况监管不力的； （四）未依法受理举报、控告和查处违…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1062, 565, 1727, '第五条', '第五条 城乡规划主管部门负责组织开展保护规划的编制、历史文化街区和历史建筑的普查及维护修缮等工作，并会同文物主管部门组织实施本条例。 文物主管部门负责法律法规和本条例规定的有关历史文化名城的保护和监督管理工作。 城市管理和综合执法部门负责对历史文化名城保护中违反规…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (566, 'FBMCLI.10.1424720', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (567, 'FBMCLI.10.1424720', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1063, 567, 1752, '第三十条', '…照规定形成历史建筑测绘、图像等资料，报送市、县（区）城乡规划主管部门。 历史建筑原址保护、迁移、拆除所需费用，由建设单位列入建设工程预算。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1064, 567, 1744, '第二十二条', '…等； （三）使用现状和权属变化情况； （四）保护规划； （五）设计、测绘信息资料； （六）修缮、迁移、拆除过程中形成的文字、图纸、图片和影像等资料； （七）其他需要保存的资料。 第三章 保护责任和保护措施', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1065, 567, 1768, '第四十六条', '…活动的； （三）拆除历史建筑以外的建筑物、构筑物或者其他设施的； （四）对历史建筑进行外部修缮装饰、添加设施以及改变历史建筑的结构或者使用性质的； （五）其他影响传统格局、历史风貌或者历史建筑的。 有关单位或者个人经批准进行上述活动，但是在活动过程中对传统格局、历史风貌或者历史建筑构成破坏性影响的，依照本条第一款…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (568, 'FBMCLI.10.1424720', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1066, 568, 1728, '第六条', '…展规划，将历史文化名城保护经费列入本级财政预算。 市、县（区）人民政府设立历史文化名城保护专项资金，用于保护对象普查、保护名录制定、保护规划编制、维护修缮补助、表彰和奖励、学术研究、宣传教育等方面。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (569, 'FBMCLI.10.1424720', 'COMP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1067, 569, 1728, '第六条', '…民政府设立历史文化名城保护专项资金，用于保护对象普查、保护名录制定、保护规划编制、维护修缮补助、表彰和奖励、学术研究、宣传教育等方面。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1068, 569, 1733, '第十一条', '…实物。 在历史文化名城保护工作中做出突出贡献的单位和个人，由市、县（区）人民政府给予表彰和奖励。 第二章 保护规划和保护名录', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1069, 569, 1754, '第三十二条', '…要求履行维护修缮义务的，市、县（区）人民政府可以根据其维护修缮的面积、程度和质量等情况给予补助。 维护修缮补助的具体办法，由市、县（区）人民政府制定。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (570, 'FBMCLI.10.1424720', 'RES', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (571, 'FBMCLI.10.1424720', 'BIZ', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (572, 'FBMCLI.10.1424720', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (573, 'FBMCLI.10.1424720', 'SUP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1070, 573, 1764, '第四十二条', '…保护状况实施监督检查，或者对经批准的保护对象的改造、利用情况监管不力的； （四）未依法受理举报、控告和查处违法行为的； （五）滥用职权、玩忽职守、徇私舞弊的； （六）法律法规规定的其他违法行为。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1071, 573, 1733, '第十一条', '…十一条 任何单位和个人都有权提出历史文化名城保护的意见和建议，对破坏历史文化名城的行为进行举报。 鼓励企事业单位、社会团体和个人通过设立社会基金、捐赠、开展志愿者活动等形式参与历史文化名城的保护。 鼓励单位和个人开展传统地名、历史文献、历史影像等资料的搜集整理工作，向档案部门提供历史文献、历史影像资料的信息或实物…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (574, 'FBMCLI.10.1424720', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1072, 574, 1766, '第四十四条', '…采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处五十万元以上一百万元以下罚款，对个人并处五万元以上十万元以下罚款；造成损失的，依法承担赔偿责任。 违反本条例第三十四条第（四）项规定的，由市、县（区）城市管理和综合执法部门责令恢复原状或者采取其他补救措施，并处五十元罚款。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1073, 574, 1768, '第四十六条', '…或者采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处五万元以上十万元以下罚款，对个人并处一万元以上五万元以下罚款；造成损失的，依法承担赔偿责任： （一）改变园林绿地、河湖水系等自然状态的； （二）进行影视摄制、举办大型群众性活动的； （三）拆除历史建筑以外的建筑物、构筑物或者其他设施的； （四）…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1074, 574, 1765, '第四十三条', '…采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处二十万元以上五十万元以下罚款，对个人并处十万元以上二十万元以下罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (575, 'FBMCLI.10.1587081', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、8 个相关用语，关联 42 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1075, 575, 1818, '第四十九条', '第四十九条 区县（市）人民政府应当确定历史文化街区、历史文化风貌区的保护责任人，并向社会公布。 保护责任人应当按照保护规划，履行下列保护责任： （一）保持保护范围内建筑物、构筑物的传统格局、历史风貌、特色装饰、空间尺度和历史环境要素的完整性； （二）开展日常巡查，发现危…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1076, 575, 1838, '第六十九条', '…历史发展过程或者某一发展时期风貌，历史范围清楚，历史建筑较多，需要保护控制的区域。 （二）历史文化街区，是指经省人民政府核定公布，保存文物特别丰富、历史建筑集中成片、能够较完整和真实地体现传统格局和历史风貌，并具有一定规模的区域。 （三）历史文化风貌区，是指经市、县（市）人民政府核定公布，保存历史建筑集中成片，建筑样式、…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1077, 575, 1820, '第五十一条', '第五十一条 资源规划部门会同住建部门，与历史院落和历史建筑保护责任人签订保护责任书，明确保护责任。历史院落和历史建筑的保护责任人，应当按照保护规划的要求，履行下列保护责任： （一）保持原有的高度、体量、外观形象和色彩，整洁美观； （二）保护传统格局、历史风貌、特色装饰和历史环境…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (576, 'FBMCLI.10.1587081', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1078, 576, 1788, '第十九条', '… 市、县（市）人民政府应当自保护名录公布之日起六十日内，在历史文化街区、历史文化风貌区核心保护范围的主要出入口，历史院落和历史建筑显著位置设置保护标志。 保护标志的设置应当与保护对象传统风貌协调一致。保护标志应当载明保护对象的名称、编号、区位、建成时间、历史价值、文化信息等内容，根据实际需要翻译成相应的外文，配备二维…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1079, 576, 1796, '第二十七条', '第二十七条 历史建筑保护规划应当明确下列保护内容： （一）历史建筑的保护范围，包括历史建筑核心保护范围和建设控制地带； （二）历史建筑的风貌特色及其相关环境要素； （三）历史建筑的保护和利用要求。 历史院落的保护规划按照历史建筑的规划控制要求进行确定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1080, 576, 1807, '第三十八条', '第三十八条 在历史文化街区核心保护范围内，不得进行新建、扩建活动。新建、扩建必要的基础设施和公共服务设施除外。 在历史文化街区核心保护范围内，新建、扩建必要的基础设施和公共服务设施的，应当符合保护规划确定的建设控制要求。资源规划部门核发建设工程规划许可证前，…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (577, 'FBMCLI.10.1587081', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 18 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1081, 577, 1774, '第五条', '第五条 自然资源和规划行政主管部门（以下简称资源规划部门）负责历史文化名城保护和监督管理的具体工作。 文物行政主管部门（以下简称文物部门）负责不可移动文物中的建筑物、构筑物保护管理的具体工作。 财政行政主管部门（以下简称财政部门）负责历史文化名城保护资金…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1082, 577, 1820, '第五十一条', '…要素的完整性； （三）保障结构安全，防渗防潮防蛀，发现险情时及时采取排险措施，并向有关行政主管部门报告； （四）确保消防、防灾等设施、设备的正常使用。 转让、出租历史建筑的，双方当事人应当在合同中约定保护及修缮义务，出让人、出租人应当将保护修缮要求告知受让人、承租人。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1083, 577, 1773, '第四条', '第四条 本条例由市人民政府组织实施。 区县（市）人民政府负责本辖区内历史文化名城的保护和监督管理工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (578, 'FBMCLI.10.1587081', 'COORD', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1084, 578, 1777, '第八条', '…物、住建等有关部门应当根据各自职责采集、录入、管理和维护历史文化名城保护的相关信息，并实现信息共享，提高历史文化名城保护工作的智能化管理水平。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (579, 'FBMCLI.10.1587081', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 26 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1085, 579, 1800, '第三十一条', '第三十一条 经依法批准的保护规划，不得擅自修改；确需修改的，保护规划的组织编制机关应当向原审批机关提出专题报告，经同意后，方可编制修改方案。修改后的保护规划，应当按照原审批程序报送审批。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1086, 579, 1791, '第二十二条', '第二十二条 市、县（市）人民政府负责组织编制历史文化名城保护规划，报省人民政府审批。历史文化名城保护规划应当纳入城市总体规划要求。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1087, 579, 1793, '第二十四条', '…门应当自历史城区、历史文化街区、历史文化风貌区、历史院落和历史建筑批准之日起一年内编制完成保护规划，由本级人民政府批准，并报同级人民代表大会常务委员会备案。本条例公布实施前，尚未编制完成的，应当自保护名录公布之日起一年内编制完成。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (580, 'FBMCLI.10.1587081', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1088, 580, 1838, '第六十九条', '…期地域文化特点，文物古迹及历史建筑用地不足百分之六十的地区，尚不具备历史文化街区条件，或者尚未核定公布为历史文化街区的区域。 （四）历史院落，是指经市、县（市）人民政府确定公布，空间布局形态和建筑风格具有传统地方风貌特点，或者能够比较完整、真实地反映一定历史时期的历史事件、历史人物活动，主要由历史建筑所围合、限定的，有明…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (581, 'FBMCLI.10.1587081', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 17 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1089, 581, 1807, '第三十八条', '…规划部门核发建设工程规划许可证前，应当征求文物部门的意见。 在历史文化街区核心保护范围内，拆除历史建筑以外的建筑物、构筑物或者其他设施的，应当经资源规划部门会同文物部门批准。 历史文化街区核心保护范围内，除历史建筑以外的危旧房屋倒塌或者濒临倒塌，可以进行改建、复建和翻建。从事改建、复建和翻建活动的，依照有关法律、…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1090, 581, 1790, '第二十一条', '…等； （三）使用现状和权属变化情况； （四）保护规划； （五）设计、测绘信息资料； （六）修缮、迁移、拆除过程中形成的文字、图纸、图片和影像等； （七）其他需要保存的资料。 单位和个人有权依法查询档案所记载的相关信息。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1091, 581, 1814, '第四十五条', '第四十五条 对历史建筑应当实施原址保护，单位和个人不得损坏或者擅自迁移、拆除历史建筑。 因公共利益需要，无法实施原址保护、必须迁移异地保护或者拆除的，建设单位应当事先制定建设方案。迁移或者拆除历史建筑的，应当由市、县（市）资源规划部门会同同级文物部门，报省有关部门批准。 经批准迁移历史建筑…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (582, 'FBMCLI.10.1587081', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1092, 582, 1802, '第三十三条', '第三十三条 市、区县（市）人民政府应当将历史文化名城保护资金（以下简称保护资金）列入同级财政预算。保护资金主要用于以下方面： （一）濒危历史建筑的抢救工作； （二）对历史院落、历史建筑的收购、征收； （三）对历史文化街区、历史文化风貌区、历史院落和历史建筑的维护和修缮的补助； （…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1093, 582, 1774, '第五条', '…的建筑物、构筑物保护管理的具体工作。 财政行政主管部门（以下简称财政部门）负责历史文化名城保护资金的管理工作。 住房和城乡建设、城市管理等行政主管部门，按照各自职责权限，负责做好历史文化名城保护、管理和利用的相关工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1094, 582, 1803, '第三十四条', '第三十四条 市财政部门会同市资源规划等部门制定保护资金的使用管理办法，并报市人民政府批准。 保护资金的使用和管理应当接受社会的监督。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (583, 'FBMCLI.10.1587081', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1095, 583, 1802, '第三十三条', '…建筑的收购、征收； （三）对历史文化街区、历史文化风貌区、历史院落和历史建筑的维护和修缮的补助； （四）历史文化名城保护对象的普查工作； （五）对在历史文化名城保护工作中做出突出贡献的单位和个人给予奖励； （六）与历史文化名城保护相关的其他工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1096, 583, 1825, '第五十六条', '…市）人民政府或者委托专门机构予以收购；保护责任人不提出收购申请，符合《国有土地上房屋征收与补偿条例》规定的，依法予以征收。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1097, 583, 1778, '第九条', '…引导全民参与历史文化名城保护。对在历史文化名城保护工作中做出突出贡献的单位和个人给予表彰、奖励。 市、区县（市）人民政府可以委托符合条件的研究机构、行业协会和其他社会组织开展与历史文化名城保护相关的基础研究、专业培训、宣传教育活动。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (584, 'FBMCLI.10.1587081', 'RES', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1098, 584, 1832, '第六十三条', '第六十三条 保护哈尔滨典型的住宅建筑及街区环境，改善居住建筑群的市政设施，鼓励原住居民依据保护规划要求在原址居住，延续传统的生活方式和社区文脉。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1099, 584, 1780, '第十一条', '第十一条 鼓励建立历史文化名城保护专业志愿者服务队伍，引导公众参与历史文化名城保护和宣传工作。 市、区县（市）人民政府应当为社会力量参与历史文化名城保护提供服务。 第二章 保护名录', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1100, 584, 1798, '第二十九条', '…，规划委员会审议通过。 保护规划草案应当予以公示，公示时间不少于三十日，并通过召开论证会、听证会等方式征求有关部门、专家和公众的意见。保护规划报送审批文件应当附具意见采纳情况及理由；经听证的，还应当附具听证笔录。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (585, 'FBMCLI.10.1587081', 'BIZ', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1101, 585, 1830, '第六十一条', '…专业管理要求和保护规划要求的前提下，可以通过开办博物馆、陈列馆，开展传统文化研究，从事民俗经营活动等方式保护性利用历史建筑，并享有经营收益。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (586, 'FBMCLI.10.1587081', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (587, 'FBMCLI.10.1587081', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1102, 587, 1776, '第七条', '第七条 规划委员会下设历史文化名城保护专家委员会（以下简称专家委员会），对保护规划、保护名录等事项进行论证和评审。 专家委员会由规划、建筑、房产、园林、文化、文物、历史、民俗、旅游、宗教、社会和法律等方面的专家组成。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1103, 587, 1779, '第十条', '第十条 单位和个人都有保护历史文化名城的义务，对破坏历史文化名城的行为有权阻止和举报，有关部门应当及时查处，并将结果告知举报人。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1104, 587, 1782, '第十三条', '第十三条 历史城区和历史文化街区应当由资源规划部门组织调查，经专家委员会评审、规划委员会审议通过后，由市、县（市）人民政府向省人民政府申报。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (588, 'FBMCLI.10.1587081', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1105, 588, 1835, '第六十六条', '…六条 违反本条例规定，有下列行为之一的，由资源规划部门责令改正，并处五万元以上二十万元以下罚款： （一）改变一类历史建筑原有的立面造型、表面材质、色调、结构体系、平面布局和有特色的室内装饰的； （二）改变二类历史建筑原有的立面造型、表面材质、色调和主要平面布局的； （三）改变三类历史建筑原有的立面造型、表面材质和…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1106, 588, 1836, '第六十七条', '…建筑造成损坏的，由资源规划部门对维护和修缮单位责令限期恢复原状，处以十万元以上二十万元以下罚款。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1107, 588, 1833, '第六十四条', '…校本课程，通过开展公益讲座、学生社会实践等活动，加强历史文化名城保护的相关教育。 第六章 法律责任', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (589, 'FBMCLI.10.1640823', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、10 个相关用语，关联 44 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1108, 589, 1851, '第十一条', '…象包括： （一）历史城区的自然格局和传统风貌； （二）古城、圩子壕保护区，商埠区； （三）历史文化街区、传统风貌区； （四）历史文化名镇、历史文化名村、传统村落； （五）历史建筑； （六）不可移动文物、地下文物保护区、名泉、山体、湿地、古树名木、传统地名、工业遗产和法律、法规规定的保护对象。 涉及不可移动文物、地下文物保…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1109, 589, 1845, '第五条', '… 市住房和城乡建设主管部门会同自然资源和规划、文物主管部门负责历史文化名城、名镇、名村以及历史文化街区、历史建筑的保护和监督管理具体工作。 市自然资源和规划主管部门负责历史文化名城、历史文化街区、传统风貌区和历史建筑保护的规划管理工作，指导历史文化名镇、名村、传统村落保护规划编制工作。 市文物主管部门负责指导历史文化名城…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1110, 589, 1866, '第二十六条', '第二十六条 在历史文化名城、名镇、名村和历史文化街区保护范围内进行下列活动，应当保护其传统格局、历史风貌、不可移动文物和历史建筑；制订保护方案，依照有关法律、法规的规定办理相关手续： （一）改变林地绿地、河湖水系等自然状态的活动； （二）在核心保护范围内进行影视摄制、举办…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (590, 'FBMCLI.10.1640823', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、6 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1111, 590, 1861, '第二十一条', '…、所在位置和建设年代； （二）核心价值要素； （三）保护类别、保护要求和利用建议； （四）保护范围、建设活动控制要求和禁止使用功能； （五）法律、法规规定的其他内容。 市、县自然资源和规划主管部门应当将历史建筑保护图则及使用说明书，免费向所有权人、使用人、管理人（代管人）和物业服务单位提供。 第四章 保护措施', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1112, 590, 1867, '第二十七条', '第二十七条 在历史文化名镇、名村和历史文化街区、传统风貌区的保护范围内进行建设活动，应当遵守下列要求： （一）历史文化名镇、名村和历史文化街区的核心保护范围内，不得进行新建、扩建活动。确需新建、扩建基础设施、公共服务设施的，建设单位应当提交符合保护规划要求的建设方案，市、县自然资源和规划…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1113, 590, 1882, '第四十二条', '第四十二条 历史文化名镇、名村和历史文化街区的标志牌应当在保护规划批准后三个月内，在核心保护范围的主要出入口设置完毕。历史建筑的标志牌应当在保护名录公布后六个月内设置完毕。标志牌应当载明保护对象的名称、编号、区位、存续时间、保护类别和历史价值等内容，并可以根据实际需要翻译成外文。 历史城区内已消失的重要古水系、古建…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (591, 'FBMCLI.10.1640823', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 32 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1114, 591, 1845, '第五条', '第五条 市住房和城乡建设主管部门会同自然资源和规划、文物主管部门负责历史文化名城、名镇、名村以及历史文化街区、历史建筑的保护和监督管理具体工作。 市自然资源和规划主管部门负责历史文化名城、历史文化街区、传统风貌区和历史建筑保护的规划管理工作，指导历史文…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1115, 591, 1864, '第二十四条', '第二十四条 市自然资源和规划主管部门应当建立包含地理信息、地名信息、历史文化信息等内容的历史文化名城保护信息管理平台，负责历史文化名城保护信息管理平台的管理和维护。 住房和城乡建设、文物、城乡水务、园林和林业绿化、工业和信息化、民政、民族宗教、综合行政执法…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1116, 591, 1869, '第二十九条', '…采取下列保护措施： （一）传统地名无特殊情况不得变更，如确需变更地名的，民政和行政审批服务主管部门应当征得自然资源和规划主管部门同意后按法定程序批准、登记，必要时应当组织专家论证和征求公众意见。 对传统地名已消失但是城市道路、街道、桥梁、堤坝、建筑物、构筑物等还存在的，民政和行政审批服务主管部门应当会同自然资源和规划…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (592, 'FBMCLI.10.1640823', 'COORD', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1117, 592, 1864, '第二十四条', '…负责历史文化名城保护相关信息的采集、录入等工作，及时纳入历史文化名城保护信息管理平台，实现信息共享。 历史文化名城保护信息管理平台应当向社会公开发布历史文化名城保护名录，历史文化名城、名镇、名村和历史文化街区、传统风貌区的保护规划以及历史建筑保护图则等相关信息，为企事业单位、社会团体和个人开展或者参与保护利用提供支持…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1118, 592, 1844, '第四条', '第四条 市人民政府负责本市历史文化名城的保护和监督管理工作，建立历史文化名城保护联席会议制度，设立历史文化名城保护专家评审委员会，统筹协调解决工作中的重大问题等。 县（区）人民政府负责本辖区内历史文化名城的保护和监督管理工作。 镇人民政府、街道办事处应当协助做好历史文化名城的保护和监督管理工作。 村（居）民…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (593, 'FBMCLI.10.1640823', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、7 个相关用语，关联 21 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1119, 593, 1859, '第十九条', '第十九条 保护规划应当作为规划管理和建设的依据，其组织编制、审批、修改程序应当依照法律、法规的规定执行。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1120, 593, 1860, '第二十条', '第二十条 历史文化名城、名镇保护规划应当分别纳入市或者县、镇国土空间总体规划；历史文化街区、传统风貌区保护规划应当纳入所在地区的控制性详细规划；历史文化名村、传统村落保护规划应当纳入村庄规划，保护规划深度达到村庄规划深度的，可以作为该村的村庄规划。 涉及历…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1121, 593, 1893, '第五十三条', '…，依法给予处分；构成犯罪的，依法追究刑事责任： （一）未组织编制或者未按照法定程序组织编制保护规划的； （二）擅自修改保护规划的； （三）未按照保护规划的要求或者未按照法定程序履行审批职责的； （四）未依法履行保护和监督管理职责，导致历史文化名城、名镇、名村和历史文化街区被警示、撤销称号的； （五）其他滥用职权、玩忽…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (594, 'FBMCLI.10.1640823', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1122, 594, 1855, '第十五条', '第十五条 本市建立历史文化名城保护对象潜在资源预先保护制度，定期开展辖区范围内的历史文化名城保护对象潜在资源普查工作。县（区）人民政府将在普查中或者日常管理中发现并经专家论证认为具有保护价值的镇、村、街区和建筑物、构筑物等确定为预先保护对象，纳入预先保护名录。 县（区）人民…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1123, 594, 1856, '第十六条', '第十六条 纳入保护名录、预先保护名录的保护对象的保护层级和类型发生变化，或者严重损毁、灭失，确已失去保护意义，需要调整、撤销的，由相关保护主管部门及时提出保护名录调整方案。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (595, 'FBMCLI.10.1640823', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 14 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1124, 595, 1870, '第三十条', '…不小于二十厘米可以张贴楹联的空间。 （二）城乡水务主管部门应当开展对名泉泉池、泉渠的维护、修缮及其人文环境整治的监督检查和技术指导；实施对圩子壕现状河道及驳岸的整治，并会同自然资源和规划、文物、住房和城乡建设主管部门组织专家论证，报市人民政府批准后逐步贯通圩子壕水系。 （三）园林和林业绿化主管部门应当加强城市公共…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1125, 595, 1867, '第二十七条', '…时应组织专家论证和征求公众意见。 （二）在历史文化名镇、名村和历史文化街区核心保护范围内，拆除历史建筑以外的建筑物、构筑物或者其他设施的，建设单位应当提交符合保护规划要求的拆除方案，经市、县（区）住房和城乡建设主管部门会同同级自然资源和规划、文物主管部门批准，必要时应组织专家论证和征求公众意见。 （三）历史文化名…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1126, 595, 1869, '第二十九条', '…按法定程序对传统地名予以变更恢复。 （二）文物主管部门发现国有不可移动文物使用人不依法履行修缮义务时，应当责令其履行修缮义务；非国有不可移动文物所有权人具备修缮能力而拒不依法履行修缮义务的，文物主管部门报经同级人民政府批准，可以组织抢救修缮，所需费用由所有权人承担。 （三）住房和城乡建设主管部门应当会同自然资源和…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (596, 'FBMCLI.10.1640823', 'FUND', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1127, 596, 1847, '第七条', '…应当将历史文化名城保护工作纳入本级国民经济和社会发展规划，历史文化名城保护所需资金列入本级财政预算，保障经费投入。 历史文化名城保护经费用于普查、测绘、认定、抢险、规划编制、修缮、补助、奖励、学术研究等方面。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1128, 596, 1874, '第三十四条', '…历史建筑的维护和修缮的，可以向市或者县（区）人民政府申请补助。市或者县（区）人民政府可以从保护资金中给予补助。保护资金补助具体办法，由市人民政府另行制定公布。 市、县（区）住房和城乡建设、自然资源和规划主管部门应当对保护所需的抢救、修缮、维护等活动无偿提供技术指导与服务。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (597, 'FBMCLI.10.1640823', 'COMP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、5 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1129, 597, 1847, '第七条', '…财政预算，保障经费投入。 历史文化名城保护经费用于普查、测绘、认定、抢险、规划编制、修缮、补助、奖励、学术研究等方面。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1130, 597, 1889, '第四十九条', '…可以采取收购、产权置换等方式对非国有历史建筑进行保护利用。鼓励通过政策引导、费用减免、资金补助等方式吸引社会资本投入保护利用。 鼓励单位和个人采用出资、捐资、捐赠、设立基金、提供技术服务或者以建筑物、构筑物出租、入股等方式参与保护利用。 支持非物质文化遗产代表性项目传承人在历史文化街区、不可移动文物、历史建筑中开…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1131, 597, 1890, '第五十条', '第五十条 市、县（区）人民政府可以通过政策引导、资金资助、简化手续和技术指导等方式促进历史建筑的合理利用，同时还可以通过减免国有历史建筑租金、开发权益奖励等方式促进对国有历史建筑的合理利用。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (598, 'FBMCLI.10.1640823', 'RES', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1132, 598, 1885, '第四十五条', '…五条 历史文化名城、名镇、名村和历史文化街区、传统风貌区以及历史建筑的保护与利用，应当保障原住居民的合法权益，调动原住居民参与保护的积极性。 鼓励原住居民从事当地特色产业的生产经营等相关活动，改善其生产生活条件，促进历史文化名镇、名村和历史文化街区、传统风貌区原有形态、生活方式的延续传承。 鼓励原住居民在历史文化名城…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1133, 598, 1848, '第八条', '…教育活动，普及保护知识，增强社会公众保护意识。鼓励建立历史文化名城保护志愿者服务队伍，引导公众参与历史文化名城保护和宣传工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (599, 'FBMCLI.10.1640823', 'BIZ', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1134, 599, 1884, '第四十四条', '…当保护优先、适度利用，宜居则居、宜业则业，采用渐进式、微改造的方式，注重保护整体风貌，注重商业开发强度管控。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1135, 599, 1888, '第四十八条', '…文化遗产展示，发展文化旅游产业、地方文化研究，开设博物馆、陈列馆、纪念馆、传统作坊以及开展商业、民宿等活动。 历史建筑的合理利用应当与其历史价值、内部结构相适应，符合保护图则和有关消防技术标准和规范，不得擅自改变历史建筑主体结构、主要平面布局和外观，不得危害历史建筑及其附属设施的安全。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (600, 'FBMCLI.10.1640823', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (601, 'FBMCLI.10.1640823', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1136, 601, 1850, '第十条', '第十条 任何单位和个人对违反历史文化名城保护法律、法规的违法行为有权进行投诉和举报。相关部门接到投诉和举报，应当及时受理并组织核查、处理。 第二章 保护名录', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1137, 601, 1863, '第二十三条', '…道办事处，应当按照保护规划和下列要求履行保护责任： （一）受理村（居）民对历史文化名城保护投诉和意见建议，制止危害历史文化遗产的行为，并及时报告相关行政管理部门； （二）协助有关部门确保消防、防灾等公共设施、设备的正常使用； （三）本条例规定和市、县（区）人民政府确定的其他要求。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (602, 'FBMCLI.10.1640823', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、5 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1138, 602, 1894, '第五十四条', '…用由违法者承担；造成严重后果的，由综合行政执法主管部门对单位并处五十万元以上一百万元以下的罚款，对个人并处五万元以上十万元以下的罚款；造成损失的，依法承担赔偿责任： （一）开山、采石、开矿等破坏传统格局和历史风貌的； （二）占用保护规划确定保留的林地绿地、河湖水系、道路等的； （三）修建生产、储存爆炸性、易燃性、…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1139, 602, 1896, '第五十六条', '…用由违法者承担；造成严重后果的，由综合行政执法主管部门对单位并处二十万元以上五十万元以下的罚款，对个人并处十万元以上二十万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1140, 602, 1897, '第五十七条', '…需费用由违法者承担；造成严重后果的，由综合行政执法主管部门对单位并处五万元以上十万元以下的罚款，对个人并处一万元以上五万元以下的罚款；造成损失的，依法承担赔偿责任： （一）在历史文化名镇、名村和历史文化街区核心保护范围内，拆除历史建筑以外的建筑物、构筑物或者其他设施的； （二）对历史建筑进行外部修缮装饰、添加设施…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (603, 'FBMCLI.10.1591538', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 8 个核心用语、12 个相关用语，关联 15 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1141, 603, 1905, '第四条', '第四条 本市历史文化名城的保护对象包括历史城区、历史文化名镇、历史文化名村、历史村镇、历史文化街区、历史地段、历史建筑、传统风貌建筑，体现历史文化名城内涵的山水环境、文化线路、历史环境要素，以及有关法律、法规中确定的其他保护对象。 涉及不可移动文物、地下文物、名人故（旧）居、传统地名、古树名木、工业遗产、非物质文化遗…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1142, 603, 1946, '第四十五条', '…列用语的含义是： （一）传统风貌建筑，是指历史城区、历史文化名镇、历史文化名村、历史村镇、历史文化街区、历史地段范围内除文物保护单位、历史建筑外，具有一定建成历史，对整体风貌形成具有价值和意义的建（构）筑物。 （二）历史村镇，是指未被确定为国家、云南省的历史文化名镇、历史文化名村，经市人民政府批准公布为市级保护对象的村镇…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1143, 603, 1920, '第十九条', '…护图则。 历史文化名城保护规划应当划定历史城区范围。历史文化名镇、历史文化名村、历史村镇、历史文化街区、历史地段的保护规划应当单独编制，并划定保护范围。在历史城区范围和保护范围外，可以根据保护需要划定环境协调区。 保护规划深度应当达到国家有关规划编制的要求，其中涉及山水环境、文化线路、历史环境要素的，应当在保护规划中明确…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (604, 'FBMCLI.10.1591538', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、6 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1144, 604, 1920, '第十九条', '…历史文化名镇、历史文化名村、历史村镇、历史文化街区、历史地段的保护规划应当单独编制，并划定保护范围。在历史城区范围和保护范围外，可以根据保护需要划定环境协调区。 保护规划深度应当达到国家有关规划编制的要求，其中涉及山水环境、文化线路、历史环境要素的，应当在保护规划中明确保护措施和管控要求。 历史建筑应当编制保护图则，…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1145, 604, 1924, '第二十三条', '第二十三条 历史文化名镇、历史文化名村、历史村镇、历史文化街区、历史地段的保护范围包括核心保护范围和建设控制地带。历史建筑的保护范围包括历史建筑本身和必要的建设控制地带。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1146, 604, 1930, '第二十九条', '第二十九条 核心保护范围内，除了新建、扩建必要的基础设施和公共服务设施外，不得进行新建、扩建活动。对现有道路、建（构）筑物进行改建的，应当保持或者恢复其原有格局和历史风貌。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (605, 'FBMCLI.10.1591538', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 19 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1147, 605, 1906, '第五条', '…县（市、区）人民政府负责本行政区域历史文化名城的保护利用和监督管理工作。 自然资源规划行政主管部门和文物行政主管部门具体负责历史文化名城的保护和管理工作。 住房城乡建设行政主管部门配合做好历史文化名城保护的建设管理工作。 其他有关行政主管部门按照各自职责，做好历史文化名城相关保护监督管理工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1148, 605, 1914, '第十三条', '第十三条 市级保护对象由所在地县（市、区）人民政府负责组织申报，经市自然资源规划行政主管部门和市文物行政主管部门组织专家论证并向社会公示后，由市人民政府批准公布。公示时间不得少于10个工作日。 市级保护对象的认定标准及申报材料参照国家、省的有关规定执行。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1149, 605, 1935, '第三十四条', '第三十四条 历史建筑的所有权人，应当按照保护规划的要求，负责历史建筑的维护和修缮。 市、县（市、区）人民政府应当对历史建筑的维护和修缮给予补助，具体办法由市人民政府制定。 历史建筑有损毁危险，所有权人不具备维护和修缮能力的，所在地县（市、区）人民政府…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (606, 'FBMCLI.10.1591538', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (607, 'FBMCLI.10.1591538', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1150, 607, 1921, '第二十条', '第二十条 市、县（市、区）级保护对象的保护规划由本级人民政府批准公布。 保护规划自批准后20个工作日内，应当在政府网站和主要新闻媒体上公布。 经批准的保护规划不得擅自修改；确需修改的，保护规划的组织编制机关应当向原审批机关提出专题报告，经同意后，方可编制修改方案，修…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1151, 607, 1920, '第十九条', '第十九条 经批准公布的保护对象，由所在地县（市、区）人民政府组织编制保护规划或者保护图则。 历史文化名城保护规划应当划定历史城区范围。历史文化名镇、历史文化名村、历史村镇、历史文化街区、历史地段的保护规划应当单独编制，并划定保护范围。在历史城区范围和保护范围外，可以根据保护需要划定环境协调区。 …', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1152, 607, 1922, '第二十一条', '第二十一条 保护规划报送审批前，保护规划的组织编制机关应当广泛征求有关部门、专家和公众的意见；必要时，可以举行听证。 保护规划报送审批文件中应当附具意见采纳情况及理由；经听证的，还应当附具听证笔录。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (608, 'FBMCLI.10.1591538', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1153, 608, 1918, '第十七条', '…范围内的保护对象开展普查工作。 县（市、区）人民政府应当对符合本条例第十二条规定的对象进行预先保护，同时应当书面告知当事人。自当事人收到预先保护通知之日起12个月内未纳入市级保护对象的，预先保护决定自行失效。 预先保护期间，任何单位和个人不得损坏、拆除预先保护对象。因预先保护对有关单位或者个人的合法权益造成损失的，县…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (609, 'FBMCLI.10.1591538', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 14 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1154, 609, 1919, '第十八条', '…用现状情况、保护范围内建设审批情况； （四）保护规划； （五）设计、测绘信息资料； （六）修缮、维修、迁移、拆除过程中形成的文字、图纸、图片和影像等资料； （七）其他需要保存的资料。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1155, 609, 1931, '第三十条', '第三十条 核心保护范围内，新建、扩建必要的基础设施和公共服务设施，或者拆除历史建筑以外的建（构）筑物以及其他设施，所在地县（市、区）人民政府相关行政主管部门批准前，应当征求市自然资源规划行政主管部门和市文物行政主管部门、公众、专家、利害关系人的意见。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1156, 609, 1920, '第十九条', '…，保护图则包括基本信息、历史沿革、历史价值、风貌特色、保护范围、建筑测绘图、保护措施、维护修缮和使用要求、历史环境保护要求等内容。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (610, 'FBMCLI.10.1591538', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1157, 610, 1908, '第七条', '…将历史文化名城的保护纳入国民经济和社会发展规划，所需经费由市、县（市、区）两级列入本级年度财政预算。 历史文化名城保护经费用于普查、测量、认定、抢险、档案资料收集管理、学术研究、规划编制、修缮补助、宣传普及、资助、奖励等方面。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (611, 'FBMCLI.10.1591538', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1158, 611, 1908, '第七条', '…历史文化名城保护经费用于普查、测量、认定、抢险、档案资料收集管理、学术研究、规划编制、修缮补助、宣传普及、资助、奖励等方面。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1159, 611, 1910, '第九条', '…（市、区）人民政府按照国家有关规定对在历史文化名城保护中做出突出贡献的单位和个人给予表彰和奖励。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1160, 611, 1918, '第十七条', '…先保护对象。因预先保护对有关单位或者个人的合法权益造成损失的，县（市、区）人民政府应当给予补偿。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (612, 'FBMCLI.10.1591538', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1161, 612, 1922, '第二十一条', '…报送审批前，保护规划的组织编制机关应当广泛征求有关部门、专家和公众的意见；必要时，可以举行听证。 保护规划报送审批文件中应当附具意见采纳情况及理由；经听证的，还应当附具听证笔录。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (613, 'FBMCLI.10.1591538', 'BIZ', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (614, 'FBMCLI.10.1591538', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (615, 'FBMCLI.10.1591538', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1162, 615, 1907, '第六条', '…的历史文化名城保护委员会负责指导、协调涉及历史文化名城保护工作的重大事项；历史文化名城保护专家委员会负责为市人民政府和历史文化名城保护委员会决策提供咨询意见。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1163, 615, 1911, '第十条', '…，增强全社会的保护和传承意识。 任何单位和个人有权对破坏、损害历史文化名城的行为进行劝阻和举报。 第二章 保护名录', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (616, 'FBMCLI.10.1591538', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1164, 616, 1939, '第三十八条', '…照下列规定予以处罚： （一）违反第一项至第三项规定的，对单位并处50万元以上100万元以下罚款，对个人并处5万元以上10万元以下罚款； （二）违反第四项规定的，对单位并处20万元以上50万元以下罚款，对个人并处10万元以上20万元以下罚款。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1165, 616, 1941, '第四十条', '…的，由所在地县（市、区）人民政府依法拆除，由城市管理行政主管部门并处1万元以上10万元以下罚款。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1166, 616, 1942, '第四十一条', '…人民政府相关行政主管部门责令恢复原状或者采取其他补救措施，由城市管理行政主管部门并处50元罚款。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (617, 'FBMCLI.10.1429484', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、11 个相关用语，关联 30 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1167, 617, 1957, '第十条', '…市实行历史文化名城保护名录（以下简称保护名录）制度。下列保护对象应当纳入保护名录： （一）历史文化街区； （二）历史风貌区； （三）历史文化名镇、历史文化名村、传统村落； （四）包括各级文物保护单位在内的不可移动文物； （五）历史建筑； （六）近现代工业遗产； （七）地下文物埋藏区和古遗址； （八）古河湖水系、古树名木、…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1168, 617, 1949, '第二条', '…城的规划、保护、利用和管理，适用本条例。 本条例所称的历史文化名城的保护对象包括历史城区、历史文化街区、历史文化名镇、历史文化名村、历史风貌区、历史建筑、传统村落、文物保护单位、不可移动文物、古树名木、历史地名和非物质文化遗产等。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1169, 617, 1977, '第三十条', '第三十条 在历史文化街区、历史风貌区、历史文化名镇、历史文化名村保护范围内进行建设活动，应当符合保护规划，并遵守下列要求： （一）在核心保护范围内，除建设必要基础设施和公共服务设施外，不得进行新建、扩建活动；因危房集中、基础设施落后，为实施保护…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (618, 'FBMCLI.10.1429484', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1170, 618, 1967, '第二十条', '…规划应当包括以下内容： 评估风貌区特色和历史价值，提出风貌区控制内容和保护要求； 风貌区的保护范围，包括核心保护范围和建设控制地带； 建筑分类保护和控制措施； 街巷、历史环境要素的保护控制。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1171, 618, 1972, '第二十五条', '第二十五条 市、县人民政府应当在历史文化街区、历史风貌区、历史文化名镇、历史文化名村核心保护范围的主要出入口设置标志牌。 市人民政府对历史建筑设置统一保护标志，市、县城乡规划主管部门应当在历史建筑的醒目位置设置保护标志牌。 任何个人和单位不得擅自设置、移动、遮挡、涂改或者损毁标志牌和保护标志牌。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1172, 618, 1977, '第三十条', '第三十条 在历史文化街区、历史风貌区、历史文化名镇、历史文化名村保护范围内进行建设活动，应当符合保护规划，并遵守下列要求： （一）在核心保护范围内，除建设必要基础设施和公共服务设施外，不得进行新建、扩建活动；因危房集中、基础设施落后，为实施保护规划对保护对象以外的建（构）筑物进行改建的，建设…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (619, 'FBMCLI.10.1429484', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 19 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1173, 619, 1953, '第六条', '第六条 市城乡规划主管部门会同市文化（文物）主管部门负责全市历史文化名城的保护和管理具体工作；市历史文化名城保护管理机构（以下简称市名城管理机构）负责日常工作。 各县城乡规划主管部门会同同级文化（文物）主管部门负责所辖区历史文化名镇、名村、历史文…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1174, 619, 1974, '第二十七条', '…和历史环境要素的完整性； （二）发现危害历史文化资源行为的及时制止，并及时报告有管辖权限的主管部门和市名城管理机构； （三）协助有关部门确保消防、防灾等公共设施、设备的正常使用； （四）保持保护范围内整洁美观； （五）市、县（区）人民政府确定的其他要求。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1175, 619, 1975, '第二十八条', '第二十八条 历史建筑的保护责任人按照以下规定确定： （一）国有历史建筑，其代管人为保护责任人；没有代管人的，其使用权人为保护责任人。 （二）非国有历史建筑，其所有权人为保护责任人；所有权人下落不明、无法与所有权人取得联系或者房屋权属不清晰的，代管人为保…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (620, 'FBMCLI.10.1429484', 'COORD', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1176, 620, 1963, '第十六条', '…、农业、旅游等部门应当根据各自职责采集、整理相关信息，录入历史文化名城保护信息系统，并实现信息共享。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (621, 'FBMCLI.10.1429484', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 18 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1177, 621, 1965, '第十八条', '第十八条 历史文化名城、历史文化街区、历史文化名镇、历史文化名村等保护规划的内容和组织编制、审批、修改等程序，按照国家和省有关规定执行。 历史文化名城保护规划的核心内容应当纳入城市总体规划，在编制控制性详细规划时，应当落实保护规划的相关要求。 历史文化名镇保护规划的核心内容应当纳入镇总体规划；…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1178, 621, 1966, '第十九条', '第十九条 历史风貌区、历史建筑保护规划由市、县城乡规划主管部门会同同级文化（文物）主管部门按照管辖职责组织编制，报本级人民政府批准；需要修改的，按照原审批程序报送审批。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1179, 621, 1990, '第四十三条', '…成犯罪的，依法追究刑事责任： （一）未按照法定程序组织编制、修改、公布历史风貌区、历史建筑保护规划的； （二）未按照规定确定、调整保护名录的； （三）未按照规定实施行政许可、行政处罚的； （四）其他玩忽职守、滥用职权、徇私舞弊的行为。 第六章 附则', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (622, 'FBMCLI.10.1429484', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (623, 'FBMCLI.10.1429484', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1180, 623, 1977, '第三十条', '…行新建、扩建活动；因危房集中、基础设施落后，为实施保护规划对保护对象以外的建（构）筑物进行改建的，建设单位应当按照契合历史风貌的原则，根据保护规划的要求制定规划建设方案，城乡规划主管部门在作出规划许可前，应当征求同级文化（文物）主管部门的意见，必要时应当组织专家论证和征求公众意见。 （二）在建设控制地带内进行新建…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1181, 623, 1979, '第三十二条', '…在损毁危险和被鉴定为危险房屋的历史建筑，在听取历史建筑保护责任人意见后，制定历史建筑的年度修缮计划，并报本级人民政府批准后实施。 县、区房产主管部门应当根据年度修缮计划，通知历史建筑保护责任人对历史建筑进行修缮。保护责任人应当按照规定修缮，费用由保护责任人承担，符合修缮补助条件的可以申领补助资金。具体补助办法由市…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1182, 623, 1981, '第三十四条', '第三十四条 历史建筑实行原址保护。任何单位和个人不得损坏或者擅自迁移、拆除历史建筑。 因公共利益需要进行建设活动，历史建筑无法实施原址保护、必须迁移异地保护或者拆除的，由城乡规划主管部门会同文化（文物）主管部门对迁移方案、补救措施等进行论证，提出是否迁移或者拆除的意见，并依法报批。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (624, 'FBMCLI.10.1429484', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1183, 624, 1955, '第八条', '第八条 市、县（区）人民政府应当将历史文化名城的保护经费，列入本级财政预算，专款专用。 保护经费用于历史文化名城的普查、测绘、申报、认定、学术研究、专业培训、规划编制、保护信息系统建设和维护、保护设施和环境改善、保护修缮补助、宣传教育、保护奖励等方面。 鼓励个人和单位以捐赠、投资、成立公益性组…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (625, 'FBMCLI.10.1429484', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1184, 625, 1955, '第八条', '…、认定、学术研究、专业培训、规划编制、保护信息系统建设和维护、保护设施和环境改善、保护修缮补助、宣传教育、保护奖励等方面。 鼓励个人和单位以捐赠、投资、成立公益性组织、提供技术和志愿服务等多种方式参与历史文化名城的保护工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1185, 625, 1979, '第三十二条', '…筑保护责任人对历史建筑进行修缮。保护责任人应当按照规定修缮，费用由保护责任人承担，符合修缮补助条件的可以申领补助资金。具体补助办法由市、县（区）人民政府制定。 历史建筑有损毁危险、保护责任人不具备维护和修缮能力的，市、县（区）人民政府应当采取措施进行保护。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1186, 625, 1982, '第三十五条', '…保护范围内的建（构）筑物，市、县（区）人民政府可以依法对其征收或者置换，并依法对产权人进行补偿。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (626, 'FBMCLI.10.1429484', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1187, 626, 1992, '第四十五条', '… 背景资料 立法草案 南昌市人大常委会法工委关于公布《南昌市历史文化名城保护条例(草案)》征求意见的通知 本篇引用的法规 中央法规 历史文化名城名镇名村保护条例(2017修订) 中华人民共和国城乡规划法(2015修正) 引用本篇的法规 案例 论文 地方法规规章 南昌市人民政府关于公布南昌市第一批历史地段保护名录的通知…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (627, 'FBMCLI.10.1429484', 'BIZ', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1188, 627, 1985, '第三十八条', '…享有经营收益。 鼓励和引导保护责任人对历史建筑开展以旅游业、文化产业和传统手工业为主的有偿经营活动。鼓励保护责任人将历史建筑对公众开放。 第五章 法律责任', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (628, 'FBMCLI.10.1429484', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (629, 'FBMCLI.10.1429484', 'SUP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1189, 629, 1952, '第五条', '…中的重大事项，指导、协调历史文化名城保护工作。 历史文化名城保护委员会设立历史文化名城保护专家委员会（以下简称专家委员会）。专家委员会由规划、文化（文物）、房产、建筑、园林、旅游、宗教、历史、地名、民俗、法律和传统工艺等方面的专家组成，负责对历史文化名城保护名录、保护规划、保护措施等事项进行论证和评审。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (630, 'FBMCLI.10.1429484', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、6 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1190, 630, 1990, '第四十三条', '第四十三条 市、县（区）人民政府和有关部门及其工作人员有下列情形之一的，责令改正，并对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任： （一）未按照法定程序组织编制、修改、公布历史风貌区、历史建筑保护规划的； （二）未按照规定确定、调整保护名录的； （三）未按照规定实…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1191, 630, 1988, '第四十一条', '…由城市管理行政执法部门责令限期改正或者恢复原状；逾期不改正的，对单位处一万元以上三万元以下罚款，对个人处五千元以下罚款。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1192, 630, 1989, '第四十二条', '…、街道办事处及其工作人员未按照本条例第二十七条规定履行保护责任的，由所在的县（区）人民政府责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (631, 'FBMCLI.10.1521716', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 6 个核心用语、8 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1193, 631, 2006, '第十四条', '…体格局和风貌； （二）白雾村古老民居名宅、会馆、祠堂、寺庙等形成的整体格局和风貌； （三）文物保护单位、尚未核定公布为文物保护单位的不可移动文物、历史建筑，与名城格局密切相关的山水林田湖自然环境； （四）古遗址、古井、古碑、古巷道、古桥、古门窗、古牌匾、古货台、古照壁、古栅子、古牌坊，名人故（旧）居、古树名木、历史地名、…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1194, 631, 2030, '第三十八条', '…建筑，是指经会泽县人民政府确定公布的具有一定保护价值，能够反映历史风貌和地方特色，未公布为文物保护单位，也未登记为不可移动文物的建筑物、构筑物。 传统民居，是指会泽县历史城区、白雾村内各个历史时期建成，体现会泽传统风貌，反映会泽传统建造技艺、社会伦理和审美观念等文化要素的民用建筑物，已被列为文物保护单位、尚未核定公布为文…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1195, 631, 2009, '第十七条', '…（构）筑物，损害原有建筑风格、景观、视廊、环境的整体性； （二）损毁或者擅自拆除确定保护的历史建筑； （三）擅自拆除历史建（构）筑物中的古门、古窗、古牌匾、古照壁、古栅子、古货台、古坊以及其他装饰构件； （四）侵占或者损坏园林、绿地、古树名木、古井、古碑、古巷道、古桥、水面、道路； （五）在历史建（构）筑物上刻划、涂…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (632, 'FBMCLI.10.1521716', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、4 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1196, 632, 2005, '第十三条', '第十三条 名城保护范围由核心保护区、建设控制区、风貌协调区构成，具体区域由会泽县人民政府根据国务院批准的名城保护规划划定并公布。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1197, 632, 2004, '第十二条', '…保护名录应当载明保护对象的名称、区位、界限、形成时间和历史价值等，并向社会公布。 第三章 保护范围和对象', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1198, 632, 2009, '第十七条', '第十七条 名城保护范围内禁止下列行为： （一）建设与整体风貌、建设风格不相协调的建（构）筑物，损害原有建筑风格、景观、视廊、环境的整体性； （二）损毁或者擅自拆除确定保护的历史建筑； （三）擅自拆除历史建（构）筑物中的古门、古窗、古牌匾、古照…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (633, 'FBMCLI.10.1521716', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1199, 633, 1996, '第四条', '…、交通运输、财政、发展和改革、生态环境、卫生健康、公安、消防、市场监督管理、民族宗教等有关主管部门按照各自职责做好名城保护管理的相关工作。 会泽县人民政府应当成立名城保护委员会，负责统一协调名城保护有关部门的工作，推进综合执法工作。 会泽县有关街道办事处和村（居）民委员会配合做好辖区内名城保护管理的相关工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1200, 633, 2011, '第十九条', '第十九条 国有不可移动文物由使用人负责修缮、保养；非国有不可移动文物及历史建筑由所有权人负责修缮、保养。 非国有不可移动文物有损毁危险的，所有权人不具备修缮能力，会泽县人民政府可以与所有权人协商产权置换；所有权人有修缮能力拒不修缮的，会泽县人民政府可以给予抢救修缮，所需费用由所有权人承担。不能通过上述两种方…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1201, 633, 2014, '第二十二条', '…光等应当符合相关规范要求，与名城风貌相协调。影响街巷风貌的建（构）筑物，会泽县人民政府有关主管部门应当要求所有权人、使用人限期整改。 核心保护区范围内应当按照安全、消防法律、法规要求消除安全隐患，配备消防设施，确保消防安全。对有安全隐患的建（构）筑物，会泽县人民政府有关主管部门应当责令所有权人、使用人及时消除安全隐患…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (634, 'FBMCLI.10.1521716', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (635, 'FBMCLI.10.1521716', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、4 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1202, 635, 1997, '第五条', '第五条 名城保护委员会履行下列职责： （一）宣传、贯彻有关法律、法规； （二）监督名城保护规划和控制性详细规划的具体实施； （三）研究制定古城保护的相关措施和实施方案，参与重大项目实施的审查； （四）组织编制、修改完善房屋修缮导则和修缮方案、广告设置导则、业态发展规划和名城保护名录； （五）指导、协调、督促相关单…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1203, 635, 2003, '第十一条', '第十一条 会泽县人民政府应当依法编制、修改名城保护规划、保护详细规划、核心保护区修建性详细规划。电力电信、道路交通、抗震防灾、公共消防、旅游发展、地下空间开发利用等专项规划，应当与名城保护规划相衔接。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1204, 635, 2004, '第十二条', '第十二条 会泽县人民政府应当加强名城保护规划工作，建立名城保护名录制度。保护名录应当载明保护对象的名称、区位、界限、形成时间和历史价值等，并向社会公布。 第三章 保护范围和对象', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (636, 'FBMCLI.10.1521716', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1205, 636, 2006, '第十四条', '… （二）白雾村古老民居名宅、会馆、祠堂、寺庙等形成的整体格局和风貌； （三）文物保护单位、尚未核定公布为文物保护单位的不可移动文物、历史建筑，与名城格局密切相关的山水林田湖自然环境； （四）古遗址、古井、古碑、古巷道、古桥、古门窗、古牌匾、古货台、古照壁、古栅子、古牌坊，名人故（旧）居、古树名木、历史地名、历史建筑物名称…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1206, 636, 2030, '第三十八条', '…貌，反映会泽传统建造技艺、社会伦理和审美观念等文化要素的民用建筑物，已被列为文物保护单位、尚未核定公布为文物保护单位的不可移动文物、古建筑的除外。 历史街巷，是指会泽县历史城区、白雾村内存有较多文物古迹或者成片的传统民居，能够完整、真实的体现会泽传统街巷特色，并具有一定规模的地段。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (637, 'FBMCLI.10.1521716', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1207, 637, 2008, '第十六条', '…六条 名城保护范围内的建设活动应当依法经过批准。 核心保护区内确定保护的建（构）筑物的维护修缮应当保持原有的高度、体量、外观式样及色彩等，并与整体风貌相互协调；不协调建筑物的整治改造应当符合整体风貌的要求；已经破损和濒临消失的建筑物应当在依法履行相关审批手续后，按照原有的风貌进行修复或者遗址保护；不具有保护价值或…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1208, 637, 2009, '第十七条', '…标志； （六）侵占或者损毁历史遗迹、遗址； （七）擅自对历史建筑、传统民居、商铺等进行外部修缮装饰，以及改变院落格局、结构； （八）损坏或者擅自移动、拆除公共设施； （九）在河道上搭建现代建（构）筑物及各项设施； （十）侵占、围填、覆盖、堵截河道、坝塘或者改变其堤坡、宽窄、深浅、走向等自然状态； （十一）擅自挖掘…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1209, 637, 2011, '第十九条', '第十九条 国有不可移动文物由使用人负责修缮、保养；非国有不可移动文物及历史建筑由所有权人负责修缮、保养。 非国有不可移动文物有损毁危险的，所有权人不具备修缮能力，会泽县人民政府可以与所有权人协商产权置换；所有权人有修缮能力拒不修缮的，会泽县人民政府可以给予抢救修…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (638, 'FBMCLI.10.1521716', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1210, 638, 1998, '第六条', '第六条 曲靖市、会泽县人民政府应当将名城保护经费列入财政预算，并积极争取上级专项资金对名城保护的投入。 鼓励单位、个人和其他组织依法建立名城保护基金 ，用于名城保护。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (639, 'FBMCLI.10.1521716', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1211, 639, 2001, '第九条', '第九条 曲靖市、会泽县人民政府应当对在名城保护工作中做出突出贡献的单位和个人予以表彰、奖励。 第二章 保护规划', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1212, 639, 2013, '第二十一条', '…所有权人、使用人按照名城保护规划和批准方案对历史建筑进行修缮的，会泽县人民政府给予适当资金补助，名城保护委员会应当给予技术支持，具体办法由会泽县人民政府制定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1213, 639, 2018, '第二十六条', '第二十六条 鼓励单位和个人通过捐赠、资助、投资等方式，在名城保护委员会的指导下依法参与名城的保护和合理利用。 鼓励、支持社会资本对名城保护进行投资。利用社会资本保护修缮文物和公有产权房的，在不改变所有权的前提下，可以赋予其一定期限的使用权、经营权。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (640, 'FBMCLI.10.1521716', 'RES', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
