INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1214, 641, 1997, '第五条', '…，参与重大项目实施的审查； （四）组织编制、修改完善房屋修缮导则和修缮方案、广告设置导则、业态发展规划和名城保护名录； （五）指导、协调、督促相关单位对名城的保护、管理和利用工作； （六）配合相关部门做好名城非物质文化遗产的保护传承和展示； （七）组织挖掘名城传统文化，开展学术研究、对外宣传和对外交流工作； （八…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1215, 641, 2006, '第十四条', '…牌匾、古货台、古照壁、古栅子、古牌坊，名人故（旧）居、古树名木、历史地名、历史建筑物名称、商业老字号等； （五）斑铜工艺、土陶工艺、洞经音乐、小唱灯等非物质文化遗产； （六）铜商文化； （七）其他具有保护价值的文化遗产。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1216, 641, 2016, '第二十四条', '第二十四条 会泽县人民政府应当按照合理布局、总量控制的原则制定核心保护区内业态管理的具体办法，鼓励传统文化特色产业经营并予以保护和扶持。', 'supporting');
