INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (644, 'FBMCLI.10.1521716', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、6 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1217, 644, 2023, '第三十一条', '…一条 曲靖市、会泽县人民政府国家机关及其相关机构工作人员违反本条例规定，有下列行为之一的，责令改正，并对直接负责的主管人员和其他责任人员依法给予处分；构成犯罪的，依法追究刑事责任： （一）擅自调整、改变或者拒不执行经批准的名城保护规划和详细规划； （二）不履行名城保护和监管职责； （三）对破坏名城保护的行为不依法查处…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1218, 644, 2024, '第三十二条', '…者采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处1万元以上5万元以下的罚款，对个人并处500元以上1000元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1219, 644, 2025, '第三十三条', '…采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处5万元以上10万元以下的罚款，对个人并处1万元以上5万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (645, 'FBMCLI.10.1421008', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 6 个核心用语、10 个相关用语，关联 18 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1220, 645, 2033, '第二条', '…片、西园留园片、寒山寺片）。 苏州国家历史文化名城保护的对象包括历史城区的整体格局与风貌、历史文化街区、历史地段、河道水系、文物保护单位、地下文物埋藏区、苏州园林、古建筑、古城墙、传统民居、古树名木、吴文化地名、工业遗产、传统产业，以及非物质文化遗产和法律、法规规定的其他保护对象。 苏州国家历史文化名城保护范围内的文物、…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1221, 645, 2078, '第四十七条', '第四十七条 本条例所称历史文化街区，是指历史城区内保存文物特别丰富、古建筑和传统民居集中成片、能够较完整和真实地体现传统格局和历史风貌，并具有一定规模的街区。 本条例所称历史地段，是指历史城区内存有较多的文物古迹或者成片的传统民居，能较完整、真实地体现苏…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1222, 645, 2044, '第十三条', '…乡规划主管部门和国务院文物主管部门备案。 市人民政府应当依据历史文化名城保护规划，组织编制历史文化街区保护规划，并按照规定批准。 姑苏区人民政府应当依据历史文化名城保护规划、控制性详细规划，组织编制历史地段保护规划，报市人民政府批准。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (646, 'FBMCLI.10.1421008', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1223, 646, 2052, '第二十一条', '第二十一条 历史文化街区应当划定核心保护范围和建设控制地带，并按照下列要求进行保护： （一）控制街区周边的景观环境，保持街区原有的空间格局与尺度，不得改变街巷肌理； （二）街区的核心保护范围内，除新建、扩建必要的基础设施和公共服务设施，以及原地、原面积、原高度、原…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1224, 646, 2033, '第二条', '…业遗产、传统产业，以及非物质文化遗产和法律、法规规定的其他保护对象。 苏州国家历史文化名城保护范围内的文物、苏州园林、古建筑、古城墙、古树名木、吴文化地名和非物质文化遗产等的保护，法律、法规另有规定的，从其规定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1225, 646, 2053, '第二十二条', '…风貌，延续历史文脉，并注重保护与合理利用相结合，增强历史地段经济社会发展的活力。 历史地段保护范围内的建设活动不得改变传统格局和传统风貌。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (647, 'FBMCLI.10.1421008', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 21 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1226, 647, 2036, '第五条', '第五条 市人民政府设立苏州国家历史文化名城保护议事协调机构，负责保护工作的统筹、指导、协调、监督，履行下列具体职责： （一）研究保护、管理和利用的重大政策措施； （二）审查相关保护规划； （三）督促保护专项资金的落实和使用； （四）审查保…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1227, 647, 2062, '第三十一条', '第三十一条 市城乡规划主管部门应当会同市住房和城乡建设、文化（文物）主管部门和姑苏区人民政府，组织制定传统民居形制导则和图集，明确传统民居的建筑高度、体量、外观形象、色彩、材料、细部特征、工艺手法等要求。 传统民居保护责任人对传统民居日常保养维护、修…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1228, 647, 2038, '第七条', '第七条 市城乡规划主管部门负责相关保护规划的编制，以及规划实施的监督管理。 市文化（文物）主管部门负责文物、古建筑、古城墙和非物质文化遗产保护等的监督管理。 园林和绿化、水利（水务）、民政、住房和城乡建设、市容市政（城市管理）、公安、交通运输等部…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (648, 'FBMCLI.10.1421008', 'COORD', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1229, 648, 2037, '第六条', '第六条 苏州国家历史文化名城保护议事协调机构的办事机构设在姑苏区人民政府，具体负责下列工作： （一）组织拟订保护名录和调整方案； （二）宣传、贯彻有关历史文化名城保护的法律、法规； （三）组织或者协助有关部门开展历史文化名城保护工作情况调查、研究和信息的收集、整理…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1230, 648, 2036, '第五条', '第五条 市人民政府设立苏州国家历史文化名城保护议事协调机构，负责保护工作的统筹、指导、协调、监督，履行下列具体职责： （一）研究保护、管理和利用的重大政策措施； （二）审查相关保护规划； （三）督促保护专项资金的落实和使用； （四）审查保护名录和调整方案； （五）研究、论证重大…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (649, 'FBMCLI.10.1421008', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 17 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1231, 649, 2049, '第十八条', '第十八条 市城乡规划主管部门应当依据保护规划相关要求，组织编制历史城区和苏州国家历史文化名城其他重点地区的城市设计，报市人民政府审批。 重点地区城市设计的内容应当纳入控制性详细规划，并落实到控制性详细规划相关指标中。控制性详细规划未体现城市设计内容和要求的，应当及…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1232, 649, 2044, '第十三条', '第十三条 市人民政府组织编制历史文化名城保护规划，报省人民政府审批，并报国务院城乡规划主管部门和国务院文物主管部门备案。 市人民政府应当依据历史文化名城保护规划，组织编制历史文化街区保护规划，并按照规定批准。 姑苏区人民政府应当依据历史文化名城保护规划、控制性详细规划…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1233, 649, 2038, '第七条', '第七条 市城乡规划主管部门负责相关保护规划的编制，以及规划实施的监督管理。 市文化（文物）主管部门负责文物、古建筑、古城墙和非物质文化遗产保护等的监督管理。 园林和绿化、水利（水务）、民政、住房和城乡建设、市容市政（城市管理）、公安、交通运输等部门按照各自职责，…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (650, 'FBMCLI.10.1421008', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1234, 650, 2078, '第四十七条', '…貌，反映苏州传统建造技艺、社会伦理和审美观念等文化要素的民用建筑物，已被列为文物保护单位、尚未核定公布为文物保护单位的不可移动文物、古建筑的除外。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (651, 'FBMCLI.10.1421008', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1235, 651, 2051, '第二十条', '…。 （七）不得违反规划新建、改建、扩建建（构）筑物。现有的违法建（构）筑物、设施，依法予以拆除。不符合保护规划要求的合法建（构）筑物，逐步改造或者拆除。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1236, 651, 2060, '第二十九条', '…不得有下列行为： （一）损毁、破坏房屋； （二）擅自改建、扩建房屋； （三）不配合所有权人修缮房屋； （四）擅自将房屋转租他人； （五）擅自改变房屋用途； （六）利用房屋进行非法活动。 住房和城乡建设、文化（文物）等主管部门应当加强对历史城区文物保护单位、古建筑、传统民居中的公有住房所有权人、承租人的监督，督促其…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1237, 651, 2061, '第三十条', '…特殊技术规范实施前，历史城区内的市政基础设施或者消防设施、消防通道，以及古建筑、传统民居的修缮、迁移和重建无法满足现行技术规范要求的，由市人民政府组织市住房和城乡建设、城乡规划、文化（文物）、公安等主管部门和姑苏区人民政府以及相关行业专家进行论证，确定适应保护需要的建设、管理和保障方案。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (652, 'FBMCLI.10.1421008', 'FUND', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1238, 652, 2041, '第十条', '…将苏州国家历史文化名城的基础设施规划、建设、运行、维护、管理费用和苏州国家历史文化名城保护专项资金纳入财政预算。 市人民政府设立苏州国家历史文化名城产业转型升级基金，推进产业转型升级。 市、姑苏区人民政府应当引导和鼓励社会资本参与苏州国家历史文化名城保护。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1239, 652, 2036, '第五条', '…责： （一）研究保护、管理和利用的重大政策措施； （二）审查相关保护规划； （三）督促保护专项资金的落实和使用； （四）审查保护名录和调整方案； （五）研究、论证重大建设项目，审查保护工作中重大问题的解决方案； （六）指导、协调保护工作中重大突发事件的处理； （七）指导、协调、督促成员单位开展保护工作； （八）市人民…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1240, 652, 2063, '第三十二条', '…，姑苏区人民政府应当给予资金补助。 前两款规定的补偿、补助费用纳入苏州国家历史文化名城保护专项资金中统筹解决。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (653, 'FBMCLI.10.1421008', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1241, 653, 2063, '第三十二条', '第三十二条 市人民政府应当建立历史城区保护补偿制度，通过资金补贴或者其他政策措施，对单位和个人因政府进行历史城区保护而受到的损失，给予适当补偿。 传统民居保护责任人按照保护规划、技术标准和规范要求进行修缮、改建，或者房屋所有权人和公有住房使用人积极配合政府征收活动或…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1242, 653, 2043, '第十二条', '…在苏州国家历史文化名城保护工作中做出突出贡献的单位和个人，市、姑苏区人民政府应当予以表彰、奖励。 第二章 保护规划', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (654, 'FBMCLI.10.1421008', 'RES', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1243, 654, 2040, '第九条', '…项听证制度。对属于保护规划、确定历史地段和传统民居保护名录等方面的重大事项，应当邀请专家和公众参与听证。听证结果应当作为重大事项决策的重要参考。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1244, 654, 2045, '第十四条', '…历史文化街区和历史地段的保护规划草案，在政府网站或者本市主要新闻媒体上公告，并采取论证会、听证会或者其他方式征求专家和公众的意见。公告时间不少于三十日。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1245, 654, 2080, '第四十九条', '…国家历史文化名城保护条例(草案)》审议结果的报告 《苏州国家历史文化名城保护条例(草案)》征求意见公告 本篇引用的法规 中央法规 中华人民共和国文物保护法(2017修正) 历史文化名城名镇名村保护条例(2017修订) 中华人民共和国城乡规划法(2015修正) 中华人民共和国非物质文化遗产法 引用本篇的法规 案例 论文…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (655, 'FBMCLI.10.1421008', 'BIZ', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1246, 655, 2064, '第三十三条', '…象的合理利用。 鼓励社会力量合理利用历史资源发展符合保护规划的产业，从事符合产业布局规划的经营活动。 鼓励利用旧厂房、仓库等闲置建筑，开展文化、旅游、养老和其他利用活动。具体办法由市人民政府另行制定。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1247, 655, 2067, '第三十六条', '第三十六条 历史城区的产业业态应当符合保护规划的要求。 姑苏区人民政府应当依法制定产业引导、控制和禁止目录，支持发展科技创意、文化旅游、特色商贸等现代服务业和总部经济，提升文化传承、旅游休闲和传统产业发展、苏式居住等功能。 合理保留、优化提升教育、科…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (656, 'FBMCLI.10.1421008', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (657, 'FBMCLI.10.1421008', 'SUP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1248, 657, 2043, '第十二条', '…保护苏州国家历史文化名城的义务，有权对破坏苏州国家历史文化名城保护的各类违法行为进行劝阻、举报和控告。 对在苏州国家历史文化名城保护工作中做出突出贡献的单位和个人，市、姑苏区人民政府应当予以表彰、奖励。 第二章 保护规划', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (658, 'FBMCLI.10.1421008', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1249, 658, 2074, '第四十三条', '…法部门责令限期恢复原状或者采取其他补救措施；造成严重后果的，对单位处以五万元以上十万元以下罚款，对个人处以一万元以上五万元以下罚款；造成他人财产损失的，依法承担民事责任。 违反本条例第三十一条第三款规定，故意损毁传统民居，或者具备维护和修缮能力的传统民居保护责任人未履行保护责任造成传统民居损毁、坍塌的，由姑苏区有…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1250, 658, 2075, '第四十四条', '…标志的，由姑苏区有关行政执法部门责令限期改正；逾期不改正的，对单位处以一万元以上五万元以下罚款，对个人处以一千元以上一万元以下罚款。 违反本条例第三十四条第二款规定，在历史城区露天烧烤食品的，由姑苏区有关行政执法部门责令改正，没收烧烤工具和违法所得，并处以五百元以上五千元以下罚款；情节严重的，处以五千元以上二万元…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1251, 658, 2072, '第四十一条', '…等信息在内的苏州国家历史文化名城保护信息管理系统，提高保护工作的智能化管理水平。 第五章 法律责任', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (659, 'FBMCLI.10.1552061', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、10 个相关用语，关联 19 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1252, 659, 2094, '第十四条', '…发展过程或者某一发展时期风貌的历史城区； （二）反映一定历史时期传统风貌和民族、地方特色的历史地段； （三）除文物保护单位、历史建筑外，具有一定建成史，对历史地段整体风貌特征形成具有价值和意义的传统风貌建筑； （四）地下文物埋藏区； （五）反映历史风貌的古井、围墙、石阶、铺地、驳岸、古树名木等历史环境要素； （六）其…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1253, 659, 2100, '第二十条', '第二十条 在历史文化街区、名镇、名村、传统村落、历史地段、历史建筑、传统风貌建筑的建设控制地带内，新建、改建、扩建建（构）筑物及其他设施的，其高度、体量、形态、风格、色彩等，应当与传统格局和历史风貌保持一致。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1254, 659, 2082, '第二条', '…区域内历史文化名城的规划、保护、利用和管理，适用本条例。 历史文化名城保护包括对历史城区、历史文化街区、历史地段、历史文化名镇、历史文化名村、传统村落、历史建筑、传统风貌建筑、不可移动文物、地下文物埋藏区、历史环境要素等保护。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (660, 'FBMCLI.10.1552061', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1255, 660, 2089, '第九条', '第九条 保护规划应当划定保护对象的保护范围。 历史文化街区、历史文化名镇、历史文化名村、传统村落、历史地段、历史建筑、传统风貌建筑的保护规划应当划定核心保护范围和建设控制地带，并设立界标，向社会公布。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1256, 660, 2099, '第十九条', '第十九条 历史文化街区、历史文化名镇、历史文化名村核心保护范围内，除必要的基础设施和公共服务设施建设外，不得从事新建、改建、扩建活动。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1257, 660, 2098, '第十八条', '第十八条 在保护范围内禁止以下行为： （一）开山、采石（矿）、取土、爆破等破坏传统格局和历史风貌的活动； （二）修建生产、经营、储存、使用爆炸性、易燃性、放射性、毒害性、腐蚀性物品的工厂、仓库等； （三）占用保护规划确定保留的道路、河湖水系…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (661, 'FBMCLI.10.1552061', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 25 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1258, 661, 2084, '第四条', '第四条 城乡规划主管部门负责历史文化名城保护规划管理工作。 文物主管部门负责文物的保护与管理工作。 住房和城乡建设、文化、旅游、城市管理、水行政、财政、交通运输、民政、公安、教育、宗教等部门按照各自的职责，履行相应的历史文化名城保护职责。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1259, 661, 2088, '第八条', '第八条 市、县级市人民政府组织编制历史文化名城保护规划。 城乡规划主管部门负责编制本行政区域内历史城区、历史文化街区、历史地段和历史建筑保护规划。 县级市（区）人民政府组织编制历史文化名镇、名村、传统村落的保护规划。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1260, 661, 2123, '第四十三条', '第四十三条 保护责任人应当履行以下义务： （一）负责保护对象的日常维护和保养； （二）及时修缮有损毁危险的保护对象； （三）接受所在地镇人民政府、街道办事处以及文物、应急管理等部门的检查和指导； （四）其他应当履行的保护责任。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (662, 'FBMCLI.10.1552061', 'COORD', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1261, 662, 2111, '第三十一条', '…历史资料信息，建立档案，并持续补充完善，将历史文化名城保护信息纳入全市大数据管理系统，实现信息共享。 第五章 合理利用', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (663, 'FBMCLI.10.1552061', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 12 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1262, 663, 2091, '第十一条', '第十一条 保护规划依照法律、法规及有关规定报批。 保护规划应当自批准之日起三十日内，在政府网站和主要新闻媒体上公布。 经批准的保护规划，未经法定程序不得修改。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1263, 663, 2088, '第八条', '第八条 市、县级市人民政府组织编制历史文化名城保护规划。 城乡规划主管部门负责编制本行政区域内历史城区、历史文化街区、历史地段和历史建筑保护规划。 县级市（区）人民政府组织编制历史文化名镇、名村、传统村落的保护规划。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1264, 663, 2089, '第九条', '第九条 保护规划应当划定保护对象的保护范围。 历史文化街区、历史文化名镇、历史文化名村、传统村落、历史地段、历史建筑、传统风貌建筑的保护规划应当划定核心保护范围和建设控制地带，并设立界标，向社会公布。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (664, 'FBMCLI.10.1552061', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (665, 'FBMCLI.10.1552061', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、5 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1265, 665, 2099, '第十九条', '…文化名镇、历史文化名村核心保护范围内，除必要的基础设施和公共服务设施建设外，不得从事新建、改建、扩建活动。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1266, 665, 2100, '第二十条', '…史文化街区、名镇、名村、传统村落、历史地段、历史建筑、传统风貌建筑的建设控制地带内，新建、改建、扩建建（构）筑物及其他设施的，其高度、体量、形态、风格、色彩等，应当与传统格局和历史风貌保持一致。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1267, 665, 2107, '第二十七条', '…七条 市城乡规划主管部门应当会同文物、住房和城乡建设等部门组织编制历史建筑、传统风貌建筑的修缮技术规范。 对历史建筑、传统风貌建筑进行外部修缮装饰、添加设施以及改变历史建筑的结构或者使用性质的，应当经城乡规划主管部门会同同级文物主管部门批准，并依照有关法律、法规的规定办理手续。 在保护范围内，需要实施修缮保护的历…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (666, 'FBMCLI.10.1552061', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1268, 666, 2085, '第五条', '…人民政府应当将历史文化名城保护工作纳入国民经济和社会发展规划，并安排专项保护经费，列入同级财政预算。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (667, 'FBMCLI.10.1552061', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1269, 667, 2086, '第六条', '第六条 市、县级市（区）人民政府及其有关部门鼓励和支持单位和个人以捐赠、资助、提供技术服务等方式参与历史文化名城保护；对在历史文化名城保护工作中作出突出贡献的单位和个人给予奖励。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1270, 667, 2126, '第四十六条', '第四十六条 对单位或者个人因历史文化名城保护而受到损失的，给予公平合理补偿，具体补偿办法由市人民政府制定。 保护责任人按照保护规划、技术规范等要求修缮保护范围内的历史建筑的，或者所有权人和公有住房使用人配合征收、协议搬迁的，给予资金补助。 第七章 法律责任', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1271, 667, 2115, '第三十五条', '第三十五条 鼓励通过政策引导、资金资助、简化手续等方式，促进对历史建筑、传统风貌建筑的合理利用。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (668, 'FBMCLI.10.1552061', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1272, 668, 2090, '第十条', '第十条 编制机关应当依法公示保护规划草案，并采取论证会、听证会等方式征求有关部门、专家、利害关系人和社会公众的意见，公示时间不得少于三十日。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (669, 'FBMCLI.10.1552061', 'BIZ', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1273, 669, 2117, '第三十七条', '…文化创意、文化研究、文化体验、休闲旅游等活动，开展符合保护规划的文化展览、手工业等传统特色经营活动。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (670, 'FBMCLI.10.1552061', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (671, 'FBMCLI.10.1552061', 'SUP', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (672, 'FBMCLI.10.1552061', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1274, 672, 2127, '第四十七条', '…，所需费用由违法行为人承担；因违法活动造成严重后果的，对单位并处五十万元以上一百万元以下的罚款，对个人并处五万元以上十万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1275, 672, 2128, '第四十八条', '…者采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处五万元以上十万元以下的罚款，对个人并处一万元以上五万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1276, 672, 2131, '第五十一条', '…者采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处五万元以上十万元以下的罚款，对个人并处一万元以上五万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (673, 'FBMCLI.10.5520945', 'OBJ', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1277, 673, 2164, '第三十条', '…和国城乡规划法 引用本篇的法规 案例 论文 地方法规规章 开封市人民政府办公室关于印发加强历史文化街区、历史建筑、历史文化名镇、名村及传统村落保护利用工作方案的通知 河南省住房和城乡建设厅、河南省文物局关于印发《河南省历史建筑保护与利用管理办法(试行)》的通知 洛阳市人民政府办公室关于印发洛阳市历史建筑保护和利用管理办法…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (674, 'FBMCLI.10.5520945', 'BND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1278, 674, 2144, '第十条', '第十条 历史文化名城保护规划应当包括：保护的总体目标、保护内容、保护范围、保护标准、保护规划的实施保障措施等。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1279, 674, 2147, '第十三条', '…主管部门编制出详细规划，合理确定规划的主要控制指标，并由城市规划行政主管部门设立标志，标明保护范围。 历史文化名城重点保护区和传统风貌协调区的详细规划，由省城市规划行政主管部门征得省文物行政主管部门同意后审批。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (675, 'FBMCLI.10.5520945', 'RESP', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1280, 675, 2141, '第七条', '第七条 历史文化名城所在地的城市规划行政主管部门和文物行政主管部门依据各自职责，负责历史文化名城的规划、保护、管理和监督工作。 发展和改革、财政、旅游、交通、环保、公安、消防等有关部门应当依据各自的职责，共同做好历史文化名城的保护工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1281, 675, 2147, '第十三条', '…历史文化名城保护规划中确定的重点保护区、传统风貌协调区、重点保护建筑物，应当由城市规划行政主管部门会同文物行政主管部门编制出详细规划，合理确定规划的主要控制指标，并由城市规划行政主管部门设立标志，标明保护范围。 历史文化名城重点保护区和传统风貌协调区的详细规划，由省城市规划行政主管部门征得省文物行政主管部门同意后审批…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1282, 675, 2151, '第十七条', '第十七条 未经省城市规划行政主管部门和省文物行政主管部门依法审查同意，历史文化名城所在地不得擅自拓宽保护规划范围内的道路或者进行旧城改造，不得在重点保护区和传统风貌协调区内安排建设项目。 法宝联想 司法案例 司法案例（1）', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (676, 'FBMCLI.10.5520945', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (677, 'FBMCLI.10.5520945', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、5 个相关用语，关联 15 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1283, 677, 2143, '第九条', '第九条 历史文化名城所在地的人民政府应当及时组织编制历史文化名城保护规划，经同级人民代表大会或者其常务委员会审查同意后，按照批准程序报批。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1284, 677, 2147, '第十三条', '第十三条 对历史文化名城保护规划中确定的重点保护区、传统风貌协调区、重点保护建筑物，应当由城市规划行政主管部门会同文物行政主管部门编制出详细规划，合理确定规划的主要控制指标，并由城市规划行政主管部门设立标志，标明保护范围。 历史文化名城重点保护区和传统…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1285, 677, 2145, '第十一条', '第十一条 编制历史文化名城保护规划应当符合以下要求： （一）保持和延续历史文化名城的格局、风貌特征，保护文物古迹，继承传统文化； （二）根据历史文化遗存的性质、形态、分布和空间环境等特点，确定保护原则和工作重点，保护和利用人文资源； （三）对于具有传统风…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (678, 'FBMCLI.10.5520945', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (679, 'FBMCLI.10.5520945', 'REPAIR', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (680, 'FBMCLI.10.5520945', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1286, 680, 2138, '第四条', '…负责保护本行政区域内的历史文化名城，并把保护工作纳入国民经济和社会发展计划，将保护经费列入财政预算。 鼓励和支持社会各界以捐赠、资助等方式参与历史文化名城的保护工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (681, 'FBMCLI.10.5520945', 'COMP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1287, 681, 2138, '第四条', '…把保护工作纳入国民经济和社会发展计划，将保护经费列入财政预算。 鼓励和支持社会各界以捐赠、资助等方式参与历史文化名城的保护工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1288, 681, 2142, '第八条', '…为。 各级人民政府和有关部门对在历史文化名城保护工作中做出突出贡献的单位和个人给予表彰或者奖励。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (682, 'FBMCLI.10.5520945', 'RES', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (683, 'FBMCLI.10.5520945', 'BIZ', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1289, 683, 2145, '第十一条', '…布和空间环境等特点，确定保护原则和工作重点，保护和利用人文资源； （三）对于具有传统风貌的商业区、手工业区、民居以及其他古迹区整体规划保护； （四）保护重要革命遗址，弘扬革命传统； （五）历史文化名城保护与经济、社会发展和人文、生态环境相协调。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (684, 'FBMCLI.10.5520945', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (685, 'FBMCLI.10.5520945', 'SUP', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (686, 'FBMCLI.10.5520945', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、6 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1290, 686, 2162, '第二十八条', '…他有关部门的工作人员在历史文化名城的保护工作中有下列行为之一的，由其所在单位或上级主管部门责令改正或者给予行政处分；构成犯罪的，依法追究刑事责任： （一）不按规定进行保护规划的编制、申报、审查的； （二）不按保护规划组织实施保护，致使历史实物遗存、传统风貌遭受破坏的； （三）有其他滥用职权、玩忽职守和徇私舞弊行为的。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1291, 686, 2161, '第二十七条', '…不涉及文物的，由城市规划行政主管部门责令其停止损害，限期改正，并可处一万元以上五万元以下的罚款。造成损失的，应当赔偿损失。 有本条例第二十条第（二）项规定行为的，由文物行政主管部门责令其停止违法行为，限期采取补救措施，并依法处罚。 有本条例第二十条第（三）项规定行为的，由城市规划行政主管部门责令其停止违法行为，限…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (687, 'FBMCLI.10.452415', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 6 个核心用语、9 个相关用语，关联 24 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1292, 687, 2166, '第二条', '…利用和管理，适用本条例。 历史文化名城保护的对象包括老城格局和城市风貌、历史文化名镇名村、历史文化街区、历史风貌区、历史街巷、历史建筑、古镇古村、地下文物重点保护区、非物质文化遗产等。 法宝联想 司法案例 司法案例（1）', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1293, 687, 2175, '第十一条', '…一）基础资料； （二）历史文化价值和现状评估； （三）传统格局和历史风貌保护要求； （四）历史文化街区、名镇、名村的核心保护范围和建设控制地带； （五）保护的原则、内容、范围、要求和措施； （六）开发强度、利用方式和实施方案。 具体保护对象的保护规划应当包括保护文本、图则和相关附件。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1294, 687, 2181, '第十七条', '…涵较为丰富、特色明显，体现名城风貌特征的历史街巷； （四）反映历史风貌和地方特色，未公布为文物保护单位，未登记为不可移动文物，但是具有一定保护价值的历史建筑； （五）地下文物重点保护区； （六）其他应当列入保护名录的保护对象。 调整保护名录应当按照原审批程序报送审批并公布。 法宝联想 法律法规 规范性文件（4）', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (688, 'FBMCLI.10.452415', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、6 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1295, 688, 2175, '第十一条', '…价值和现状评估； （三）传统格局和历史风貌保护要求； （四）历史文化街区、名镇、名村的核心保护范围和建设控制地带； （五）保护的原则、内容、范围、要求和措施； （六）开发强度、利用方式和实施方案。 具体保护对象的保护规划应当包括保护文本、图则和相关附件。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1296, 688, 2212, '第四十八条', '…物局关于在南京城墙建设控制地带内进行南京城墙博物馆建设项目的意见 国家文物局关于在南京城墙保护范围和建设控制地带内进行电力工程建设项目的批复 地方法规规章 南京市政府办公厅关于印发市政府2025年立法计划的通知 南京市城市管理局关于印发《南京市城市管理领域行政处罚(强制)裁量权基准(2024版)及其适用说明》的通知 …', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1297, 688, 2188, '第二十四条', '…格保护六朝建康城、南唐金陵宫城、明代南京宫城和民国南京城的遗迹遗址。任何单位和个人不得破坏保护范围内的遗迹遗址。考古、施工中发现的重要遗迹遗址应当原址保护，并作为城市公共空间向公众展示。 严格保护南唐、明代都城城墙和护城河。任何单位和个人不得破坏明代外郭城墙现存段落及整体走向，墙基两侧各划定三十米至五十米的公共绿地。…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (689, 'FBMCLI.10.452415', 'RESP', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、5 个相关用语，关联 22 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1298, 689, 2169, '第五条', '…名城保护委员会，负责规划、协调、审议、指导历史文化名城保护工作的重大事项。 市城乡规划行政主管部门会同文物行政主管部门负责组织实施本条例。 建设、房产、国土、财政、文化、旅游、城市管理、公安等行政主管部门，应当按照各自职责做好历史文化名城的保护工作。 区、县人民政府负责组织实施本辖区内历史文化名城保护的具体工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1299, 689, 2208, '第四十四条', '…条 违反本条例规定，国家机关及其工作人员有下列情形之一的，由市、区、县人民政府或者有关行政主管部门责令其改正，对直接负责的主管人员和其他直接责任人员，依法追究行政责任： （一）未按照法定程序组织编制、修改保护规划和确定、调整保护名录的； （二）未按照法定程序或者未按照保护规划的要求履行审批职责的； （三）未依法对保护…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1300, 689, 2174, '第十条', '…依据历史文化名城保护规划，编制各类保护对象的保护规划。其中，市区范围内的，由市城乡规划行政主管部门会同市、区有关部门组织编制；高淳县、溧水县范围内的，由县人民政府组织编制。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (690, 'FBMCLI.10.452415', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (691, 'FBMCLI.10.452415', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、5 个相关用语，关联 14 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1301, 691, 2208, '第四十四条', '…接负责的主管人员和其他直接责任人员，依法追究行政责任： （一）未按照法定程序组织编制、修改保护规划和确定、调整保护名录的； （二）未按照法定程序或者未按照保护规划的要求履行审批职责的； （三）未依法对保护对象的保护状况实施监督检查，或者对经批准的保护对象的改造、利用情况监管不力的； （四）未依法受理举报、控告和查处违…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1302, 691, 2177, '第十三条', '第十三条 历史文化名城保护规划经市人民代表大会常务委员会审议后，依法报经批准。保护规划除法律、法规规定必须报省以上人民政府或者部门批准的，由市人民政府批准。经批准的保护规划，任何单位和个人不得违反。保护规划需要修改的，按照原审批程序报送审批。 法宝联…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1303, 691, 2174, '第十条', '第十条 南京市历史文化名城保护规划由市人民政府组织编制。 依据历史文化名城保护规划，编制各类保护对象的保护规划。其中，市区范围内的，由市城乡规划行政主管部门会同市、区有关部门组织编制；高淳县、溧水县范围内的，由县人民政府组织编制。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (692, 'FBMCLI.10.452415', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (693, 'FBMCLI.10.452415', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1304, 693, 2196, '第三十二条', '第三十二条 历史建筑需要拆除、迁移、修缮并经批准，原有资料不全或者缺失的，建设单位应当委托有关单位对历史建筑进行测绘，测绘资料移交市、县房产行政主管部门保存。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1305, 693, 2180, '第十六条', '第十六条 保护范围内新建、改建、扩建建筑物、构筑物以及各类基础设施的，其退让、间距、日照、节能、抗震以及道路路幅宽度等，应当符合现行规范标准。因现有条件限制，无法达到现行规范标准的，应当按照保护要求，确定建设工程设计方案，经批准后执行。其中，市政基础…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1306, 693, 2191, '第二十七条', '第二十七条 历史建筑的建筑立面、平面布局、院落、牌坊、树木等不得破坏，经批准改建、扩建的历史建筑，在高度、体量、风格、材料、色彩等方面应当与原有建筑相协调。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (694, 'FBMCLI.10.452415', 'FUND', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1307, 694, 2172, '第八条', '第八条 市、区、县人民政府应当把历史文化名城保护资金列入同级财政预算。 鼓励企事业单位、社会团体和个人以捐赠等形式参与历史文化名城的保护。 历史文化名城保护资金和受赠款项，应当专项用于历史文化名城保护，不得挪作他用。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1308, 694, 2195, '第三十一条', '…、县房产行政主管部门申请补贴，由区、县房产行政主管部门报市房产行政主管部门批准。补贴费用从保护资金中列支。 所有权不明或者被政府代管的历史建筑，由市房产行政主管部门负责修缮。 法宝联想 司法案例 司法案例（1）', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1309, 694, 2206, '第四十二条', '…经印刷技艺、秦淮灯会等项目，市、区、县人民政府应当明确保护责任单位，落实保护责任，安排财政专项资金，用于非物质文化遗产的普查、征集、抢救、研究、传播、宣传教育等。 保护责任单位应当按照非物质文化遗产保护的相关规定履行保护义务。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (695, 'FBMCLI.10.452415', 'COMP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1310, 695, 2171, '第七条', '…报和控告。 在历史文化名城保护工作中做出突出贡献的单位和个人，由市、区、县人民政府予以表彰奖励。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1311, 695, 2201, '第三十七条', '…计方案有序组织实施。因保护性更新改造需要搬迁住户的，应当依照有关法律、法规的规定实施并予以补偿。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (696, 'FBMCLI.10.452415', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1312, 696, 2176, '第十二条', '…的编制，应当经专家委员会论证，并征求有关部门和社会公众的意见。涉及重大公共利益的，应当组织听证。 法宝联想 司法案例 司法案例（1）', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (697, 'FBMCLI.10.452415', 'BIZ', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (698, 'FBMCLI.10.452415', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (699, 'FBMCLI.10.452415', 'SUP', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1313, 699, 2176, '第十二条', '第十二条 保护规划的编制，应当经专家委员会论证，并征求有关部门和社会公众的意见。涉及重大公共利益的，应当组织听证。 法宝联想 司法案例 司法案例（1）', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1314, 699, 2208, '第四十四条', '…保护状况实施监督检查，或者对经批准的保护对象的改造、利用情况监管不力的； （四）未依法受理举报、控告和查处违法行为的； （五）滥用职权、玩忽职守、徇私舞弊的； （六）法律、法规规定的其他违法行为。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1315, 699, 2170, '第六条', '第六条 本市设立历史文化名城专家委员会。专家委员会由规划、文物、文化、建筑、园林、旅游、宗教、历史、民俗和法律等方面的专家组成，负责对保护规划、保护名录等事项进行论证和评审。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (700, 'FBMCLI.10.452415', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1316, 700, 2209, '第四十五条', '…采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位处以十万元以上五十万元以下的罚款，对个人处以一万元以上五万元以下的罚款；造成损失的，依法承担赔偿责任。 法宝联想 法律法规 规范性文件（1）', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1317, 700, 2211, '第四十七条', '…市管理行政执法部门责令限期改正或者恢复原状；逾期不改正的，对单位处以五千元以上五万元以下的罚款，对个人处以二百元以上二千元以下的罚款。 第七章 附 则', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1318, 700, 2207, '第四十三条', '…集、整理非物质文化遗产的珍贵资料，培养传承人，积极组织和参与相关展示、展演活动。 第六章 法律责任', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (701, 'FBMCLI.10.343577', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、5 个相关用语，关联 15 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1319, 701, 2225, '第十三条', '第十三条 历史文化名城保护的主要内容包括：历史城区、历史文化街区、历史建筑、历史文化名镇名村和非物质文化遗产等。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1320, 701, 2228, '第十六条', '…十六条 历史建筑是指具有一定历史意义和保护价值，能够反映沈阳历史风貌和地方特色的，未公布为文物保护单位，也未登记为不可移动文物的建筑物和构筑物。 历史建筑的认定标准和程序，由市人民政府制定并公布。 第四章 保护措施', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1321, 701, 2238, '第二十六条', '第二十六条 市规划行政部门应当会同市文物行政部门对历史文化街区、历史建筑和重要历史遗址等设置保护标志或者纪念标志。 任何单位和个人不得擅自设置、移动、涂改或者损毁保护标志和纪念标志。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (702, 'FBMCLI.10.343577', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1322, 702, 2222, '第十条', '…控制性详细规划，报市人民政府批准后公布施行。 专项保护规划和控制性详细规划的内容应当包括：保护范围，保护原则，需要保护的建筑物、构筑物和其他设施，保持传统风貌的建筑高度、体量、色彩等控制指标，土地使用功能，人口密度，市政基础设施的改善，不同建筑的分类保护和整治措施，保证保护规划实施的具体措施以及其他应当纳入专项保护规…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1323, 702, 2226, '第十四条', '…初期形成的城区。主要包括明清时期形成的盛京城、民国时期形成的满铁附属地和商埠地等。 盛京城保护范围是清时期沈阳城外城（八关）以内的区域，位于惠工街、联合路、东边城街、南关路、青年大街以内。 满铁附属地保护范围是满铁附属地发展的核心区，东至和平大街，西至长大铁路，南至南五马路，北至北七马路。 商埠地保护范围是北至哈尔滨…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1324, 702, 2227, '第十五条', '… 历史文化街区包括方城、慈恩寺、沈阳站-中山路-中山广场、铁西工人村等。 方城历史文化街区保护范围是西顺城街、北顺城路、东顺城街、南顺城路以内的区域。 慈恩寺历史文化街区保护范围是南至富教巷和般若寺巷、北至龙凤寺巷、东至大佛寺巷和慈恩寺东巷、西至大南街。 沈阳站－中山路－中山广场历史文化街区保护范围是西至长大铁路、东…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (703, 'FBMCLI.10.343577', 'RESP', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1325, 703, 2215, '第三条', '第三条 市人民政府负责本市行政区域内历史文化名城的保护和监督管理工作。 区、县（市）人民政府负责本辖区内历史文化名城的保护和监督管理工作。 市规划行政部门负责本市历史文化名城保护的规划管理工作。 市文物行政部门负责文物保护工作，参与本市历…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1326, 703, 2236, '第二十四条', '第二十四条 历史建筑的所有权人应当按照保护规划和修缮标准的要求，负责历史建筑的维护和修缮。 所有权人和管理人、使用人对维护、修缮义务另有约定的，从其约定。 对于所有权人和管理人、使用人确不具备维护、修缮能力的历史建筑，市和区、县（市）人民政府应当采取…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1327, 703, 2221, '第九条', '第九条 市人民政府应当依法组织编制历史文化名城保护规划，并纳入城市总体规划。 区、县（市）人民政府应当依法组织编制历史文化名镇、名村保护规划。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (704, 'FBMCLI.10.343577', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (705, 'FBMCLI.10.343577', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、7 个相关用语，关联 15 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1328, 705, 2222, '第十条', '第十条 市规划行政部门应当会同市文物行政部门，根据历史文化名城保护规划的要求，组织编制专项保护规划和控制性详细规划，报市人民政府批准后公布施行。 专项保护规划和控制性详细规划的内容应当包括：保护范围，保护原则，需要保护的建筑物、构筑物和其他设施，保持传统风貌的建筑高度、体量、色彩等控制指标…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1329, 705, 2224, '第十二条', '第十二条 历史文化名城保护规划经批准公布后，任何单位和个人不得擅自修改；确需修改的，应当按照本条例第十一条规定的程序执行。 第三章 保护内容', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1330, 705, 2233, '第二十一条', '第二十一条 市规划行政部门对历史文化名城保护规划范围内的建设项目进行规划审批时，应当对建设项目进行有关历史文化名城风貌影响的评估。未经评估，或者未通过评估的，不得进行审批。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (706, 'FBMCLI.10.343577', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (707, 'FBMCLI.10.343577', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、7 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1331, 707, 2243, '第三十一条', '…成犯罪的，依法追究刑事责任： （一）擅自调整保护规划的； （二）擅自批准拆除、改建、扩建、迁移历史建筑的； （三）未按照保护规划要求审批建设项目的； （四）其他违反法律法规和本条例规定的行为。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1332, 707, 2235, '第二十三条', '第二十三条 历史建筑不得违法拆除、改建、扩建。 依法拆除的国有历史建筑中具有收藏价值的壁画、雕塑、建筑构件等，由文物行政部门指定的文物收藏单位收藏。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1333, 707, 2232, '第二十条', '…合保护规划要求的建筑物、构筑物和其他设施，建设单位应当按照保护规划的要求逐步改造、迁建或者拆除。 对历史文化名城保护规划范围内违法建设的并不符合保护规划要求的建筑物、构筑物和其他设施，规划行政部门及有关部门应当依法拆除或者责令改造。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (708, 'FBMCLI.10.343577', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1334, 708, 2217, '第五条', '… 市和区、县（市）人民政府应当把历史文化名城保护纳入本级经济和社会发展规划；将历史文化名城保护资金列入本级财政预算。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (709, 'FBMCLI.10.343577', 'COMP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1335, 709, 2218, '第六条', '第六条 鼓励单位和个人以捐赠、资助、提供技术服务或者提出建议等方式参与历史文化名城的保护工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1336, 709, 2220, '第八条', '…人民政府及其有关行政部门应当对在历史文化名城保护工作中做出突出贡献的单位和个人，给予表彰和奖励。 第二章 保护规划', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (710, 'FBMCLI.10.343577', 'RES', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (711, 'FBMCLI.10.343577', 'BIZ', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (712, 'FBMCLI.10.343577', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (713, 'FBMCLI.10.343577', 'SUP', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (714, 'FBMCLI.10.343577', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1337, 714, 2243, '第三十一条', '…反本条例规定，国家机关及其工作人员有下列情形之一的，由市和区、县（市）人民政府或者有关部门责令改正，并依法给予行政处分；构成犯罪的，依法追究刑事责任： （一）擅自调整保护规划的； （二）擅自批准拆除、改建、扩建、迁移历史建筑的； （三）未按照保护规划要求审批建设项目的； （四）其他违反法律法规和本条例规定的行为。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1338, 714, 2244, '第三十二条', '…采取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处5万元以上10万元以下的罚款，对个人并处1万元以上5万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1339, 714, 2245, '第三十三条', '…取其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处20万元以上50万元以下的罚款，对个人并处10万元以上20万元以下的罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (715, 'FBMCLI.10.60978', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、5 个相关用语，关联 25 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1340, 715, 2252, '第三条', '…革命胜地、湖湘文化、山水洲城的人文和自然特色，保护的主要内容： （一）历史文化风貌保护区和历史文化街区、村镇； （二）文物和历史建筑、重要历史遗址（迹）及其周围相协调的环境； （三）风景名胜、古井名泉、古树名木； （四）传统文化艺术、传统工艺、老字号、百年名校和历史地名等非物质文化遗产； （五）法律、法规和规章规定的其他…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1341, 715, 2258, '第九条', '…创造条件；应当确定历史文化名城保护的总体目标、保护原则和保护内容，划定历史文化风貌保护区、历史文化街区、历史文化村镇、文物保护单位、其他不可移动文物、历史建筑的保护范围及建设控制地带，划定文物埋藏区，提出控制要求和保护措施。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1342, 715, 2268, '第十九条', '第十九条 历史文化街区应当保留传统街巷格局和路面特色，保留历史地名；保护好街区内的历史建筑；恢复街区内的历史人文景观。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (716, 'FBMCLI.10.60978', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1343, 716, 2258, '第九条', '…历史文化风貌保护区、历史文化街区、历史文化村镇、文物保护单位、其他不可移动文物、历史建筑的保护范围及建设控制地带，划定文物埋藏区，提出控制要求和保护措施。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1344, 716, 2262, '第十三条', '第十三条 岳麓山、小西门、天心阁、潮宗街、开福寺等历史文化风貌保护区的保护范围、重点保护内容由市人民政府依据已批准的城市总体规划公布。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1345, 716, 2263, '第十四条', '第十四条 在历史文化风貌保护区的保护范围和建设控制地带内进行建设活动，应当尽量保持原有自然环境、风貌特色，保护反映历史文化风貌的不可移动文物、历史建筑和街巷格局。 新建或者改建的建筑物的高度、体量、形式、色彩、用途等，应当符合历史文化名城保护专项规划及其控制性…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (717, 'FBMCLI.10.60978', 'RESP', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 13 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1346, 717, 2279, '第三十条', '第三十条 市人民政府应当组织对历史建筑的安全使用等级进行鉴定，有关部门应当提出相应的整改措施。 产权所有人或者使用人应当负责历史建筑的安全、保养和修缮，确无修缮和维护能力的，市人民政府可视情况予以资助，或者依法置换历史建筑的产权。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1347, 717, 2254, '第五条', '第五条 市人民政府统一领导历史文化名城的保护工作。市、区（县、市）人民政府应当把历史文化名城的保护纳入国民经济和社会发展计划，并在财政预算中安排专项资金。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1348, 717, 2256, '第七条', '…、控告和制止破坏历史文化名城的行为。 在历史文化名城保护工作中作出突出贡献的单位和个人，由市人民政府给予表彰和奖励。 第二章 历史文化名城保护规划', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (718, 'FBMCLI.10.60978', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (719, 'FBMCLI.10.60978', 'PLAN', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1349, 719, 2285, '第三十六条', '…位依法追究直接负责的主管人员和其他直接责任人员的行政责任： （一）违法调整历史文化名城各类保护规划的； （二）违法批准新建、改建建筑或者拆除历史建筑的； （三）其他不按照本条例的要求违法审批的。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1350, 719, 2256, '第七条', '…名城保护工作中作出突出贡献的单位和个人，由市人民政府给予表彰和奖励。 第二章 历史文化名城保护规划', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (720, 'FBMCLI.10.60978', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1351, 720, 2273, '第二十四条', '第二十四条 尚未核定公布为文物保护单位的不可移动文物，由县级人民政府文化行政管理部门依法登记、制定保护措施并公布；对其进行修缮，必须经县级人民政府文化行政管理部门同意。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (721, 'FBMCLI.10.60978', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、6 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1352, 721, 2285, '第三十六条', '…的行政责任： （一）违法调整历史文化名城各类保护规划的； （二）违法批准新建、改建建筑或者拆除历史建筑的； （三）其他不按照本条例的要求违法审批的。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1353, 721, 2269, '第二十条', '第二十条 历史文化街区内的新建、改建、修缮等建设活动，应当符合历史文化街区控制性和修建性详细规划的要求；对其设计方案，市规划行政管理部门应当会同市建设、文化行政管理部门在20日内提出审核意见并书面告知申请人。审核合格的，方可办理建设手续。 街区内的文化旅游设施和…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1354, 721, 2277, '第二十八条', '第二十八条 历史建筑应当原址原貌保护，不得擅自拆除。确需迁移的，迁移方案由市规划行政管理部门会同市建设、文化行政管理部门论证并提出书面意见报市人民政府批准。上述工作应当在30日内完成。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (722, 'FBMCLI.10.60978', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1355, 722, 2254, '第五条', '…区（县、市）人民政府应当把历史文化名城的保护纳入国民经济和社会发展计划，并在财政预算中安排专项资金。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (723, 'FBMCLI.10.60978', 'COMP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1356, 723, 2256, '第七条', '…文化名城的行为。 在历史文化名城保护工作中作出突出贡献的单位和个人，由市人民政府给予表彰和奖励。 第二章 历史文化名城保护规划', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1357, 723, 2279, '第三十条', '…或者使用人应当负责历史建筑的安全、保养和修缮，确无修缮和维护能力的，市人民政府可视情况予以资助，或者依法置换历史建筑的产权。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (724, 'FBMCLI.10.60978', 'RES', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (725, 'FBMCLI.10.60978', 'BIZ', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (726, 'FBMCLI.10.60978', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (727, 'FBMCLI.10.60978', 'SUP', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (728, 'FBMCLI.10.60978', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1358, 728, 2287, '第三十八条', '…坏历史建筑的，由建设行政管理部门责令停止违法行为，恢复原状，对个人处二千元以上二万元以下的罚款；对单位处五万元以上二十万元以下罚款。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1359, 728, 2288, '第三十九条', '…标志和历史遗址（迹）纪念标志的，由建设行政管理部门责令恢复原状，并可处二百元以上五百元以下罚款。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1360, 728, 2284, '第三十五条', '…的历史地名应当予以保留；确需更改或者取消的，地名管理机构应当听取有关方面的意见。 第六章 法律责任', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (729, 'FBMCLI.17.652269', 'OBJ', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1361, 729, 2304, '第十三条', '…十三条 本条例所称会理历史文化名城保护是指： （一）保护历史文化名城的历史风貌、传统格局、历史建筑和空间尺度； （二）保护历史文化名城文物古迹和具有历史传统特色的街区、巷道、古建筑、古民居、古民居院落、古树名木、古井和具有历史文化风貌的不可移动文物等； （三）保护历史文化名城风景名胜区的自然景观和环境； （四）保护历…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1362, 729, 2310, '第十九条', '…会理历史文化名城保护区内的古民居、古建筑及其中的门、窗、牌、匾、枋等建筑、装饰构件；不得对历史建筑物进行影响历史风貌和传统格局的改建和装修。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1363, 729, 2313, '第二十二条', '第二十二条 会理历史文化名城保护区的古树名木、古井实行统一建档，挂牌保护，公民、法人或其他社会组织不得毁坏、填埋、砍伐和擅自迁移。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (730, 'FBMCLI.17.652269', 'BND', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (731, 'FBMCLI.17.652269', 'RESP', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (732, 'FBMCLI.17.652269', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (733, 'FBMCLI.17.652269', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、3 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1364, 733, 2300, '第九条', '…条 会理县人民政府根据国家有关规定，结合会理历史文化名城保护的需要，制定的会理历史文化名城保护规划或调整的规划，经省人民政府批准，向社会公布后实施。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1365, 733, 2301, '第十条', '第十条 会理历史文化名城保护规划应当按照保护为主、合理开发利用的方针编制。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1366, 733, 2307, '第十六条', '…应当遵守国家有关法律法规和本条例规定，符合省人民政府批准的会理县城市总体规划和历史文化名城保护规划。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (734, 'FBMCLI.17.652269', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (735, 'FBMCLI.17.652269', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、5 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1367, 735, 2309, '第十八条', '…名城保护区内历史传统街区的整治，古建筑、挂牌保护的古民居院落、名胜古迹、风景名胜区的建设和修缮，应当由县人民政府确定修缮方案，经论证后按有关法律规定报批。 其他古民居、古民居院落的修缮须经相关部门审批。 宗教活动场所的建设、修缮应当符合城市规划，并尊重宗教场所的建设风格，按规定程序报批。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1368, 735, 2310, '第十九条', '第十九条 任何单位和个人不得擅自拆除会理历史文化名城保护区内的古民居、古建筑及其中的门、窗、牌、匾、枋等建筑、装饰构件；不得对历史建筑物进行影响历史风貌和传统格局的改建和装修。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1369, 735, 2302, '第十一条', '…编制对会理历史文化名城保护区内的历史传统街区、巷道、古民居、古民居院落、风景名胜区的建设和修缮规划，并由有关部门组织实施。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (736, 'FBMCLI.17.652269', 'FUND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1370, 736, 2298, '第七条', '第七条 会理历史文化名城保护资金以政府投入为主，鼓励社会捐助、民间资本投入。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (737, 'FBMCLI.17.652269', 'COMP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1371, 737, 2299, '第八条', '…城保护、管理与利用工作中做出突出贡献的公民、法人和其他社会组织，按照国家有关规定给予表彰和奖励。 第二章 规划与实施', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (738, 'FBMCLI.17.652269', 'RES', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (739, 'FBMCLI.17.652269', 'BIZ', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (740, 'FBMCLI.17.652269', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (741, 'FBMCLI.17.652269', 'SUP', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (742, 'FBMCLI.17.652269', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1372, 742, 2325, '第三十四条', '第三十四条 违反本条例规定的，由会理县人民政府责令限期改正或者恢复原状；情节严重的，根据国家法律、法规的规定对当事人进行行政处罚；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1373, 742, 2324, '第三十三条', '…间工艺品开发、收藏、展示、交易活动； （七）其它地方特色文化、产品的开发和经营。 第四章 法律责任', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (743, 'FBMCLI.17.7307208', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、10 个相关用语，关联 22 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1374, 743, 2332, '第三条', '…、古树名木、非物质文化遗产的保护，按照有关法律法规的规定执行。 前款所称传统风貌建筑，是指文物保护单位、历史建筑外，具有一定建成历史，对历史城区整体风貌特征形成具有价值和意义的建（构）筑物。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1375, 743, 2355, '第二十六条', '第二十六条 历史建筑保护责任人应当履行下列保护责任： （一）按照历史建筑保护要求及其功能，合理使用历史建筑； （二）保持历史建筑原有的高度、体量、外观形象和色彩； （三）保护历史建筑的传统格局、历史风貌、特色装饰和历史环境要素的完整性； （…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1376, 743, 2371, '第四十二条', '…制、报批、修改、公布保护规划的； （二）未按照法定程序履行审批职责的； （三）未按照规定对历史文化街区、历史建筑、传统风貌建筑开展日常巡查保护，或者未履行对历史建筑和传统风貌建筑安全监管职责的； （四）未履行或者未按照要求履行其他相关职责，导致镇远历史文化名城保护工作受到严重影响，或者列入保护名录的保护对象的历史、艺术、…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (744, 'FBMCLI.17.7307208', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1377, 744, 2339, '第十条', '…街传统风貌区等区域，具体范围由镇远县人民政府根据名城保护规划划定。 历史文化街区划分为核心保护范围和建设控制地带。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1378, 744, 2348, '第十九条', '…史文化街区建设控制地带内新建、扩建、改建建（构）筑物的高度、体量、色彩、肌理等，应当与核心保护范围的历史风貌相协调。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1379, 744, 2352, '第二十三条', '第二十三条 镇远县人民政府应当依法划定历史建筑保护范围，对历史文化街区外的历史建筑还应当划定必要的建设控制地带。 在历史建筑保护范围内不得新建建（构）筑物。确因保护需要建设附属设施的，应当经镇远县人民政府履行规划职责的部门会同文物主管部门批准。 在历史建筑建设控制地带内新建…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (745, 'FBMCLI.17.7307208', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 9 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1380, 745, 2371, '第四十二条', '…，国家机关及其工作人员有下列情形之一，尚不构成犯罪的，由自治州、镇远县人民政府或者有关行政主管部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分： （一）未组织或者未按照法定程序组织编制、报批、修改、公布保护规划的； （二）未按照法定程序履行审批职责的； （三）未按照规定对历史文化街区、历史建筑、传统风…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1381, 745, 2334, '第五条', '…名城保护管理工作协调和考核机制，研究名城保护管理中的重大事项，其日常工作由县住房和城乡建设主管部门承担。 镇远县人民政府相关部门、乡镇人民政府、街道办事处按照各自职责，协同做好名城保护管理工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1382, 745, 2347, '第十八条', '…和公共服务设施的，镇远县人民政府履行规划职责的部门核发建设工程规划许可证前，应当征求县文物主管部门的意见。 在历史文化街区核心保护范围内拆除历史建筑以外的建（构）筑物或者其他设施的，应当经镇远县人民政府履行规划职责的部门会同县文物主管部门批准。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (746, 'FBMCLI.17.7307208', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (747, 'FBMCLI.17.7307208', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、7 个相关用语，关联 12 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1383, 747, 2371, '第四十二条', '…和其他直接责任人员依法给予处分： （一）未组织或者未按照法定程序组织编制、报批、修改、公布保护规划的； （二）未按照法定程序履行审批职责的； （三）未按照规定对历史文化街区、历史建筑、传统风貌建筑开展日常巡查保护，或者未履行对历史建筑和传统风貌建筑安全监管职责的； （四）未履行或者未按照要求履行其他相关职责，导致镇远…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1384, 747, 2336, '第七条', '第七条 镇远县人民政府应当依法编制名城保护规划以及历史文化街区、传统风貌区、历史建筑等专项保护规划，经批准后实施。 经批准的名城保护规划以及其他专项保护规划应当严格执行，不得擅自变更。确需变更的，按照原批准程序执行。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1385, 747, 2362, '第三十三条', '第三十三条 镇远县人民政府应当按照保护规划要求，在历史城区外围划设环境协调区并及时向社会公布。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (748, 'FBMCLI.17.7307208', 'PRE', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1386, 748, 2351, '第二十二条', '…布名录，对符合历史建筑条件的建（构）筑物提出申报意见，报县人民政府批准。 建立历史建筑线索预先保护制度，预先保护期间不得损坏或者拆除该建（构）筑物。预先保护期限为12个月，从镇远县人民政府履行规划职责的部门或者县文物主管部门发出预先保护通知之日起计算。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (749, 'FBMCLI.17.7307208', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 15 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1387, 749, 2350, '第二十一条', '…县履行规划职责的部门会同县文物主管部门，依照法律、法规的规定报请批准。 对历史建筑进行外部修缮装饰、添加设施以及改变历史建筑的结构或者使用性质的，应当经镇远县履行规划职责的部门会同县文物主管部门批准，并依照有关法律、法规的规定办理相关手续。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1388, 749, 2347, '第十八条', '…部门核发建设工程规划许可证前，应当征求县文物主管部门的意见。 在历史文化街区核心保护范围内拆除历史建筑以外的建（构）筑物或者其他设施的，应当经镇远县人民政府履行规划职责的部门会同县文物主管部门批准。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1389, 749, 2352, '第二十三条', '…远县人民政府履行规划职责的部门会同文物主管部门批准。 在历史建筑建设控制地带内新建、扩建、改建建（构）筑物，以及修建道路、地下工程以及其他市政公用设施的，应当采取有效的保护措施，不得破坏历史建筑的环境风貌。新建、扩建、改建的建（构）筑物，应当在高度、体量、立面、材料、色彩等方面与历史建筑相协调。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (750, 'FBMCLI.17.7307208', 'FUND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1390, 750, 2335, '第六条', '第六条 镇远县人民政府应当将名城保护管理工作纳入国民经济和社会发展规划，所需经费列入财政预算。州人民政府根据名城保护工作实际需要，给予经费支持。 鼓励单位和个人以捐赠、资助、志愿服务等方式参与名城的保护工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (751, 'FBMCLI.17.7307208', 'COMP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1391, 751, 2335, '第六条', '…费列入财政预算。州人民政府根据名城保护工作实际需要，给予经费支持。 鼓励单位和个人以捐赠、资助、志愿服务等方式参与名城的保护工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1392, 751, 2338, '第九条', '…控告。 对在名城保护管理工作中做出突出贡献的单位和个人，按照国家和省的有关规定予以表彰或者奖励。 第二章 历史城区保护', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (752, 'FBMCLI.17.7307208', 'RES', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (753, 'FBMCLI.17.7307208', 'BIZ', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1393, 753, 2346, '第十七条', '…一）在核心保护范围内进行必要的基础设施和公共服务设施之外的新建、扩建活动； （二）进行大型商业开发； （三）在公共场地放养鸡犬等畜禽； （四）占道经营并对街区环境造成不良影响。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1394, 753, 2366, '第三十七条', '…当统筹规划、合理利用名城历史文化遗产，优化名城文化、休闲及旅游功能，通过人居环境改善、功能业态调整以及相关配套设施建设，促进名城旅游产业发展。 在遵循保护规划的前提下，鼓励和支持对名城各类保护对象的合理利用、有序开放，但不得破坏当地自然景观、人文景观和历史文化资源。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1395, 753, 2368, '第三十九条', '…住、使用条件，适应现代生活需要。 鼓励利用传统风貌建筑和历史建筑依法从事与名城保护相适应的经营活动，展示名城居民传统生活形态和民俗文化。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (754, 'FBMCLI.17.7307208', 'DIG', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1396, 754, 2337, '第八条', '… 镇远县人民政府应当根据名城保护规划和本条例规定，结合名城保护实际，建立名城保护对象名录和数字化档案，设立保护标志，明确保护管理措施和责任人，实行分区分级分类保护管理。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (755, 'FBMCLI.17.7307208', 'SUP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1397, 755, 2338, '第九条', '…公众的名城保护意识。 单位和个人都有保护名城的义务，有权对破坏名城的各类违法行为进行劝阻、举报和控告。 对在名城保护管理工作中做出突出贡献的单位和个人，按照国家和省的有关规定予以表彰或者奖励。 第二章 历史城区保护', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (756, 'FBMCLI.17.7307208', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、6 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1398, 756, 2372, '第四十三条', '…其他补救措施，所需费用由违法者承担；造成严重后果的，对单位并处以50万元以上100万元以下罚款，对个人并处以5万元以上10万元以下罚款；造成损失的，依法承担赔偿责任。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1399, 756, 2371, '第四十二条', '…关及其工作人员有下列情形之一，尚不构成犯罪的，由自治州、镇远县人民政府或者有关行政主管部门责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分： （一）未组织或者未按照法定程序组织编制、报批、修改、公布保护规划的； （二）未按照法定程序履行审批职责的； （三）未按照规定对历史文化街区、历史建筑、传统风貌建筑开…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1400, 756, 2370, '第四十一条', '…故事、传统习俗等非物质文化遗产； （八）利用名城资源传承优秀传统文化的其他活动。 第六章 法律责任', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (757, 'FBMCLI.17.1550906', 'OBJ', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1401, 757, 2409, '第三十三条', '第三十三条 凤凰历史文化名城保护范围内的各级文物保护单位，应根据《中华人民共和国文物保护法》的要求，划定保护范围和建设控制地带，编制专项保护规划和保护方案，有计划地实施保护工程。对历史建筑及其它重点民居、吊脚楼群、古树名木实行建档、挂牌保护。 第五章 法律责任', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1402, 757, 2402, '第二十六条', '…护的总体目标、保护原则和保护内容，划定历史城区、历史文化保护区、山水保护区、历史文化村镇、文物保护单位、其他不可移动文物、历史建筑的保护范围及建设控制地带。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1403, 757, 2401, '第二十五条', '…批准后公布实施。 县规划行政主管部门应当会同建设、文化、文物等行政管理部门根据专项规划编制历史文化街区、历史文化村镇控制性详细规划和修建性详细规划，经县人民政府批准后公布实施。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (758, 'FBMCLI.17.1550906', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 14 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1404, 758, 2402, '第二十六条', '…城区、历史文化保护区、山水保护区、历史文化村镇、文物保护单位、其他不可移动文物、历史建筑的保护范围及建设控制地带。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1405, 758, 2409, '第三十三条', '第三十三条 凤凰历史文化名城保护范围内的各级文物保护单位，应根据《中华人民共和国文物保护法》的要求，划定保护范围和建设控制地带，编制专项保护规划和保护方案，有计划地实施保护工程。对历史建筑及其它重点民居、吊脚楼群、古树名木实行建档、挂牌保护。 第五章 法律…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1406, 758, 2396, '第二十条', '…防火、森林病虫害防治工作。 在保护规划划定的南华山、八角楼、喜鹊坡、奇峰寺、北园等周边山体保护范围内禁止葬坟、采石、取土、伐木等破坏植被、景观的行为，未经批准不得兴建建筑物、构筑物。 第三章 黄丝桥古城和南方长城保护', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (759, 'FBMCLI.17.1550906', 'RESP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1407, 759, 2384, '第八条', '…层建筑檐口高度不超过五点六米，色调控制为黑、白、灰及灰褐色、原木色。 核心保护区内古建筑的所有权人或管理使用人对古建筑维修改造的，应当按照保护维修规划和要求进行施工。维修资金确有困难的，可以向凤凰历史文化名城保护管理机构申请适当补助。 风貌协调区内新建、改建、扩建的建筑物，其建筑风格应为木结构或小青砖墙，青瓦面坡屋顶…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1408, 759, 2391, '第十五条', '…通信等公共消防设施建设。无法按照标准和规范设置的，由凤凰县人民政府公安消防机构会同城乡规划主管部门制订相应的防火安全保障方案。 公共活动场所、居住场所的单位和个人必须做好消防安全工作，禁止燃放烟花爆竹。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1409, 759, 2401, '第二十五条', '…凤凰历史文化名城保护专项规划（以下简称专项规划），经省人民政府批准后公布实施。 县规划行政主管部门应当会同建设、文化、文物等行政管理部门根据专项规划编制历史文化街区、历史文化村镇控制性详细规划和修建性详细规划，经县人民政府批准后公布实施。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (760, 'FBMCLI.17.1550906', 'COORD', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (761, 'FBMCLI.17.1550906', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1410, 761, 2409, '第三十三条', '…物保护单位，应根据《中华人民共和国文物保护法》的要求，划定保护范围和建设控制地带，编制专项保护规划和保护方案，有计划地实施保护工程。对历史建筑及其它重点民居、吊脚楼群、古树名木实行建档、挂牌保护。 第五章 法律责任', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1411, 761, 2386, '第十条', '…的建筑物或者构筑物、道路、水系和其它设施，需要进行保养、维修、改造、改建、新建的，应当根据保护规划确定的保护要求，按照保护管理等级分别由有关部门提出实施方案，经凤凰历史文化名城保护管理机构审核后，依照国家有关规定报批，由具有专业资质的施工单位实施。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1412, 761, 2378, '第二条', '第二条 凤凰历史文化名城保护范围：《凤凰历史文化名城保护规划》（以下简称保护规划）确定的凤凰古城、黄丝桥古城、南方长城（湘西边墙，下同）以及其它应当保护的地带。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (762, 'FBMCLI.17.1550906', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (763, 'FBMCLI.17.1550906', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、5 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1413, 763, 2384, '第八条', '…批的基础设施和公共服务设施外，不得进行任何新建、扩建活动。 核心保护区内的建筑物、构筑物的修缮、翻建，必须采取保留外壳、整修内部的保护措施，保持原有的历史风貌。其建筑风格、体量、色调必须保持明清时期的布局和风貌，修旧如旧。建筑物高度必须控制在二层以下，一层建筑檐口高度不超过三米，二层建筑檐口高度不超过五点六米，色…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1414, 763, 2386, '第十条', '第十条 凤凰古城内的建筑物或者构筑物、道路、水系和其它设施，需要进行保养、维修、改造、改建、新建的，应当根据保护规划确定的保护要求，按照保护管理等级分别由有关部门提出实施方案，经凤凰历史文化名城保护管理机构审核后，依照国家有关规定报批，由具有专业资质的施工单位实施。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1415, 763, 2404, '第二十八条', '…文化名城保护专项规划及其控制性、修建性详细规划的建筑和设施，应当按照规划的要求逐步改造或者拆除。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (764, 'FBMCLI.17.1550906', 'FUND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1416, 764, 2381, '第五条', '…政府应当将凤凰历史文化名城保护纳入国民经济和社会发展计划，并将保护、维修和管理经费列入本级财政预算，吸纳符合国家规定的拨款和社会资助。 凤凰历史文化名城维护资金按照国家、省有关规定筹集，专项用于凤凰历史文化名城的保护。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (765, 'FBMCLI.17.1550906', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1417, 765, 2381, '第五条', '…经济和社会发展计划，并将保护、维修和管理经费列入本级财政预算，吸纳符合国家规定的拨款和社会资助。 凤凰历史文化名城维护资金按照国家、省有关规定筹集，专项用于凤凰历史文化名城的保护。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1418, 765, 2382, '第六条', '…告的权利。 州人民政府、凤凰县人民政府对保护凤凰历史文化名城成绩显著的单位和个人给予表彰和奖励。 第二章 凤凰古城保护', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1419, 765, 2384, '第八条', '…保护维修规划和要求进行施工。维修资金确有困难的，可以向凤凰历史文化名城保护管理机构申请适当补助。 风貌协调区内新建、改建、扩建的建筑物，其建筑风格应为木结构或小青砖墙，青瓦面坡屋顶，高度控制在二层以内，二层檐口高度不超过六米，色调、体量和建筑风格应当与核心保护区风貌相协调。 区域控制区新建、改建、扩建的建筑物，其…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (766, 'FBMCLI.17.1550906', 'RES', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (767, 'FBMCLI.17.1550906', 'BIZ', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1420, 767, 2387, '第十一条', '第十一条 凤凰县人民政府应当控制凤凰古城的商业过度开发，对古城内的经营活动进行指导和监督，适时发布鼓励或者限制经营的项目目录，重点发展具有当地民族文化特色的无污染、无公害产业，合理安排古城内商品经营市场布局。凤凰历史文化名城保护管理机构负责具体实施。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1421, 767, 2385, '第九条', '第九条 核心保护区内的历史街道、巷道应保持原有的视线走廊及空间尺度，严禁拓宽或缩小，商业街巷立面应当保持历史样式。 严禁占用道路、古井、沿街沿河空地及绿化地等公共活动场所。临街建筑物不得新开门窗，严禁使用防盗门、卷帘门、铝合金门窗、水泥花板等现代建筑设施和材料。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1422, 767, 2394, '第十八条', '…沱江水体保护范围内，禁止下列行为： （一）从事对水体有污染的行业； （二）在水面上擅自从事经营活动； （三）向河道排放污水、倾倒固体废弃物； （四）毒鱼、炸鱼、电鱼； （五）兴办有污染的项目； （六）其他污染水体或损坏水生态的行为。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (768, 'FBMCLI.17.1550906', 'DIG', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (769, 'FBMCLI.17.1550906', 'SUP', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (770, 'FBMCLI.17.1550906', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、5 个相关用语，关联 7 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1423, 770, 2411, '第三十五条', '…限期恢复原状或者采取其他补救措施；有违法所得的，没收违法所得；可并处五百元以上一千元以下的罚款。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1424, 770, 2415, '第三十九条', '…令停止违法行为、限期恢复原状或者采取其他补救措施，没收违法所得，并处一千元以上一万元以下的罚款。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1425, 770, 2412, '第三十六条', '…乱画乱贴、乱丢垃圾、占道摆设摊点、乱放杂物的，由执法局责令改正，可处以五元以上五十元以下的罚款；运用音响设备叫卖，设置与古城历史风貌不协调的广告、招牌的，由执法局责令改正，可处以五十元以上五百元以下的罚款；燃放烟花爆竹的，由执法局处以四十元以上一千元以下的罚款。存放、销售易燃易爆和有毒有害物品的，由凤凰县公安部门…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (771, 'FBMCLI.17.1550900', 'OBJ', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (772, 'FBMCLI.17.1550900', 'BND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1426, 772, 2420, '全文', '…区承载量，依据保护需要建立绿色交通运输和接驳服务体系，严格控制社会车辆进入凤凰历史文化名城保护范围，保障交通安全、畅通、环保。具体办法由凤凰县人民政府制定并公布。” 八、将第三十六条中的“第十三条”删除。 九、将第三十八条中的“工商、海事、畜牧等”删除。 本决定自公布之日起施行。 《湘西土家族苗族自治州凤凰历史文化名…', 'supporting');
