INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1427, 785, 2434, '第十四条', '第十四条 名城保护对象包括： （一）新石器时代以来各个历史时期有价值的历史遗迹； （二）历史文化街区、名镇、名村和传统村落； （三）文物； （四）历史建筑、名人故居； （五）革命纪念遗址； （六）历史街巷、传统地名； （七）古道、古桥、古井、古树名木； （八）非物质文化遗产； （九）苍山洱海风景区自然景观环境； （十）…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1428, 785, 2462, '第四十二条', '第四十二条 大理古城是名城的历史城区，其范围与大理古城历史文化街区一致。喜洲古镇包含喜洲历史文化街区。 大理古城墙遗址四至范围，是指以大理古城为中心，北至中和路，南至一塔路，西至大凤路，东至洪武路的范围。 历史建筑，是指经市人民政府确定公布的具有一定保护价值，能够反映历史风貌和地方特色…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1429, 785, 2423, '第三条', '第三条 名城保护范围主要包括： （一）大理古城； （二）喜洲古镇、龙尾关历史文化街区； （三）双廊历史文化名镇、周城历史文化名村； （四）崇圣寺三塔、太和城遗址（含南诏德化碑）、元世祖平云南碑等市级以上文物保护单位以及历史建筑的保护范围和建设控制地带； （五）大理风景名胜区中苍山洱海风景区在大理市（以下…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (786, 'FBMCLI.17.5049775', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、5 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1430, 786, 2433, '第十三条', '第十三条 市人民政府应当根据经依法批准的名城保护规划划定名城的核心保护范围和建设控制地带，并在核心保护范围的主要出入口设置标志牌。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1431, 786, 2441, '第二十一条', '…建筑物、构筑物的，应当符合名城保护规划确定的建设控制要求，其形态、高度、体量、色彩等与核心保护范围风貌相协调，临街、临巷的墙面、门窗使用传统建筑材料。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1432, 786, 2423, '第三条', '第三条 名城保护范围主要包括： （一）大理古城； （二）喜洲古镇、龙尾关历史文化街区； （三）双廊历史文化名镇、周城历史文化名村； （四）崇圣寺三塔、太和城遗址（含南诏德化碑）、元世祖平云南碑等市级以上文物保护单位以及历史建筑的保护范围和建…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (787, 'FBMCLI.17.5049775', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 25 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1433, 787, 2448, '第二十八条', '…者权属不明的，使用人为保护责任人，所有权人、使用人均不明确的，市人民政府住房和城乡建设行政主管部门为保护责任人。 历史建筑保护责任人应当履行下列保护责任： （一）保障历史建筑安全，确保防灾、消防设施设备的正常使用，发现安全隐患或者险情，及时报告并采取排除措施； （二）合理使用历史建筑，对历史建筑进行日常维护和修缮应当…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1434, 787, 2426, '第六条', '第六条 市人民政府住房和城乡建设行政主管部门会同文化和旅游行政主管部门负责名城保护管理和监督工作。 市人民政府自然资源行政主管部门负责名城保护涉及的规划管理等工作。 市人民政府发展和改革、财政、应急管理、公安、卫生健康、城市管理、农业农村、生态环境、林业和草原、苍…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1435, 787, 2427, '第七条', '第七条 市人民政府大理古城保护管理机构具体负责大理古城墙遗址四至范围内的名城保护工作，具体履行下列职责： （一）宣传贯彻执行有关法律法规及本条例； （二）组织实施古城保护相关规划及措施； （三）负责古城的园林绿化、环境卫生及市容市貌管理；…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (788, 'FBMCLI.17.5049775', 'COORD', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1436, 788, 2425, '第五条', '第五条 自治州人民政府应当加强对名城保护工作的领导，建立联席会议制度，研究名城保护的重大事项。 市人民政府负责名城保护管理工作，将其纳入国民经济和社会发展规划，所需保护经费列入财政预算，并成立名城保护管理委员会，统筹协调名城保护工作。 乡（镇）人民政府（街道办事处）负责辖区内名城保护…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (789, 'FBMCLI.17.5049775', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、7 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1437, 789, 2430, '第十条', '第十条 市人民政府应当组织编制名城保护规划，经自治州人民政府审定后报省人民政府审批。 名城保护规划应当符合市国土空间规划。涉及名城保护的专项规划应当与名城保护规划相衔接。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1438, 789, 2432, '第十二条', '第十二条 名城保护规划和历史文化街区、名镇、名村的保护规划报送审批前，市人民政府应当向社会公示，征求相关部门、专家和公众的意见。公示时间不得少于三十日。 经依法批准的名城保护规划和历史文化街区、名镇、名村的保护规划应当自批准之日起十五日内向社…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1439, 789, 2431, '第十一条', '第十一条 市人民政府应当根据经依法批准的名城保护规划组织编制历史文化街区、名镇、名村的保护规划，经自治州人民政府审定后报省人民政府审批。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (790, 'FBMCLI.17.5049775', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (791, 'FBMCLI.17.5049775', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、5 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1440, 791, 2442, '第二十二条', '第二十二条 大理古城墙遗址应当进行保护和修缮。古城墙遗址内侧13.5米、外侧20米以内禁止新建、改建、扩建建筑物、构筑物，原有建筑物、构筑物应当逐步拆除，符合法定补偿条件的，由市人民政府依法予以补偿。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1441, 791, 2440, '第二十条', '…内不符合名城保护规划，影响历史格局、街巷肌理和传统风貌的建筑物、构筑物应当逐步进行改造或者拆除。符合法定补偿条件的，由市人民政府依法予以补偿。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1442, 791, 2441, '第二十一条', '第二十一条 在名城建设控制地带内新建、改建、扩建建筑物、构筑物的，应当符合名城保护规划确定的建设控制要求，其形态、高度、体量、色彩等与核心保护范围风貌相协调，临街、临巷的墙面、门窗使用传统建筑材料。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (792, 'FBMCLI.17.5049775', 'FUND', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1443, 792, 2425, '第五条', '…大事项。 市人民政府负责名城保护管理工作，将其纳入国民经济和社会发展规划，所需保护经费列入财政预算，并成立名城保护管理委员会，统筹协调名城保护工作。 乡（镇）人民政府（街道办事处）负责辖区内名城保护的日常管理工作。 村（居）民委员会协助乡（镇）人民政府（街道办事处）做好名城保护相关工作。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (793, 'FBMCLI.17.5049775', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1444, 793, 2428, '第八条', '… 自治州、市人民政府对在名城保护中有突出贡献的单位和个人，按照国家和省的有关规定给予表彰和奖励。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1445, 793, 2440, '第二十条', '…护规划，影响历史格局、街巷肌理和传统风貌的建筑物、构筑物应当逐步进行改造或者拆除。符合法定补偿条件的，由市人民政府依法予以补偿。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1446, 793, 2442, '第二十二条', '…外侧20米以内禁止新建、改建、扩建建筑物、构筑物，原有建筑物、构筑物应当逐步拆除，符合法定补偿条件的，由市人民政府依法予以补偿。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (794, 'FBMCLI.17.5049775', 'RES', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1447, 794, 2424, '第四条', '第四条 名城保护遵循科学规划、严格保护、合理利用、公众参与、社会监督的原则，保持和延续名城传统格局和历史风貌，维护历史文化遗产的真实性和完整性，保留公众对名城的情感记忆。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (795, 'FBMCLI.17.5049775', 'BIZ', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1448, 795, 2454, '第三十四条', '…技艺加工制作、文化创意等与传统文化相协调的经营活动，推进活化利用，培育文化和旅游融合发展新业态。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1449, 795, 2457, '第三十七条', '…符合相关保护要求的基础上，合理利用历史建筑进行文化遗产展示，开展特色商业、休闲体验、民宿等经营活动。 对历史建筑的合理利用应当与其历史价值、内部结构相适应，不得擅自改变建筑主体结构、主要平面布局和外观，不得危害建筑主体及附属设施的安全。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (796, 'FBMCLI.17.5049775', 'DIG', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1450, 796, 2447, '第二十七条', '第二十七条 市人民政府应当建设名城保护数字化系统，对名城保护范围内重点保护区域、重点保护对象等设置智能监控系统。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (797, 'FBMCLI.17.5049775', 'SUP', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1451, 797, 2424, '第四条', '第四条 名城保护遵循科学规划、严格保护、合理利用、公众参与、社会监督的原则，保持和延续名城传统格局和历史风貌，维护历史文化遗产的真实性和完整性，保留公众对名城的情感记忆。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1452, 797, 2428, '第八条', '… 任何单位和个人都有保护名城的义务，有权对保护工作提出意见建议，对破坏名城的行为进行劝阻、举报和控告。 自治州、市人民政府对在名城保护中有突出贡献的单位和个人，按照国家和省的有关规定给予表彰和奖励。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (798, 'FBMCLI.17.5049775', 'LIAB', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、5 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1453, 798, 2460, '第四十条', '…放烟花爆竹的时间、地点燃放烟花爆竹的，由公安机关责令停止燃放，处100元以上500元以下的罚款；构成违反治安管理行为的，依法给予治安管理处罚； （二）违反第三十条第一至第三项规定之一的，由市人民政府自然资源行政主管部门责令停止违法行为、限期恢复原状或者采取其他补救措施；有违法所得的，没收违法所得；逾期不恢复原状或…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1454, 798, 2458, '第三十八条', '…织学生定期参观博物馆、展览馆、艺术馆，开展社会实践等活动，学习传承优秀传统文化。 第五章 法律责任', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (799, 'FBMCLI.10.9903391', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 7 个核心用语、11 个相关用语，关联 19 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1455, 799, 2477, '第十三条', '…落； （四）湖熟、竹镇、龙潭等古镇和窦村等古村； （五）历史城区； （六）夫子庙、颐和路等历史文化街区和内秦淮河两岸、百子亭等历史地段； （七）中国地质学会旧址等历史建筑； （八）惠济寺银杏、龙泉寺腊梅等古树名木； （九）红色文化资源、工业遗产、农业文化遗产、灌溉工程遗产、地名文化遗产等； （十）南京云锦织造技艺、金陵刻…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1456, 799, 2492, '第二十八条', '第二十八条 历史文化街区、名镇、名村、传统村落、古镇、古村、历史地段的保护责任人应当落实保护规划要求，履行下列保护责任： （一）保护和延续传统格局、街巷肌理和历史风貌特征；保护其所依存的地形地貌、河湖水系等自然景观和环境； （二）组织开展日常巡…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1457, 799, 2470, '第六条', '…人制度落实等工作。 市城乡建设主管部门负责南京历史文化名城保护涉及的市政基础设施建设，以及历史建筑等房屋建筑的施工审批管理工作，负责传统村落的申报和监督管理。 市农业农村主管部门负责统筹推动历史文化名村、古村的基础设施建设，改善人居环境，以及农业文化遗产的规划编制、保护利用和监督管理等工作。 市住房保障和房产主管部门…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (800, 'FBMCLI.10.9903391', 'BND', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 4 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1458, 800, 2493, '第二十九条', '第二十九条 历史文化街区、名镇、名村核心保护范围和建设控制地带内以及传统村落、古镇、古村、历史地段保护范围内的建设活动，应当符合保护规划，并遵守下列要求： （一）在历史文化街区、名镇、名村核心保护范围和建设控制地带内的建设活动，按照相关法律、法规和规章执行。 （二）在…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1459, 800, 2499, '第三十五条', '第三十五条 市级以上文物保护单位保护范围内的建设工程规划设计方案经市人民政府审查后，依据文物保护相关法律、法规报批。市级以上文物保护单位建设控制地带内的建设工程规划设计方案，应当经国家规定的文物主管部门同意后，报市人民政府批准。 历史文化街区、名镇、名村核心保…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1460, 800, 2519, '第五十五条', '…的含义： （一）历史地段，是指未核定公布为历史文化街区，且不在历史文化名镇、名村和传统村落保护范围内，能够真实反映一定历史时期传统风貌、历史格局和文化特色，具有一定保护价值的地段。 （二）古镇，是指尚未公布为历史文化名镇、具有特定历史时期传统风貌和格局的镇或者街道。 （三）古村，是指尚未公布为历史文化名村或者传统村落…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (801, 'FBMCLI.10.9903391', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 5 个核心用语、8 个相关用语，关联 22 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1461, 801, 2469, '第五条', '第五条 市人民政府负责南京历史文化名城保护工作，将其纳入本市国民经济和社会发展规划、计划，加大政策支持和资金保障力度。 区人民政府和江北新区管理机构负责本区域内历史文化名城保护工作，统筹安排保护资金，建立健全日常巡查管理制度，将巡查工作纳…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1462, 801, 2470, '第六条', '第六条 市规划和自然资源主管部门会同市文化和旅游（文物）、城乡建设主管部门负责组织实施本条例。 市规划和自然资源主管部门负责南京历史文化名城保护相关规划管理工作，承担市文化遗产保护传承工作协调机构涉及历史文化名城保护的日常工作。 市文化和旅游（文物）主…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1463, 801, 2478, '第十四条', '…入本市保护名录。 保护名录的认定和调整应当按照国家和省市有关规定执行；未作规定的，保护对象主管部门应当对推荐的保护名录按照程序征求有关部门、所有权人或者使用权人、管理人的意见，经专家论证、社会公示，由市人民政府批准后公布。 保护对象主管部门应当自保护名录公布之日起一年内建立保护名录档案，载明保护对象的名称、区位、建成…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (802, 'FBMCLI.10.9903391', 'COORD', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1464, 802, 2470, '第六条', '…规划和自然资源主管部门负责南京历史文化名城保护相关规划管理工作，承担市文化遗产保护传承工作协调机构涉及历史文化名城保护的日常工作。 市文化和旅游（文物）主管部门负责世界文化遗产、不可移动文物、非物质文化遗产等的规划编制、保护利用和监督管理等工作，组织红色文化资源调查认定、标识管理、保护责任人制度落实等工作。 市城乡建…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1465, 802, 2468, '第四条', '…工作格局，增强南京历史文化名城保护的整体性、系统性。 市、区和江北新区文化遗产保护传承工作协调机构统筹、指导、协调、审议历史文化名城保护工作重大事项。 南京历史文化名城保护专家委员会为历史文化名城保护重大事项提供评审、论证等服务。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (803, 'FBMCLI.10.9903391', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、7 个相关用语，关联 12 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1466, 803, 2486, '第二十二条', '第二十二条 保护规划的编制和审批，应当遵守下列规定： （一）南京历史文化名城保护规划由市人民政府组织编制，依法报批并备案。 （二）历史文化名镇、名村的保护规划由所在地的区人民政府、江北新区管理机构组织编制，依法报批并备案。 （三）历史文化街…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1467, 803, 2487, '第二十三条', '第二十三条 依法批准的保护规划，不得擅自修改；确需修改的，保护规划的组织编制机关应当向原审批机关提出专题报告，经同意后，方可编制修改方案。修改后的保护规划，应当按照原审批程序报送审批。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1468, 803, 2482, '第十八条', '…北新区管理机构提出退出申请，报市人民政府批准。 法律、法规另有规定的，从其规定。 第三章 保护规划', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (804, 'FBMCLI.10.9903391', 'PRE', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1469, 804, 2480, '第十六条', '第十六条 本市建立历史文化资源预先保护机制。 历史文化资源调查中发现应当保护的历史文化资源，在被纳入推荐的保护名录后，保护对象主管部门应当及时通知所在地的区人民政府、江北新区管理机构；区人民政府、江北新区管理机构在保护对象社会公示前向其所有权人或者使用权人、…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1470, 804, 2515, '第五十一条', '第五十一条 违反本条例第十六条第五款规定，擅自迁移或者拆除预先保护对象的，由区人民政府或者江北新区管理机构确定的行政执法主体责令停止违法行为、限期恢复原状或者采取其他补救措施；有违法所得的，没收违法所得；造成严重后果的，对单位并处五万元以上十万元以下的罚款，对个人并处一万元以上五万元以…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (805, 'FBMCLI.10.9903391', 'REPAIR', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、4 个相关用语，关联 10 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1471, 805, 2480, '第十六条', '…的行为应当及时制止；情况严重的，上报区人民政府、江北新区管理机构。 任何单位和个人不得擅自迁移或者拆除预先保护对象。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1472, 805, 2493, '第二十九条', '…活动，应当延续传统格局和风貌，控制建（构）筑物的高度、体量、风格、色彩等。 （三）不得擅自拆除历史文化街区、名镇、名村核心保护范围和建设控制地带内以及传统村落、古镇、古村、历史地段保护范围内的传统风貌建筑。在历史文化街区、名镇、名村核心保护范围内，因特殊情况需要拆除传统风貌建筑的，应当经市规划和自然资源主管部门会…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1473, 805, 2497, '第三十三条', '…开的，应当尽可能实施原址保护；因公共利益需要进行建设活动，无法对历史建筑实施原址保护、必须迁移异地保护或者拆除的，应当按照国家相关规定执行。 历史建筑拆除后，有条件的应当择地重建，或者在原址立碑，保留和传递历史信息。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (806, 'FBMCLI.10.9903391', 'FUND', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、5 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1474, 806, 2471, '第七条', '第七条 本市建立南京历史文化名城保护资金多渠道筹集机制，资金来源包括： （一）市、区人民政府和江北新区管理机构财政预算安排的保护利用资金、奖补资金； （二）合理利用南京历史文化名城保护对象中的国有建筑的收益； （三）企业和其他社会组织、个人设立的历史文化保护利…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1475, 806, 2469, '第五条', '…持和资金保障力度。 区人民政府和江北新区管理机构负责本区域内历史文化名城保护工作，统筹安排保护资金，建立健全日常巡查管理制度，将巡查工作纳入社区网格化管理。 镇人民政府、街道办事处依照本条例有关规定履行本辖区内历史文化名城保护的相关职责，加强巡查、宣传，引导公众参与历史文化名城保护工作。 村民委员会、居民委员会协助镇…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (807, 'FBMCLI.10.9903391', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1476, 807, 2473, '第九条', '…出意见和建议，对破坏南京历史文化名城保护对象的行为进行监督、举报。 鼓励单位和个人以捐赠、资助、志愿服务等方式参与南京历史文化名城保护利用工作，对在南京历史文化名城保护工作中做出突出贡献的单位和个人，按照国家和省有关规定，给予表彰、奖励。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1477, 807, 2496, '第三十二条', '…保护责任人可以按照房屋使用安全管理相关规定向所在地的区人民政府或者江北新区管理机构申请资金补助。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (808, 'FBMCLI.10.9903391', 'RES', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1478, 808, 2469, '第五条', '…、街道办事处依照本条例有关规定履行本辖区内历史文化名城保护的相关职责，加强巡查、宣传，引导公众参与历史文化名城保护工作。 村民委员会、居民委员会协助镇人民政府、街道办事处做好历史文化名城保护相关工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1479, 808, 2492, '第二十八条', '…实活化利用和人居环境改善相关工作职责； （四）按照职责开展安全和防灾减灾工作； （五）引导居民参与历史文化资源的保护，配合有关部门开展历史文化名城保护的宣传和展示活动。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (809, 'FBMCLI.10.9903391', 'BIZ', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (810, 'FBMCLI.10.9903391', 'DIG', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1480, 810, 2472, '第八条', '…机构及其有关部门应当推动新技术、新方法在历史文化名城保护利用中的应用，发挥历史文化名城保护信息平台作用，整合历史文化资源的调查、规划、保护、管理等信息，提升保护管理效能。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1481, 810, 2481, '第十七条', '…显著位置设置保护标志。法律、法规另有规定的，从其规定。 保护标志的设置应当统一规范，并运用数字化手段，支持公众查询相关信息。 任何单位和个人不得擅自设置、移动、遮挡、涂改或者损毁保护标志。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (811, 'FBMCLI.10.9903391', 'SUP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1482, 811, 2468, '第四条', '第四条 本市坚持党委领导、政府主导、部门联动、多方参与、社会监督的南京历史文化名城保护工作格局，增强南京历史文化名城保护的整体性、系统性。 市、区和江北新区文化遗产保护传承工作协调机构统筹、指导、协调、审议历史文化名城保护工作重大事项。 南京历史文化名城保护专家委员会为历史文化名城保…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1483, 811, 2473, '第九条', '…历史文化名城保护利用相关工作提出意见和建议，对破坏南京历史文化名城保护对象的行为进行监督、举报。 鼓励单位和个人以捐赠、资助、志愿服务等方式参与南京历史文化名城保护利用工作，对在南京历史文化名城保护工作中做出突出贡献的单位和个人，按照国家和省有关规定，给予表彰、奖励。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (812, 'FBMCLI.10.9903391', 'LIAB', 1, 2, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、4 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1484, 812, 2515, '第五十一条', '…其他补救措施；有违法所得的，没收违法所得；造成严重后果的，对单位并处五万元以上十万元以下的罚款，对个人并处一万元以上五万元以下的罚款。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1485, 812, 2513, '第四十九条', '…障、农业农村等部门组织开展传统工匠专业培训和职业技能认定，推动传统技能活态传承。 第六章 法律责任', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (813, 'FBMCLI.10.9844892', 'OBJ', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 14 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1486, 813, 2536, '第十六条', '…估，梳理评测既有建筑状况，明确应保留保护的建筑清单，并组织专家论证。未开展调查评估、未完成历史文化街区划定和历史建筑确定专项工作的区域，不得实施城市更新。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1487, 813, 2522, '第二条', '…督管理等活动，适用本条例。 本条例所指的历史文化名城保护对象包括历史文化名城、名镇、名村、历史文化街区、历史地段、传统村落、不可移动文物、历史建筑、非物质文化遗产以及法律法规规定的其他保护对象。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1488, 813, 2527, '第七条', '第七条 历史文化名城、名镇、名村、历史文化街区、历史地段、传统村落、历史建筑等保护规划的编制应当符合历史文化保护要求，重点体现广府文化、端砚文化等肇庆本地特色文化以及红色革命文化的传承发展，保持传统格局、历史风貌和空间尺度，保护与其相互依存的人文景观、自然景观和背景…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (814, 'FBMCLI.10.9844892', 'BND', 1, 3, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、6 个相关用语，关联 6 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1489, 814, 2528, '第八条', '第八条 历史文化名城、名镇、名村、历史文化街区、历史地段、传统村落的保护规划，应当划定保护范围。保护范围依法设定核心保护范围和建设控制地带。 保护范围内进行建设活动，应当符合规划要求，在布局、高度、体量、建筑风格、色调等方面与历史风貌相协调，不得破坏传统格局和历史风貌。 在核心保护范围内，除建设必要的基础设施、公…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1490, 814, 2531, '第十一条', '…，并向社会公布。 保护名录应当分类设置，建立完整保护档案。档案应当明确各类保护对象的主体和保护范围界线，载明保护对象的名称、类别、区位、面积、保护范围、权属、保护责任人、历史沿革、设计或测绘资料等内容，并附有明确的地理坐标及相应的界址地形图。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1491, 814, 2544, '第二十四条', '…防、防灾等设施设备的正常使用。 历史文化名镇、名村、历史文化街区、历史地段、传统村落等核心保护范围内的消防设施、消防通道，应当按照有关消防技术标准和规范设置，明确消防安全责任人。确因保护需要无法按照消防技术标准和规范设置的，由市、县（市、区）人民政府消防救援机构会同同级保护对象主管部门制订防火安全保障方案。 历史文化…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (815, 'FBMCLI.10.9844892', 'RESP', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、7 个相关用语，关联 11 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1492, 815, 2532, '第十二条', '…的，应当明确专门人员负责保护工作。 市、县（市、区）人民政府住房和城乡建设部门、文化和旅游主管部门等有关职能部门，应当定期组织保护责任人进行培训。培训包括历史文化名城相关法律法规和政策、历史建筑的日常保护和修缮、安全管理、应急处置和活化利用等内容。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1493, 815, 2525, '第五条', '第五条 市、县（市、区）住房和城乡建设主管部门会同同级文物主管部门，负责本行政区域内历史文化名城的保护和监督管理，并组织实施本条例。 发展改革、教育、工业和信息化、公安、民政、财政、人力资源社会保障、自然资源、生态环境、农业农村、商务、应急管理、消防救援、城市管理和…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1494, 815, 2533, '第十三条', '第十三条 历史文化名城、名镇、名村、历史文化街区、历史地段、传统村落的保护责任人应当履行以下职责： （一）保持传统格局、空间尺度、街巷肌理、历史风貌，保护与其相依存的自然景观和环境要素的完整性； （二）改善基础设施、公共服务设施和居住环境； （三）保持保护范围内环境的整洁美观； （四）发掘、展示历史…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (816, 'FBMCLI.10.9844892', 'COORD', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、3 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1495, 816, 2545, '第二十五条', '…化和旅游主管部门、应急、消防救援、城市管理和综合执法等部门应当建立健全信息通报、定期联系、联合执法等协作联动机制，共同做好历史文化名城保护工作。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1496, 816, 2524, '第四条', '…城的保护和监督管理工作，将相关工作纳入国民经济和社会发展规划。建立健全历史文化名城保护工作联席会议机制，协调解决重大问题，加强政策保障和资金保障。 乡镇人民政府、街道办事处负责本辖区内历史文化名城保护对象的日常巡查，将其纳入网格化管理，做好宣传引导和监督工作，指导村民委员会、居民委员会配合做好保护工作。 村民委员会、…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (817, 'FBMCLI.10.9844892', 'PLAN', 1, 2, 'medium', 'machine_draft', '机器初编检出 1 个核心用语、6 个相关用语，关联 8 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1497, 817, 2530, '第十条', '第十条 市、县（市、区）人民政府应当根据保护规划，组织制定年度保护计划，并纳入城市更新专项规划予以实施。 年度保护计划应当根据监测评估、日常巡查中发现的问题以及保护规划确定的总体目标，对保护对象实施分级分类管理。年度保护计划应当包括保护对象、项目清单、资金安排、责任分…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1498, 817, 2527, '第七条', '第七条 历史文化名城、名镇、名村、历史文化街区、历史地段、传统村落、历史建筑等保护规划的编制应当符合历史文化保护要求，重点体现广府文化、端砚文化等肇庆本地特色文化以及红色革命文化的传承发展，保持传统格局、历史风貌和空间尺度，保护与其相互依存的人文景观、自然景观和背景环境，严格控制建筑高度和建筑形态，保护景…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1499, 817, 2537, '第十七条', '…容应当包括工程质量验收和保护要求的符合性验收，验收通过后方可使用。 历史建筑保护责任人按照保护规划和保护图则的要求对历史建筑进行修缮且已验收合格的，市、县（市、区）人民政府可以根据其维护修缮的面积、程度和质量等情况给予资金补助。修缮补助的具体办法由市人民政府制定，并向社会公布。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (818, 'FBMCLI.10.9844892', 'PRE', 0, 0, 'low', 'machine_draft', '未检出该指标的核心制度用语，需人工复核是否存在同义表达。');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (819, 'FBMCLI.10.9844892', 'REPAIR', 1, 3, 'medium', 'machine_draft', '机器初编检出 4 个核心用语、6 个相关用语，关联 5 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1500, 819, 2528, '第八条', '…（市、区）人民政府应当进行整治改造。如无法通过整治改造使其符合规划要求的，应当迁建或者依法拆除。需要迁建、拆除的建筑物、构筑物以及其他设施，属于历史上形成或者经批准建成的，由县（市、区）人民政府分期分批组织实施，并依法给予安置、补偿；属于违法建设的，依法处置。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1501, 819, 2541, '第二十一条', '…等； （三）使用现状和权属变化情况； （四）保护规划； （五）设计、测绘信息资料； （六）修缮、维修、迁移、拆除过程中形成的文字、图纸、图片和影像等资料； （七）其他需要保存的资料。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1502, 819, 2537, '第十七条', '第十七条 对历史建筑进行外部修缮装饰、添加设施以及改变历史建筑的结构或者使用性质的，应当由保护责任人提出申请，依法办理审批手续。 在历史建筑修缮项目正式竣工前，建设单位应当组织设计、施工、监理单位及历史文化保护专家进行评审和验收，验收内容应当包括工程质…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (820, 'FBMCLI.10.9844892', 'FUND', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1503, 820, 2542, '第二十二条', '第二十二条 市、县（市、区）人民政府应当将历史文化名城保护利用资金列入本级财政预算，统筹现有历史文化名城保护传承相关领域各级财政资金，支持历史文化名城保护传承工作。 鼓励社会资本参与历史文化名城保护传承项目，拓宽历史文化名城保护传承投入渠道。市、县（市、区）人民政府应当通过制定政策措施、发布项目信息等…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (821, 'FBMCLI.10.9844892', 'COMP', 1, 2, 'medium', 'machine_draft', '机器初编检出 3 个核心用语、3 个相关用语，关联 3 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1504, 821, 2526, '第六条', '…民政府及其相关部门决策提供咨询意见。 鼓励和支持企事业单位、社会团体和个人通过投资、捐赠、资助、技术服务、开展志愿者活动等形式参与历史文化名城的保护工作。 鼓励和支持广播、电视、报刊、网络等各类媒体开展历史文化名城保护宣传与推广，提升公众的保护意识和参与度。 任何单位和个人有权对破坏历史文化名城的行为进行劝阻和举…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1505, 821, 2528, '第八条', '…，属于历史上形成或者经批准建成的，由县（市、区）人民政府分期分批组织实施，并依法给予安置、补偿；属于违法建设的，依法处置。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1506, 821, 2537, '第十七条', '…且已验收合格的，市、县（市、区）人民政府可以根据其维护修缮的面积、程度和质量等情况给予资金补助。修缮补助的具体办法由市人民政府制定，并向社会公布。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (822, 'FBMCLI.10.9844892', 'RES', 1, 2, 'low', 'machine_draft', '机器初编检出 2 个核心用语、2 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1507, 822, 2523, '第三条', '第三条 历史文化名城保护应当遵循保护优先、科学规划、分类管理、合理利用、公众参与的原则，保护和延续传统格局和历史风貌，维护历史文化遗产的真实性和完整性，正确处理经济社会发展与历史文化遗产保护的关系，继承和弘扬本地优秀历史文化。', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1508, 822, 2538, '第十八条', '…村、历史文化街区、传统村落的保护利用，应当坚持保护优先、有效传承、合理利用的原则，应当保障原住居民的合法权益，保持传统生活习俗的延续性。 鼓励原住居民依据保护规划要求在原址居住，改善生产生活条件，从事当地特色产业的生产经营等相关活动。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (823, 'FBMCLI.10.9844892', 'BIZ', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1509, 823, 2540, '第二十条', '…各类历史文化遗产的研究阐释，挖掘其历史故事、文化价值、精神内涵，按照特色化、差异化要求进行业态策划，开发融入生产生活的历史文化展示线路，推动文化旅游和相关文化产业发展。 鼓励和支持单位和个人对历史文化名镇、名村、历史文化街区、历史地段、传统村落、历史建筑等进行活化利用。鼓励通过下列方式，对历史文化遗产进行多功能、…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (824, 'FBMCLI.10.9844892', 'DIG', 1, 2, 'medium', 'machine_draft', '机器初编检出 2 个核心用语、4 个相关用语，关联 2 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1510, 824, 2541, '第二十一条', '第二十一条 保护对象主管部门应当建立保护对象档案，进行数字化管理并动态维护更新。保护档案应当记载所形成的下列资料： （一）普查、认定获取的资料； （二）有关保护对象的文化艺术特征、历史特征、历史沿革、历史事件、名人事迹和技术资料等； （三）使用现状和权属变化情况； （四）保护规划…', 'supporting');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1511, 824, 2543, '第二十三条', '…分布状况、生存环境、保护现状等情况，收集和妥善保存相关资料和实物，建立非物质文化遗产档案和数据库。 对濒临消失的非物质文化遗产项目，市、县（市、区）人民政府文化和旅游主管部门应当立即予以记录并收集有关实物，或者采取其他抢救性保存措施；对需要传承的，应当采取有效措施支持传承。 市、县（市、区）人民政府应当统筹规划或者…', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (825, 'FBMCLI.10.9844892', 'SUP', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、2 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1512, 825, 2526, '第六条', '…与推广，提升公众的保护意识和参与度。 任何单位和个人有权对破坏历史文化名城的行为进行劝阻和举报。有关职能部门接到举报后，应当及时核实、处理。对实名举报的，应当将处理结果向举报人反馈，并为举报人保密。', 'supporting');
INSERT OR REPLACE INTO codings (id, law_id, indicator_code, presence, strength, confidence, review_status, coding_note) VALUES (826, 'FBMCLI.10.9844892', 'LIAB', 1, 1, 'low', 'machine_draft', '机器初编检出 1 个核心用语、1 个相关用语，关联 1 条证据条文。');
INSERT OR REPLACE INTO evidence (id, coding_id, article_id, article_label, excerpt, relevance) VALUES (1513, 826, 2546, '第二十六条', '第二十六条 违反本条例规定的行为，法律、法规已规定法律责任的，从其规定。', 'supporting');
